      const out={};
      const cles=new Set(Object.keys(l).concat(Object.keys(d)));
      for(const k of cles){
        if(!p&&SYNC_HORS_FUSION.indexOf(k)>=0) continue;
        const v=rec(l[k],d[k],p?(p+SYNC_SEP+k):k,prof+1);
        if(v!==undefined) out[k]=v;
      }
