  if(Array.isArray(r.videos)) r.videos=r.videos.filter(v=>!(v&&mv.has(String(v.id))));
  if(Array.isArray(r.bilans))
    r.bilans=r.bilans.filter(b=>!(b&&mb.has(String(b.date)+'|'+String(b.type||''))));
