function v(id){return document.getElementById(id)?.value?.trim()||'';}

// ── Âge minimum à l'inscription ─────────────────────────────────────────────
// 16 ans révolus. L'art. 8 du RGPD fixe 16 ans par défaut et laisse chaque État
// descendre jusqu'à 13 ; la France a retenu 15 ans (art. 45 de la loi
// Informatique et Libertés). RepCore se place volontairement au-dessus du seuil
// français, parce qu'il traite des données de santé au sens de l'art. 9.
const AGE_MINIMUM=16;
// Âge RÉVOLU, par comparaison des quantièmes. Une division du nombre de
// millisecondes par 365,25 jours se trompe autour de l'anniversaire et sur les
// années bissextiles — pour un seuil légal, l'à-peu-près n'est pas tenable.
function _ageRevolu(iso){
  if(!iso) return null;
  const n=new Date(iso+'T00:00:00');
  if(isNaN(n.getTime())) return null;
  const a=new Date();
  let age=a.getFullYear()-n.getFullYear();
  const m=a.getMonth()-n.getMonth();
  if(m<0||(m===0&&a.getDate()<n.getDate())) age--;
  return age;
}
// Borne haute du sélecteur natif : la date la plus récente encore acceptable.
// LES DEUX CHAMPS DE DATE partagent ces bornes : celui de l'inscription et
// celui du profil. Deux jeux finiraient par diverger, et celui du profil
// serait le dernier mis à jour.
function _initBirthdateMax(){
  const d=new Date();
  d.setFullYear(d.getFullYear()-AGE_MINIMUM);
  const max=d.toISOString().slice(0,10);
  // 'r-birthdate' a disparu avec le champ de l'inscription ; 'nai-birthdate'
  // prend sa place — c'est le meme champ, sur l'ecran qui le demande
  // desormais. Le plafond natif reste un confort : validerNaissanceGenre
  // reverifie, car l'attribut est trivial a contourner.
  for(const id of ['nai-birthdate','atp-birthdate']){
    const el=document.getElementById(id);
    if(!el) continue;
    el.max=max;
    el.min='1900-01-01';
  }
}
// Normalise toutes les conventions historiques ('femme','F','f') → booléen
function isFemale(g){const s=String(g||'');return s==='F'||s==='f'||s.toLowerCase()==='femme';}
function genCode(){
  const c='ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
  return 'GCP-'+Array.from({length:6},()=>c[Math.floor(Math.random()*c.length)]).join('');
}
// ══════ LE CODE COACH EN ATTENTE, SANS BLOQUER SI LE STOCKAGE EST PLEIN ══
//
// Ce n'est PAS une donnee de l'utilisateur : c'est un relais de quelques
// caracteres entre deux ecrans, et l'ecran d'arrivee sait le redemander. Son
// echec ne doit donc jamais couter plus que lui-meme — surtout pas le go() qui
// le suit, comme c'etait le cas.
//
// ON LE DIT QUAND MEME. Regle du projet : aucune perte silencieuse. L'athlete
// qui devra retaper son code doit savoir pourquoi, sinon il croit que le lien
// de son coach est casse.
function _poserCodeEnAttente(code){
  try{
    localStorage.setItem('pendingCode',code||'');
    return true;
  }catch(e){
    console.warn('[RepCore] pendingCode non enregistré :',e);
    try{ toast('Stockage plein : garde ton code sous la main, il te sera redemandé à l’écran suivant.','var(--orange)'); }catch(_){}
    return false;
  }
}
function localISODate(d){
  const m=String(d.getMonth()+1).padStart(2,'0'),day=String(d.getDate()).padStart(2,'0');
  return d.getFullYear()+'-'+m+'-'+day;
}
function copyCoachInviteLink(){
  if(!currentUser||currentUser.role!=='coach') return;
  // Embed coach profile in URL so athlete's device can import it without a backend
  const payload={
    id:currentUser.id,
    fname:currentUser.fname,
    lname:currentUser.lname,
    email:currentUser.email,
    code:currentUser.code,
    role:'coach',
    _st:undefined
  };
  const encoded=btoa(unescape(encodeURIComponent(JSON.stringify(payload))));
  const url=APP_BASE_URL+'?coachpkg='+encoded;
  if(navigator.clipboard){
    navigator.clipboard.writeText(url).then(()=>toast('✓ Lien copié ! Envoie-le à ton athlète par WhatsApp ou SMS.'));
  }else{
    const ta=document.createElement('textarea');ta.value=url;document.body.appendChild(ta);ta.select();document.execCommand('copy');ta.remove();
    toast('✓ Lien copié !');
  }
}

async function doAthleteCode(){
  // La valeur brute est lue SANS mise en majuscules : la charge base64 d'un lien
  // d'invitation y est sensible, et c'est ce qui faisait échouer tout collage de
  // lien complet dans ce champ. La normalisation n'intervient qu'après, pour les
  // codes courts — même logique que le oninput de cc-code.
  const raw=(document.getElementById('ae-code').value||'').trim();
  const errEl=document.getElementById('ae-err');
  errEl.style.display='none';
  if(!raw){errEl.textContent='Entre un code valide.';errEl.style.display='block';return;}
  // Compté sur la tentative RÉELLE, après le champ vide : un clic sur un
  // formulaire vide n'est pas une saisie de code, et le compter ferait croire
  // à un abandon massif entre « code saisi » et « code valide ».
  rcm('code_entered');

  // Cas 1 : lien d'invitation complet (?coachpkg=BASE64) — aligné sur doLinkCoach.
  // L'athlète n'a pas encore de compte : on mémorise le coach et son code, puis
  // on enchaîne sur l'inscription, exactement comme la branche du code GCP.
  // LE CODE DU LIEN EST RETENU, PAS VÉRIFIÉ ICI. Le `catch` de ce try est vide
  // — il l'était déjà, pour tolérer une saisie qui n'est pas une URL. Y mettre
  // la vérification réseau aurait avalé ses erreurs : « ce code a déjà été
  // utilisé » serait devenu un silence, puis le message générique du bas.
  let _invDuLien=null;
  try{
    const _url=new URL(raw);
    const pkg=_url.searchParams.get('coachpkg');
    const inv=String(_url.searchParams.get('inv')||'').trim().toUpperCase();
    if(pkg){
      const coach=_validateCoachPkg(JSON.parse(decodeURIComponent(escape(atob(pkg)))));
      if(coach){
        const users=DB.get('users')||{};
        users[coach.email]=Object.assign(users[coach.email]||{},coach);
        DB.set('users',users);
        // Le lien porte un vrai code d'accès : on le traite comme tel, à
        // l'identique de la branche RC-XXXX-XXXX plus bas. Sinon seulement,
        // on retombe sur le code GCP — le rattachement même-appareil.
        if(_INVITE_RE.test(inv)){ _invDuLien=inv; }
        else {
          // LE QUOTA NE DOIT PAS BLOQUER L'INSCRIPTION. Sur un stockage
          // sature — 81 % de base64 d'images chez cet utilisateur — cette
          // ecriture levait, et l'exception emportait le go() qui suit : l'app
          // affichait « VERIFICATION… » et ne faisait plus rien. Un ecran mort,
          // sans un mot, sur le tout premier geste d'un nouvel athlete.
          //
          // MEME COMPORTEMENT QUE DB.setLocal : on avertit, et ON CONTINUE. Le
          // code sera redemande a l'ecran suivant — c'est une gene, pas une
          // impasse, et c'est infiniment mieux qu'un bouton qui ne repond plus.
          _poserCodeEnAttente(coach.code||'');
          go('s-register');
          setTimeout(()=>selectRole('athlete',true),50);
          return;
        }
      }
    }
  }catch(e){}
  // Hors du try : ici, une erreur se dit.
  if(_invDuLien){
    const btn=document.getElementById('ae-valider');
    const libelle=btn?btn.textContent:'';
    if(btn) arcAttendre(btn,'VÉRIFICATION…');
    try{
      // SANS CONSOMMER : le compte n'existe pas encore, et un code brûlé par
      // une inscription abandonnée serait perdu pour de bon.
      const payload=await _verifierCodeSansConsommer(_invDuLien);
      rcm('code_valid');
      _retenirCodeVerifie(_invDuLien,payload);
      go('s-register');
      setTimeout(()=>selectRole('athlete',true),50);
    }catch(e){
      rcm('code_invalid');
      errEl.textContent=e.message||'Code invalide.';
      errEl.style.display='block';
    }finally{
      if(btn) arcRendre(btn,libelle);
    }
    return;
  }

  // Cas 2 : codes courts. C'est SEULEMENT ici que la mise en majuscules a un sens.
  const code=raw.toUpperCase();
  // Try RCACCESS token (starts with "RCACCESS:")
  // Format abandonné : doLinkCoach le refuse déjà en aval. Le laisser passer
  // jusqu'à l'inscription faisait créer un compte à quelqu'un qui apprenait
  // ensuite seulement que son code n'était plus accepté.
  if(code.startsWith('RCACCESS:')){
    errEl.textContent='Ancien format de code : demande un nouveau code (RC-XXXX-XXXX) à ton coach.';
    errEl.style.display='block';
    return;
  }
  // Code RC-XXXX-XXXX : vérifié AUPRÈS DU SERVEUR avant toute inscription.
  // L'ancienne version se contentait du format et envoyait sur s-register :
  // un code désactivé, expiré ou déjà utilisé n'était découvert qu'APRÈS la
  // création du compte Firebase et le consentement au traitement des données
  // de santé — un consentement collecté pour un accès qui n'existait pas.
  if(_INVITE_RE.test(code)){
    const btn=document.getElementById('ae-valider');
    const libelle=btn?btn.textContent:'';
    if(btn) arcAttendre(btn,'VÉRIFICATION…');
    try{
      const payload=await _verifierCodeSansConsommer(code);
      rcm('code_valid');
      _retenirCodeVerifie(code,payload);
      go('s-register');
      setTimeout(()=>selectRole('athlete',true),50);
    }catch(e){
      rcm('code_invalid');
      errEl.textContent=e.message||'Code invalide.';
      errEl.style.display='block';
    }finally{
      if(btn) arcRendre(btn,libelle);
    }
    return;
  }
  // Try coach main GCP code or student code
  const users=DB.get('users')||{};
  const allCoaches=Object.values(users).filter(u=>u.role==='coach');
  // Check coach's main GCP code
  const directCoach=allCoaches.find(u=>u.code&&u.code.toUpperCase()===code);
  if(directCoach){
    // Meme geste, meme risque : voir _poserCodeEnAttente.
    _poserCodeEnAttente(code);
    go('s-register');
    setTimeout(()=>selectRole('athlete',true),50);
    return;
  }
  // Le lien d'invitation vient d'être tenté sans succès : ne pas le recommander.
  errEl.textContent='Ce code ne correspond à aucun coach. Vérifie que tu as bien collé le lien complet envoyé par ton coach, ou demande-lui de te le renvoyer.';
  errEl.style.display='block';
}
function linkToCoach(coach){
  // Helper: link currentUser to a coach object and save
  const users=DB.get('users')||{};
  currentUser.coachId=coach.id;
  currentUser.coachName=coach.fname+' '+coach.lname;
  currentUser.coachCode=coach.code;
  currentUser.status='COACHING_SUIVI';
  if(!coach.clients) coach.clients=[];
  if(!coach.clients.includes(currentUser.id)) coach.clients.push(currentUser.id);
  users[currentUser.email]=currentUser;
  users[coach.email]=coach;
  DB.set('users',users);DB.set('session',currentUser);
  // La liaison a abouti : le code a joue son role et peut partir.
  try{localStorage.removeItem('pendingCode');}catch(e){}
  toast('Lié à '+((coach.fname||'')+' '+(coach.lname||'')).trim()+' ✓');
  _apresRattachement();
}

// Point d'arrivée unique après un rattachement réussi — trois chemins y
// menaient et ouvraient chacun `openBilan('depart')` sans détour.
// Un questionnaire de six étapes barrait donc l'entrée d'un athlète qui venait
// de saisir son code et voulait simplement voir son programme : le seul moyen
// d'avancer était de le remplir, ou de trouver le lien « plus tard ».
// Le bilan reste demandé — carte permanente sur l'accueil, relance à la fin de
// la première séance — mais il ne conditionne plus l'accès à l'app.
function _apresRattachement(){
  // L INSCRIPTION A L ANNUAIRE DE SON COACH. C est le seul moyen pour lui de
  // DECOUVRIR ce dossier depuis un autre appareil : les regles lui
  // interdisent de parcourir /users. Sans await et sans traitement d echec —
  // c est du confort pour le coach, pas une etape de ce parcours-ci, et
  // l ouverture suivante la reposera de toute facon.
  try{ CLOUD.pushAnnuaire(currentUser); }catch(e){}
  go('s-client-home');
  loadClientHome();
}

// Applique un code DÉJÀ vérifié et consommé à currentUser. Extrait de
// doLinkCoach pour que le rattachement automatique d'après inscription et la
// saisie manuelle de rattrapage produisent exactement le même état — deux
// copies de cette logique auraient divergé au premier correctif porté sur une
// seule (coachEmailKey, pushOne et accessExpiry sont trop faciles à oublier).
function _appliquerPayloadCode(payload){
  const users=DB.get('users')||{};
  const coach=Object.values(users).find(u=>u.id===payload.coachId);
  if(coach){
    if(!coach.clients) coach.clients=[];
    if(!coach.clients.includes(currentUser.id)) coach.clients.push(currentUser.id);
    users[coach.email]=coach;
  }
  // R-03 : l'octroi ne dépend plus de creatorFree. Un code de type 'athlete',
  // émis par le créateur OU par un affilié, ouvre l'accès. Le paywall ne
  // subsiste que pour l'inscription AUTONOME, sans code — ce chemin-ci n'y
  // passe pas.
  const _mois=_moisAutorises(payload);
  const _octroi=payload.creatorFree||(payload.type||'athlete')==='athlete';
  if(_octroi){
    // Accès accordé immédiatement
    currentUser.coachId=payload.coachId;
    currentUser.coachName=payload.coachName||'Coach';
    // Pose EXPLICITE, depuis le code et non depuis le cache local : c'est la
    // seule valeur qui ouvre le dossier au coach cote serveur. Le repli
    // derive la cle de coachEmail pour les codes emis avant ce changement.
    const _ck=payload.coachEmailKey
      ||((payload.coachEmail||'').replace(/\./g,','))||null;
    if(_ck) currentUser.coachEmailKey=_ck;
    currentUser.status='COACHING_SUIVI';
    // Le plafond est RE-VÉRIFIÉ ici, à la consommation : le payload vient du
    // réseau, et une vérification côté émetteur seule ne protège de rien.
    // On recalcule l'échéance depuis months plutôt que de faire confiance à
    // expiry, qu'un code forgé porterait à dix ans.
    const _exp=_mois>0?Date.now()+_mois*_MONTH_MS:payload.expiry;
    // Un athlète DÉJÀ payant garde la date la plus lointaine : saisir un code
    // de coach ne doit jamais raccourcir un accès acheté.
    currentUser.accessExpiry=Math.max(Number(currentUser.accessExpiry)||0,
      Number(_exp)||0)||_exp;
    users[currentUser.email]=currentUser;
    const _u1=DB.set('users',users),_s1=DB.set('session',currentUser);
    // Envoi immediat : sans lui, le coach ne voit rien tant que l'athlete
    // n'a pas declenche une autre ecriture.
    // N3.18 — LE « ✓ » ATTEND LES DEUX DESTINATIONS. C'est l'ecriture la plus
    // consequente de tout le parcours de l'athlete : reseau coupe, il lisait
    // « Acces active ✓ » et son coach ne le voyait jamais apparaitre.
    const _envoi=CLOUD.pushOne(currentUser.email,currentUser);
    // Idem : succes confirme, le code en attente n'a plus lieu d'etre.
    _oublierCodeVerifie();
    toastSync(_u1&&_s1,_envoi,'Accès activé ✓','ton accès est');
    _apresRattachement();
  } else {
    // Code NON athlète (invitation coach) : le paiement reste le chemin
    sessionStorage.setItem('pendingCodePayload',JSON.stringify(payload));
    users[currentUser.email]=currentUser;
    DB.set('users',users);
    // Le code n'est PAS oublié ici : le paiement peut échouer ou être
    // abandonné, et l'athlète doit pouvoir revenir sur s-subscribe sans
    // redemander son code au coach. loadSubscribePage le relit.
    goAvecRetour('s-subscribe');
    loadSubscribePage('pending-code',payload);
  }
}

// Rattachement automatique juste après l'inscription. Le code a déjà été
// validé sur l'écran d'entrée ; _verifyAccessCode est rappelée ici parce que
// c'est elle qui CONSOMME (PATCH redeemed), ce que la vérification préalable
// s'interdit — et parce qu'à ce stade currentUser et le jeton existent enfin.
// Retourne true si l'athlète a été routé, false s'il faut le laisser sur
// l'écran de rattrapage.
async function _appliquerCodeApresInscription(){
  const retenu=_codeVerifieEnAttente();
  if(!retenu||!retenu.code) return false;
  try{
    const r=await _verifyAccessCode(retenu.code,(currentUser.fname||'')+' '+(currentUser.lname||''));
    _appliquerPayloadCode(r.payload);
    return true;
  }catch(e){
    // Rare : le code était valide quelques secondes plus tôt. Réseau coupé
    // pendant l'inscription, ou code consommé entre-temps par un autre
    // appareil. On ne laisse pas l'athlète sans explication ni sans issue.
    toast(e.message||'Code non appliqué : ressaisis-le.','var(--orange)');
    return false;
  }
}

// PURE. L athlete est-il deja rattache, et a qui ? Rend le nom du coach, ou
// null. On lit le dossier, pas l ecran.
function coachActuelDe(user){
  const u=_dossier(user);
  if(!u||!u.coachId) return null;
  const nom=String(u.coachName||'').trim();
  if(nom) return nom;
  const c=Object.values(DB.get('users')||{}).find(x=>x&&x.id===u.coachId);
  return c?((c.fname||'')+' '+(c.lname||'')).trim()||'ton coach':'ton coach';
}
// PURE. Le lien recu designe-t-il le coach qu on a deja ? Deux cas tres
// differents : rouvrir SON propre lien est anodin, en ouvrir un AUTRE est un
// changement de coach, et ca ne se fait pas par inadvertance.
function _memeCoachQueLien(coachDuLien,user){
  const u=_dossier(user);
  if(!u||!u.coachId||!coachDuLien) return false;
  return String(coachDuLien.id||'')===String(u.coachId);
}
// Le message dedie. Rend true quand il a pris la main — l appelant s arrete
// alors la, et AUCUN second rattachement n a lieu.
// L'INVITATION EST ANNONCÉE, JAMAIS APPLIQUÉE. On pose le code en attente et
// on le dit ; la validation reste un geste de l'athlète, et
// _annoncerDejaRattache — juste en dessous — garde la main sur ce geste.
//
// Le code du LIEN passe avant le code GCP du coach : `inv` porte le code
// d'accès daté, `coach.code` ne rattache qu'au même appareil.
function _annoncerInvitation(coach){
  if(!coach) return null;
  const code=window._invitationCode||coach.code||'';
  // MEME CHEMIN QUE LES DEUX AUTRES : l'echec etait avale en silence ici, et
  // l'athlete ne comprenait pas pourquoi son code lui etait redemande.
  if(code) _poserCodeEnAttente(code);
  const prenom=(coach.fname||coach.lname||'ton coach').trim();
  // DÉJÀ SUIVI PAR QUELQU'UN D'AUTRE : on ne promet rien. « Valide ton accès »
  // annoncerait exactement ce que _annoncerDejaRattache va refuser au clic
  // suivant.
  const _mien=currentUser&&currentUser.coachId;
  const _autre=!!_mien&&_mien!==coach.id;
  const msg=_autre
    ? 'Invitation de '+prenom+' reçue. Tu es déjà suivi par '+(coachActuelDe(currentUser)||'un coach')
      +' : parles-en à ton coach avant tout changement.'
    : 'Invitation de '+prenom+' reconnue, valide ton accès.';
  const z=document.getElementById('cc-invit');
  const inp=document.getElementById('cc-code');
  // Le champ est pré-rempli quoi qu'il arrive, mais seulement s'il est vide :
  // il servira le jour où l'athlète ouvrira l'écran de saisie.
  if(inp&&!inp.value&&code) inp.value=code;
  if(z){ z.textContent=msg; }
  // LE MESSAGE SUIT L'ÉCRAN AFFICHÉ, PAS L'EXISTENCE DE L'ÉLÉMENT. #cc-invit
  // vit dans s-client-code, qui est TOUJOURS dans le document — seulement
  // masqué quand il n'est pas actif. Se fier à sa présence écrivait le message
  // dans un écran caché : un athlète dont l'accès est actif atterrit sur son
  // accueil et ne voyait rien du tout. Mesuré, la branche toast était morte.
  const _surEcranCode=!!document.getElementById('s-client-code')
    &&document.getElementById('s-client-code').classList.contains('active');
  if(_surEcranCode){
    if(z) z.style.display='block';
  } else {
    if(z) z.style.display='none';
    toast(msg,_autre?'var(--orange)':'var(--green)');
  }
  return {code,msg,autre:_autre,canal:_surEcranCode?'encart':'toast'};
}
// N’EST PLUS APPELÉE QUE POUR UN AUTRE COACH.
//
// Ses deux appelants vérifient l’écart d’identité avant d’appeler : le lien
// de SON coach est une prolongation, pas un changement. La branche « même
// coach » est donc partie — elle affirmait « ton accès est déjà actif, ce
// lien ne sert plus à rien », ce qui était faux dès que accessExpiry était
// dépassée, et plus rien ne l’affichait.
function _annoncerDejaRattache(coachDuLien){
  const actuel=coachActuelDe();
  if(!actuel) return false;
  const nomLien=coachDuLien?(((coachDuLien.fname||'')+' '+(coachDuLien.lname||'')).trim()||'ce coach'):'ce coach';
  const html='<div id="modal-overlay" onclick="closeModal()" style="position:fixed;inset:0;'
    +'background:var(--scrim);z-index:var(--z-modal);display:flex;align-items:flex-end;justify-content:center">'
    +'<div onclick="event.stopPropagation()" style="background:var(--surface-2);'
    +'border-radius:var(--r-4) var(--r-4) 0 0;padding:18px 20px 22px;width:100%;max-width:480px;'
    +'animation:fadeIn var(--t-3) var(--c-out)">'
    +'<h2 style="margin-bottom:8px;font-size:var(--fs-lg)">Tu es déjà suivi</h2>'
    +'<p class="sub" style="font-size:var(--fs-sm);line-height:1.65;margin-bottom:14px">'
    +'Tu es actuellement suivi par <strong style="color:var(--text-strong)">'+escapeHtml(actuel)+'</strong>, '
    +'et ce lien vient de <strong style="color:var(--text-strong)">'+escapeHtml(nomLien)+'</strong>. '
    +'Changer de coach ne se fait pas en ouvrant un lien : demande à '
    +escapeHtml(actuel)+' de te libérer, puis rouvre celui-ci. '
    +'<strong style="color:var(--text-strong)">Rien n\'a été modifié.</strong>'
    +'</p>'
    +'<button class="btn btn-red" style="min-height:46px" onclick="closeModal();go(\'s-client-home\')">'
    +'Revenir à mon accueil</button>'
    +'<button class="btn btn-outline" style="margin-top:9px;min-height:44px" onclick="closeModal()">Fermer</button>'
    +'</div></div>';
  document.body.insertAdjacentHTML('beforeend',html);
  return true;
}
async function doLinkCoach(){
  const raw=document.getElementById('cc-code').value.trim();
  if(!raw){return showErr('cc-err','Entre un code ou lien coach.');}
  // LE BOUTON DIT QU IL SE PASSE QUELQUE CHOSE. À partir d’ici, la fonction
  // peut enchaîner _verifyAccessCode, _coachDuCode puis _appliquerPayloadCode
  // — trois allers-retours réseau pendant lesquels rien ne bougeait à
  // l’écran. Un second appui relançait toute la vérification, et le PATCH de
  // _verifyAccessCode consomme le code : le deuxième passage le trouvait
  // « déjà utilisé ».
  //
  // Le libellé est MÉMORISÉ, jamais réécrit en dur : celui du bouton et
  // celui du code finiraient par diverger.
  const _btnLC=document.getElementById('cc-valider');
  // DEJA EN COURS : on ne relance rien. Sans ce garde, un second appel
  // memoriserait « VÉRIFICATION… » comme libellé d’origine et le rendrait à
  // la fin — le bouton resterait figé sur un mot d’attente.
  if(_btnLC&&_btnLC.disabled) return;
  const _libLC=_btnLC?_btnLC.textContent:'';
  if(_btnLC) arcAttendre(_btnLC,'VÉRIFICATION…');
  // Le try couvre TOUS les chemins de sortie, `return showErr(...)` compris :
  // c’est précisément eux qui laissaient le bouton mort dans doAthleteCode
  // avant son propre correctif.
  try{

    // Case 1: URL d'invitation coach (?coachpkg=BASE64) — cross-device
    //
    // LE CODE DU LIEN EST RETENU, PAS VÉRIFIÉ ICI : le `catch` de ce try est
    // vide, et la vérification réseau y perdrait ses messages d'erreur.
    let _invDuLien=null;
    try{
      const urlObj=new URL(raw);
      const pkg=urlObj.searchParams.get('coachpkg');
      const inv=String(urlObj.searchParams.get('inv')||'').trim().toUpperCase();
      if(pkg){
        const coach=_validateCoachPkg(JSON.parse(decodeURIComponent(escape(atob(pkg)))));
        if(coach){
          // DEJA RATTACHE A UN AUTRE : on le DIT, et on s’arrête là. Ni erreur
          // muette, ni second rattachement — changer de coach ne se fait pas en
          // ouvrant un lien.
          //
          // MAIS LE LIEN DE SON PROPRE COACH EST LE GESTE DE PROLONGATION.
          // L’arrêter refusait de renouveler un accès, et le message annonçait
          // « ton accès est déjà actif » à quelqu’un dont l’échéance venait
          // justement de passer. On continue donc vers `inv`, comme le cas 2.
          //
          // _memeCoachQueLien rend exactement le test du cas 2 : un coach en
          // place ET différent. Sans coach du tout, il rend false et
          // _annoncerDejaRattache s’abstient de lui-même.
          if(!_memeCoachQueLien(coach)&&_annoncerDejaRattache(coach)) return;
          const users=DB.get('users')||{};
          users[coach.email]=Object.assign(users[coach.email]||{},coach);
          DB.set('users',users);
          // LE LIEN PORTE UN VRAI CODE D'ACCÈS. linkToCoach rattache mais ne
          // pose PAS accessExpiry, et checkAccess lit une échéance absente
          // comme un accès ILLIMITÉ : tout athlète arrivé par lien obtenait un
          // accès perpétuel, et le code restait « ouvert » dans /rc_codes, donc
          // réutilisable par quelqu'un d'autre. On passe par le vrai chemin.
          if(_INVITE_RE.test(inv)){ _invDuLien=inv; }
          else return linkToCoach(coach);
        }
      }
    }catch(e){}
    // Hors du try : ici, une erreur se dit.
    if(_invDuLien){
      let _res;
      try{
        _res=await _verifyAccessCode(_invDuLien,(currentUser.fname||'')+' '+(currentUser.lname||''));
      }catch(e){
        return showErr('cc-err',e.message||'Code invalide ou corrompu. Contacte ton coach.');
      }
      _appliquerPayloadCode(_res.payload);
      return;
    }

    // Case 2: code RC-XXXX-XXXX — vérifié via Firebase RTDB directement
    if(/^RC-[A-Z0-9]{4}-[A-Z0-9]{4}$/.test(raw)||raw.startsWith('RCACCESS:')){
      if(raw.startsWith('RCACCESS:')) return showErr('cc-err','Ancien format de code : demande un nouveau code (RC-XXXX-XXXX) à ton coach.');
      // LA MÊME GARDE QU'AU CAS 1. Sans elle, un code suffisait à changer de
      // coach en silence — là où le lien d'invitation, lui, était arrêté.
      //
      // La lecture est SEULE et ne juge rien : elle ne sert qu'à comparer les
      // coachs. Elle vient AVANT _verifyAccessCode, qui consomme le code par un
      // PATCH : décider après aurait brûlé un code qu'on refuse.
      //
      // Elle n'a lieu que si un coach est déjà en place. Un athlète qui n'en a
      // pas, ou qui saisit un code de SON coach — la prolongation — ne paie
      // aucun aller-retour supplémentaire.
      if(coachActuelDe()){
        const _cl=await _coachDuCode(raw);
        if(_cl&&String(_cl.id)!==String(currentUser.coachId||'')){
          _annoncerDejaRattache(_cl);
          return;
        }
      }
      let result;
      try{
        result=await _verifyAccessCode(raw,(currentUser.fname||'')+' '+(currentUser.lname||''));
      }catch(e){
        return showErr('cc-err',e.message||'Code invalide ou corrompu. Contacte ton coach.');
      }
      _appliquerPayloadCode(result.payload);
      return;
    }

    // NOTE — une branche « ancien format RC-XXXX-XXXX » figurait ici. Elle etait
    // INATTEIGNABLE : la Case 2 plus haut teste le MEME motif exact et retourne
    // toujours. Son commentaire affirmait de surcroit qu'une « regle RTDB bloque
    // /rc_codes/* », alors que database.rules.json les ouvre en lecture ET en
    // ecriture a tout compte authentifie. Code mort porteur d'une contre-verite :
    // retire plutot que corrige.

    // Case 3: RCLINK token (legacy)
    if(raw.startsWith('RCLINK:')){
      try{
        const payload=JSON.parse(decodeURIComponent(escape(atob(raw.slice(7)))));
        if(!payload.c||!payload.f||!payload.i) throw new Error('invalid');
        currentUser.coachId=payload.i;
        currentUser.coachName=payload.f+(payload.l?' '+payload.l:'');
        currentUser.coachCode=payload.c;
        currentUser.status='COACHING_SUIVI';
        const users=DB.get('users')||{};
        users[currentUser.email]=currentUser;
        const _u2=DB.set('users',users),_s2=DB.set('session',currentUser);
        toastEcriture(_u2&&_s2,'Lié à '+currentUser.coachName+' ✓','le rattachement est');
        _apresRattachement();return;
      }catch(e){return showErr('cc-err','Lien invalide. Demande un nouveau lien à ton coach.');}
    }

    // Case 4: Code GCP-XXXXXX
    const code=raw.toUpperCase().replace(/\s/g,'');
    if(code.startsWith('GCP-')){
      const users=DB.get('users')||{};
      const coach=Object.values(users).find(u=>u.role==='coach'&&u.code&&u.code.toUpperCase()===code);
      if(coach) return linkToCoach(coach);
      // Code GCP non trouvé → probablement autre appareil
      return showErr('cc-err','❌ Code introuvable sur cet appareil.\n\nTon coach doit appuyer sur "Copier le lien d\'invitation" depuis son écran de code, puis t\'envoyer ce lien par WhatsApp. Colle ce lien ici à la place du code court.');
    }

    showErr('cc-err','Format non reconnu. Entre le lien d\'invitation de ton coach.');
  } finally {
    if(_btnLC) arcRendre(_btnLC,_libLC);
  }
}
function showCoachCode(){
  document.getElementById('coach-code-val').textContent=currentUser.code;
  go('s-coach-code');
}
async function regenCoachCode(){
  // CE QUE ÇA COUPE, ET CE QUE ÇA NE COUPE PAS. L'ancien texte promettait que
  // « tous les liens déjà partagés » cesseraient de fonctionner : c'était vrai
  // quand le seul lien portait le code GCP. Les invitations NOMINATIVES portent
  // &inv=RC-XXXX-XXXX, et doAthleteCode traite cette branche EN PRIORITÉ sans
  // jamais lire coach.code — le pré-remplissage de l’écran d’entrée non plus.
  //
  // Un message de sécurité doit dire ce qu’il fait, et surtout ce qu’il NE fait
  // pas : croire avoir fermé un accès qui reste ouvert est pire que de savoir
  // qu’il faut le fermer ailleurs. D’où le renvoi vers l’onglet CODES.
  if(!await rcConfirm('⚠️ Régénérer ton code coach ?',
    'Ça remplace ton code court et le lien générique de « Copier le lien '
    +'d\'invitation » : les deux cessent de fonctionner.\n\n'
    +'En revanche, les invitations NOMINATIVES déjà envoyées continuent de '
    +'fonctionner : elles portent leur propre code. Pour en fermer une, '
    +'désactive-la dans l\'onglet CODES.\n\n'
    +'Les athlètes déjà liés ne sont PAS affectés.','Régénérer')) return;
  currentUser.code=genCode();
  saveUser();
  document.getElementById('coach-code-val').textContent=currentUser.code;
  toast('Nouveau code généré : pense à partager le nouveau lien.','var(--green)');
}

// ======= COACH HOME =======
// Types d'alerte portant sur la SANTÉ. Leur report obéit à deux règles que les
// alertes administratives n'ont pas :
//   — il ne peut jamais dépasser sept jours, même si une valeur plus lointaine
//     a été écrite. Un coach peut décider de ne pas agir ; il ne doit pas
//     pouvoir faire disparaître définitivement une alerte de santé d'un clic.
//   — une aggravation le casse immédiatement.
const ALERTES_SANTE=Object.freeze(['douleur','douleurdiff']);
const REPORT_SANTE_MAX=7*864e5;
function _pireDouleur(c){
  const sg=signauxEntrainement(c);
  return Math.max(
    (sg.details&&sg.details.douleur&&sg.details.douleur.painMax)||0,
    (sg.details&&sg.details.douleurDiffuse&&sg.details.douleurDiffuse.painMax)||0);
}
function isAlertSnoozed(type,clientId,latestBilanTs,client){
  const st=(currentUser.alertStatus||{})[type+'-'+clientId];
  if(!st) return false;
  if(st.until&&Date.now()>=st.until) return false;
  if(type==='bilan'&&latestBilanTs&&st.seenUpTo&&latestBilanTs>st.seenUpTo) return false;
  if(ALERTES_SANTE.includes(type)){
    // Plafond appliqué à la LECTURE et non seulement à l'écriture : une entrée
    // écrite autrement, ou par une version future du code, reste bornée.
    // Sans horodatage de report, l'entrée n'est PAS un report valable — sinon
    // il suffisait d'écrire un « until » lointain sans « at » pour enterrer
    // définitivement une alerte de santé. reporterAlerte écrit toujours « at ».
    if(!st.at||Date.now()>=st.at+REPORT_SANTE_MAX) return false;
    if(client&&st.painMax!=null&&_pireDouleur(client)>st.painMax) return false;
  }
  return true;
}
// Report d'un athlète pour un type donné. Extrait de dismissTodoRow pour que
// la ligne par athlète et la ligne groupée écrivent exactement la même chose.
function reporterAlerte(type,c,jours){
  if(!currentUser.alertStatus) currentUser.alertStatus={};
  const lt=(c.bilans||[]).reduce((m,b)=>Math.max(m,b.date),0);
  // `jours` est FACULTATIF : sans lui, les sept jours d avant. Les appels
  // existants ne changent donc pas d un iota, et il n existe toujours qu un
  // seul mecanisme de mise en veille.
  const _j=(Number(jours)>0)?Number(jours):7;
  const st={s:'ignoré',until:Date.now()+_j*864e5,at:Date.now(),
    seenUpTo:type==='bilan'?lt:0};
  if(ALERTES_SANTE.includes(type)){
    // Niveau de douleur au moment du report : sans cette référence,
    // « passer de 4 à 6 » n'est pas détectable.
    st.painMax=_pireDouleur(c);
    if(!currentUser.journalDouleur) currentUser.journalDouleur=[];
    currentUser.journalDouleur.push({at:Date.now(),type,clientId:c.id,painMax:st.painMax});
    // Journal borné : c'est une trace, pas un historique complet.
    if(currentUser.journalDouleur.length>200)
      currentUser.journalDouleur=currentUser.journalDouleur.slice(-200);
  }
  currentUser.alertStatus[type+'-'+c.id]=st;
}
function dismissTodoRow(idx){
  const r=window._todoRows&&window._todoRows[idx];if(!r) return;
  // L'ECRITURE N'EST PAS RETARDEE PAR L'ANIMATION : elle est groupee avec le
  // re-rendu, qui l'etait deja. pointer-events coupes TOUT DE SUITE — le report
  // est deja decide, un second appui pendant les 180 ms ne doit rien atteindre.
  // A huit lignes a reporter le dimanche soir, le coach visait une cible qui
  // avait bouge entre deux appuis.
  const fin=()=>{
    r.list.forEach(c=>reporterAlerte(r.type,c));
    saveUser();
    renderTodoBlock(getClients());
  };
  const n=arcDernierElement('.rc-ligne');
  if(!n||arcReduit()||!n.animate) return fin();
  n.style.pointerEvents='none';
  const a=n.animate([{opacity:1,transform:'translateX(0)'},{opacity:0,transform:'translateX(-16px)'}],
    {duration:180,easing:ARC.charge,fill:'forwards'});
  if(!a) return fin();
  let fait=false;
  const une=()=>{ if(fait) return; fait=true; fin(); };
  a.addEventListener('finish',une);
  a.addEventListener('cancel',une);
  setTimeout(une,260);             // le filet : le rappel porte l'ecriture
}

// ══════════════ SIGNAUX D'ENTRAÎNEMENT ══════════════
// Le tableau de bord triait sur six signaux dont AUCUN ne parlait
// d'entraînement : bilan en retard, accès qui expire, inscrit qui n'a jamais
// commencé. La douleur par série était collectée depuis toujours, colorait la
// ligne pendant la séance, et ne remontait nulle part.
//
// Ces signaux DÉCRIVENT, ils ne décident pas : aucune modification de
// programme, aucune charge réduite, aucun exercice retiré automatiquement.
// Retirer un exercice sur la foi d'un chiffre de 1 à 6 serait une décision de
// coaching prise par un algorithme.
const SIG_PAIN_SEUIL=4;
const SIG_SEANCES=3;              // fenêtre « les trois dernières séances »
const SIG_DOULEUR_MIN_SEANCES=2;  // la sécurité n'attend pas un échantillon
const SIG_DIFFUS_JOURS=14;
const SIG_DIFFUS_MIN=5;
const SIG_DECROCHAGE=0.70;
const SIG_FORME_ECART=1.5;
const SIG_MEV_SEMAINES_CANDIDAT=4;// recul servant à savoir si le muscle est travaillé
const SIG_DOULEUR_JOURS=30;       // bloc « douleur » de la fiche client

// Disclaimer unique, réutilisé partout où une douleur est affichée — coach
// comme athlète. Une seule constante : impossible d'ajouter un affichage de
// douleur en oubliant l'avertissement, il suffit de le concaténer.
const DISCLAIMER_DOULEUR='L\'échelle de douleur est déclarative. Elle n\'est ni un diagnostic ni un avis médical. Une douleur qui persiste ou qui s\'aggrave doit être évaluée par un professionnel de santé.';
function blocDisclaimerDouleur(){
  return `<div style="font-size:var(--fs-2xs);color:var(--text-faint);line-height:1.6;margin-top:8px">${DISCLAIMER_DOULEUR}</div>`;
}

// Muscles en plateau. Extrait de renderPlateauxCoach pour être partagé avec
// signauxEntrainement : la logique contient un piège qu'il ne faut pas
// réécrire deux fois. Le verdict est construit à partir de la liste DÉJÀ
// calculée par _listeEtats, et non par un appel à etatMuscle : celui-ci exige
// un créneau, et _memeCreneau rejette TOUTES les séances quand slot et
// progName sont nuls. Chaque exercice porte déjà le créneau où il a été vu.
function musclesEnPlateau(c){
  const parMuscle={};
  for(const x of _listeEtats(c)){
    if(x.etat==='insuffisant') continue;
    const cls=resoudreMusclesLecture(x.nom,{name:x.nom},c);
    if(!cls||cls===VOL_CARDIO) continue;
    for(const m of (cls.p||[])) (parMuscle[m]=parMuscle[m]||[]).push(x);
  }
  const out=[];
  for(const m in parMuscle){
    const ex=parMuscle[m];
    if(ex.filter(e=>e.etat==='plateau'||e.etat==='regression').length>=2) out.push({m,exercices:ex});
  }
  return out;
}

// Séries à douleur déclarée d'une séance. La série n'a pas besoin d'être
// validée : une douleur saisie est une douleur saisie, et l'ignorer parce que
// la case « fait » est restée vide irait dans le mauvais sens.
function _seriesDouloureuses(sess){
  const out=[];
  if(!sess||!sess.data) return out;
  for(const nom of Object.keys(sess.data)){
    const d=sess.data[nom];
    for(const s of ((d&&d.sets)||[])){
      const p=parseInt(s&&s.pain,10);
      if(isFinite(p)&&p>=SIG_PAIN_SEUIL) out.push({nom,pain:p});
    }
  }
  return out;
}
// Clés des n dernières semaines ISO RÉVOLUES. La semaine en cours est exclue :
// le lundi matin elle est vide, et tout le monde serait sous son MEV.
function _semainesRevolues(n){
  const out=[], lundi=_lundiDe(new Date());
  for(let i=1;i<=n;i++){
    const d=new Date(lundi); d.setDate(d.getDate()-7*i);
    out.push(semaineISO(d));
  }
  return out;
}
// Douleur des trente derniers jours, par exercice. Sert au bloc de la fiche
// client et au détail des alertes.
function douleurParExercice(c,jours){
  const limite=Date.now()-(jours||SIG_DOULEUR_JOURS)*864e5;
  const parEx={};
  for(const sess of ((c&&c.sessions)||[])){
    if(!sess||!(sess.date>=limite)) continue;
    for(const x of _seriesDouloureuses(sess)){
      const e=parEx[x.nom]=parEx[x.nom]||{nom:x.nom,n:0,painMax:0,derniere:0};
      e.n++; e.painMax=Math.max(e.painMax,x.pain);
      e.derniere=Math.max(e.derniere,sess.date);
    }
  }
  return Object.values(parEx).sort((a,b)=>b.n-a.n||b.derniere-a.derniere);
}

// ══════════ VISIBILITÉ COACH : DES DÉFAUTS EXPLICITES, PAS DEVINÉS ══════════
// Quatre blocs sont visibles du coach par défaut parce qu'il en a besoin pour
// décider : le cycle règle des repères nutritionnels, les états déclarés font
// ajuster les lipides et poser la question du bilan, le traitement change la
// lecture d'une prise de poids, le statut hormonal décale la fourchette.
//
// Quatre ne le sont PAS, et le défaut compte plus que le réglage : personne
// ne va chercher un interrupteur qu'il ignore. Grossesse et PES relèvent de
// l'intime avant de relever du coaching ; constantes et analyses sont des
// données médicales brutes que RepCore conserve sans les interpréter.
//
// MODIFIABLE PAR L'ATHLÈTE SEULEMENT. Aucune fonction d'écriture n'est
// exposée côté coach, et un test le vérifie.
const SANTE_BLOCS=Object.freeze(['cycle','etats','traitement','statutHormonal',
  'grossesse','pes','constantes','analyses']);
const SANTE_VISIBLE_DEFAUT=Object.freeze({
  cycle:true, etats:true, traitement:true, statutHormonal:true,
  grossesse:false, pes:false, constantes:false, analyses:false
});
// PURE. Rend le défaut du bloc quand l'athlète n'a rien réglé, et false pour
// un bloc inconnu : un nom mal orthographié ne doit pas ouvrir une visibilité.
function santeVisibleCoach(user,bloc){
  if(SANTE_BLOCS.indexOf(bloc)<0) return false;
  const v=(((user||{}).sante)||{}).visibleCoach;
  if(v&&typeof v[bloc]==='boolean') return v[bloc];
  // Repli sur les interrupteurs déjà livrés, à leur emplacement historique.
  // Aucune écriture, aucune migration : on LIT là où la donnée se trouve.
  const u=user||{};
  if(bloc==='grossesse'&&typeof u.grossessePartagee==='boolean') return u.grossessePartagee;
  if(bloc==='pes'&&typeof u.pesPartagee==='boolean') return u.pesPartagee;
  if(bloc==='cycle'&&u.cycle&&typeof u.cycle.contraceptionPartagee==='boolean')
    return u.cycle.contraceptionPartagee;
  return SANTE_VISIBLE_DEFAUT[bloc];
}
// Les blocs masqués, et OÙ ils vivent dans le dossier. C'est la seule table
// qui fasse le lien entre un nom de bloc et un champ : la garder unique évite
// qu'un envoi et un effacement divergent un jour.
const SANTE_CHAMPS=Object.freeze({
  grossesse:['grossesse'],
  pes:['pes'],
  constantes:['constantes'],
  analyses:['analyses']
});
// PURE. Ce qui doit partir vers sante_privee pour ce dossier.
// ══════ MIGRATION DES RELEVÉS VERS sante_privee ══════
// constantes et analyses étaient retirées avant envoi, faute de nœud où les
// mettre : elles ne survivaient pas à un changement d'appareil, et un
// localStorage purgé les emportait. Le nœud existe désormais ; ce lot les y
// écrit et les relit.
//
// LE SCHÉMA DES RÈGLES ÉTAIT FAUX et rejetait tout : elles déclaraient
// {valeur, valeur2, unite} là où le client émet {sys, dia, pouls}. Firebase
// refuse le PUT ENTIER sur un champ hors liste blanche, sans un mot. Ce sont
// les règles qui ont été alignées sur le client.
//
// UNION PAR DATE, jamais écrasement. Deux appareils qui relèvent chacun une
// tension le même jour doivent garder les deux ; c'est la date ISO complète
// qui dédoublonne, à la milliseconde.
function _unionParDate(a,b){
  const out=[];
  const vus=new Set();
  for(const l of [Array.isArray(a)?a:[],Array.isArray(b)?b:[]]){
    for(const e of l){
      if(!e||typeof e!=='object'||!e.date) continue;
      // La clé porte TOUT le contenu, pas seulement la date : deux relevés
      // différents au même horodatage — une tension et un pouls saisis
      // ensemble — ne doivent pas s'annuler.
      const k=JSON.stringify(e);
      if(vus.has(k)) continue;
      vus.add(k);
      out.push(e);
    }
  }
  return out.sort((x,y)=>x.date<y.date?-1:(x.date>y.date?1:0));
}
// IDEMPOTENTE : deux exécutions produisent le même état. Le drapeau `migre`
// n'est pas une garde d'exécution — c'est un horodatage. La garde, c'est
// l'union elle-même : rejouer ne crée aucun doublon.
//
// AUCUNE DONNÉE LOCALE N'EST SUPPRIMÉE. localStorage reste un cache, jamais
// une source unique. Si l'écriture distante échoue, le local est intact et
// la migration se rejoue au prochain démarrage.
async function _migrerSantePriveeLocale(){
  try{
    const u=currentUser;
    if(!u||!u.email||u.role==='coach') return null;
    if(!CLOUD.ok||!CLOUD.ok()) return null;
    const dist=await CLOUD.pullSantePrivee(u.email);
    const cst=_unionParDate(u.constantes,dist&&dist.constantes);
    const ana=_unionParDate(u.analyses,dist&&dist.analyses);
    // Rien des deux côtés : pas d'écriture à vide, qui écraserait le nœud.
    if(!cst.length&&!ana.length) return null;
    // Le LOCAL est enrichi le premier : même si l'envoi échoue, l'athlète
    // récupère ce que l'autre appareil avait déjà écrit.
    if(cst.length) u.constantes=cst;
    if(ana.length) u.analyses=ana;
    try{ saveUser(); }catch(e){}
    // L'envoi passe par le chemin NORMAL : santeBlocsPrives collecte les
    // deux séries, _doPushOne les écrit dans sante_privee. Un second chemin
    // d'écriture divergerait un jour de celui-ci.
    await CLOUD.pushOne(u.email,u);
    return {constantes:cst.length,analyses:ana.length};
  }catch(e){ console.warn('[RepCore] migration santé privée :',e); return null; }
}
// ══════════ EXPORT INTÉGRAL — ARTICLES 15 ET 20 ══════════
// Un export incomplet est PIRE qu'une absence d'export : il donne l'illusion
// d'avoir répondu. Tout ce qui n'est pas exportable est donc NOMMÉ dans le
// manifeste, avec sa raison.
//
// LE PIÈGE CENTRAL : un export bâti sur le seul objet currentUser raterait
// constantes, analyses, grossesse et pes — ils vivent dans sante_privee,
// hors de users/. On lit les DEUX nœuds, explicitement.
//
// Et un fait mesuré, contraire à ce qu'on croit souvent ici : cycle,
// contraception, SOPK, thyroïde, traitements et statut hormonal vivent dans
// users/, PAS dans sante_privee — ils sont délibérément visibles du coach,
// qui ajuste des repères avec. L'export les prend donc par le premier nœud.
//
// _validateAthletePkg n'est PAS réutilisée : douze champs sur quatre-vingt-dix.
const EXPORT_AVERTISSEMENT='CE FICHIER CONTIENT DES DONNÉES DE SANTÉ EN CLAIR. '
  +'Il n\'est ni chiffré ni protégé par mot de passe. Ne le dépose pas sur un '
  +'service partagé et ne l\'envoie pas par un canal que tu ne maîtrises pas.';
// Catégories annoncées dans privacy.html qui ne PEUVENT pas figurer, et
// pourquoi. Les taire rendrait l'export silencieusement incomplet.
const EXPORT_NON_INCLUS=Object.freeze([
  Object.freeze({categorie:'Photos de plan alimentaire (diète stricte)',
    raison:'Stockées uniquement sur cet appareil (localStorage), jamais synchronisées : elles ne font partie d\'aucun dossier.'}),
  Object.freeze({categorie:'Fichiers vidéo d\'exécution',
    raison:'Hébergés chez Cloudinary. Seules les URL figurent dans « medias » ; les fichiers se demandent par écrit.'}),
  Object.freeze({categorie:'Fiche programme au format PDF',
    raison:'Hébergée chez Firebase Storage. Seule l\'URL figure dans « medias ».'}),
  Object.freeze({categorie:'Jeton d\'authentification',
    raison:'Secret technique de connexion. L\'exporter reviendrait à exporter un mot de passe.'}),
  Object.freeze({categorie:'Profil de ton coach',
    raison:'Données d\'un tiers. Un export ne contient jamais les données de quelqu\'un d\'autre.'}),
  // Une note ECRITE PAR le coach mais PORTANT SUR l athlete est la donnee
  // personnelle de l athlete (art. 15), pas celle d un tiers. La ranger sous
  // « profil de ton coach » rendrait ce manifeste faux — or il existe
  // exactement pour dire ce qui manque et pourquoi.
  Object.freeze({categorie:'Notes privées de ton coach à ton sujet',
    raison:'Elles sont enregistrées dans le dossier de ton coach, auquel RepCore ne te donne pas accès : '
      +'cet export ne peut pas les contenir. Elles te sont néanmoins communicables — demande-les-lui.'}),
  Object.freeze({categorie:'Compteurs techniques (quota, mesure de tunnel)',
    raison:'Agrégats anonymes sans lien avec ton compte : ils ne te concernent pas individuellement.'}),
  Object.freeze({categorie:'Brouillon de séance en cours',
    raison:'État transitoire de l\'écran, effacé à la fin de la séance.'})
]);
// Les URL de médias, sans les fichiers. Ta règle : aucun contenu embarqué.
function _exportMedias(u){
  const out=[];
  try{
    for(const v of (u.videos||[])) if(v&&v.url)
      out.push({type:'video',url:v.url,exercice:v.exercice||v.nom||'',date:v.date||null});
  }catch(e){}
  try{ if(u.programPdfUrl) out.push({type:'pdf',url:u.programPdfUrl,nom:u.programPdfName||''}); }catch(e){}
  try{
    for(const b of (u.bilans||[]))
      for(const k of Object.keys(b||{}))
        if(/photo/i.test(k)&&typeof b[k]==='string'&&/^https?:/.test(b[k]))
          out.push({type:'photo',url:b[k],date:b.date||null});
  }catch(e){}
  return out;
}
const EXPORT_MEDIAS_MARCHE='Ces fichiers ne sont pas inclus dans l\'export. '
  +'Les URL ci-dessus permettent de les télécharger tant qu\'ils existent. '
  +'Pour en obtenir une copie durable, écris à '+CREATOR_EMAIL+' en '
  +'mentionnant ton adresse de compte : la réponse est due sous un mois '
  +'(RGPD art. 12.3).';
// Charge les DEUX nœuds. Réseau d'abord, cache local en repli — et le
// manifeste DIT lequel a servi. Un export amputé qui ne se déclare pas
// amputé est un piège pour celui qui s'en sert.
//
// DISPONIBLE SUR UN COMPTE EXPIRÉ, IMPAYÉ, OU SANS COACH. Règle cardinale :
// le droit d'accès ne se suspend pas pour défaut de paiement.
async function _chargerExportComplet(user){
  const u=user||currentUser;
  if(!u||!u.email) return null;
  const src={profil:'local',sante_privee:'absent'};
  const notes=[];
  // 1. Le dossier. Le local fait foi s'il est plus complet : c'est lui que
  // l'utilisateur voit, et un export doit refléter ce qu'il a sous les yeux.
  let profil={...u};
  try{
    if(CLOUD.ok&&CLOUD.ok()){
      const dist=await CLOUD.pullUser(u.email);
      if(dist&&typeof dist==='object'){
        profil=Object.assign({},dist,u);   // le local prime, champ par champ
        src.profil='réseau + local';
      } else {
        notes.push('Le dossier distant n\'a pas pu être lu : cet export repose sur les données de cet appareil. Il peut manquer ce qui a été saisi ailleurs et pas encore redescendu.');
      }
    } else {
      notes.push('Hors ligne au moment de l\'export : seules les données de cet appareil y figurent.');
    }
  }catch(e){
    notes.push('Lecture du dossier distant en échec ('+(e&&e.message||'erreur')+') : export construit sur cet appareil.');
  }
  // Jamais dans un export : ce sont des secrets, pas des données personnelles.
  for(const k of ['pwd','pwdHash','_st','_stb64','_sk']) delete profil[k];
  // 2. Le nœud privé. SANS LUI, l'export raterait exactement l'article 9.
  let prive=null;
  try{
    if(CLOUD.ok&&CLOUD.ok()){
      prive=await CLOUD.pullSantePrivee(u.email);
      if(prive) src.sante_privee='réseau';
    }
  }catch(e){
    notes.push('Lecture du nœud de santé privée en échec : les relevés locaux sont utilisés à la place.');
  }
  // Repli local : santeBlocsPrives sait exactement ce qui y vit.
  const local=santeBlocsPrives(u);
  if(!prive&&Object.keys(local).length){ prive=local; src.sante_privee='local'; }
  else if(prive){
    // Union, jamais écrasement : un relevé local non encore monté doit sortir.
    for(const k of ['constantes','analyses'])
      if(local[k]) prive[k]=_unionParDate(prive[k],local[k]);
    for(const k of ['grossesse','pes'])
      if(prive[k]===undefined&&local[k]!==undefined) prive[k]=local[k];
  }
  return {profil:profil,prive:prive||{},sources:src,notes:notes};
}
// Le manifeste : ce qu'il y a, et surtout ce qu'il n'y a PAS.
function _manifesteExport(paquet){
  const pr=paquet.profil||{}, pv=paquet.prive||{};
  const presentes=[];
  const inspecter=(obj,noeud)=>{
    for(const k of Object.keys(obj||{})){
      const v=obj[k];
      if(v===undefined||v===null) continue;
      if(Array.isArray(v)&&!v.length) continue;
      presentes.push({cle:k,noeud:noeud,
        entrees:Array.isArray(v)?v.length:(typeof v==='object'?Object.keys(v).length:1)});
    }
  };
  inspecter(pr,'users');
  inspecter(pv,'sante_privee');
  return {
    genere_le:new Date().toISOString(),
    politique_acceptee:((pr.consent||{}).policyVersion)||null,
    politique_courante:POLICY_VERSION,
    sources:paquet.sources,
    avertissements:paquet.notes||[],
    categories_incluses:presentes,
    categories_non_incluses:EXPORT_NON_INCLUS.map(x=>({categorie:x.categorie,raison:x.raison})),
    a_savoir:'Cet export est un INSTANTANÉ. Il n\'est pas conçu pour être réimporté dans RepCore. '
      +'Les catégories non incluses ci-dessus sont listées pour que tu saches ce qui manque et pourquoi : '
      +'un export silencieusement incomplet ne vaudrait rien.'
  };
}
// ── CSV : trois séries, pour qui veut ouvrir un tableur ─────────────────
// Le JSON répond à l'article 20 — format structuré, lisible par machine. Le
// CSV répond à l'usage réel : ouvrir ses pesées dans un tableur sans savoir
// ce qu'est un JSON.
function _csvEchap(v){
  const t=(v===undefined||v===null)?'':String(v);
  // Point-virgule comme séparateur : Excel en français découpe là-dessus.
  return /[";\n\r]/.test(t)?'"'+t.replace(/"/g,'""')+'"':t;
}
function _csv(lignes){
  // BOM UTF-8 : sans lui, Excel affiche « SÃ©ance » au lieu de « Séance ».
  return '\ufeff'+lignes.map(l=>l.map(_csvEchap).join(';')).join('\r\n');
}
function _csvSeances(u){
  const l=[['date','seance','exercice','serie','charge_kg','repetitions','rir','douleur']];
  for(const s2 of ((u&&u.sessions)||[])){
    const d=s2&&s2.date?new Date(s2.date).toISOString():'';
    const nom=(s2&&s2.name)||'';
    const data=(s2&&s2.data)||{};
    for(const ex of Object.keys(data)){
      const sets=(data[ex]&&data[ex].sets)||[];
      sets.forEach((st,i)=>l.push([d,nom,ex,i+1,
        st&&st.weight,st&&st.reps,st&&st.rir,st&&st.pain]));
    }
  }
  return _csv(l);
}
function _csvJournalAlimentaire(u){
  const l=[['jour','repas','aliment','quantite','kcal','proteines_g','glucides_g','lipides_g','sel_g','fibres_g']];
  const log=(((u&&u.nutrition)||{}).log)||{};
  for(const jour of Object.keys(log).sort()){
    for(const e of ((log[jour]&&log[jour].entries)||[]))
      l.push([jour,e&&e.repas,e&&e.nom,e&&e.qte,e&&e.kcal,e&&e.p,e&&e.c,e&&e.l,e&&e.sel,e&&e.fibres]);
  }
  return _csv(l);
}
function _csvPesees(u){
  const l=[['date','poids_kg']];
  for(const e of ((u&&u.weightLog)||[])) if(e&&e.date) l.push([e.date,e.kg]);
  return _csv(l);
}
// Un téléchargement, et l'URL objet RÉVOQUÉE : sans révocation, le blob reste
// en mémoire jusqu'au rechargement de la page — et un export de dossier
// complet pèse.
function _telecharger(nom,contenu,type){
  try{
    const b=new Blob([contenu],{type:type||'application/json;charset=utf-8'});
    const url=URL.createObjectURL(b);
    const a=document.createElement('a');
    a.href=url; a.download=nom;
    document.body.appendChild(a); a.click(); a.remove();
    setTimeout(()=>{ try{ URL.revokeObjectURL(url); }catch(e){} },4000);
    return true;
  }catch(e){ console.error('[RepCore] export :',e); return false; }
}
function _nomFichierExport(ext){
  const d=new Date();
  const j=d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')
    +'-'+String(d.getDate()).padStart(2,'0');
  return 'repcore-mes-donnees-'+j+'.'+ext;
}
// L'export complet, disponible SANS CONDITION : compte expiré, impayé, coach
// parti. Le droit d'accès ne se suspend pas pour défaut de paiement, et rien
// ici ne consulte checkAccess ni le statut.
async function exporterMesDonnees(){
  const u=currentUser;
  if(!u||!u.email){ toast('Aucun dossier à exporter.','var(--orange)'); return false; }
  toast('Préparation de ton export…','var(--sub)');
  const paquet=await _chargerExportComplet(u);
  if(!paquet){ toast('Export impossible : dossier illisible.','var(--red)'); return false; }
  const doc={
    _avertissement:EXPORT_AVERTISSEMENT,
    manifeste:_manifesteExport(paquet),
    profil:paquet.profil,
    sante_privee:paquet.prive,
    medias:{fichiers:_exportMedias(paquet.profil),marche_a_suivre:EXPORT_MEDIAS_MARCHE}
  };
  _telecharger(_nomFichierExport('json'),JSON.stringify(doc,null,2));
  _telecharger('repcore-seances.csv',_csvSeances(paquet.profil),'text/csv;charset=utf-8');
  _telecharger('repcore-journal-alimentaire.csv',_csvJournalAlimentaire(paquet.profil),'text/csv;charset=utf-8');
  _telecharger('repcore-pesees.csv',_csvPesees(paquet.profil),'text/csv;charset=utf-8');
  // LA DATE SEULE. Ni le contenu, ni la taille, ni ce qui a été demandé.
  try{
    if(!u.rgpd||typeof u.rgpd!=='object') u.rgpd={};
    u.rgpd.dernierExport=Date.now();
    saveUser();
  }catch(e){}
  toast('Export téléchargé ✓','var(--green)');
  return true;
}
// Voir AVANT de télécharger : ce qui sort, et surtout ce qui ne sort pas.
async function voirContenuExport(cible){
  // Deux écrans l'appellent — celui du coach et celui de l'athlète — et un
  // même identifiant ne peut pas exister deux fois. La cible est passée.
  const z=document.getElementById(cible||'exp-manifeste');
  if(!z) return false;
  z.style.display='block';
  z.innerHTML='<div class="sub" style="font-size:var(--fs-sm)">Lecture…</div>';
  const paquet=await _chargerExportComplet(currentUser);
  if(!paquet){ z.innerHTML='<div class="sub" style="font-size:var(--fs-sm)">Dossier illisible.</div>'; return false; }
  const m=_manifesteExport(paquet);
  const lst=(t,items)=>`<div style="font-size:var(--fs-xs);color:var(--sub);letter-spacing:1.5px;text-transform:uppercase;font-weight:700;margin:10px 0 6px">${escapeHtml(t)}</div>`
    +items.map(x=>`<div style="font-size:var(--fs-xs);color:var(--text-strong);line-height:1.6;padding:2px 0">${x}</div>`).join('');
  z.innerHTML=lst('Inclus ('+m.categories_incluses.length+')',
      m.categories_incluses.map(c=>escapeHtml(c.cle)+' <span style="color:var(--text-faint)">· '+escapeHtml(c.noeud)+' · '+c.entrees+'</span>'))
    +lst('NON inclus ('+m.categories_non_incluses.length+')',
      m.categories_non_incluses.map(c=>'<b>'+escapeHtml(c.categorie)+'</b><br><span style="color:var(--text-faint)">'+escapeHtml(c.raison)+'</span>'))
    +(m.avertissements.length?lst('À savoir',m.avertissements.map(escapeHtml)):'')
    +`<div style="font-size:var(--fs-2xs);color:var(--text-faint);line-height:1.5;margin-top:10px">${escapeHtml(EXPORT_AVERTISSEMENT)}</div>`;
  return true;
}
function santeBlocsPrives(user){
  const out={};
  for(const bloc of Object.keys(SANTE_CHAMPS)){
    if(santeVisibleCoach(user,bloc)) continue;
    for(const champ of SANTE_CHAMPS[bloc]){
      const v=(user||{})[champ];
      if(v!==undefined&&v!==null) out[champ]=v;
    }
  }
  return out;
}
const _cacheSignaux=new Map();
function _viderCacheSignaux(){ _cacheSignaux.clear(); }
const SIGNAUX_VIDES=Object.freeze({douleur:false,douleurDiffuse:false,decrochage:false,chuteAssiduite:false,
  plateauMuscle:false,sousMEV:false,volumeHaut:false,formeBasse:false,
  restrictionLongue:false,calibrageDu:false,blocPrioriteFini:false,
  sautDeCharge:false,details:Object.freeze({})});

// opts.complet : ne PAS court-circuiter les signaux de rang 6 quand un rang
// superieur est deja acquis. Le classement n en a pas besoin — un 6 ne peut
// pas depasser un 9 deja obtenu — mais celui qui SCORE, si : sans cette
// option, un athlete douloureux ET en surcharge de volume pesait MOINS qu un
// athlete seulement en surcharge, l inverse de ce qu on mesure.
function signauxEntrainement(c,opts){
  const _complet=!!(opts&&opts.complet);
  // Invité non inscrit : aucun historique d'entraînement chez le coach, donc
  // aucun signal. Cohérent avec les exclusions déjà présentes d'urgencyScore.
  if(!c||c._fromCode) return SIGNAUX_VIDES;
  const ss=(c.sessions||[]).filter(s=>s&&s.date);
  const tri=ss.slice().sort((a,b)=>a.date-b.date);
  const der=tri.slice(-SIG_SEANCES);
  // La clé porte une empreinte du CONTENU douleur des trois dernières séances,
  // et pas seulement (identifiant, nombre, date). Sans elle, deux historiques
  // de même longueur et de même date finale partagent une entrée de cache —
  // et une douleur qui passe de 4 à 6 dans une séance corrigée ou resynchronisée
  // reste invisible. C'est exactement le cas que la règle d'aggravation doit
  // rattraper : le cache ne doit pas la masquer. Coût borné à trois séances.
  let emp='';
  for(const sess of der){
    const l=_seriesDouloureuses(sess);
    emp+=';'+(sess.id||sess.date)+':'+l.length+':'+l.reduce((m,x)=>Math.max(m,x.pain),0);
  }
  const _ph=c.phase&&c.phase.type?(c.phase.type+'@'+c.phase.debut):'';
  const _mk=(()=>{ const m=(c.nutrition||{}).macros;
    if(!m) return ''; return String((m.on&&m.on.kcal)||'')+'/'+String((m.off&&m.off.kcal)||''); })();
  const cle=c.id+'|'+ss.length+'|'+(ss.length?tri[tri.length-1].date:0)+'|'+emp+'|'+_ph+'|'+_mk+(_complet?'|C':'');
  if(_cacheSignaux.has(cle)) return _cacheSignaux.get(cle);
  const r={douleur:false,douleurDiffuse:false,decrochage:false,chuteAssiduite:false,
    plateauMuscle:false,sousMEV:false,volumeHaut:false,formeBasse:false,
    restrictionLongue:false,calibrageDu:false,blocPrioriteFini:false,
    sautDeCharge:false,details:{}};
  // La restriction prolongée ne dépend pas des séances : elle se calcule ICI,
  // avant le retour anticipé. Placée plus bas, un athlète en sèche longue qui
  // ne journalise aucune séance ne serait jamais remonté au coach.
  try{
    if(restrictionProlongee(c)){
      r.restrictionLongue=true;
      const _pl=plancherEffectif(c);
      const _m=(c.nutrition||{}).macros||{};
      const _bas=Math.min.apply(null,[_m.on,_m.off].filter(x=>x&&Number(x.kcal)>0).map(x=>Number(x.kcal)));
      r.details.restrictionLongue={semaines:semainesEcoulees(c),kcal:_bas,plancher:_pl.kcal};
    }
  }catch(e){}
  if(!ss.length){ _cacheSignaux.set(cle,r); return r; }

  // ── Douleur ciblée : même exercice, au moins deux séries ET deux séances ──
  if(tri.length>=SIG_DOULEUR_MIN_SEANCES){
    const parEx={};
    for(const sess of der){
      const vues=new Set();
      for(const x of _seriesDouloureuses(sess)){
        const e=parEx[x.nom]=parEx[x.nom]||{nom:x.nom,series:0,seances:0,painMax:0,dates:[]};
        e.series++; e.painMax=Math.max(e.painMax,x.pain);
        if(!vues.has(x.nom)){ vues.add(x.nom); e.seances++; e.dates.push(sess.date); }
      }
    }
    const touches=Object.values(parEx)
      .filter(e=>e.series>=2&&e.seances>=SIG_DOULEUR_MIN_SEANCES)
      .sort((a,b)=>b.painMax-a.painMax||b.seances-a.seances);
    if(touches.length){
      r.douleur=true;
      r.details.douleur=touches[0];
      r.details.douleurTous=touches;
    }
  }

  // ── Douleur diffuse : exercices confondus, sur quatorze jours ──
  const limite=Date.now()-SIG_DIFFUS_JOURS*864e5;
  let nDiffus=0, painMaxDiffus=0; const exDiffus=new Set();
  for(const sess of tri){
    if(!(sess.date>=limite)) continue;
    for(const x of _seriesDouloureuses(sess)){
      nDiffus++; exDiffus.add(x.nom); painMaxDiffus=Math.max(painMaxDiffus,x.pain);
    }
  }
  if(nDiffus>=SIG_DIFFUS_MIN){
    r.douleurDiffuse=true;
    r.details.douleurDiffuse={series:nDiffus,exercices:[...exDiffus],
      jours:SIG_DIFFUS_JOURS,painMax:painMaxDiffus};
  }

  // ── Décrochage d'exécution ──
  // Les séances antérieures au champ setsPlanned sont EXCLUES : un « 5 » sans
  // prévu ne dit pas s'il vaut 5 sur 5 ou 5 sur 12.
  if(tri.length>=SIG_SEANCES){
    const evaluables=der.filter(s=>Number(s.setsPlanned)>0);
    if(evaluables.length){
      let faits=0,prevus=0;
      for(const s of evaluables){ faits+=(parseInt(s.sets,10)||0); prevus+=Number(s.setsPlanned); }
      if(prevus>0&&(faits/prevus)<SIG_DECROCHAGE){
        r.decrochage=true;
        r.details.decrochage={faits,prevus,seances:evaluables.length,
          ratio:Math.round(faits/prevus*100)/100};
      }
    }
  }

  // ── Signaux de niveau 6 : jamais calculés si un niveau supérieur est acquis ──
  // Ce n'est pas une approximation. Un signal de niveau 6 ne peut pas dépasser
  // un 7, 8 ou 9 déjà obtenu : le classement est identique, et on épargne le
  // parcours complet de l'historique pour les athlètes déjà en tête.
  if(!_complet&&(r.douleur||r.douleurDiffuse||r.decrochage)){ _cacheSignaux.set(cle,r); return r; }

  // CHUTE D ASSIDUITE. Le taux de completion ne declenche AUCUNE notification :
  // il n alimente que ce signal-la, et seulement si la tendance perd plus de
  // TC_TENDANCE_CHUTE points. Un taux bas mais STABLE ne remonte rien - c est
  // une mesure, pas un jugement.
  try{
    const _tc=tauxCompletion(c,Date.now());
    if(_tc&&_tc.interpretable&&_tc.tendance!=null&&_tc.tendance<-TC_TENDANCE_CHUTE){
      r.chuteAssiduite=true;
      r.details.chuteAssiduite={taux:_tc.taux,tendance:_tc.tendance,fenetre:_tc.fenetre};
    }
  }catch(e){}
  // ── Habitudes sous le seuil ──
  // Un signal d'INTENDANCE, jamais de santé : il rejoint le niveau 6 et n'y
  // bouge plus. Sans habitude assignée, il ne se lève pas — l'absence n'est
  // pas un manquement.
  try{
    if(habSignalBas(c)){
      r.habitudesBasses=true;
      r.details.habitudesBasses={taux:habTauxGlobal(c,HAB_SIGNAL_JOURS),
        jours:HAB_SIGNAL_JOURS,seuil:HAB_SIGNAL_SEUIL};
    }
  }catch(e){}
  try{
    const mus=musclesEnPlateau(c);
    if(mus.length){
      r.plateauMuscle=true;
      const x=mus[0];
      r.details.plateauMuscle={muscle:x.m,
        lib:(MUSCLES[x.m]||{}).lib||x.m,
        bloques:x.exercices.filter(e=>e.etat==='plateau'||e.etat==='regression').length,
        semaines:Math.max(0,Math.floor(Math.max(...x.exercices.map(e=>e.joursDepuisRecord||0))/7))};
    }
  }catch(e){}

  // ── LE BLOC DE PRIORITE EST-IL ARRIVE A ECHEANCE ? ──
  // RIEN NE SE RECONDUIT TOUT SEUL. A l'echeance, le coach decide de
  // reconduire, d'inverser ou de revenir a plat — et pour decider il lui faut
  // le rapprochement avec les mensurations, qui ferme la boucle : le volume a
  // bouge, est-ce que le corps a suivi ?
  try{
    const _av=blocAvancement(c);
    if(_av&&_av.fini){
      const _b=blocPriorite(c);
      r.blocPrioriteFini=true;
      const _m=(_b&&_b.hauts.length)
        ? blocMesureBilan(c,_b.hauts[0],_b.debut,Date.now()) : null;
      r.details.blocPrioriteFini={semaines:_av.total,
        hauts:(_b&&_b.hauts)||[],mesure:_m};
    }
  }catch(e){}
  // ── LA CHARGE A-T-ELLE SAUTE ? ──
  // DEUX SEMAINES DE SUITE, PAS UNE. Une semaine chargee est un choix
  // d'entrainement ; deux d'affilee au-dessus de la moitie de la moyenne du
  // mois, c'est une derive que personne n'a decidee.
  try{
    const _sc=sautDeCharge(c);
    if(_sc){ r.sautDeCharge=true; r.details.sautDeCharge=_sc; }
  }catch(e){}
  // ── LE CALIBRAGE DU RIR EST-IL A REFAIRE ? ──
  // CE N'EST PAS UNE URGENCE, C'EST DE L'ENTRETIEN. Le signal n'entre pas dans
  // urgencyScore — deliberement : un calibrage perime ne remonte personne dans
  // la liste du coach, il ajoute seulement une ligne en bas de ses taches.
  // Trois mois, parce que la perception s'affine avec l'entrainement : un
  // repere pris au huitieme mois ne dit plus rien au vingtieme.
  try{ if(calibrageRirDu(c)){
    r.calibrageDu=true;
    const _cal=calibrageRirDe(c);
    r.details.calibrageDu={n:(_cal&&_cal.n)||0,maj:(_cal&&_cal.maj)||null,
      seances:ss.length,
      jours:(_cal&&_cal.maj)?Math.floor((Date.now()-_cal.maj)/864e5):null};
  } }catch(e){}
  try{
    const [s1,s2]=_semainesRevolues(2);
    const recentes=_semainesRevolues(SIG_MEV_SEMAINES_CANDIDAT);
    const v1=volumeSemaine(c,s1)||{}, v2=volumeSemaine(c,s2)||{};
    // Muscle CANDIDAT : travaillé au moins une fois sur les quatre dernières
    // semaines révolues. Sans ce filtre, un débutant qui ne fait que du haut
    // du corps serait signalé « sous MEV » sur douze muscles qu'il n'a jamais
    // eu l'intention de travailler.
    const candidats=new Set();
    for(const cle2 of recentes){
      const v=volumeSemaine(c,cle2)||{};
      for(const m in v) if(v[m]>0) candidats.add(m);
    }
    for(const m of candidats){
      const rep=reperesEffectifs(c,m);
      // Un muscle sans repere ne peut sortir d'aucune zone : ni sous le MEV,
      // ni au-dessus du MRV. LOMBAIRES, ABDUCTEURS et ADDUCTEURS sont dans ce
      // cas et ne leveront donc jamais ces deux signaux.
      if(!rep) continue;
      if(!r.sousMEV&&(v1[m]||0)<rep.mev&&(v2[m]||0)<rep.mev){
        r.sousMEV=true;
        r.details.sousMEV={muscle:m,lib:(MUSCLES[m]||{}).lib||m,
          mev:rep.mev,s1:v1[m]||0,s2:v2[m]||0,semaines:[s1,s2]};
      }
      // Symetrique du sous-MEV, sur le MEME patron : deux semaines revolues
      // consecutives au-dessus du repere haut. Une seule semaine ne suffit
      // pas — un pic isole est un choix d'entrainement, pas une derive.
      if(!r.volumeHaut&&(v1[m]||0)>rep.mrv&&(v2[m]||0)>rep.mrv){
        r.volumeHaut=true;
        r.details.volumeHaut={muscle:m,lib:(MUSCLES[m]||{}).lib||m,
          mrv:rep.mrv,s1:v1[m]||0,s2:v2[m]||0,semaines:[s1,s2]};
      }
      if(r.sousMEV&&r.volumeHaut) break;
    }
  }catch(e){}

  try{
    if(tri.length>=SIG_SEANCES){
      const moy=formeMoy3(c), base=baseForme(c);
      if(moy!=null&&base!=null&&moy<=base-SIG_FORME_ECART){
        r.formeBasse=true;
        r.details.formeBasse={moy:Math.round(moy*10)/10,base:Math.round(base*10)/10,
          ecart:Math.round((base-moy)*10)/10};
      }
    }
  }catch(e){}

  _cacheSignaux.set(cle,r);
  return r;
}

// ══════════════ FATIGUE ACCUMULÉE ══════════════
// PROPOSER une semaine de décharge, motivée par des chiffres. JAMAIS la
// déclencher : aucune écriture sur `deload` sans un geste explicite du coach.
//
// CE CALCUL NE MESURE RIEN DE NEUF, ET C'EST VOULU.
// Quatre des cinq signaux demandés existaient déjà, calculés, chiffrés et mis
// en cache dans signauxEntrainement : volumeHaut, plateauMuscle (qui porte
// aussi la régression), formeBasse, douleur et douleurDiffuse. Les recalculer
// avec des règles voisines mais différentes — « ≥ 1 primaire ou ≥ 2 muscles »
// contre « deux semaines révolues consécutives » — aurait produit deux verdicts
// divergents sur le même athlète. scoreFatigue LIT donc signauxEntrainement et
// se contente de pondérer. Un seul calcul, une seule vérité, et aucun seuil
// existant n'est touché.
//
// LA DOULEUR RÉUTILISE LE SEUIL DUR EXISTANT (série ≥ 4, sur ≥ 2 séries ET
// ≥ 2 séances, ou ≥ 6 séries diffuses sur quatorze jours). Une « moyenne ≥ 3 »
// aurait été un SECOND seuil de douleur, plus bas que celui que l'application
// défend partout ailleurs, et verrouillé par une assertion.
const FATIGUE_SEUIL=60;              // score à partir duquel on propose
const FATIGUE_SEMAINES_MIN=3;        // en dessous, aucun verdict
const FATIGUE_SOMMEIL_J=21;          // un refus met la détection en sommeil
const FATIGUE_REPORT_J=7;            // un report la décale d'une semaine
const FATIGUE_COUPURE_J=21;          // au-delà, les compteurs repartent de zéro
// Les poids, EXPOSÉS et non cachés : c'est ce qui permet au coach de discuter
// la proposition au lieu de la subir.
const FATIGUE_POIDS=Object.freeze({
  volumeHaut:35, regression:25, plateau:15, douleur:15, forme:10
});
// PURE. Le sous-dossier fatigue, quel que soit l'état du document. Un champ
// corrompu ne doit ni lever d'exception ni faire disparaître l'écran coach.
function fatigueDe(user){
  const f=user&&user.fatigue;
  if(!f||typeof f!=='object'||Array.isArray(f)) return null;
  const pa=(f.propositionActive&&typeof f.propositionActive==='object'
    &&!Array.isArray(f.propositionActive))?f.propositionActive:null;
  return {
    score:isFinite(Number(f.score))?Number(f.score):0,
    motifs:Array.isArray(f.motifs)?f.motifs.filter(m=>m&&typeof m==='object'):[],
    calculeLe:isFinite(Number(f.calculeLe))?Number(f.calculeLe):0,
    sommeilJusquA:isFinite(Number(f.sommeilJusquA))?Number(f.sommeilJusquA):0,
    suspendue:f.suspendue===true,
    propositionActive:(pa&&pa.statut==='ouverte')?pa:null
  };
}
// PURE. La détection est SUSPENDUE sans jamais dire pourquoi.
//
// L'athlète décide si son coach voit sa grossesse : _sanitizeForCoach efface
// le champ quand elle ne l'a pas partagé. Une carte qui annoncerait « détection
// suspendue pour raison de santé » la révélerait donc à celui à qui elle a
// choisi de ne rien dire. Le drapeau `suspendue` est écrit CÔTÉ ATHLÈTE, au
// moment où elle déclare ou révoque — un point de sauvegarde qui existe déjà,
// donc pas une écriture de plus — et il ne porte AUCUN motif.
function fatigueSuspendue(c){
  if(!c) return true;
  const f=fatigueDe(c);
  if(f&&f.suspendue) return true;
  try{ if(grossesseSuspend(c)) return true; }catch(e){}
  try{ if(drapeauQuelconqueActif(c)) return true; }catch(e){}
  return false;
}
// Écrit le drapeau neutre. Appelée aux transitions de grossesse, jamais en
// boucle : elle ne provoque aucune sauvegarde à elle seule.
function majSuspensionFatigue(user){
  const u=_dossier(user);
  if(!u) return false;
  let susp=false;
  try{ susp=grossesseSuspend(u); }catch(e){}
  if(!u.fatigue||typeof u.fatigue!=='object'||Array.isArray(u.fatigue)) u.fatigue={};
  if(susp) u.fatigue.suspendue=true; else delete u.fatigue.suspendue;
  // Une détection suspendue ne laisse pas une proposition ouverte derrière
  // elle : elle serait appliquée sans que rien ne la recalcule.
  if(susp) delete u.fatigue.propositionActive;
  return susp;
}
// PURE. Le nombre de semaines révolues CONSÉCUTIVES portant au moins une
// séance, en partant de la plus récente. Sert de garde d'exploitabilité.
function _semainesFatigue(user,dateRef){
  const ss=((user&&user.sessions)||[]).filter(x=>x&&x.date);
  if(!ss.length) return 0;
  const ref=(dateRef instanceof Date)?dateRef.getTime():Number(dateRef||Date.now());
  // Reprise après une coupure longue : les compteurs repartent de zéro. Ce
  // n'est pas de la fatigue accumulée, c'est un retour.
  const derniere=ss.reduce((m,x)=>Math.max(m,x.date),0);
  if(ref-derniere>=FATIGUE_COUPURE_J*864e5) return 0;
  const lundi=_lundiDe(new Date(ref)).getTime();
  let n=0;
  for(let i=1;i<=FATIGUE_SEMAINES_MIN+9;i++){
    // EN CALENDRIER : une borne de semaine posee en millisecondes derive d'une
    // heure au changement d'horaire, et une seance du dimanche soir bascule
    // alors dans la semaine voisine — ici, elle romprait la serie et ferait
    // sous-estimer l'anciennete de la charge.
    const d=_datePlusJours(lundi,-i*7).getTime(), f=_datePlusJours(lundi,-(i-1)*7).getTime();
    if(ss.some(x=>x.date>=d&&x.date<f)) n++; else break;
  }
  return n;
}
// PURE, AUCUNE ÉCRITURE. Rend {score, motifs, exploitable}.
//
// Chaque motif porte sa valeur ET son unité : une proposition sans motif chiffré
// serait une injonction, et l'application n'en produit pas.
function scoreFatigue(user,dateRef){
  const vide={score:0,motifs:[],exploitable:false};
  if(!user) return vide;
  const semaines=_semainesFatigue(user,dateRef);
  if(semaines<FATIGUE_SEMAINES_MIN) return vide;
  let sg=null;
  try{ sg=signauxEntrainement(user,{complet:true}); }catch(e){ return vide; }
  if(!sg) return vide;
  const d=sg.details||{};
  const motifs=[]; let score=0;
  const pousser=(code,libelle,valeur,unite,poids)=>{
    motifs.push({code,libelle,valeur,unite}); score+=poids; };
  if(sg.volumeHaut&&d.volumeHaut){
    pousser('volume','Volume au-dessus du MRV sur '+(d.volumeHaut.lib||d.volumeHaut.muscle),
      Math.round((d.volumeHaut.s1||0)*10)/10,'séries pondérées (MRV '+d.volumeHaut.mrv+')',
      FATIGUE_POIDS.volumeHaut);
  }
  // Plateau et régression viennent du MÊME calcul par muscle : on les sépare
  // parce qu'un recul ne se lit pas comme une stagnation.
  // _listeEtats est le parcours DEJA partage entre l ecran de plateaux et
  // signauxEntrainement : meme detecteur, memes seuils, meme cache. On le lit
  // au niveau de l EXERCICE et non de l agregat musculaire de musclesEnPlateau,
  // qui exige deux primaires en plateau sur un meme muscle — un critere de
  // remontee au coach, trop strict pour peser une fatigue.
  let recul=0, stagne=0, nomRecul=null, nomStagne=null;
  try{
    for(const x of _listeEtats(user)){
      if(x.etat==='regression'){ recul++; if(!nomRecul) nomRecul=x.nom; }
      else if(x.etat==='plateau'){ stagne++; if(!nomStagne) nomStagne=x.nom; }
    }
  }catch(e){}
  if(recul){
    pousser('regression','Recul sur '+String(nomRecul||'').toLowerCase(),
      recul,recul>1?'exercices':'exercice',FATIGUE_POIDS.regression);
  }
  if(stagne){
    pousser('plateau','Plateau sur '+String(nomStagne||'').toLowerCase(),
      stagne,stagne>1?'exercices':'exercice',FATIGUE_POIDS.plateau);
  }
  if(sg.douleur&&d.douleur){
    pousser('douleur','Douleur répétée sur '+String(d.douleur.nom||'').toLowerCase(),
      d.douleur.series,'séries douloureuses',FATIGUE_POIDS.douleur);
  }else if(sg.douleurDiffuse&&d.douleurDiffuse){
    pousser('douleur','Douleur diffuse sur '+d.douleurDiffuse.jours+' jours',
      d.douleurDiffuse.series,'séries douloureuses',FATIGUE_POIDS.douleur);
  }
  if(sg.formeBasse&&d.formeBasse){
    pousser('forme','Indice de forme sous sa base habituelle',
      d.formeBasse.ecart,'points sous '+d.formeBasse.base,FATIGUE_POIDS.forme);
  }
  return {score,motifs,exploitable:true,semaines};
}
// PURE. La semaine visée : l'index dans le bloc quand F-31 en fournit un, la
// clé ISO sinon. Les deux voyagent, la carte se sert de ce qu'elle a.
function _semaineFatigue(user,dateRef){
  const dt=(dateRef instanceof Date)?dateRef:new Date(Number(dateRef||Date.now()));
  let idx=null;
  try{ idx=indexSemaineBloc(user,dt); }catch(e){}
  return {cle:semaineISO(dt),index:(typeof idx==='number')?idx:null};
}
// La décharge DÉJÀ planifiée qui suit la semaine visée, s'il y en a une : la
// carte propose alors de l'AVANCER au lieu d'en ajouter une seconde.
function dechargePlanifieeApres(user,index){
  if(typeof index!=='number') return null;
  let pr=null;
  try{ pr=programmeDe(user); }catch(e){}
  if(!pr) return null;
  const suivantes=pr.decharges.filter(x=>x>index);
  return suivantes.length?suivantes[0]:null;
}
// Évalue et ÉCRIT la proposition dans le dossier — mais jamais sur `deload`.
// Rend la proposition ouverte, ou null. Une seule à la fois par athlète.
function evaluerPropositionDecharge(user,dateRef){
  const u=_dossier(user);
  if(!u) return null;
  if(fatigueSuspendue(u)) return null;
  const now=(dateRef instanceof Date)?dateRef.getTime():Number(dateRef||Date.now());
  const f=fatigueDe(u);
  if(f&&f.sommeilJusquA>now) return null;
  if(f&&f.propositionActive) return f.propositionActive;
  const r=scoreFatigue(u,now);
  if(!r.exploitable||r.score<FATIGUE_SEUIL) return null;
  // Règle 3, tenue par le code et pas seulement par le commentaire : une
  // proposition sans motif chiffré ne sort pas d'ici.
  if(!r.motifs.length) return null;
  if(!u.fatigue||typeof u.fatigue!=='object'||Array.isArray(u.fatigue)) u.fatigue={};
  const sem=_semaineFatigue(u,now);
  u.fatigue.score=r.score;
  u.fatigue.motifs=r.motifs;
  u.fatigue.calculeLe=now;
  u.fatigue.propositionActive={semaineProposee:sem.cle,semaineIndex:sem.index,
    creeLe:now,statut:'ouverte'};
  return u.fatigue.propositionActive;
}
// Lecture SANS calcul : c'est elle que le tri des athlètes appelle, sur des
// dizaines de dossiers. Recalculer un score à chaque rendu de liste coûterait
// cinq millisecondes par athlète pour une information déjà écrite.
function propositionDechargeOuverte(c){
  const f=fatigueDe(c);
  return (f&&f.propositionActive)?f.propositionActive:null;
}
function _fermerProposition(u){ if(u&&u.fatigue) delete u.fatigue.propositionActive; }
// Un refus met la détection en sommeil vingt-et-un jours POUR CET ATHLÈTE.
function refuserDecharge(user){
  const u=_dossier(user);
  if(!u||!propositionDechargeOuverte(u)) return false;
  if(!u.fatigue) u.fatigue={};
  u.fatigue.sommeilJusquA=Date.now()+FATIGUE_SOMMEIL_J*864e5;
  _fermerProposition(u);
  return true;
}
// Un report la décale d'une semaine, sans l'enterrer.
function reporterDecharge(user){
  const u=_dossier(user);
  if(!u||!propositionDechargeOuverte(u)) return false;
  if(!u.fatigue) u.fatigue={};
  u.fatigue.sommeilJusquA=Date.now()+FATIGUE_REPORT_J*864e5;
  _fermerProposition(u);
  return true;
}
// APPLIQUE. Le seul point du lot qui touche à la décharge, et il n'est atteint
// que par un clic du coach.
//
// Deux représentations de la décharge cohabitent : le booléen `deload` des
// créneaux, sans date, et `programme.decharges`, des index de semaines. Quand
// un bloc existe, on écrit dans le BLOC — et si une décharge était déjà prévue
// plus loin, on l'AVANCE au lieu d'en ajouter une seconde. Sans bloc, on
// retombe sur le geste existant : `deload` sur les créneaux actifs, les
// inactifs intacts.
// B3.3 — L'ALLEGEMENT PAR DEFAUT D'UNE SEMAINE DE DECHARGE. Nommes, pour
// qu'on puisse en discuter : ce sont des reglages de coaching, pas des
// constantes techniques.
const DECHARGE_FACTEUR_SERIES=0.6;   // 60 % du volume du gabarit
const DECHARGE_RIR_PLUS=1;           // une repetition de plus en reserve
function appliquerDecharge(user,semaine){
  const u=_dossier(user);
  if(!u) return false;
  const idx=(typeof semaine==='number')?semaine:null;
  let pr=null;
  try{ pr=programmeDe(u); }catch(e){}
  let fait=false;
  if(pr&&idx!==null&&idx>=0&&idx<pr.semaines){
    const avancee=dechargePlanifieeApres(u,idx);
    const l=pr.decharges.filter(x=>x!==avancee);
    if(l.indexOf(idx)<0) l.push(idx);
    u.programme.decharges=l.sort((a,b)=>a-b);
    // B3.3 — ET LA SEMAINE PRESCRIT REELLEMENT MOINS.
    //
    // Cette branche se contentait d'ajouter l'index dans programme.decharges.
    // Faute d'ecart, la semaine marquee « dech. » prescrivait EXACTEMENT le
    // meme travail que les autres : _volumePrevisionnel lit les creneaux,
    // c'est-a-dire le gabarit. La decharge n'etait qu'un bandeau chez
    // l'athlete et une exclusion de la detection de plateau. Un coach qui
    // planifiait une decharge en S5 croyait avoir allege la semaine ; il ne
    // l'avait pas fait.
    //
    // MOINS DE SERIES ET PLUS DE RIR, les deux ensemble : une decharge qui ne
    // toucherait qu'au volume laisserait l'athlete pousser jusqu'a l'echec sur
    // ce qui reste, et ce n'est pas une decharge.
    //
    // 60 % DES SERIES ET +1 DE RIR : c'est l'allegement le plus courant en
    // periodisation, et il est ECRIT — donc visible dans la grille, et
    // modifiable comme n'importe quel autre ecart. Un allegement silencieux
    // dont le coach ignorerait l'existence serait pire que pas d'allegement.
    try{ poserEcartSemaine(u,idx,{facteurSeries:DECHARGE_FACTEUR_SERIES,
                                  rir:DECHARGE_RIR_PLUS,_decharge:true}); }catch(e){}
    fait=true;
  }else{
    const cfg=Array.isArray(u.sessions_config)?u.sessions_config:[];
    const actifs=cfg.filter(x=>x&&x.active);
    if(!actifs.length) return false;
    actifs.forEach(x=>{ x.deload=true; });
    fait=true;
  }
  if(!fait) return false;
  _fermerProposition(u);
  // Les caches portent des verdicts que la décharge change : une séance de
  // décharge sort de la détection de plateau.
  try{ _viderCachePlateau(); _viderCacheVolume(); _cacheSignaux.clear(); }catch(e){}
  return true;
}
// ══════════════ LA STRUCTURE DU BLOC, COTE ATHLETE ═════════════════════
//
// Le coach lit « 8 semaines, du 1er au 26 · Decharges : S3, S6 · semaine 3 en
// cours ». L'athlete, lui, ne voyait rien : il traversait une semaine dure
// sans savoir combien il en restait ni quand ca s'allegerait. Une semaine
// dure qu'on sait etre l'avant-derniere se traverse ; la meme, sans horizon,
// se negocie.
//
// UNE SEULE SOURCE : le programme date. Il porte le nombre de semaines ET les
// decharges — le bloc de priorite, lui, n'a que des semaines, et melanger les
// deux ferait une phrase dont les deux moities ne parleraient pas de la meme
// chose.
//
// ⚠ LA DECHARGE ANNONCEE EST LA PROCHAINE, PAS LA PREMIERE. dechargePlanifiee-
// Apres existe deja pour cela : sans elle, un athlete en semaine 5 d'un bloc
// dont la decharge de S3 est passee se serait vu annoncer « decharge en
// semaine 3 » — une consigne dans le passe.
//
// PURE. Rend '' quand il n'y a rien a dire : pas de programme, ou une date
// hors bloc. Une absence de structure n'est pas une structure a annoncer.
function ligneStructureBloc(user,maintenant){
  const u=_dossier(user);
  let p=null;
  try{ p=programmeDe(u); }catch(e){ p=null; }
  if(!p) return '';
  const d=(maintenant instanceof Date)?maintenant:new Date(Number(maintenant)||Date.now());
  let i=null;
  try{ i=indexSemaineBloc(u,d); }catch(e){ i=null; }
  if(i===null) return '';
  const base='Semaine '+(i+1)+' sur '+p.semaines;
  // CETTE SEMAINE EST LA DECHARGE : on le dit, et on ne renvoie pas vers une
  // autre. C'est l'information la plus utile du jour.
  if(p.decharges.indexOf(i)>=0) return base+' · c’est ta semaine de décharge.';
  let suivante=null;
  try{ suivante=dechargePlanifieeApres(u,i); }catch(e){ suivante=null; }
  if(suivante===null) return base+'.';
  return base+' · décharge en semaine '+(suivante+1)+'.';
}
// LE PONT. Une semaine planifiée en décharge dans le bloc ne posait `deload`
// sur AUCUNE séance : le bandeau ne s'allumait pas, et les séances de cette
// semaine continuaient d'entrer dans la détection de plateau — alors qu'une
// décharge cochée à la main, elle, en sortait. Deux décharges, deux
// comportements. PURE, aucune écriture.
function semaineEstDecharge(user,date){
  try{
    const w=getSemaineEffective(user,date||new Date());
    return !!(w&&w.decharge);
  }catch(e){ return false; }
}

// ── Dépistage par profil : des QUESTIONS au coach, rien d'autre ────────────
// Toutes les règles reposent sur des données DÉJÀ déclarées : aucune question
// nouvelle à l'athlète, aucune case à cocher de plus. Si une donnée manque, la
// règle ne se déclenche pas — on ne déduit rien.
//
// Ce bloc ne nomme aucune carence, ne propose aucun complément, ne pose aucun
// diagnostic. Il produit un constat chiffré puis une question à poser. Il
// n'entre PAS dans urgencyScore et ne déclenche aucune notification : ce n'est
// pas une alerte, c'est une aide à la conversation.
const MICRO_SECHE_SEMAINES=8;      // fer : ancienneté de sèche requise
const MICRO_SOMMEIL_SEUIL=6;       // magnésium : moyenne en heures
const MICRO_SOMMEIL_JOURS=14;      // fenêtre d'observation
// Une moyenne sur deux nuits n'est pas une moyenne sur quinze jours. En dessous
// de la moitié de la fenêtre, la donnée manque et la règle se tait.
const MICRO_SOMMEIL_MIN_NUITS=7;
// Novembre à mars inclus, en indices JavaScript (0 = janvier).
const MICRO_MOIS_PEU_SOLEIL=Object.freeze([10,11,0,1,2]);
const MICRO_MOTS_VEGE=Object.freeze(['vegetarien','vegetarienne','vegetalien',
  'vegetalienne','vegan','vegane','vegetalisme','vegetarisme']);
// Les trois champs libres du bilan de départ où ce genre de précision se tape
// en pratique. On ne fouille pas tout le dossier : ailleurs, le mot voudrait
// dire autre chose.
const MICRO_CHAMPS_VEGE=Object.freeze(['deb-allergies','deb-food-hate','deb-health','deb-food-love']);
// ══════════════ COUVERTURE EN MICRONUTRIMENTS ══════════════
// On CONSTATE une couverture, on ne diagnostique rien. Le mot « carence »
// n'apparaît nulle part hors de MICRO_DISCLAIMER, et aucun score global n'est
// produit : agréger huit nutriments en une note donnerait un chiffre qui ne
// veut rien dire et que personne ne pourrait contredire.
//
// RÉFÉRENCES NUTRITIONNELLES POUR LA POPULATION (RNP), adulte.
// Source unique : Anses, « Les références nutritionnelles en vitamines et
// minéraux », https://www.anses.fr/fr/content/les-references-nutritionnelles-en-vitamines-et-mineraux
// Consulté le 30 juillet 2026. Aucune valeur n'est estimée ni interpolée : un
// nutriment absent de cette source aurait été retiré du lot.
//
// Trois valeurs demandent un choix explicite, l'Anses en donnant plusieurs
// selon le contexte :
//  · FER, femme : 16 mg correspond aux pertes menstruelles ÉLEVÉES (11 mg pour
//    des pertes faibles ou modérées). On retient 16, la borne prudente — cette
//    règle sert à ouvrir une conversation, pas à rassurer.
//  · ZINC : la RNP dépend de l'acide phytique du régime. On retient la ligne
//    600 mg/j de phytates (H 11,7 · F 9,3), régime mixte courant. Un régime
//    très végétal en contient davantage et sa vraie RNP serait plus haute : la
//    couverture affichée est donc OPTIMISTE pour ces athlètes.
//  · CALCIUM : 950 mg, valeur adulte à partir de 25 ans.
const MICRO_REFS=Object.freeze({
  fe: {lib:'Fer',          unite:'mg', H:11,   F:16},
  ca: {lib:'Calcium',      unite:'mg', H:950,  F:950},
  mg: {lib:'Magnésium',    unite:'mg', H:380,  F:300},
  zn: {lib:'Zinc',         unite:'mg', H:11.7, F:9.3},
  io: {lib:'Iode',         unite:'µg', H:150,  F:150},
  k_: {lib:'Potassium',    unite:'mg', H:3500, F:3500},
  b9: {lib:'Folates',      unite:'µg', H:330,  F:330},
  b12:{lib:'Vitamine B12', unite:'µg', H:4,    F:4}
});
const MICRO_JOURS_FENETRE=7;
const MICRO_COUVERTURE_SEUIL=0.70;
const MICRO_DOC_MINIMALE=0.60;
// Sexe inconnu : on prend la référence la PLUS ÉLEVÉE des deux, et l'affichage
// le dit. Sous-estimer la référence gonflerait la couverture et éteindrait la
// question au moment où elle serait le plus utile.
function refMicro(user,cle){
  const r=MICRO_REFS[cle];
  if(!r) return null;
  const sexe=(user&&(user._evol_gender||user.gender))||'';
  if(!sexe) return {valeur:Math.max(r.H,r.F),sexeConnu:false,lib:r.lib,unite:r.unite};
  return {valeur:isFemale(sexe)?r.F:r.H,sexeConnu:true,lib:r.lib,unite:r.unite};
}
// PURE. Rend {part, partDocumentee, nJours, ...} ou null.
//
// partDocumentee est la FIABILITÉ du calcul, pas un résultat nutritionnel :
// la part des kilocalories journalisées dont l'aliment porte une valeur pour ce
// nutriment. Un aliment sans donnée est exclu de l'apport ET du total — il
// n'est JAMAIS compté zéro, ce qui reviendrait à affirmer qu'il n'en contient
// pas. C'est la même règle que le sel du journal, pour la même raison.
function couvertureMicro(user,cle,joursISO){
  const r=MICRO_REFS[cle];
  if(!r||!user) return null;
  const log=((user.nutrition||{}).log)||{};
  const jours=(joursISO||[]).filter(j=>log[j]&&Array.isArray(log[j].entries)&&log[j].entries.length);
  if(jours.length<MICRO_JOURS_FENETRE) return null;
  const ref=refMicro(user,cle);
  if(!ref||!(ref.valeur>0)) return null;
  let apport=0, kcalDoc=0, kcalTotal=0;
  for(const j of jours){
    for(const e of log[j].entries){
      if(!e) continue;
      const kc=Number(e.kcal)||0;
      kcalTotal+=kc;
      const v=e[cle];
      // undefined (journée saisie avant ce lot) et null (aliment sans donnée)
      // tombent du même côté : inconnu.
      if(v==null) continue;
      apport+=Number(v)||0;
      kcalDoc+=kc;
    }
  }
  return {
    part:Math.round((apport/jours.length)/ref.valeur*1000)/1000,
    partDocumentee:kcalTotal>0?Math.round(kcalDoc/kcalTotal*1000)/1000:0,
    nJours:jours.length,ref:ref.valeur,unite:ref.unite,lib:ref.lib,
    sexeConnu:ref.sexeConnu
  };
}
// Les MICRO_JOURS_FENETRE derniers jours calendaires, du plus ancien au plus
// récent. La fenêtre est FIXE : « sept jours consécutifs » ne veut pas dire
// « les sept dernières journées où l'athlète a saisi quelque chose ».
function _microDerniersJours(ref){
  const base=(ref instanceof Date)?ref:new Date();
  const out=[];
  for(let i=MICRO_JOURS_FENETRE-1;i>=0;i--)
    // EN CALENDRIER : au passage a l'heure d'hiver, reculer de 24 h depuis
    // minuit rend 23 h la veille de la veille — un jour serait saute, un autre
    // compte deux fois, et la fenetre des micro-signaux mentirait d'un jour.
    out.push(localISODate(_datePlusJours(base,-i)));
  return out;
}
// Phrase du journal. La mention de fiabilité est OBLIGATOIRE dès que la part
// documentée n'est pas totale : sans elle, « 68 % de la référence » se lirait
// comme un résultat, alors que c'est un calcul partiel.
function phraseCouvertureMicro(c){
  if(!c) return '';
  let s=c.lib+' : '+Math.round(c.part*100)+' % de la référence sur '+c.nJours+' jours';
  if(c.partDocumentee<1)
    s+=' — calculé sur '+Math.round(c.partDocumentee*100)
      +' % de ce que tu as journalisé, le reste n\'a pas de donnée';
  s+='.';
  if(!c.sexeConnu)
    s+=' Sexe non renseigné : la référence la plus élevée est retenue.';
  return s;
}
function _htmlCouvertureMicro(user,ref){
  const jours=_microDerniersJours(ref);
  const lignes=[];
  for(const cle in MICRO_REFS){
    const c=couvertureMicro(user,cle,jours);
    if(c) lignes.push(phraseCouvertureMicro(c));
  }
  if(!lignes.length) return '';
  // Aucune couleur d'alerte, aucun tri par « manque », aucun total : huit
  // phrases dans l'ordre de la table, et le rappel qui les encadre.
  return `<div style="margin-top:14px;background:var(--surface-1);border:1px solid var(--border);border-radius:var(--r-3);padding:13px">
    <div style="font-size:var(--fs-xs);font-weight:800;letter-spacing:2px;color:var(--sub);text-transform:uppercase;margin-bottom:8px">Micronutriments · ${MICRO_JOURS_FENETRE} jours</div>
    ${lignes.map(t=>`<div style="font-size:var(--fs-xs);color:var(--text-strong);line-height:1.6;padding:4px 0;border-bottom:1px solid #161616">${escapeHtml(t)}</div>`).join('')}
    <div style="font-size:var(--fs-2xs);color:var(--text-faint);line-height:1.6;margin-top:9px">${escapeHtml(MICRO_DISCLAIMER)}</div>
  </div>`;
}

// ══════════════ CE QUE LE COACH A LE DROIT DE REECRIRE ═════════════════
//
// ⚠ LE COACH PEUT ECRIRE DANS /users/<son athlete>. Les regles de la base le
// permettent, et une trentaine d'ecritures du produit passent par pushOne :
// assigner une phase, demander une video, repondre a un bilan. Or le coach ne
// detient du tableau des traitements QUE la version masquee — id, moments, et
// rien d'autre. La poussee est un PUT, un remplacement complet : sans ce qui
// suit, la premiere phase assignee remplacait chez l'athlete le nom, la dose et
// le prescripteur de chacun de ses traitements par du vide.
//
// LA VERITE EST LE NOEUD DISTANT. On repart de lui, et on n'y superpose que ce
// que le coach a LUI-MEME saisi — `saisiPar:'coach'`. Tout le reste est
// recopie verbatim, y compris ce que le coach ne peut pas lire.
//
// PURE, et separee pour cette raison : c'est la fonction qu'on peut casser
// exprès pour verifier qu'une assertion la retient.
function _fusionnerTraitementsPoussee(distant,localCoach){
  const dist=_tabBloc(distant).filter(t=>t&&typeof t==='object');
  const loc =_tabBloc(localCoach).filter(t=>t&&typeof t==='object');
  // Ce que le coach a saisi, et lui seul. Un traitement de l'athlete present
  // dans sa copie n'y est qu'en version masquee : le reprendre l'effacerait.
  const siens={};
  for(const t of loc) if(t.saisiPar==='coach'&&t.id!=null) siens[String(t.id)]=t;
  const out=[];
  const vus={};
  for(const t of dist){
    const k=String(t.id);
    vus[k]=true;
    // ⚠ RIEN N'EST JAMAIS RETIRE ICI. Un traitement ne se supprime pas — la
    // trace est une donnee medicale, et elle explique parfois une periode
    // entiere des annees plus tard ; on l'ARRETE, en posant une date de fin.
    // Une absence dans la copie du coach est donc une desynchronisation, pas
    // une intention, et la lire comme une suppression detruirait le dossier de
    // l'athlete a la premiere ouverture d'un coach mal synchronise.
    out.push(siens[k]||t);
  }
  // Les siens qui n'existent pas encore a distance : ce sont les ajouts.
  for(const k in siens) if(!vus[k]) out.push(siens[k]);
  return out;
}
// PURE. LA REGLE DE TROIS DES MICRONUTRIMENTS, ECRITE UNE SEULE FOIS.
//
// Elle l'etait deux fois, mot pour mot : dans saveFoodEntry et dans l'entree
// d'equivalence. Deux copies d'un prorata ne divergent pas le jour ou on les
// ecrit, elles divergent le jour ou quelqu'un en corrige une.
//
// ⚠ LA CLE N'EST POSEE QUE SI L'ALIMENT PORTE LA VALEUR. Un aliment sans
// donnee reste sans cle : il n'est JAMAIS ecrit a zero, ce qui reviendrait a
// affirmer qu'il n'en contient pas. C'est toute la difference entre « on ne
// sait pas » et « il n'y en a pas », et c'est le piege central de ce lot.
//
// Trois decimales : l'iode et la B12 se comptent en microgrammes, et un
// arrondi au centieme y perdrait le dixieme de la reference journaliere.
function _poserMicros(cible,f,r){
  for(const _mc in MICRO_REFS){
    const _v=f&&f[_mc];
    if(_v!=null) cible[_mc]=parseFloat((_v*r).toFixed(3));
  }
  return cible;
}
const MICRO_DISCLAIMER="RepCore n'est pas un dispositif médical. Seul un bilan sanguin peut établir une carence.";

// ══════════════ LE SIGNAL D'APPORT ═════════════════════════════════════════
//
// Ce qui precede CONSTATE, en huit lignes, chaque fois que le journal est
// ouvert. Ce qui suit SIGNALE, au plus une fois, et seulement quand quatre
// gardes sont franchies ensemble. Les deux ne se remplacent pas : l'un est un
// tableau de bord, l'autre est une phrase qu'on lit parce qu'elle est rare.
//
// ⚠ LES REPERES SONT CEUX DE MICRO_REFS, et il n'en existe pas d'autres. Une
// seconde table serait une seconde doctrine : le jour ou l'Anses revise le
// zinc, l'une des deux serait corrigee et pas l'autre.
//
// ⚠ ILS NE SONT PAS MAJORES PAR L'ENTRAINEMENT, et ce n'est pas un oubli. Il
// n'existe pas de reference nutritionnelle publiee pour le sportif sur ces
// huit nutriments — seulement des fourchettes de revue, sans consensus. Une
// majoration inventee, meme prudente, rendrait TOUT LE MONDE deficitaire et
// ferait de ce signal un bruit permanent. Que personne ne « corrige » ceci
// dans six mois sans une source qui le porte.
const MICRO_SIGNAL_JOURS_MIN=5;      // sur les 7 de la fenetre
const MICRO_SIGNAL_SEUIL=0.70;       // sous 70 % du repere journalier
const MICRO_SIGNAL_SEMAINES=2;       // et vrai deux semaines de suite
const MICRO_SIGNAL_N_ALIMENTS=3;
// Un aliment n'est dit « riche » que si 100 g en apportent au moins un
// dixieme de la reference du jour. Sans ce plancher, la liste se remplirait
// d'aliments qui contiennent le nutriment sans en apporter : proposer une
// salade verte contre un apport en fer bas, c'est perdre la confiance du
// lecteur en une ligne.
const MICRO_RICHE_PART=0.10;
// ⚠ ET UN PLAFOND, QUI VAUT AUTANT QUE LE PLANCHER. Trier la base par teneur
// au cent grammes remonte ce qui n'est pas mange au cent grammes : l'ao-nori
// sechee (205 mg de fer), la chlorelle (177), le maerl (144), le sel marin, la
// levure chimique. Mesure faite sur les 3 484 fiches Ciqual avant d'ecrire
// cette ligne. Proposer de la chlorelle contre un apport en fer bas, c'est
// pire qu'une liste d'abats : c'est la derniere fois que la phrase est lue.
//
// Deux filtres, et ils ne s'appliquent QU'A LA BASE :
//  · un aliment qui livre plus de DEUX jours de reference en 100 g n'est pas
//    mange en 100 g — c'est un condiment, une poudre ou une algue sechee ;
//  · deux groupes Ciqual sortent en entier. « Aides culinaires et ingredients
//    divers » contient les epices, les algues et les levures ; « eaux et
//    autres boissons » remontait le cafe soluble sur le potassium et la
//    feuille de the sur le fer. Les aliments infantiles n'ont rien a faire
//    dans une proposition faite a un adulte.
//
// ⚠ CE QUE L'ATHLETE A DEJA JOURNALISE ECHAPPE AUX DEUX. S'il mange de
// l'ao-nori, la lui proposer est juste : c'est la base qu'on borne, pas lui.
const MICRO_RICHE_PLAFOND=2;
const MICRO_GROUPES_EXCLUS=Object.freeze(['aides culinaires et ingrédients divers',
  'eaux et autres boissons','aliments infantiles','']);

// PURE. LA SEMAINE, SOMMEE. Les sept jours calendaires qui s'achevent a
// `finISO`, celui-ci compris.
//
// ⚠ LA COMPARAISON SE FAIT EN MOYENNE JOURNALIERE, jamais en total sur sept.
// La garde d'en dessous accepte 5 jours renseignes sur 7 ; opposer la somme de
// cinq journees a une reference multipliee par sept donnerait au mieux 71 %, et
// declarerait donc un manque a quiconque ne journalise pas le week-end. Le
// manque serait fabrique par la garde censee l'eviter.
//
// ⚠ ET UN CHAMP ABSENT N'EST PAS UN ZERO. L'aliment sort de l'apport ET du
// total : sa part d'energie est accumulee a part, dans `couverture`, qui dit
// sur quelle fraction du journal le chiffre est calcule. Compter zero
// fabriquerait un manque des qu'un produit OpenFoodFacts entre au journal —
// et OFF ne porte presque jamais l'iode ni la B12.
function microSemaine(user,finISO){
  const u=_dossier(user);
  const log=((u&&u.nutrition)||{}).log||{};
  const fin=_dateDeISO(String(finISO||localISODate(new Date())).slice(0,10));
  const jours=_microDerniersJours(fin);
  const out={joursRenseignes:0,jours:jours.slice(),couverture:{},part:{},kcal:0};
  const apport={}, kcalDoc={};
  for(const cle in MICRO_REFS){ out[cle]=0; apport[cle]=0; kcalDoc[cle]=0; }
  let kcalTotal=0;
  for(const j of jours){
    const es=(log[j]&&Array.isArray(log[j].entries))?log[j].entries:null;
    if(!es||!es.length) continue;
    out.joursRenseignes++;
    for(const e of es){
      if(!e) continue;
      const kc=Number(e.kcal)||0;
      kcalTotal+=kc;
      for(const cle in MICRO_REFS){
        const v=e[cle];
        // undefined (journee saisie avant que la cle existe) et null (aliment
        // sans donnee) tombent du meme cote : inconnu.
        if(v==null) continue;
        apport[cle]+=Number(v)||0;
        kcalDoc[cle]+=kc;
      }
    }
  }
  out.kcal=Math.round(kcalTotal);
  for(const cle in MICRO_REFS){
    out[cle]=Math.round(apport[cle]*1000)/1000;
    out.couverture[cle]=kcalTotal>0?Math.round(kcalDoc[cle]/kcalTotal*1000)/1000:0;
    const r=refMicro(u,cle);
    out.part[cle]=(out.joursRenseignes>0&&r&&r.valeur>0)
      ? Math.round((apport[cle]/out.joursRenseignes)/r.valeur*1000)/1000
      : null;
  }
  return out;
}

// PURE. LES NUTRIMENTS EN DEFAUT SUR UNE SEMAINE — trois des quatre gardes.
// La quatrieme, la persistance, ne peut pas se juger sur une seule semaine :
// elle est appliquee par signalMicro.
function _microDefauts(user,finISO){
  const s=microSemaine(user,finISO);
  const out=[];
  if(s.joursRenseignes<MICRO_SIGNAL_JOURS_MIN) return out;
  for(const cle in MICRO_REFS){
    if(!(s.couverture[cle]>MICRO_SIGNAL_SEUIL)) continue;
    const p=s.part[cle];
    if(p==null||!(p<MICRO_SIGNAL_SEUIL)) continue;
    out.push({cle:cle,part:p,couverture:s.couverture[cle],
      joursRenseignes:s.joursRenseignes});
  }
  return out;
}

// PURE. LE SIGNAL, OU RIEN. Quatre gardes ensemble, deux semaines de suite,
// et UN SEUL nutriment nomme — le plus bas de la semaine courante.
//
// ⚠ UNE PHRASE QUI EN LISTE TROIS N'EST PLUS UNE CONSIGNE. Elle devient un
// bulletin, on la lit une fois, et on ne la lit plus.
function signalMicro(user,finISO){
  const u=_dossier(user);
  if(!u) return null;
  const fin=String(finISO||localISODate(new Date())).slice(0,10);
  const cette=_microDefauts(u,fin);
  if(!cette.length) return null;
  // LA SEMAINE PRECEDENTE, decalee de la largeur exacte de la fenetre.
  const avant=_microDefauts(u,localISODate(
    _datePlusJours(_dateDeISO(fin),-MICRO_JOURS_FENETRE)));
  const persistants=cette.filter(x=>avant.some(y=>y.cle===x.cle));
  if(!persistants.length) return null;
  // LE PLUS BAS, et lui seul.
  persistants.sort((a,b)=>a.part-b.part);
  const g=persistants[0];
  const r=refMicro(u,g.cle);
  return {cle:g.cle,lib:r.lib,unite:r.unite,ref:r.valeur,sexeConnu:r.sexeConnu,
    part:g.part,pct:Math.round(g.part*100),couverture:g.couverture,
    joursRenseignes:g.joursRenseignes,semaines:MICRO_SIGNAL_SEMAINES,
    autres:persistants.length-1};
}

// PURE. TROIS ALIMENTS RICHES, PRIS D'ABORD DANS LES SIENS.
//
// ⚠ UN CONSEIL BATI SUR SES PROPRES ALIMENTS EST SUIVI ; une liste d'abats ne
// l'est pas. On balaie donc le journal ET le dictionnaire des aliments
// frequents avant d'ouvrir la base, et chaque proposition dit d'ou elle vient.
function alimentsRichesEn(user,cle,n,finISO){
  const r=MICRO_REFS[cle];
  if(!r) return [];
  const combien=Math.max(1,Math.round(Number(n)||MICRO_SIGNAL_N_ALIMENTS));
  const ref=refMicro(_dossier(user),cle);
  const plancher=(ref&&ref.valeur>0)?ref.valeur*MICRO_RICHE_PART:0;
  let base=[];
  try{ base=Array.isArray(_ciqualDB)?_ciqualDB:[]; }catch(e){ base=[]; }
  if(!base.length) return [];
  // ── CE QU'IL A DEJA ENREGISTRE ────────────────────────────────────────
  const siens={};
  const u=_dossier(user);
  const log=((u&&u.nutrition)||{}).log||{};
  for(const j in log){
    const es=log[j]&&log[j].entries;
    if(!Array.isArray(es)) continue;
    for(const e of es) if(e&&e.alim_id!=null) siens[String(e.alim_id)]=true;
  }
  try{ for(const k in (((u&&u.nutrition)||{}).usageFoods||{})) siens[k]=true; }catch(e){}
  const trier=(a,b)=>(Number(b[cle])||0)-(Number(a[cle])||0);
  const riche=f=>f&&f[cle]!=null&&Number(f[cle])>=plancher;
  // Le plafond et l'exclusion de groupe ne bornent QUE la base.
  const mangeable=f=>riche(f)
    && Number(f[cle])<=(ref&&ref.valeur>0?ref.valeur*MICRO_RICHE_PLAFOND:Infinity)
    && MICRO_GROUPES_EXCLUS.indexOf(String(f.g||''))<0;
  const dedans=base.filter(f=>riche(f)&&siens[String(f.id)]).sort(trier)
    .slice(0,combien).map(f=>({id:f.id,nom:f.n,valeur:Number(f[cle]),
      unite:r.unite,sien:true}));
  if(dedans.length>=combien) return dedans;
  // ── ET SEULEMENT ENSUITE, LA BASE ─────────────────────────────────────
  // Le complement est trie par teneur, mais on ecarte ce qui est deja retenu.
  const pris={}; for(const x of dedans) pris[String(x.id)]=true;
  const reste=base.filter(f=>mangeable(f)&&!pris[String(f.id)]).sort(trier)
    .slice(0,combien-dedans.length).map(f=>({id:f.id,nom:f.n,
      valeur:Number(f[cle]),unite:r.unite,sien:false}));
  return dedans.concat(reste);
}

// ⚠ LE MOT « CARENCE » N'EST PAS ECRIT ICI, ET IL NE DOIT PAS L'ETRE. L'app
// parle d'APPORTS ALIMENTAIRES — ce qui est entre dans le journal — et non
// d'un etat biologique, qu'elle n'a ni les moyens ni la qualite d'etablir. Le
// seul endroit du fichier ou le mot apparait est MICRO_DISCLAIMER, qui dit
// justement que seul un bilan sanguin peut en etablir une.
function phraseSignalMicro(s){
  if(!s) return '';
  let t='Tes apports en '+s.lib.toLowerCase()+' sont à '+s.pct
    +' % du repère depuis deux semaines.';
  if(!s.sexeConnu) t+=' Sexe non renseigné : le repère le plus élevé est retenu.';
  return t;
}
// PURE. La ligne du coach. Meme rarete, meme unicite du nutriment ; ce qui
// change est qu'elle porte la fiabilite du calcul, parce que c'est un
// professionnel qui la lit et qu'il doit savoir sur quoi elle se fonde.
function phraseSignalMicroCoach(s){
  if(!s) return '';
  return 'Ses apports en '+s.lib.toLowerCase()+' ressortent à '+s.pct
    +' % du repère sur deux semaines consécutives, calculés sur '
    +Math.round(s.couverture*100)+' % de ce qui a été journalisé ('
    +s.joursRenseignes+' jours sur '+MICRO_JOURS_FENETRE+' la dernière semaine).'
    +(s.autres>0?' '+s.autres+' autre'+(s.autres>1?'s':'')
      +' nutriment'+(s.autres>1?'s':'')+' est dans le même cas.':'');
}


function _microNorm(s){
  return String(s==null?'':s).normalize('NFD').replace(/[̀-ͯ]/g,'').toLowerCase();
}
// Sommeil : moyenne des nuits renseignées dans la fenêtre. Rend null quand il
// n'y en a pas assez pour que le mot « moyenne » veuille dire quelque chose.
function _microSommeil(user,ref){
  const maintenant=(ref instanceof Date)?ref.getTime():Date.now();
  const limite=localISODate(_datePlusJours(maintenant,-MICRO_SOMMEIL_JOURS));
  const nuits=((user&&user.sleepLog)||[])
    .filter(e=>e&&e.date&&String(e.date)>=limite&&Number(e.duration)>0)
    .map(e=>Number(e.duration));
  if(nuits.length<MICRO_SOMMEIL_MIN_NUITS) return null;
  return {moyenne:Math.round(nuits.reduce((a,b)=>a+b,0)/nuits.length*10)/10,
    nuits:nuits.length};
}
// Cycle DÉCLARÉ actif : la case activée et une date de dernières règles. C'est
// la même condition que _manageCycleSupplements — on ne devine pas un cycle.
function _microCycleActif(user){
  const c=confCycle(user);
  return !!(c.enabled&&c.lastPeriodDate);
}
// Vrai si la reponse vaut oui, quelle que soit la forme sous laquelle la case
// a ete enregistree au fil des versions du questionnaire.
function _microCoche(v){
  const t=_microNorm(_texteReponse(v));
  return t==='oui'||t==='true'||t==='1'||t==='on'||t==='vege'||t==='vegetarien'
    ||t==='vegetalien';
}
function _microVege(user){
  const bl=((user&&user.bilans)||[]).filter(b=>b&&b.type==='depart');
  // La case cochee PRIME : elle est explicite. La recherche de mot-cle n'est
  // qu'un rattrapage pour les dossiers anterieurs a ce champ.
  for(const b of bl) if(_microCoche(b['deb-vege'])) return true;
  for(const b of bl){
    for(const champ of MICRO_CHAMPS_VEGE){
      const t=_microNorm(b[champ]);
      if(t&&MICRO_MOTS_VEGE.some(m=>t.indexOf(m)>=0)) return true;
    }
  }
  return false;
}

// PURE : ne lit aucun état global hors constantes, n'écrit rien. `ref` sert aux
// tests à fixer la date — sans elle, la règle saisonnière serait inéprouvable
// huit mois par an.
function risquesMicro(user,ref){
  const out=[];
  if(!user||typeof user!=='object') return out;
  const date=(ref instanceof Date)?ref:new Date();
  const phase=phaseCourante(user);
  const enSeche=!!(phase&&phase.type==='seche');
  const semaines=enSeche
    ? Math.floor((date.getTime()-phase.debut)/(7*24*3600*1000))
    : null;

  // ── Fer : sèche longue chez une athlète dont le cycle est suivi ──────────
  const sexe=(user._evol_gender||user.gender)||'';
  if(isFemale(sexe)&&_microCycleActif(user)&&semaines!=null&&semaines>=MICRO_SECHE_SEMAINES){
    out.push({cle:'fer',lib:'Sèche longue et cycle actif',
      motif:'Sèche depuis '+semaines+' semaines, cycle menstruel suivi dans l\'app.',
      question:'As-tu un bilan sanguin récent (ferritine) ?'});
  }

  // ── Stagnation inexpliquée : la question thyroïdienne, au coach ──────────
  // Côté COACH, la question est nommée : c'est un professionnel qui parle à
  // un médecin. Côté athlète, aucune pathologie n'est citée.
  try{
    const st=_ajustStagnationBloque(user);
    if(st){
      const a=st.adh||{};
      const pctAdh=(a.cibleMoyenne>0)
        ?Math.round(100-Math.abs(a.ecartKcal)/a.cibleMoyenne*100):null;
      out.push({cle:'stagnation',lib:'Stagnation inexpliquée',
        motif:'Sèche de '+st.semaines+' semaines, adhérence de '
          +(pctAdh!=null?pctAdh+' %':'—')+' sur '+(a.nJours||0)
          +' jours journalisés, perte mesurée quasi nulle.',
        question:'Un bilan thyroïdien récent existe-t-il ?'});
    }
  }catch(e){}

  // ── SOPK déclaré : on renvoie vers le suivi, on n'affirme rien ───────────
  // Aucun contenu sur le traitement, aucun complément suggéré : une question,
  // au même format que les autres.
  try{
    if(aSOPK(user)){
      out.push({cle:'sopk',lib:'SOPK déclaré',
        motif:'Un SOPK est déclaré dans son dossier.',
        question:'Le suivi médical est-il en place ? Y a-t-il un traitement en cours ?'});
    }
  }catch(e){}

  // ── Saison : de novembre à mars, pour tout le monde ──────────────────────
  // Meme motif que hasUserOmega : un complement ACTIF portant le nom du
  // nutriment eteint la regle. La question a deja recu sa reponse, et la
  // reposer chaque hiver use la seule chose qui compte ici, l'attention.
  const _aVitD=(((user.nutrition||{}).supplements)||[]).some(x=>x&&x.active!==false
    &&/vitamine\s*d\b|\bd3\b/i.test(String(x.name||'')));
  if(!_aVitD&&MICRO_MOIS_PEU_SOLEIL.indexOf(date.getMonth())>=0){
    const mois=date.toLocaleDateString('fr-FR',{month:'long'});
    out.push({cle:'vitamineD',lib:'Saison peu ensoleillée',
      motif:'Nous sommes en '+mois+' : de novembre à mars, l\'ensoleillement est faible sous nos latitudes.',
      question:'Le dosage de la vitamine D a-t-il été abordé avec un professionnel de santé ?'});
  }

  // ── Couverture journalisée sous le seuil ─────────────────────────────────
  // Deux conditions, et la seconde compte autant que la premiere : une
  // couverture basse calculee sur un tiers du journal ne dit rien du tout.
  // En dessous de MICRO_DOC_MINIMALE, la regle SE TAIT — l'affichage du
  // journal, lui, continue de montrer la faible fiabilite.
  {
    const _jours=_microDerniersJours(date);
    // ⚠ LE SIGNAL PERSISTANT PASSE DEVANT, ET IL RETIRE SON NUTRIMENT DE LA
    // BOUCLE. Deux lignes sur le meme fer — l'une disant « la derniere semaine
    // journalisee », l'autre « deux semaines consecutives » — feraient lire la
    // moins informative des deux, et laisseraient croire a deux constats
    // independants la ou il n'y en a qu'un.
    //
    // Il ne remplace pas la boucle : un nutriment tombe UNE seule semaine reste
    // dit, sans la persistance, exactement comme avant ce lot.
    let _sig=null;
    try{ _sig=signalMicro(user,localISODate(date)); }catch(e){ _sig=null; }
    if(_sig) out.push({cle:'couverture_'+_sig.cle,
      lib:'Couverture '+_sig.lib.toLowerCase()+' — deux semaines',
      motif:phraseSignalMicroCoach(_sig),
      question:'Un bilan sanguin récent existe-t-il ?'});
    for(const _cle in MICRO_REFS){
      if(_sig&&_sig.cle===_cle) continue;
      const _c=couvertureMicro(user,_cle,_jours);
      if(!_c) continue;
      if(!(_c.part<MICRO_COUVERTURE_SEUIL)) continue;
      if(!(_c.partDocumentee>=MICRO_DOC_MINIMALE)) continue;
      out.push({cle:'couverture_'+_cle,lib:'Couverture '+_c.lib.toLowerCase(),
        motif:'Ses apports en '+_c.lib.toLowerCase()+' ressortent à '
          +Math.round(_c.part*100)+' % de la référence sur la dernière semaine'
          +' journalisée, sur '+Math.round(_c.partDocumentee*100)
          +' % de ce qui a été journalisé.',
        question:'Un bilan sanguin récent existe-t-il ?'});
    }
  }

  // ── Hydratation basse déclarée ──────────────────────────────────────────
  // Une question, pas un verdict : « moins d'un litre » est une DÉCLARATION,
  // faite une fois au bilan de départ, et elle ne dit rien de ce que l'athlète
  // boit aujourd'hui. Elle ne se déclenche que quand le contexte la rend
  // pertinente — une sèche, ou un volume d'entraînement soutenu.
  {
    const eau=_texteReponse(_dernierChamp(user,'deb-water'));
    const basse=eau&&/moins de 1\s*l/i.test(_microNorm(eau));
    const creneaux=((user.sessions_config)||[]).filter(x=>x&&x.active).length;
    if(basse&&(enSeche||creneaux>=4)){
      out.push({cle:'hydratation',lib:'Hydratation basse déclarée',
        motif:'Il déclare boire moins d\'un litre par jour.',
        question:'Est-ce que l\'hydratation a été abordée ?'});
    }
  }

  // ── Alimentation végétarienne ou végétalienne déclarée ───────────────────
  if(_microVege(user)){
    out.push({cle:'b12_fer_vegetal',lib:'Régime végétarien ou végétalien',
      motif:'Un régime végétarien ou végétalien est mentionné au bilan de départ.',
      question:'Un bilan sanguin (B12, ferritine) a-t-il été fait depuis ce changement d\'alimentation ?'});
  }

  // ── Sommeil court pendant une sèche ──────────────────────────────────────
  if(enSeche){
    const s=_microSommeil(user,date);
    if(s&&s.moyenne<MICRO_SOMMEIL_SEUIL){
      out.push({cle:'magnesium',lib:'Sommeil court en sèche',
        motif:'Moyenne de '+String(s.moyenne).replace('.',',')+' h sur '+s.nuits
          +' nuits renseignées, pendant une sèche.',
        question:'Est-ce que le sommeil fait partie de ce que vous suivez ensemble en ce moment ?'});
    }
  }

  // ── Traitement déclaré ──────────────────────────────────────────────────
  // La CASE seule. Le motif ne reprend RIEN du texte libre : le coach le lit
  // dans les réponses au bilan, pas dans une entrée générée.
  if(traitementDeclare(user)){
    const fam=famillesTraitement(user)
      .map(c=>(FAMILLES_TRAITEMENT.find(f=>f.cle===c)||{}).lib).filter(Boolean);
    out.push({cle:'traitement',lib:'Traitement déclaré',
      motif:'Un traitement régulier est déclaré.'
        +(fam.length?' Familles indiquées : '+fam.join(', ')+'.':''),
      question:'A-t-il été pris en compte dans les objectifs ?'});
  }

  // ── Récupération : le palier du lot A3-04, porté au coach ───────────────
  // SANS CONDITION DE GENRE. Le score de A3-04 compte des critères dont
  // certains sont féminins par nature — l'absence de règles — mais il ne
  // s'adresse pas qu'aux femmes : la restriction longue, le sommeil court et
  // le volume au plafond comptent pour tout le monde. Chez un homme, le motif
  // se compose simplement des critères qui, eux, sont remplis.
  //
  // Les libellés viennent de risqueDeficitEnergetique TELS QUELS : les
  // reformuler ici ferait deux vocabulaires pour un seul score.
  try{
    const pal=paliersDeficit(user);
    if(pal==='vigilance'||pal==='blocage'){
      const r=risqueDeficitEnergetique(user);
      const lst=(r.criteres||[]).map(c=>c.lib+(c.valeur?' ('+c.valeur+')':''));
      // Dédoublonnage par clé : rien ne pousse 'recuperation' aujourd'hui,
      // la garde est là pour le jour où le palier arriverait par deux
      // chemins. Une question posée deux fois se lit comme une insistance.
      if(lst.length&&!out.some(x=>x.cle==='recuperation')){
        out.push({cle:'recuperation',lib:'Récupération à vérifier',
          motif:lst.join(', ')+'.',
          question:'La récupération est-elle suffisante ? Un avis médical a-t-il été envisagé ?'});
      }
    }
  }catch(e){}
  return out;
}

// ══════════════ PROPORTIONS SEGMENTAIRES ══════════════
// Deux longueurs, deux ratios, et des QUESTIONS au coach. Rien de plus : aucun
// exercice n'est retiré, remplacé ni masqué, et l'athlète ne voit jamais rien
// de tout ceci. Même registre que risquesMicro — un constat chiffré, puis une
// question à poser en séance.
//
// Les valeurs de référence sont des REPÈRES DE POPULATION, pas des seuils et
// encore moins une norme : la longueur de jambe rapportée à la taille tourne
// autour de 0,46 et celle du bras autour de 0,45 chez l'adulte, avec une
// dispersion large. Être en dehors n'est ni un défaut ni un diagnostic — c'est
// une raison de proposer une variante d'un mouvement, jamais de l'interdire.
const RATIO_JAMBES_REF=0.46;
const RATIO_BRAS_REF=0.45;
const RATIO_MARGE=0.03;
// Comparaison au centième : un entrejambe relevé au centimètre près sur une
// personne de 180 cm ne porte pas plus de précision que ça, et c'est déjà
// l'arrondi qu'affiche le motif (« 49 % »). La marge est ATTEINTE, pas
// dépassée : sinon 0,489 tomberait dedans, alors que le cahier des charges le
// donne dehors.
function _horsMarge(ratio,ref){
  if(ratio==null||!isFinite(ratio)) return false;
  return Math.abs(Math.round(ratio*100)/100-ref)>=RATIO_MARGE-1e-9;
}
// Bornes d'aberration. Une mesure hors de ces bornes n'est pas calculée : elle
// est signalée à revérifier. Mieux vaut une case vide qu'un ratio faux.
const LONGUEUR_MIN_CM=30;
const MORPHO_DISCLAIMER="RepCore n'est pas un dispositif médical. Ces proportions ne disent pas ce qu'il faut faire : elles ouvrent une conversation.";
// Au-delà, la question du rapport quadriceps / ischios se pose. Ce n'est pas
// un seuil de risque : c'est le rapport à partir duquel l'écart cesse d'être
// une préférence d'exercices et mérite d'être vu.
const DOMINANCE_QI_SIGNAL=2.0;

// Taille en centimètres, lue comme partout ailleurs dans l'app.
function _tailleCm(user){
  const bl=((user&&user.bilans)||[]).filter(b=>b&&b.date).slice().sort((a,b)=>a.date-b.date);
  const b=bl[bl.length-1]||{};
  const t=parseFloat((user&&(user._evol_height||user['init-height']))
    ||b['deb-height']||(user&&user.height)||0);
  return (isFinite(t)&&t>0)?t:null;
}
// PURE. Rend {cm} si la mesure tient debout, {motif:'absente'|'aberrante'}
// sinon. Jamais 0, jamais une valeur devinée.
function longueurSegment(user,champ){
  const t=_tailleCm(user);
  const brut=_dernierChamp(user,champ);
  if(brut==null||String(brut).trim()==='') return {cm:null,motif:'absente'};
  const v=parseFloat(String(brut).replace(',','.'));
  if(!isFinite(v)||v<=0) return {cm:null,motif:'aberrante'};
  if(v<LONGUEUR_MIN_CM) return {cm:null,motif:'aberrante'};
  // Un segment plus long que la personne entière : la mesure est fausse, ou
  // saisie en millimètres. On ne calcule pas, on le dit.
  if(t!=null&&v>t) return {cm:null,motif:'aberrante'};
  if(t==null) return {cm:null,motif:'taille-absente'};
  return {cm:v,motif:null};
}
function ratioJambes(user){
  const l=longueurSegment(user,'deb-entrejambe');
  const t=_tailleCm(user);
  return (l.cm!=null&&t)?l.cm/t:null;
}
function ratioBras(user){
  const l=longueurSegment(user,'deb-bras');
  const t=_tailleCm(user);
  return (l.cm!=null&&t)?l.cm/t:null;
}

// Exercices du même schéma moteur, à titre de VARIANTES POSSIBLES. Ce lot
// n'écarte rien : ces noms sont proposés à côté, jamais à la place.
function _variantesSchema(schema,combien){
  const out=[];
  for(const k in _SCHEMA_INDEX){
    if(_SCHEMA_INDEX[k]===schema){ out.push(k); if(out.length>=(combien||4)) break; }
  }
  return out;
}

// Rapport des volumes quadriceps / ischios sur les dernières semaines
// ENTRAÎNÉES, avec le comptage de volume existant et les mêmes bornes que le
// reste du produit — VOL_COUPURE pour la coupure, VOL_DELTA_MIN pour le
// minimum exploitable. Rend null si l'un des deux volumes est nul : un rapport
// à dénominateur nul ne veut rien dire.
function dominanceQuadIschio(user){
  let q=0,i=0,n=0,vides=0;
  for(let k=0;k<=26&&n<VOL_DELTA_N;k++){
    const c=_calculSemaine(user,_volCleDecalee(k));
    if(!c.eligibles){ if(++vides>=VOL_COUPURE) break; continue; }
    vides=0; n++;
    q+=c.muscles.QUADRICEPS||0;
    i+=c.muscles.ISCHIOS||0;
  }
  if(n<VOL_DELTA_MIN) return null;
  if(!(q>0)||!(i>0)) return null;
  return Math.round(q/i*100)/100;
}

// ══════════════ MORPHO — LOT M1 : SIX MESURES, QUATRE TESTS ══════════════
//
// Même discipline que les deux longueurs d'origine : facultatives, bornées, et
// quand une mesure ne tient pas debout on le DIT au lieu de calculer dessus.
// Elles ne bougent plus une fois adulte — on ne les redemande pas à chaque
// bilan de suivi.
//
// ⚠ LA CONSIGNE FAIT LA MESURE, et c'est pourquoi chaque champ porte la sienne
// à l'écran, au moment de la saisie. Une auto-mesure prise avec un protocole
// affiché s'accorde bien avec celle d'un technicien ; prise sans, on ne sait
// même pas ce qui a été mesuré, et deux bilans cessent d'être comparables.
//
// LES BORNES SONT LARGES À DESSEIN. Elles écartent la faute de frappe et
// l'unité fausse — 7 cm de tour de poignet, 190 cm de hauteur de genou — pas la
// morphologie inhabituelle. Chacune porte son ordre de grandeur en commentaire.

/**
 * Les mesures morphologiques, avec leur consigne et leurs bornes.
 * `type` : une LONGUEUR ne peut pas dépasser la taille de la personne, un TOUR
 * de membre n'a pas de raison d'être comparé à elle — la garde ne s'applique
 * donc qu'aux longueurs.
 * `origine` : les deux premières existaient avant ce lot ; leur calcul reste
 * celui de longueurSegment, qu'on ne réécrit pas.
 */
const MORPHO_MESURES=Object.freeze([
  {cle:'deb-entrejambe',lib:'Entrejambe',court:'Entrejambe',type:'longueur',origine:'M0',
   consigne:'Du sol au pubis, pieds nus, dos au mur.'},
  {cle:'deb-bras',lib:'Longueur de bras',court:'Bras',type:'longueur',origine:'M0',
   consigne:'Bras tendu le long du corps, de la pointe de l’épaule au poignet.'},
  // Du sol à l'interligne du genou : environ 27 % de la taille, soit 39 cm à
  // 145 cm et 55 cm à 200 cm. Les bornes couvrent largement au-delà.
  {cle:'deb-genou',lib:'Hauteur de genou',court:'Genou',type:'longueur',min:25,max:75,
   consigne:'Debout, pieds nus : du sol au creux du genou, là où la jambe plie.'},
  // Du sol au milieu de la rotule : le meme ordre de grandeur que la hauteur
  // de genou ci-dessus, deux a trois centimetres plus haut. Memes bornes.
  //
  // ⚠ ELLE NE REMPLACE PAS `deb-genou`, ELLE S'AJOUTE. Voir le bloc du lot 7 :
  //   deux protocoles differents ne peuvent pas partager une colonne.
  {cle:'deb-rotule',lib:'Hauteur de rotule',court:'Rotule',type:'longueur',min:25,max:75,
   consigne:'Du sol au milieu de la rotule, pieds nus, dos au mur, jambes tendues.',
   schema:true},
  // Olécrane → styloïde : environ 14,5 % de la taille, soit 21 à 29 cm chez
  // l'adulte.
  {cle:'deb-avantbras',lib:'Avant-bras',court:'Av.-bras',type:'longueur',min:15,max:45,
   consigne:'Coude plié à angle droit : de la pointe du coude à l’os du poignet.'},
  // Largeur biacromiale : environ 23 % de la taille, soit 33 à 46 cm.
  {cle:'deb-epaules',lib:'Largeur d’épaules',court:'Épaules',type:'longueur',min:25,max:65,
   consigne:'De dos, bras relâchés : d’une pointe d’épaule à l’autre, en ligne droite.'},
  // Largeur biiliaque : environ 16 à 18 % de la taille, soit 23 à 36 cm.
  {cle:'deb-bassin',lib:'Largeur de bassin',court:'Bassin',type:'longueur',min:18,max:55,
   consigne:'Mains à plat sur les crêtes des hanches : d’un os à l’autre, en ligne droite.'},
  // Tour de poignet : 14 à 19 cm chez l'adulte, os fin ou large compris.
  {cle:'deb-poignet',lib:'Tour de poignet',court:'Poignet',type:'tour',min:10,max:26,
   consigne:'Juste sous l’os saillant, mètre ruban à plat, sans serrer.'},
  // Tour de cheville au plus fin : 19 à 27 cm chez l'adulte.
  {cle:'deb-cheville',lib:'Tour de cheville',court:'Cheville',type:'tour',min:14,max:38,
   consigne:'Au plus fin, juste au-dessus de l’os de la cheville, sans serrer.'}
]);

/**
 * PURE. Une mesure morphologique, si elle tient debout. Même contrat que
 * longueurSegment — {cm} ou {motif} — et c'est LUI qui répond pour les deux
 * mesures d'origine : elles ont leurs bornes historiques, et deux sources de
 * vérité sur la même mesure finiraient par diverger.
 * @returns {{cm:number|null, motif:string|null}}
 */
function mesureMorpho(user,cle){
  const d=MORPHO_MESURES.find(m=>m.cle===cle);
  if(!d) return {cm:null,motif:'inconnue'};
  if(d.origine==='M0') return longueurSegment(user,cle);
  const brut=_dernierChamp(user,cle);
  if(brut==null||String(brut).trim()==='') return {cm:null,motif:'absente'};
  const v=parseFloat(String(brut).replace(',','.'));
  if(!isFinite(v)||v<=0) return {cm:null,motif:'aberrante'};
  if(v<d.min||v>d.max) return {cm:null,motif:'aberrante'};
  // UNE LONGUEUR PLUS GRANDE QUE LA PERSONNE est une saisie fausse, ou des
  // millimètres pris pour des centimètres. On ne calcule pas, on le dit.
  const t=_tailleCm(user);
  if(d.type==='longueur'&&t!=null&&v>t) return {cm:null,motif:'aberrante'};
  return {cm:v,motif:null};
}

/**
 * Les incohérences entre deux mesures. Ce ne sont pas des morphologies rares :
 * un genou plus haut que le pubis, un avant-bras plus long que le bras entier,
 * un bassin plus large que les épaules d'un tiers — ce sont des saisies
 * fausses, et tout rapport bâti dessus le serait aussi.
 * `k` : le facteur appliqué à la seconde mesure avant comparaison.
 */
const MORPHO_COHERENCES=Object.freeze([
  {cle:'coherence_genou',a:'deb-genou',b:'deb-entrejambe',k:1,lib:'Genou et entrejambe',
   motif:'La hauteur de genou dépasse l’entrejambe, alors que le genou est forcément plus bas que le pubis.',
   question:'Peux-tu reprendre les deux, pieds nus et dos au mur ?'},
  {cle:'coherence_avantbras',a:'deb-avantbras',b:'deb-bras',k:1,lib:'Avant-bras et bras',
   motif:'L’avant-bras est donné plus long que le bras entier, dont il fait partie.',
   question:'Peux-tu reprendre l’avant-bras, coude plié à angle droit ?'},
  // Un bassin plus large que les épaules existe ; plus large d'un tiers, non.
  {cle:'coherence_bassin',a:'deb-bassin',b:'deb-epaules',k:1.3,lib:'Bassin et épaules',
   motif:'Le bassin est donné nettement plus large que les épaules — plus d’un tiers d’écart.',
   question:'Peux-tu reprendre les deux largeurs en ligne droite, de dos ?'}
]);
/**
 * PURE. Les incohérences trouvées, au format de questionsMorpho. Rien n'est
 * signalé tant que les DEUX mesures ne sont pas là et lisibles : une case vide
 * n'est pas une faute.
 * @returns {{cle:string, lib:string, motif:string, question:string}[]}
 */
function coherencesMorpho(user){
  const out=[];
  if(!user||typeof user!=='object') return out;
  for(const c of MORPHO_COHERENCES){
    const a=mesureMorpho(user,c.a), b=mesureMorpho(user,c.b);
    if(a.cm==null||b.cm==null) continue;
    if(a.cm>b.cm*c.k+1e-9) out.push({cle:c.cle,lib:'Mesures à revérifier — '+c.lib,
      motif:c.motif,question:c.question});
  }
  return out;
}

// ── LES QUATRE TESTS D'AMPLITUDE ────────────────────────────────────────────
//
// ⚠ AUCUN NE NOMME UNE CAUSE. « Butée nette » est un constat : le mouvement
// s'arrête franchement. Ce que cette butée est — os, capsule, muscle — ne se
// décide pas au mur d'un salon, et l'app ne le dira pas.
//
// QUATRE-VINGT-DIX JOURS. Une amplitude se travaille et se perd : passé un
// trimestre, un test ne décrit plus l'athlète d'aujourd'hui. Il n'est pas
// effacé — il est marqué périmé, et reproposé.
const MORPHO_PEREMPTION_J=90;
const MORPHO_TESTS=Object.freeze([
  {cle:'cheville',lib:'Cheville, genou au mur',champ:'cm',unite:'cm',min:0,max:25,
   protocole:'Pied nu, orteils face à un mur. Avance le genou jusqu’à toucher le mur sans '
     +'décoller le talon, puis recule le pied jusqu’à la distance la plus grande où le genou '
     +'touche encore. Mesure de l’orteil au mur.'},
  {cle:'hanche',lib:'Hanche — flexion et rotations',champ:'deg',unite:'°',min:30,max:160,
   protocole:'Allongé sur le dos, l’autre jambe tendue au sol : monte le genou vers la '
     +'poitrine jusqu’à ce que le bassin commence à basculer. Note l’angle atteint, et si '
     +'l’arrêt est net ou élastique.'},
  {cle:'epaule',lib:'Épaule — au mur et main dans le dos',champ:'paire',unite:'cm',min:0,max:60,
   mur:true,
   protocole:'Dos au mur, lombaires plaquées : monte les bras tendus, note la distance des '
     +'poignets au mur. Puis main dans le dos, note la distance entre les deux mains. '
     +'Un côté après l’autre. Note aussi si les bras touchent le mur sans que les lombaires '
     +'décollent.'},
  {cle:'posterieur',lib:'Chaîne postérieure — flexion avant',champ:'niveau',unite:'',
   protocole:'Debout, jambes tendues, descends les mains vers le sol sans forcer. Note où le '
     +'dos commence à s’enrouler : haut du dos, milieu, ou bas du dos.',
   niveaux:['haut','milieu','bas']}
]);
/**
 * PURE. Les tests d'amplitude d'un athlète, normalisés et datés, avec leur
 * péremption. Un test absent n'est pas une erreur : c'est un test à faire, et
 * le moteur doit fonctionner sans.
 * @param {any} user
 * @param {number} [maintenant]  ms, pour que le test de la péremption soit reproductible
 * @returns {{cle:string, lib:string, texte:string, date:number|null, jours:number|null, perime:boolean}[]}
 */
function testsMorpho(user,maintenant){
  const now=Number(maintenant)||Date.now();
  const src=(user&&user.morphoTests&&typeof user.morphoTests==='object')?user.morphoTests:{};
  return MORPHO_TESTS.map(d=>{
    const v=src[d.cle];
    const date=(v&&isFinite(Number(v.date))&&Number(v.date)>0)?Math.round(Number(v.date)):null;
    const jours=date==null?null:Math.floor((now-date)/864e5);
    return {cle:d.cle,lib:d.lib,texte:_morphoTexteTest(d,v),date,jours,
      perime:jours!=null&&jours>MORPHO_PEREMPTION_J};
  });
}
/** PURE. Ce qu'un test dit, en une ligne — ou '' s'il n'a pas été fait. */
function _morphoTexteTest(d,v){
  if(!v||typeof v!=='object') return '';
  const n=(x)=>{ const q=parseFloat(String(x).replace(',','.')); return isFinite(q)?q:null; };
  if(d.champ==='cm'){ const q=n(v.cm); return q==null?'':Math.round(q)+' cm au mur'; }
  if(d.champ==='deg'){
    const q=n(v.deg);
    if(q==null) return '';
    const b=v.butee==='nette'?', butée nette':v.butee==='elastique'?', butée élastique':'';
    return Math.round(q)+'°'+b;
  }
  if(d.champ==='paire'){
    const g=n(v.g), dr=n(v.d);
    const mur=v.mur==='oui'?'les bras touchent le mur'
      :v.mur==='non'?'les bras ne touchent pas le mur sans décoller les lombaires':'';
    if(g==null&&dr==null) return mur;
    const cm='gauche '+(g==null?'—':Math.round(g)+' cm')+' · droite '+(dr==null?'—':Math.round(dr)+' cm');
    return mur?mur+' · '+cm:cm;
  }
  if(d.champ==='niveau'){
    const k=String(v.niveau||'');
    return (d.niveaux||[]).includes(k)?'le dos s’enroule par le '+k+' du dos':'';
  }
  return '';
}

// ══════════════ MORPHO — LOT M2 : LES NEUF AXES ══════════════
//
// Un athlète n'est pas rangé dans une case : il occupe une POSITION sur
// chacun des neuf axes, avec la confiance que mérite la source. Neuf axes
// renvoyés, toujours, même vides — un axe absent porte ce qu'il faudrait
// mesurer pour qu'il existe, et c'est une sortie de première classe.
//
// ⚠ L'ORDRE DE LECTURE EST DANS LA STRUCTURE, PAS DANS LA DOCTRINE.
// morphoAxes rend les axes ACQUIS d'abord, FONCTIONNELS ensuite, OSSEUX en
// dernier. Un mollet plat après deux ans sans mollets n'est pas une affaire
// d'insertions : inverser cet ordre, c'est justifier par la génétique ce qui
// relève de la programmation.
//
// ⚠ DEUX REPÈRES SEULEMENT SONT IMPORTÉS, ET CE SONT CEUX DU CODE.
// A1 (0,46 ± 0,03) et A3 (0,45 ± 0,03) existaient avant ce lot. A6 porte le
// seul repère chiffré de l'étude qui soit assorti de sa condition — homme de
// plus de 1,65 m. LES TROIS AUTRES (A2, A4, A5) N'ONT PAS DE REPÈRE :
// l'étude en cite un pour A2 (« autour de 1,15–1,25 »), mais il porte sur les
// longueurs OSSEUSES fémur et tibia, pas sur ce qu'un mètre mesure debout.
// Entrejambe moins hauteur de genou n'est pas le fémur, et la hauteur de genou
// n'est pas le tibia : elle inclut le pied. Le rapport calculable tourne autour
// de 0,85, pas de 1,20. Reprendre le 1,15–1,25 ici serait un repère inventé —
// pire qu'un axe absent. Ces trois axes attendent donc un repère CALIBRÉ sur
// les athlètes réels du coach, et le disent tant qu'il n'existe pas.

// Ce que pèse chaque source (§7.1 de l'étude).
// Le mètre du coach vaut plus que celui de l'athlète, mais RepCore ne sait pas
// aujourd'hui lequel des deux a tenu le ruban : les mensurations arrivent par
// le bilan, que l'athlète remplit. On retient donc la valeur ATHLÈTE, la plus
// basse des deux — on ne s'attribue pas une précision qu'on ne peut pas
// prouver.
const MORPHO_CONF=Object.freeze({metre:0.75, photo:0.6, test:0.85, carnet:0.95});
// Sous ce seuil, l'axe ne sort pas et l'app dit ce qui le débloquerait.
const MORPHO_CONF_MIN=0.6;
// Mètre et photo qui divergent de plus de 10 % : on ne tranche pas.
const MORPHO_DESACCORD=0.10;
// En dessous, aucun axe OSSEUX n'est présenté : les proportions changent
// pendant la croissance.
const MORPHO_AGE_OSSEUX=18;
// Protocole, annexe A : « deux mesures ; si elles diffèrent de plus de 0,5 cm,
// une troisième ». C'est l'erreur de mesure que l'app s'autorise à propager.
const MORPHO_ERREUR_CM=0.5;
// En dessous de huit athlètes mesurés, aucun repère local : une médiane sur
// trois personnes n'est pas une population.
const MORPHO_CALIB_MIN=8;
// Une asymétrie demande un écart FRANC (au-delà du centimètre d'erreur
// technique sur un tour de membre) et RÉPÉTÉ sur trois bilans consécutifs,
// toujours du même côté.
const MORPHO_ASYM_CM=1;
const MORPHO_ASYM_BILANS=3;
// Le rapport à partir duquel un couple antagoniste cesse d'être une préférence
// d'exercices. C'est le seuil déjà retenu pour quadriceps / ischios, généralisé
// aux quatre autres couples comme l'étude le demande.
const MORPHO_DOM_SIGNAL=DOMINANCE_QI_SIGNAL;

/**
 * Les cinq couples antagonistes. Le premier existait déjà sous la forme de
 * dominanceQuadIschio, qui reste le point d'entrée d'origine et n'est pas
 * réécrit ; les quatre autres sont la généralisation demandée.
 */
const MORPHO_COUPLES=Object.freeze([
  {cle:'quad_ischio',a:'QUADRICEPS',b:'ISCHIOS',lib:'Quadriceps et ischios'},
  {cle:'pec_dos',a:'PECTORAUX',b:'DORSAUX',lib:'Pectoraux et dorsaux'},
  {cle:'delt',a:'DELT_ANT',b:'DELT_POST',lib:'Deltoïde antérieur et postérieur'},
  {cle:'bras',a:'BICEPS',b:'TRICEPS',lib:'Biceps et triceps'},
  {cle:'tronc',a:'ABDOS',b:'LOMBAIRES',lib:'Abdominaux et lombaires'}
]);
/** Les trois mensurations relevées des deux côtés à chaque bilan. */
const MORPHO_PAIRES=Object.freeze([
  {cle:'bicep',g:'bicep-l',d:'bicep-r',lib:'Biceps'},
  {cle:'thigh',g:'thigh-l',d:'thigh-r',lib:'Cuisse'},
  {cle:'calf',g:'calf-l',d:'calf-r',lib:'Mollet'}
]);

/**
 * Les neuf axes, dans l'ordre de lecture imposé. `segment` sert au garde-fou
 * G5 : un axe osseux n'est présenté qu'après les axes acquis et fonctionnels
 * DU MÊME SEGMENT.
 * `calibrable` : l'axe n'a pas de repère de population utilisable et attend
 * celui du coach.
 */
const MORPHO_AXES=Object.freeze([
  {cle:'A9',lib:'Histoire d’entraînement',court:'Entraînement',nature:'acquis',segment:'global'},
  {cle:'A7',lib:'Amplitude de cheville',court:'Cheville',nature:'fonctionnel',segment:'bas'},
  {cle:'A8',lib:'Amplitudes articulaires',court:'Articulations',nature:'fonctionnel',segment:'global'},
  {cle:'A1',lib:'Levier fémoral',court:'Fémur / tronc',nature:'osseux',segment:'bas'},
  {cle:'A2',lib:'Répartition de jambe',court:'Fémur / tibia',nature:'osseux',segment:'bas',calibrable:true},
  {cle:'A3',lib:'Levier brachial',court:'Bras / taille',nature:'osseux',segment:'haut'},
  {cle:'A4',lib:'Répartition de bras',court:'Humérus / avant-bras',nature:'osseux',segment:'haut',calibrable:true},
  {cle:'A5',lib:'Charpente scapulaire',court:'Épaules / bassin',nature:'osseux',segment:'haut',calibrable:true},
  {cle:'A6',lib:'Ossature',court:'Poignet',nature:'osseux',segment:'global',calibrable:true}
]);

/** PURE. La dernière valeur d'un champ de bilan, AVEC la date du bilan d'où
 *  elle vient : une valeur sans sa date ne peut pas porter sa source (G6). */
function _morphoChampDate(user,champ){
  const bl=((user&&user.bilans)||[]).filter(x=>x&&x.date).slice().sort((x,y)=>y.date-x.date);
  for(const x of bl){
    const v=x[champ];
    if(v!=null&&String(v).trim()!=='') return {brut:v,date:x.date};
  }
  return {brut:null,date:null};
}

/**
 * PURE. Arbitrage des sources pour une mesure : LE MÈTRE PRIME SUR LA PHOTO.
 * Les deux d'accord font monter la confiance ; les deux en désaccord de plus
 * de 10 % la font disparaître — on ne tranche pas, on demande une reprise.
 * @returns {{cm:number|null, source:string|null, date:number|null, conf:number, motif:string|null}}
 */
function _morphoSource(user,cle){
  const m=mesureMorpho(user,cle);
  const dm=m.cm!=null?_morphoChampDate(user,cle).date:null;
  const pm=(user&&user.morphoPhoto&&user.morphoPhoto.mesures
    &&typeof user.morphoPhoto.mesures==='object')?user.morphoPhoto.mesures:null;
  const ph=pm?pm[cle]:null;
  const pc=(ph&&isFinite(Number(ph.cm))&&Number(ph.cm)>0)?Number(ph.cm):null;
  const pd=(ph&&isFinite(Number(ph.date))&&Number(ph.date)>0)?Math.round(Number(ph.date)):null;
  if(m.cm!=null&&pc!=null){
    const ecart=Math.abs(m.cm-pc)/m.cm;
    if(ecart>MORPHO_DESACCORD)
      return {cm:null,source:null,date:null,conf:0,motif:'desaccord'};
    // D'accord : la photo confirme le mètre. La confiance monte, sans jamais
    // dépasser celle de la meilleure des deux sources.
    return {cm:m.cm,source:'metre',date:dm,conf:Math.min(0.9,MORPHO_CONF.metre+0.1),motif:null};
  }
  if(m.cm!=null) return {cm:m.cm,source:'metre',date:dm,conf:MORPHO_CONF.metre,motif:null};
  if(pc!=null) return {cm:pc,source:'photo',date:pd,conf:MORPHO_CONF.photo,motif:null};
  return {cm:null,source:null,date:null,conf:0,motif:m.motif||'absente'};
}

/** PURE. bas / neutre / haut. La marge est ATTEINTE, pas dépassée — même
 *  convention que _horsMarge, dont A1 et A3 continuent de dépendre. */
function _morphoPosition(v,ref,marge){
  if(v==null||ref==null||marge==null||!isFinite(v)) return null;
  if(v<=ref-marge+1e-9) return 'bas';
  if(v>=ref+marge-1e-9) return 'haut';
  return 'neutre';
}
/** PURE. Médiane d'une liste de nombres. */
function _morphoMediane(l){
  if(!l.length) return null;
  const t=l.slice().sort((a,b)=>a-b), m=t.length>>1;
  return t.length%2?t[m]:(t[m-1]+t[m])/2;
}

/**
 * PURE. LE REPÈRE LOCAL, calculé sur les athlètes réels du coach — la seule
 * réponse honnête pour les axes dont aucun repère de population publié ne
 * décrit ce que le mètre mesure ici.
 *
 * Médiane pour le centre (une faute de frappe ne la déplace pas), écart
 * interquartile ramené à un écart-type robuste pour la dispersion. La marge ne
 * descend jamais sous DEUX fois l'erreur de mesure propagée : sous ce plancher,
 * on classerait du bruit de ruban en morphologie.
 *
 * @param {any[]} athletes
 * @returns {Object<string,{ref:number,marge:number,n:number,date:number}>}
 */
function morphoCalibrage(athletes){
  const out={};
  const l=Array.isArray(athletes)?athletes:[];
  for(const a of MORPHO_AXES){
    if(!a.calibrable) continue;
    const vals=[],errs=[];
    for(const u of l){
      let r=null;
      try{ r=_morphoBrut(u,a.cle); }catch(e){ r=null; }
      if(r&&r.valeur!=null&&isFinite(r.valeur)){ vals.push(r.valeur); errs.push(r.erreur||0); }
    }
    if(vals.length<MORPHO_CALIB_MIN) continue;
    const t=vals.slice().sort((x,y)=>x-y);
    const q=(p)=>t[Math.min(t.length-1,Math.max(0,Math.round(p*(t.length-1))))];
    const sigma=(q(0.75)-q(0.25))/1.349;
    const plancher=2*(_morphoMediane(errs)||0);
    const ref=_morphoMediane(vals);
    out[a.cle]={ref:Math.round(ref*1000)/1000,
      marge:Math.round(Math.max(sigma,plancher)*1000)/1000,
      n:vals.length,date:Date.now()};
  }
  // LES RAPPORTS LUS SUR PHOTO, sur la même population et avec la même
  // discipline. Leur plancher de marge vient de la tolérance de lecture :
  // si les deux côtés du MÊME corps peuvent différer de 10 % avant qu'on
  // refuse la photo, la moitié de ça est le moins qu'on puisse exiger
  // avant de déclarer DEUX corps différents.
  for(const d of MORPHO_PHOTO_RAPPORTS){
    const vals=[];
    for(const u of l){
      let r=null;
      try{ r=_morphoRapportPhoto(u,d.axe); }catch(e){ r=null; }
      if(r) vals.push(r.valeur);
    }
    if(vals.length<MORPHO_CALIB_MIN) continue;
    const t=vals.slice().sort((x,y)=>x-y);
    const q=(p)=>t[Math.min(t.length-1,Math.max(0,Math.round(p*(t.length-1))))];
    const ref=_morphoMediane(vals);
    out[d.cle]={ref:Math.round(ref*1000)/1000,
      marge:Math.round(Math.max((q(0.75)-q(0.25))/1.349,ref*0.05)*1000)/1000,
      n:vals.length,date:Date.now()};
  }
  return out;
}

/**
 * PURE. La valeur BRUTE d'un axe et l'erreur de mesure qu'elle porte, avant
 * tout repère. C'est ce que le calibrage agrège et ce que morphoAxes habille.
 * @returns {{valeur:number|null, erreur:number, unite:string, source:string|null,
 *            date:number|null, conf:number, motif:string|null, aMesurer:string|null}|null}
 */
function _morphoBrut(user,cle){
  const E=MORPHO_ERREUR_CM;
  const t=_tailleCm(user);
  const manque=(txt)=>({valeur:null,erreur:0,unite:'',source:null,date:null,conf:0,
    motif:'absente',aMesurer:txt});
  // Combine deux sources : la plus ancienne des deux dates, la plus basse des
  // deux confiances. Une chaîne ne vaut pas mieux que son maillon faible.
  const duo=(a,b)=>({date:(a.date&&b.date)?Math.min(a.date,b.date):(a.date||b.date),
    source:(a.source==='photo'||b.source==='photo')?'photo':'metre',
    conf:Math.min(a.conf,b.conf)});
  if(cle==='A1'){
    const e=_morphoSource(user,'deb-entrejambe');
    if(e.motif==='desaccord') return {valeur:null,erreur:0,unite:'× taille',source:null,date:null,
      conf:0,motif:'desaccord',aMesurer:null};
    if(e.cm==null||!t) return manque('l’entrejambe, du sol au pubis, pieds nus et dos au mur');
    return {valeur:e.cm/t,erreur:E/t,unite:'× taille',source:e.source,date:e.date,conf:e.conf,
      motif:null,aMesurer:null};
  }
  if(cle==='A2'){
    const e=_morphoSource(user,'deb-entrejambe'), g=_morphoSource(user,'deb-genou');
    if(e.motif==='desaccord'||g.motif==='desaccord') return {valeur:null,erreur:0,unite:'',
      source:null,date:null,conf:0,motif:'desaccord',aMesurer:null};
    if(g.cm==null) return manque('la hauteur de genou, du sol au creux du genou — une minute au mur');
    if(e.cm==null) return manque('l’entrejambe, du sol au pubis, pieds nus et dos au mur');
    if(e.cm<=g.cm) return {valeur:null,erreur:0,unite:'',source:null,date:null,conf:0,
      motif:'incoherente',aMesurer:null};
    const v=(e.cm-g.cm)/g.cm;
    // Propagation : ∂v/∂E = 1/G, ∂v/∂G = −E/G². Un rapport bâti sur une
    // DIFFÉRENCE amplifie l'erreur — c'est pourquoi la marge a un plancher.
    const err=Math.sqrt(Math.pow(E/g.cm,2)+Math.pow(E*e.cm/(g.cm*g.cm),2));
    const d=duo(e,g);
    return {valeur:v,erreur:err,unite:'',source:d.source,date:d.date,conf:d.conf,
      motif:null,aMesurer:null};
  }
  if(cle==='A3'){
    const b=_morphoSource(user,'deb-bras');
    if(b.motif==='desaccord') return {valeur:null,erreur:0,unite:'× taille',source:null,date:null,
      conf:0,motif:'desaccord',aMesurer:null};
    if(b.cm==null||!t) return manque('la longueur de bras, de la pointe de l’épaule au poignet');
    return {valeur:b.cm/t,erreur:E/t,unite:'× taille',source:b.source,date:b.date,conf:b.conf,
      motif:null,aMesurer:null};
  }
  if(cle==='A4'){
    const b=_morphoSource(user,'deb-bras'), a=_morphoSource(user,'deb-avantbras');
    if(b.motif==='desaccord'||a.motif==='desaccord') return {valeur:null,erreur:0,unite:'',
      source:null,date:null,conf:0,motif:'desaccord',aMesurer:null};
    if(a.cm==null) return manque('l’avant-bras, coude plié à angle droit, de l’olécrane à la styloïde');
    if(b.cm==null) return manque('la longueur de bras, de la pointe de l’épaule au poignet');
    if(b.cm<=a.cm) return {valeur:null,erreur:0,unite:'',source:null,date:null,conf:0,
      motif:'incoherente',aMesurer:null};
    const v=(b.cm-a.cm)/a.cm;
    const err=Math.sqrt(Math.pow(E/a.cm,2)+Math.pow(E*b.cm/(a.cm*a.cm),2));
    const d=duo(b,a);
    return {valeur:v,erreur:err,unite:'',source:d.source,date:d.date,conf:d.conf,
      motif:null,aMesurer:null};
  }
  if(cle==='A5'){
    const e=_morphoSource(user,'deb-epaules'), b=_morphoSource(user,'deb-bassin');
    if(e.motif==='desaccord'||b.motif==='desaccord') return {valeur:null,erreur:0,unite:'',
      source:null,date:null,conf:0,motif:'desaccord',aMesurer:null};
    if(e.cm==null) return manque('la largeur d’épaules, d’un acromion à l’autre');
    if(b.cm==null) return manque('la largeur de bassin, d’une crête iliaque à l’autre');
    const v=e.cm/b.cm;
    const err=Math.sqrt(Math.pow(E/b.cm,2)+Math.pow(E*e.cm/(b.cm*b.cm),2));
    const d=duo(e,b);
    return {valeur:v,erreur:err,unite:'',source:d.source,date:d.date,conf:d.conf,
      motif:null,aMesurer:null,epaulesCm:e.cm,bassinCm:b.cm};
  }
  if(cle==='A6'){
    const p=_morphoSource(user,'deb-poignet');
    if(p.motif==='desaccord') return {valeur:null,erreur:0,unite:'cm',source:null,date:null,
      conf:0,motif:'desaccord',aMesurer:null};
    if(p.cm==null) return manque('le tour de poignet, juste sous l’os saillant, sans serrer');
    // Le calibrage travaille sur le rapport à la taille — un poignet de 17 cm
    // ne dit pas la même chose à 1,60 m et à 1,95 m. L'axe, lui, s'affiche en
    // centimètres, et le repère local se reconvertit à la taille de l'athlète.
    if(!t) return {valeur:p.cm,erreur:E,unite:'cm',source:p.source,date:p.date,conf:p.conf,
      motif:null,aMesurer:null};
    return {valeur:p.cm/t,erreur:E/t,unite:'× taille',source:p.source,date:p.date,conf:p.conf,
      motif:null,aMesurer:null,cm:p.cm,taille:t};
  }
  return null;
}

/**
 * PURE. Les volumes par muscle sur les dernières semaines ENTRAÎNÉES, lus UNE
 * fois pour les cinq couples. Mêmes bornes que dominanceQuadIschio, qui reste
 * le point d'entrée d'origine du couple quadriceps / ischios.
 */
function _morphoVolumes(user){
  const tot={}; let n=0,vides=0;
  for(let k=0;k<=26&&n<VOL_DELTA_N;k++){
    const c=_calculSemaine(user,_volCleDecalee(k));
    if(!c.eligibles){ if(++vides>=VOL_COUPURE) break; continue; }
    vides=0; n++;
    for(const m in c.muscles) tot[m]=(tot[m]||0)+(c.muscles[m]||0);
  }
  return n<VOL_DELTA_MIN?null:tot;
}
/**
 * PURE. Les couples antagonistes déséquilibrés. Un rapport à dénominateur nul
 * ne veut rien dire : le couple sort du calcul plutôt que de partir à l'infini.
 * @returns {{cle:string, lib:string, rapport:number, fort:string, faible:string}[]}
 */
function _morphoDominances(user){
  const out=[];
  let v=null;
  try{ v=_morphoVolumes(user); }catch(e){ v=null; }
  // NULL, PAS []. Un carnet trop court ne dit pas « rien à signaler » : il
  // ne dit rien du tout, et l'axe ne doit pas passer pour renseigné.
  if(!v) return null;
  for(const c of MORPHO_COUPLES){
    const a=v[c.a]||0, b=v[c.b]||0;
    if(!(a>0)||!(b>0)) continue;
    const r=a>=b?a/b:b/a;
    if(r<=MORPHO_DOM_SIGNAL) continue;
    out.push({cle:c.cle,lib:c.lib,rapport:Math.round(r*100)/100,
      fort:(a>=b?c.a:c.b),faible:(a>=b?c.b:c.a)});
  }
  return out.sort((x,y)=>y.rapport-x.rapport);
}
/**
 * PURE. Les asymétries gauche / droite SOUTENUES. Trois bilans consécutifs,
 * toujours du même côté, et un écart au-delà du centimètre d'erreur technique
 * d'un tour de membre auto-mesuré. En dessous, c'est du bruit de ruban — et
 * lancer une chasse à l'asymétrie sur du bruit est le plus sûr moyen de rendre
 * un athlète anxieux sur son corps.
 * @returns {{cle:string, lib:string, ecart:number, cote:string, bilans:number, date:number}[]}
 */
function _morphoAsymetries(user){
  const out=[];
  const bl=((user&&user.bilans)||[]).filter(b=>b&&b.date).slice().sort((a,b)=>b.date-a.date);
  for(const p of MORPHO_PAIRES){
    const ecarts=[],dates=[];
    for(const b of bl){
      const g=getBM(b,p.g), d=getBM(b,p.d);
      if(g==null||d==null||!(g>0)||!(d>0)) continue;
      ecarts.push(d-g); dates.push(b.date);
      if(ecarts.length>=MORPHO_ASYM_BILANS) break;
    }
    if(ecarts.length<MORPHO_ASYM_BILANS) continue;
    const franc=ecarts.every(e=>Math.abs(e)>MORPHO_ASYM_CM+1e-9);
    const memeCote=ecarts.every(e=>e>0)||ecarts.every(e=>e<0);
    if(!franc||!memeCote) continue;
    const moyen=ecarts.reduce((s,e)=>s+e,0)/ecarts.length;
    out.push({cle:p.cle,lib:p.lib,ecart:Math.round(Math.abs(moyen)*10)/10,
      cote:moyen>0?'droite':'gauche',bilans:ecarts.length,date:dates[0]});
  }
  return out.sort((a,b)=>b.ecart-a.ecart);
}

/** PURE. Un nombre écrit en français : la virgule, et pas le point. */
function _morphoVirgule(x){ return String(x).replace('.',','); }
/** PURE. « (mètre, 12/09/2026, ± 1 cm) » — G6 : source, date, tolérance. */
function _morphoAttribut(source,date,tol){
  const s=source==='metre'?'mètre':source==='photo'?'photo':source==='test'?'test'
    :source==='carnet'?'carnet':'';
  const l=[];
  if(s) l.push(s);
  if(date) l.push(new Date(date).toLocaleDateString('fr-FR'));
  if(tol) l.push('± '+_morphoVirgule(tol));
  return l.length?'('+l.join(', ')+')':'';
}
/** PURE. Un ratio, rendu lisible sans fausse précision. */
function _morphoNb(v,unite){
  if(v==null||!isFinite(v)) return '—';
  if(unite==='× taille') return Math.round(v*100)+' % de la taille';
  if(unite==='cm') return Math.round(v*10)/10+' cm';
  return String(Math.round(v*100)/100).replace('.',',');
}

/**
 * PURE. LES NEUF AXES D'UN ATHLÈTE. Toujours neuf, toujours dans l'ordre de
 * lecture — acquis, fonctionnel, osseux.
 *
 * Chaque axe porte sa valeur, sa source, sa date, sa tolérance et sa
 * confiance ; quand il ne peut pas conclure, il porte CE QU'IL FAUDRAIT
 * MESURER. « Je ne sais pas encore » est une sortie de première classe, et
 * elle est actionnable.
 *
 * @param {any} user
 * @param {{calibrage?:any, maintenant?:number}} [opts]
 * @returns {{cle:string, lib:string, court:string, nature:string, segment:string,
 *   valeur:number|null, unite:string, repere:number|null, marge:number|null,
 *   repereTexte:string|null, position:string|null, confiance:number,
 *   source:string|null, dateISO:string|null, tolerance:string|null,
 *   perime:boolean, manque:string|null, aMesurer:string|null, texte:string,
 *   facettes?:any, dominances?:any[], asymetries?:any[]}[]}
 */
function morphoAxes(user,opts){
  const o=opts||{};
  const now=Number(o.maintenant)||Date.now();
  const cal=(o.calibrage&&typeof o.calibrage==='object')?o.calibrage:{};
  let age=null;
  try{ age=ageActuel(user); }catch(e){ age=null; }
  const mineur=(age!=null&&age<MORPHO_AGE_OSSEUX);
  const tests=(function(){ try{ return testsMorpho(user,now); }catch(e){ return []; } })();
  const parCle={}; tests.forEach(t=>{ parCle[t.cle]=t; });
  const brut=(user&&user.morphoTests&&typeof user.morphoTests==='object')?user.morphoTests:{};

  return MORPHO_AXES.map(d=>{
    /** @type {any} */
    const a={cle:d.cle,lib:d.lib,court:d.court,nature:d.nature,segment:d.segment,
      valeur:null,unite:'',repere:null,marge:null,repereTexte:null,position:null,
      confiance:0,source:null,dateISO:null,tolerance:null,perime:false,
      manque:null,aMesurer:null,texte:''};

    // ── A9 · ACQUIS. Le premier axe à lire, et le seul entièrement sous
    //    contrôle : il vient du carnet, pas d'une mesure humaine.
    if(d.cle==='A9'){
      const brutDom=(function(){ try{ return _morphoDominances(user); }catch(e){ return null; } })();
      const dom=brutDom||[];
      const asy=(function(){ try{ return _morphoAsymetries(user); }catch(e){ return []; } })();
      const lu=(brutDom!==null)||asy.length>0;
      a.dominances=dom; a.asymetries=asy;
      a.source=lu?'carnet':null; a.confiance=lu?MORPHO_CONF.carnet:0;
      a.position=(dom.length||asy.length)?'haut':(lu?'neutre':null);
      a.dateISO=asy.length?new Date(asy[0].date).toISOString().slice(0,10):null;
      if(!dom.length&&!asy.length){
        a.manque=lu?'rien-a-signaler':'absente';
        if(!lu) a.aMesurer='assez de séances enregistrées pour que le compteur de volume parle';
        a.texte=lu?'Aucun déséquilibre de volume ni écart gauche / droite soutenu sur ce qui est enregistré.'
          :'Le carnet n’a pas encore assez de semaines entraînées pour dire ce que la programmation explique déjà.';
      } else {
        const p=[];
        dom.forEach(x=>p.push(x.lib.toLowerCase()+' à '+String(x.rapport).replace('.',',')+' pour 1'));
        asy.forEach(x=>p.push(x.lib.toLowerCase()+' : '+String(x.ecart).replace('.',',')
          +' cm de plus à '+x.cote+' sur '+x.bilans+' bilans'));
        a.texte=p.join(' · ')+' '+_morphoAttribut('carnet',asy.length?asy[0].date:null,null);
      }
      return a;
    }

    // ── A7 · FONCTIONNEL. Le test du genou au mur : trente secondes, et il
    //    doit être fait AVANT toute conclusion sur les leviers.
    if(d.cle==='A7'){
      const t=parCle['cheville'];
      const v=brut['cheville']&&isFinite(Number(brut['cheville'].cm))?Number(brut['cheville'].cm):null;
      a.unite='cm'; a.repere=10; a.marge=0;
      a.repereTexte='Un squat complet demande de l’ordre de 35 à 40° de flexion dorsale ; '
        +'sous 10 cm au mur, la contrainte devient visible en séance.';
      if(v==null||!t||!t.date){
        a.manque='absente';
        a.aMesurer='le test du genou au mur : trente secondes, pied nu, talon au sol';
        a.texte='Amplitude de cheville non relevée.';
        return a;
      }
      a.valeur=v; a.source='test'; a.confiance=MORPHO_CONF.test;
      a.dateISO=new Date(t.date).toISOString().slice(0,10);
      a.tolerance='1 cm'; a.perime=!!t.perime;
      a.position=v<10?'bas':'neutre';
      a.texte=Math.round(v)+' cm au mur '+_morphoAttribut('test',t.date,'1 cm')
        +(t.perime?' — périmé, à refaire':'');
      return a;
    }

    // ── A8 · FONCTIONNEL. Trois facettes : hanche, épaule, chaîne
    //    postérieure. L'étude nomme cet axe par la hanche et y rattache aussi
    //    l'épaule (P11) et les postérieurs (P12) — ce sont les trois mêmes
    //    tests, la même nature, et la même péremption.
    if(d.cle==='A8'){
      const f={};
      const th=parCle['hanche'], bh=brut['hanche']||{};
      f.hanche={position:null,texte:th?th.texte:'',dateISO:th&&th.date?new Date(th.date).toISOString().slice(0,10):null,
        perime:!!(th&&th.perime),butee:bh.butee||null};
      // ⚠ « BUTÉE NETTE » EST UN CONSTAT, pas une cause. Ce que cette butée
      //   est — os, capsule, muscle — demande une imagerie que personne n'ira
      //   faire. On décrit, on ne tranche pas.
      if(th&&th.date&&(bh.butee==='nette'||bh.butee==='elastique'))
        f.hanche.position=bh.butee==='nette'?'haut':'neutre';
      const te=parCle['epaule'], be=brut['epaule']||{};
      f.epaule={position:null,texte:te?te.texte:'',dateISO:te&&te.date?new Date(te.date).toISOString().slice(0,10):null,
        perime:!!(te&&te.perime),mur:be.mur||null};
      if(te&&te.date&&(be.mur==='oui'||be.mur==='non'))
        f.epaule.position=be.mur==='non'?'bas':'neutre';
      const tp=parCle['posterieur'], bp=brut['posterieur']||{};
      f.posterieur={position:null,texte:tp?tp.texte:'',dateISO:tp&&tp.date?new Date(tp.date).toISOString().slice(0,10):null,
        perime:!!(tp&&tp.perime),niveau:bp.niveau||null};
      if(tp&&tp.date&&bp.niveau) f.posterieur.position=bp.niveau==='bas'?'bas':'neutre';
      a.facettes=f;
      const faites=['hanche','epaule','posterieur'].filter(k=>f[k].dateISO);
      if(!faites.length){
        a.manque='absente';
        a.aMesurer='les tests de hanche, d’épaule et de flexion avant';
        a.texte='Aucun test d’amplitude articulaire relevé.';
        return a;
      }
      a.source='test'; a.confiance=MORPHO_CONF.test;
      a.dateISO=f[faites[0]].dateISO;
      a.perime=faites.some(k=>f[k].perime);
      a.position=f.hanche.position;
      a.texte=faites.map(k=>({hanche:'Hanche',epaule:'Épaule',posterieur:'Chaîne postérieure'})[k]
        +' : '+(f[k].texte||'—')+(f[k].perime?' (périmé)':'')).join(' · ');
      return a;
    }

    // ── A1 à A6 · OSSEUX. Rien de tout ceci n'est présenté à un mineur : les
    //    proportions changent pendant la croissance, et une phrase sur le
    //    squelette d'un adolescent ne décrit que son mois de mesure.
    const r=_morphoBrut(user,d.cle);
    if(mineur){
      a.manque='croissance';
      a.texte='Moins de '+MORPHO_AGE_OSSEUX+' ans : les proportions changent encore. '
        +'Aucun axe osseux n’est présenté avant la fin de la croissance.';
      return a;
    }
    if(!r) return a;
    a.unite=r.unite; a.aMesurer=r.aMesurer;
    if(r.valeur==null){
      a.manque=r.motif||'absente';
      a.texte=r.motif==='desaccord'
        ? 'Le mètre et la photo divergent de plus de '+Math.round(MORPHO_DESACCORD*100)
          +' % : aucun des deux n’est retenu tant que la mesure n’a pas été reprise.'
        : r.motif==='incoherente'
        ? 'Les deux mesures ne tiennent pas ensemble : aucun rapport n’est calculé dessus.'
        : (r.aMesurer?'Il manque '+r.aMesurer+'.':'Mesure absente.');
      return a;
    }
    a.valeur=r.valeur; a.source=r.source; a.confiance=r.conf;
    // LA LECTURE PHOTO EST ATTACHÉE AVANT LE REPÈRE, et non après : sans
    // repère calibré l'axe rend la main tout de suite, et la photo serait
    // perdue sur le chemin le plus fréquent.
    const rp=(function(){ try{ return _morphoRapportPhoto(user,d.cle); }catch(e){ return null; } })();
    if(rp){
      const cp=cal[rp.cle];
      a.photo={cle:rp.cle,lib:rp.lib,valeur:rp.valeur,
        position:cp?_morphoPosition(rp.valeur,cp.ref,cp.marge):null,
        dateISO:rp.date?new Date(rp.date).toISOString().slice(0,10):null};
    }
    if(r.epaulesCm!=null) a.epaulesCm=r.epaulesCm;
    if(r.bassinCm!=null) a.bassinCm=r.bassinCm;
    if(r.date) a.dateISO=new Date(r.date).toISOString().slice(0,10);

    // Le repère : celui du code pour A1 et A3, celui de l'étude pour A6 quand
    // sa condition est remplie, celui du coach partout ailleurs.
    let tol=null;
    if(d.cle==='A1'||d.cle==='A3'){
      a.repere=d.cle==='A1'?RATIO_JAMBES_REF:RATIO_BRAS_REF; a.marge=RATIO_MARGE;
      a.repereTexte='Repère de population autour de '+Math.round(a.repere*100)+' % de la taille, '
        +'à ± '+Math.round(RATIO_MARGE*100)+' points.';
      a.position=_morphoPosition(a.valeur,a.repere,a.marge);
      tol=Math.max(1,Math.ceil(r.erreur*100))+' point'+(Math.ceil(r.erreur*100)>1?'s':'')+' de %';
    } else if(d.cle==='A6'){
      const sexe=(user&&(user._evol_gender||user.gender))||'';
      const t=r.taille||_tailleCm(user);
      const c=cal[d.cle];
      if(!isFemale(sexe)&&t&&t>165){
        // Le seul repère chiffré de l'étude qui porte sa condition : fine sous
        // 16,5 cm de poignet, épaisse au-delà de 19, chez l'homme de plus de
        // 1,65 m. On l'applique là où il vaut, et nulle part ailleurs.
        a.unite='cm'; a.valeur=r.cm; tol=_morphoVirgule(MORPHO_ERREUR_CM)+' cm';
        a.repere=17.75; a.marge=1.25;
        a.repereTexte='Chez l’homme de plus de 1,65 m : ossature fine sous 16,5 cm de poignet, '
          +'épaisse au-delà de 19 cm.';
        a.position=_morphoPosition(r.cm,17.75,1.25);
      } else if(c){
        a.repere=c.ref; a.marge=c.marge;
        a.repereTexte='Repère calibré sur '+c.n+' athlètes suivis, le '
          +new Date(c.date).toLocaleDateString('fr-FR')+'.';
        a.position=_morphoPosition(a.valeur,a.repere,a.marge);
        tol=Math.max(1,Math.ceil(r.erreur*100))+' point'+(Math.ceil(r.erreur*100)>1?'s':'')+' de %';
      } else {
        a.manque='repere-conditionne';
        a.texte='Tour de poignet à '+_morphoNb(r.cm,'cm')+' '+_morphoAttribut(r.source,r.date,_morphoVirgule(MORPHO_ERREUR_CM)+' cm')
          +'. Le seul repère publié vaut pour l’homme de plus de 1,65 m ; ici il ne s’applique pas, '
          +'et il en faudrait un calibré sur les athlètes suivis.';
        return a;
      }
    } else {
      const c=cal[d.cle];
      if(!c){
        // ⚠ PAS DE REPÈRE, DONC PAS DE POSITION. La valeur est montrée — elle
        //   est juste, elle est datée — mais l'app ne dit pas si elle est
        //   haute ou basse, parce qu'elle ne le sait pas.
        a.manque='repere-a-calibrer';
        a.texte=_morphoNb(a.valeur,a.unite)+' '+_morphoAttribut(r.source,r.date,
          Math.round(r.erreur*100)/100+'')
          +'. Aucun repère de population ne décrit ce que le mètre mesure ici : il se calibrera '
          +'sur les athlètes suivis, à partir de '+MORPHO_CALIB_MIN+' mesurés.'
          +(a.photo?' '+a.photo.lib+' à '+_morphoVirgule(Math.round(a.photo.valeur*100)/100)
            +' '+_morphoAttribut('photo',rp?rp.date:null,null)+'.':'');
        return a;
      }
      a.repere=c.ref; a.marge=c.marge;
      a.repereTexte='Repère calibré sur '+c.n+' athlètes suivis, le '
        +new Date(c.date).toLocaleDateString('fr-FR')+'.';
      a.position=_morphoPosition(a.valeur,a.repere,a.marge);
      tol=_morphoVirgule(Math.round(r.erreur*100)/100);
    }
    a.tolerance=tol;
    a.texte=_morphoNb(a.valeur,a.unite)+' '+_morphoAttribut(r.source,r.date,tol)
      +(a.repereTexte?' — '+a.repereTexte:'');
    // LA PHOTO CONCLUT. Elle ne remplace rien : elle confirme ou elle
    // contredit. Et quand elle contredit franchement — l'un dit haut,
    // l'autre dit bas — on ne tranche pas, on suspend et on demande la
    // reprise. C'est la règle des sources en désaccord.
    if(rp&&a.photo){
      const pp=a.photo.position;
      const oppose=pp&&a.position&&pp!=='neutre'&&a.position!=='neutre'&&pp!==a.position;
      if(oppose){
        a.position=null; a.confiance=0; a.manque='desaccord';
        a.texte='Le mètre et la photo se contredisent sur cet axe : '
          +_morphoNb(a.valeur,a.unite)+' au ruban, '+rp.lib.toLowerCase()+' à '
          +_morphoVirgule(Math.round(rp.valeur*100)/100)+' sur la photo. Aucun des deux n’est '
          +'retenu tant que la mesure n’a pas été reprise.';
      } else if(pp){
        a.texte+=' · '+rp.lib+' à '+_morphoVirgule(Math.round(rp.valeur*100)/100)
          +' '+_morphoAttribut('photo',rp.date,null)
          +(pp===a.position?' — la photo confirme.':' — la photo ne contredit pas.');
      }
    }
    return a;
  });
}

// ══════════════ MORPHO — LOT M4 : LES QUATORZE FICHES ══════════════
//
// Des combinaisons FRÉQUENTES, pas un catalogue fermé. Neuf axes à trois
// positions font 19 683 combinaisons : ces quatorze-là sont celles qu'on
// rencontre, et « aucun profil marqué » reste le résultat le plus courant.
//
// ⚠ G1 — AUCUN EXERCICE N'EST INTERDIT. Le champ s'appelle `amenager`, jamais
//   « proscrit », et chaque aménagement porte SON RÉGLAGE et une variante du
//   même schéma moteur. Un exercice écarté sans réglage est un interdit
//   déguisé, et un interdit né d'un test de trente secondes devient permanent.
//
// ⚠ `piege` EST AFFICHÉ, pas commenté. C'est l'erreur que fait le coach qui
//   rencontre ce profil — la partie la plus utile de la fiche, et celle qu'on
//   serait tenté de garder pour soi.
//
// `schema` renvoie aux clés de SCHEMA_LIB : c'est par elles que _variantesSchema
// propose des exercices réellement présents dans le catalogue, plutôt que des
// noms écrits à la main qui finiraient par ne plus exister.
const MORPHO_PROFILS=Object.freeze([
  {cle:'P13',lib:'Dominance quadriceps / ischios installée',nature:'acquis',segment:'bas',
   axes:['A9'],signature:[{axe:'A9',positions:['haut'],dominance:'quad_ischio'}],
   signatureTexte:'Rapport de volume quadriceps / ischios au-delà de 2,0 sur les dernières semaines entraînées. Sur la photo de profil : cuisse développée devant, plate derrière.',
   mecanique:'Aucune. C’est une histoire de programmation, pas de morphologie — et c’est précisément pour ça qu’il faut la lire en premier.',
   privilegier:'Leg curl sous deux profils de résistance (allongé pour la position longue, assis pour la position courte), soulevé roumain, hip thrust, fentes longues.',
   amenager:[{quoi:'Rien à retirer',reglage:'on déplace des séries : les mêmes séances, une répartition différente. C’est la correction la moins coûteuse du document.',schema:'isolation-genou'}],
   accent:'Ramener le rapport sous 1,5 sur huit à douze semaines, et le vérifier avec le compteur de volume qui existe déjà.',
   specificite:'Le même raisonnement se généralise à tous les couples : pectoraux/dos, deltoïde antérieur/postérieur, biceps/triceps, abdominaux/lombaires.',
   piege:'Expliquer des ischios plats par « la génétique » alors que le carnet montre deux séries par semaine contre douze au quadriceps. L’ordre de lecture — acquis, fonctionnel, osseux — existe pour ça.'},

  {cle:'P14',lib:'Asymétrie latérale soutenue',nature:'acquis',segment:'global',
   axes:['A9'],signature:[{axe:'A9',positions:['haut'],asymetrie:true}],
   signatureTexte:'Écart droite/gauche sur biceps, cuisse ou mollet, soutenu sur au moins trois bilans consécutifs et supérieur à l’erreur de mesure. En vidéo : déviation latérale de la barre, appui inégal.',
   mecanique:'Sans objet — c’est un constat, pas une structure. Et il y a une asymétrie normale chez tout le monde.',
   privilegier:'Travail unilatéral, en commençant systématiquement par le côté faible et en alignant le côté fort sur son nombre de répétitions — pas l’inverse.',
   amenager:[{quoi:'Les mouvements bilatéraux lourds',reglage:'ils ne sont pas à retirer : on ajoute de l’unilatéral à côté, et Motion Lab sert à vérifier que la barre ne dérive plus.',schema:'fente'}],
   accent:'Réévaluation à trois bilans. Si l’écart ne bouge pas malgré le travail unilatéral, on arrête d’insister et on oriente vers un professionnel de santé si une gêne existe.',
   specificite:'Le seuil compte plus que le signal. Avec une erreur technique de l’ordre du centimètre sur un tour de bras auto-mesuré, un écart de 1 cm ne veut rien dire. Il faut un écart franc, répété, et jamais isolé.',
   piege:'Lancer une chasse à l’asymétrie sur du bruit de mesure. C’est le plus sûr moyen de rendre un athlète anxieux sur son corps — et c’est exactement ce qu’une app ne doit jamais faire.'},

  {cle:'P9',lib:'Cheville verrouillée',nature:'fonctionnel',segment:'bas',
   axes:['A7'],signature:[{axe:'A7',positions:['bas']}],
   signatureTexte:'Moins de ~10 cm au test du genou au mur. En vidéo : talons qui décollent au fond, buste qui plonge d’un coup, ou genoux qui rentrent : les trois compensations classiques d’une amplitude qu’on n’a pas.',
   mecanique:'Un squat complet demande de l’ordre de 35–40° de flexion dorsale. Sans elle, le corps emprunte l’amplitude ailleurs. La cause n’est pas toujours la souplesse : elle peut être articulaire. Le test dit qu’il manque de l’amplitude, pas pourquoi.',
   privilegier:'Presse à cuisses, hack squat, extension de jambes : le quadriceps se charge sans exiger la cheville. Squat talons surélevés : la méta-analyse montre un gain d’amplitude de cheville et de genou à partir d’environ 2,5 cm d’élévation, avec un effet dose.',
   amenager:[{quoi:'Squat pieds serrés profond',reglage:'cale de 2,5 cm, ou stance élargi avec pointes ouvertes',schema:'squat'},
     {quoi:'Fentes avant',reglage:'fentes arrière ou bulgares, qui demandent moins de flexion dorsale à l’avant',schema:'fente'}],
   accent:'Deux voies en parallèle : la cale pour s’entraîner aujourd’hui, le travail d’amplitude pour ne plus en avoir besoin. L’app doit dire lequel des deux elle propose — une cale est un contournement, pas un traitement.',
   specificite:'La cale n’est pas gratuite : la même méta-analyse montre qu’une élévation importante réduit l’amplitude de hanche et de tronc. On déplace le travail vers le quadriceps, on ne l’ajoute pas. À assumer explicitement.',
   piege:'Attribuer à la morphologie ce qui vient de la cheville. Le test du genou au mur prend trente secondes et doit être fait avant toute conclusion sur les leviers.'},

  {cle:'P10',lib:'Hanche à butée précoce',nature:'fonctionnel',segment:'bas',
   axes:['A8'],signature:[{axe:'A8',facette:'hanche',positions:['haut']}],
   signatureTexte:'Flexion de hanche qui bute franchement, avec bascule du bassin, et un arrêt net plutôt qu’élastique. Souvent une nette asymétrie entre rotation interne et externe. En squat : profondeur limitée quel que soit le stance, ou pincement à l’aine.',
   mecanique:'La structure de hanche varie énormément d’une personne à l’autre : l’orientation du col du fémur s’étale sur une trentaine de degrés, celle du cotyle autant. Concrètement, l’un squatte pointes presque droites et descend loin, l’autre bute tôt et a besoin d’ouvrir. Ce n’est pas de la souplesse à gagner.',
   privilegier:'La recherche du stance, méthodiquement : écartement et rotation des pointes testés par paliers, à charge légère, en notant la profondeur confortable. Puis les machines qui contournent l’amplitude — presse avec pieds hauts, hack, leg curl, extension.',
   amenager:[{quoi:'Squat profond imposé',reglage:'profondeur choisie, celle où il n’y a pas de pincement',schema:'squat'},
     {quoi:'Squat pieds serrés',reglage:'ouvrir les pointes et élargir le stance',schema:'squat'},
     {quoi:'Soulevé sumo',reglage:'prudence : il demande de la rotation externe que ce profil n’a pas forcément — à tester à charge légère avant de le programmer',schema:'charniere-hanche'}],
   accent:'Amplitude utile plutôt qu’amplitude maximale. Le travail en position longue se cherche sur des exercices où la hanche n’est pas la butée : leg curl allongé, fentes, presse.',
   specificite:'Distinguer butée osseuse et raideur demande une imagerie que personne n’ira faire. RepCore décrit le test et se tait sur la cause : « l’arrêt est net et s’accompagne d’une bascule du bassin » est un constat.',
   piege:'Prescrire des mois d’étirements de hanche contre une butée qui ne cédera pas. On n’allonge pas un os ; on irrite une articulation.'},

  {cle:'P11',lib:'Épaule à amplitude limitée',nature:'fonctionnel',segment:'haut',
   axes:['A8'],signature:[{axe:'A8',facette:'epaule',positions:['bas']}],
   signatureTexte:'Bras qui ne montent pas au mur sans décoller les lombaires ; main dans le dos limitée d’un côté. En vidéo : compensation lombaire au développé militaire, épaules qui montent aux oreilles en élévation.',
   mecanique:'L’amplitude manquante est empruntée à la colonne ou à la scapula. Ce n’est pas un défaut de force : c’est une contrainte de course.',
   privilegier:'Développés assis à dossier (le dossier empêche l’emprunt lombaire et le rend visible), haltères plutôt que barre (la trajectoire s’adapte), prise neutre, poulies pour les élévations.',
   amenager:[{quoi:'Développé nuque',reglage:'devant, ou à la machine : la trajectoire reste guidée et les lombaires n’ont plus à combler l’amplitude qui manque',schema:'poussee-verticale'},
     {quoi:'Tirage nuque',reglage:'devant : le dos travaille autant, et l’épaule n’a plus à aller chercher une rotation qu’elle n’a pas',schema:'tirage-vertical'},
     {quoi:'Prise très large au développé couché',reglage:'revenir vers 180 % de la largeur d’épaules',schema:'poussee-horizontale'},
     {quoi:'Dips profonds',reglage:'limiter la descente au point où l’épaule reste devant, sans chercher le fond',schema:'poussee-horizontale'}],
   accent:'Amplitude d’épaule travaillée à part, hors des séries lourdes, et réévaluée tous les deux mois. Tant qu’elle manque, la charge reste sur des trajectoires guidées.',
   specificite:'C’est le profil le plus évolutif du document : un athlète reconnu en janvier peut ne plus l’être en mai. Le profil porte donc une date de péremption.',
   piege:'Figer l’aménagement. Un exercice écarté pour cause d’amplitude et jamais rouvert devient un interdit permanent né d’un test de trente secondes.'},

  {cle:'P12',lib:'Chaîne postérieure raide — le faux mauvais tireur',nature:'fonctionnel',segment:'bas',
   axes:['A8'],signature:[{axe:'A8',facette:'posterieur',positions:['bas']}],
   signatureTexte:'Dos qui s’enroule tôt en flexion avant jambes tendues. Au soulevé : lombaires arrondies dès le départ, pas seulement sous fatigue.',
   mecanique:'Ce n’est pas un problème de levier : c’est une amplitude manquante. La différence est décisive parce que les deux réponses sont opposées : un levier défavorable se contourne par la variante, une raideur se travaille.',
   privilegier:'Départ surélevé (soulevé aux blocs, trap bar) pour charger dans l’amplitude disponible ; soulevé roumain à amplitude partielle, augmentée progressivement ; leg curl pour les ischios sans contrainte lombaire.',
   amenager:[{quoi:'Soulevé au sol lourd',reglage:'surélever la barre jusqu’à ce que le dos tienne',schema:'charniere-hanche'},
     {quoi:'Good morning',reglage:'plus tard, quand l’amplitude est revenue',schema:'charniere-hanche'},
     {quoi:'Jambes tendues au sol',reglage:'sur banc, amplitude choisie',schema:'charniere-hanche'}],
   accent:'Amplitude d’abord, charge ensuite. Et une réévaluation datée : ce profil doit disparaître en quelques mois si le travail est fait.',
   specificite:'À ne pas confondre avec un tronc long, qui produit la même image — un dos qui souffre au soulevé — pour une raison opposée. Le test de flexion avant les départage en dix secondes.',
   piege:'L’envoyer en sumo « parce que son dos s’arrondit ». Le sumo demande plus de rotation de hanche et ne règle pas une raideur postérieure ; il la cache.'},

  {cle:'P1',lib:'Fémur long, tronc court — le squatteur penché',nature:'osseux',segment:'bas',
   axes:['A1','A2'],signature:[{axe:'A1',positions:['haut']},{axe:'A2',positions:['haut']}],
   signatureTexte:'Entrejambe au-delà de ~49 % de la taille, et rapport fémur/tibia élevé. Sur la photo de profil : assis, les genoux montent au-dessus des hanches. En vidéo : le buste plonge dès le premier tiers de la descente.',
   mecanique:'Pour garder la charge au-dessus du milieu du pied, un fémur long oblige le bassin à reculer davantage, donc le buste à s’incliner. L’inclinaison raccourcit le bras de levier du genou et allonge celui de la hanche : à charge égale, ce squat sollicite les extenseurs de hanche plus qu’un squat droit. Ce n’est pas une faute technique, c’est la solution que la géométrie impose.',
   privilegier:'Tout ce qui découple genou et hanche — presse à cuisses, hack squat, squat bulgare, extension de jambes — parce qu’ils permettent de charger le quadriceps sans passer par l’inclinaison de buste. Et tout ce qui rentabilise le levier de hanche : soulevé de terre, charnière, fessiers.',
   amenager:[{quoi:'Squat barre haute profond',reglage:'barre basse ou squat guidé, stance élargi, pointes ouvertes, cale de 1,5 à 2,5 cm',schema:'squat'},
     {quoi:'Front squat',reglage:'souvent le plus pénalisant — la charge devant impose un buste droit qu’il n’a pas ; le remplacer par un hack ou une presse pieds bas',schema:'squat'},
     {quoi:'Fentes longues',reglage:'raccourcir le pas ou passer en bulgare',schema:'fente'}],
   accent:'Quadriceps par les machines et le travail unilatéral, pas par le squat libre. La charnière devient l’exercice fort : la programmer comme telle plutôt que de s’acharner sur un squat qui ne sera jamais son terrain.',
   specificite:'Ces athlètes sont systématiquement corrigés à tort sur « le buste trop penché ». Motion Lab tranche la question : si le bras de levier de hanche reste stable pendant la descente, l’inclinaison est structurelle ; si elle s’aggrave sous fatigue, c’est technique.',
   piege:'Lui vendre de la mobilité de cheville pendant six mois pour « redresser » son squat. Une cale règle en une séance ce qu’un fémur long ne lâchera jamais. Vérifier la cheville avant d’attribuer au fémur.'},

  {cle:'P2',lib:'Tronc long, jambes courtes — le levier de dos',nature:'osseux',segment:'bas',
   axes:['A1'],signature:[{axe:'A1',positions:['bas']}],
   signatureTexte:'Entrejambe sous ~43 % de la taille. Assis, la tête dépasse celle des autres ; debout, non. Photo de profil : tronc visuellement long par rapport aux jambes.',
   mecanique:'Le squat devient confortable — buste plus droit, profondeur peu chère. En revanche, en charnière de hanche, un tronc long est un long bras de levier horizontal : le soulevé de terre conventionnel coûte davantage aux lombaires à charge égale.',
   privilegier:'Squat sous toutes ses formes, y compris front squat et gobelet : c’est son terrain. Fentes, bulgares, travail de profondeur.',
   amenager:[{quoi:'Soulevé de terre conventionnel lourd',reglage:'sumo, ou départ surélevé, ou trap bar — la littérature va dans ce sens : un rapport tronc/taille plus élevé s’accompagne de meilleures performances en sumo',schema:'charniere-hanche'},
     {quoi:'Good morning lourd',reglage:'hip thrust ou charnière guidée',schema:'charniere-hanche'}],
   accent:'Quadriceps au squat libre, sans complexe. Chaîne postérieure par des exercices à bras de levier court — hip thrust, leg curl, extension lombaire réglée — plutôt que par le soulevé lourd.',
   specificite:'Le rapport tronc/membres compte plus que la taille absolue. Un grand athlète à tronc long et jambes courtes est un profil conventionnel ; c’est la proportion qui décide, pas le mètre.',
   piege:'Le pousser au soulevé conventionnel lourd parce qu’il squatte bien et qu’on suppose qu’il « devrait » tout bien faire. C’est exactement le mouvement où son levier joue contre lui.'},

  {cle:'P3',lib:'Tibia long — le squat qui ne coûte rien',nature:'osseux',segment:'bas',
   axes:['A2'],signature:[{axe:'A2',positions:['bas']}],
   signatureTexte:'Hauteur de genou élevée pour l’entrejambe. En vidéo : genoux très avancés au fond, buste presque droit, sans effort apparent.',
   mecanique:'Un tibia long autorise le genou à s’avancer davantage à profondeur égale, ce qui maintient le buste droit et garde le bras de levier sur le genou. La charge reste sur le quadriceps.',
   privilegier:'Squat profond, front squat, squat gobelet, hack. C’est le profil qui peut vraiment charger le quadriceps au squat libre.',
   amenager:[{quoi:'Peu de choses au squat',reglage:'en revanche, attention à la cheville : un genou très avancé demande beaucoup de flexion dorsale, et un tibia long amplifie la demande',schema:'squat'}],
   accent:'Ne pas gâcher l’avantage : le squat est ici un vrai exercice de quadriceps, pas un exercice global bricolé. Les ischios, eux, demanderont un travail dédié — ils ne suivront pas.',
   specificite:'Ce profil est souvent pris pour « doué ». Il est simplement bien proportionné pour ce mouvement-là. Le dire évite deux choses : qu’il se croie supérieur, et que les autres se croient limités.',
   piege:'Faire de son squat le modèle montré aux autres. Une vidéo envoyée à un athlète aux fémurs longs comme « voilà la bonne technique » produit six mois de frustration pour une géométrie inatteignable.'},

  {cle:'P4',lib:'Bras longs, grande envergure — le tireur',nature:'osseux',segment:'haut',
   axes:['A3'],signature:[{axe:'A3',positions:['haut']}],
   signatureTexte:'Longueur de bras au-delà de ~48 % de la taille. Envergure nettement supérieure à la taille. Photo de face : mains au-dessous de la mi-cuisse, bras le long du corps.',
   mecanique:'En poussée, un bras long allonge l’amplitude et le bras de levier à franchir : plus de travail mécanique pour la même charge, et une contrainte d’épaule plus longue. En tirage, la même longueur devient un avantage : plus d’amplitude utile, plus de temps sous tension pour le dos.',
   privilegier:'Tous les tirages — rowing, tirage horizontal, tirage vertical, pull-over. Et les poussées à amplitude bornée par la machine : développé convergent, presse à pectoraux, où la course n’est pas dictée par son bras.',
   amenager:[{quoi:'Développé couché barre',reglage:'prise autour de 180–200 % de sa largeur d’épaules, ce qui réduit l’amplitude et raccourcit le bras de levier ; haltères s’il a une gêne d’épaule en fin d’amplitude',schema:'poussee-horizontale'},
     {quoi:'Tractions lestées',reglage:'coûteuses (long bras de levier) : privilégier le tirage vertical guidé pour le volume',schema:'tirage-vertical'},
     {quoi:'Dips profonds',reglage:'limiter la descente : l’amplitude coûte déjà plus cher qu’aux autres, la chercher en plus n’ajoute rien',schema:'poussee-horizontale'}],
   accent:'Construire le haut du corps par le dos, qui est son terrain, et traiter les pectoraux par des machines et des écartés où l’amplitude est réglée plutôt que subie.',
   specificite:'C’est le profil pour lequel Motion Lab apporte le plus : la largeur de prise se règle en mesurant le bras de levier réel sur trois largeurs, plutôt qu’en appliquant un pourcentage.',
   piege:'Lire sa faiblesse au développé comme un manque de pectoraux et ajouter du volume de poussée. Il fait déjà plus de travail que les autres à charge égale : le problème est l’amplitude, pas le volume.'},

  {cle:'P5',lib:'Bras courts, humérus court — le pousseur',nature:'osseux',segment:'haut',
   axes:['A3','A4'],signature:[{axe:'A3',positions:['bas']},{axe:'A4',positions:['bas']}],
   signatureTexte:'Bras sous ~42 % de la taille, humérus court pour l’avant-bras. Au développé, la barre touche vite et la course paraît courte. Chiffres de charge élevés par rapport au reste du corps.',
   mecanique:'Amplitude courte, bras de levier court : la charge grimpe vite. L’inconvénient est symétrique : moins d’amplitude utile par répétition, donc moins de temps passé en position longue — la position qui compte le plus pour l’hypertrophie.',
   privilegier:'Poussées lourdes : développé couché, incliné, militaire. Et les tractions, où un bras court est un levier favorable.',
   amenager:[{quoi:'Rien n’est à retirer',reglage:'c’est un profil avantagé ; le réglage porte sur l’amplitude — planche sur la poitrine, écartés à grande amplitude, presse à pectoraux avec départ étiré — pour compenser la course courte',schema:'poussee-horizontale'},
     {quoi:'Tirages',reglage:'allonger la course plutôt que charger',schema:'tirage-horizontal'}],
   accent:'Amplitude avant charge. C’est le seul profil où le compteur de charge trompe : les kilos montent vite, le stimulus ne suit pas forcément. La position longue doit être recherchée exercice par exercice.',
   specificite:'Attention au dos : un bras court raccourcit aussi l’amplitude des tirages. C’est souvent le profil qui « ne sent pas son dos » — pas par manque de connexion, par manque de course.',
   piege:'Le féliciter sur ses charges et ne jamais regarder son amplitude. Deux ans plus tard, un développé énorme et des pectoraux moyens.'},

  {cle:'P6',lib:'Charpente étroite — le V à construire',nature:'osseux',segment:'haut',
   axes:['A5'],signature:[{axe:'A5',positions:['bas']}],
   signatureTexte:'Rapport épaules/bassin bas. À distinguer absolument d’un tour de taille élevé : le rapport osseux ne bouge pas avec le gras.',
   mecanique:'Moins de largeur osseuse au départ. Le V ne viendra pas de la charpente, donc il viendra du deltoïde latéral et de la largeur du grand dorsal — deux muscles qui répondent bien au volume et aux profils de résistance adaptés.',
   privilegier:'Élévations latérales à haute fréquence, sous plusieurs profils de résistance (poulie pour la position longue, haltère pour la position courte). Tirages prise large et pull-over pour la largeur de dos.',
   amenager:[{quoi:'Rien à écarter',reglage:'mais on hiérarchise : le développé militaire lourd construit moins de largeur visuelle que trois fois par semaine d’élévations bien placées',schema:'isolation-epaule'},
     {quoi:'Obliques chargés',reglage:'lever le pied — ils élargissent la taille et travaillent contre l’effet recherché',schema:'gainage-tronc'}],
   accent:'Deltoïde latéral en priorité absolue, puis largeur de dos, puis gestion du tour de taille. Dans cet ordre.',
   specificite:'C’est le profil où l’écart entre « mesure » et « photo » est le plus grand : le tour de bras peut stagner pendant que la silhouette change complètement. Suivre la photo, pas seulement le mètre.',
   piege:'Confondre charpente étroite et taille épaisse, et mettre l’athlète en déficit pour « faire ressortir le V » alors que le rapport osseux ne bougera pas d’un millimètre.'},

  {cle:'P7',lib:'Charpente large, bassin large — la densité d’abord',nature:'osseux',segment:'global',
   axes:['A5','A6'],signature:[{axe:'A5',positions:['neutre','haut']},{axe:'A6',positions:['haut']}],
   signatureTexte:'Largeur biacromiale et biiliaque élevées, poignet et cheville épais. Photo de face : carrure marquée même sans muscle.',
   mecanique:'Avantage visuel d’emblée sur la carrure, désavantage sur la finesse de taille — qui est osseuse elle aussi, en partie. Les circonférences seront élevées à masse musculaire égale : le mètre flatte, la définition trompe.',
   privilegier:'Tout le travail lourd polyarticulaire : la charpente le supporte bien. Densité et épaisseur — rowing lourd, développés, squat.',
   amenager:[{quoi:'Peu de contraintes mécaniques',reglage:'la vigilance porte sur le tour de taille : obliques chargés et respiration en poussée à surveiller si l’objectif est esthétique',schema:'gainage-tronc'}],
   accent:'Gestion de l’enveloppe. Sur ce profil, la composition corporelle pèse plus lourd que le choix d’exercice : un point de masse grasse se voit davantage.',
   specificite:'Objectifs de circonférence à recalibrer à la hausse — ils partent de plus haut et progressent moins vite en pourcentage. Un même gain de muscle donne un écart de mètre plus faible.',
   piege:'Comparer ses tours de bras à ceux d’une ossature fine et conclure qu’il « prend mieux ». À muscle égal, il mesure plus. Ce n’est pas la même chose.'},

  {cle:'P8',lib:'Ossature fine — le trompe-l’œil du mètre',nature:'osseux',segment:'global',
   axes:['A6'],signature:[{axe:'A6',positions:['bas']}],
   signatureTexte:'Poignet sous ~16,5 cm chez l’homme de plus de 1,65 m, cheville fine. Tours de bras et de mollet modestes malgré un entraînement sérieux et une masse grasse basse.',
   mecanique:'La circonférence mesure os + muscle + gras. Avec moins d’os, il faut plus de muscle pour le même chiffre. En contrepartie, la définition apparaît plus tôt et la silhouette paraît plus sèche à masse grasse égale.',
   privilegier:'Rien de particulier mécaniquement. C’est un profil de programmation et d’attentes, pas de réglage.',
   amenager:[{quoi:'Les objectifs, pas les exercices',reglage:'et le suivi : si le mètre est le seul indicateur, l’athlète conclura qu’il ne progresse pas. Croiser avec la photo et la charge soulevée.',schema:'isolation-epaule'}],
   accent:'Volume sur les groupes qui portent la silhouette — deltoïdes, dos, mollets — parce que chez lui, ce sont les proportions qui font l’effet visuel, pas les circonférences absolues.',
   specificite:'C’est le profil qui abandonne. Il faut lui donner le bon instrument de mesure dès le départ : rapport taille/bras, photo à éclairage constant, charge de travail — et lui expliquer pourquoi le centimètre lui ment.',
   piege:'Lui parler de « potentiel génétique » ou de « FFMI ». Un tour de poignet ne prédit aucun plafond : il change l’unité de mesure, pas le résultat atteignable. RepCore ne dira jamais le contraire.'}
]);

// ══════════════ MORPHO — LOT M3 : LA COMPOSITION, ET LE SILENCE ══════════════
//
// Un profil n'est pas CHOISI dans une liste : il est COMPOSÉ par les axes
// saillants. Et la partie qui décide de la crédibilité n'est pas celle qui
// nomme un profil — c'est celle qui sait se taire.
//
// ⚠ L'ORDRE DE LECTURE (G5) EST APPLIQUÉ MÉCANIQUEMENT, pas recommandé.
//   Acquis d'abord, fonctionnel ensuite, osseux en dernier. Et un profil
//   OSSEUX dont le segment porte un axe FONCTIONNEL saillant part avec la
//   phrase qui le dit : « regarde la cheville avant de conclure sur le
//   fémur ». Sans elle, on justifie par la génétique ce qui relève d'une
//   amplitude de trente secondes à mesurer — l'erreur la plus commune du
//   métier, et la seule vraiment grave.
//
// ⚠ « JE NE SAIS PAS ENCORE » EST UNE SORTIE DE PREMIÈRE CLASSE, et elle est
//   actionnable : « il manque la hauteur de genou pour te dire si c'est le
//   fémur ou le tibia — une minute au mur » vaut mieux qu'un profil inventé
//   sur l'entrejambe seul.

// Deux axes ne font pas un profil : ils font une impression.
const MORPHO_AXES_MIN=3;
// Les deux ou trois saillants les plus marqués. Au-delà, ce n'est plus une
// lecture, c'est un inventaire — et le coach décroche.
const MORPHO_PROFILS_MAX=3;
const MORPHO_ORDRE=Object.freeze({acquis:0,fonctionnel:1,osseux:2});
// Le sujet de chaque fiche osseuse, pour la phrase de renvoi.
const MORPHO_SUJET=Object.freeze({P1:'le fémur',P2:'le tronc',P3:'le tibia',
  P4:'les bras',P5:'les bras',P6:'la charpente',P7:'la charpente',P8:'l’ossature'});
// Ce qu'on nomme quand on renvoie vers un axe fonctionnel ou acquis, et ce
// qu'on dit quand il n'a jamais été mesuré.
const MORPHO_RENVOI=Object.freeze({A7:'la cheville',
  A8:'les amplitudes articulaires',A9:'le carnet'});
const MORPHO_RENVOI_ABSENT=Object.freeze({
  A7:'la cheville n’a pas été mesurée, et le test du genou au mur prend trente secondes',
  A8:'ni la hanche, ni l’épaule, ni la flexion avant n’ont été testées',
  A9:'le carnet n’a pas encore assez de semaines entraînées pour dire ce que la programmation explique déjà'});
// Ce qu'il faut avoir regardé avant de lire chaque fiche osseuse. L'ordre
// compte : on nomme le premier qui a quelque chose à dire.
const MORPHO_AVANT=Object.freeze({P1:['A7','A8','A9'],P2:['A7','A8','A9'],P3:['A7','A8','A9'],
  P4:['A8','A9'],P5:['A8','A9'],P6:['A9'],P7:['A9'],P8:['A9']});

/** PURE. De combien un axe sort de sa marge, en nombre de marges. Sert à
 *  classer les saillants « par écart au repère, décroissant ». Les axes
 *  qualitatifs — carnet, tests — n'ont pas de marge : ils comptent pour une. */
function _morphoEcart(a){
  if(!a||a.position==null||a.position==='neutre') return 0;
  if(a.valeur==null||a.repere==null||!a.marge) return 1;
  return Math.abs(a.valeur-a.repere)/a.marge;
}
/** PURE. La position d'un axe ou d'une de ses facettes. */
function _morphoPos(a,facette){
  if(!a) return null;
  if(!facette) return a.position;
  return (a.facettes&&a.facettes[facette])?a.facettes[facette].position:null;
}
function _morphoPerime(a,facette){
  if(!a) return false;
  if(!facette) return !!a.perime;
  return !!(a.facettes&&a.facettes[facette]&&a.facettes[facette].perime);
}

/**
 * PURE. Les profils composés à partir des neuf axes, et — tout aussi
 * important — ce qui manque pour en composer d'autres.
 *
 * @param {any[]} axes  la sortie de morphoAxes
 * @returns {{profils:any[], silence:string|null, saillants:any[],
 *            aRegarder:string[], aMesurer:string[], perime:string[]}}
 */
function morphoProfils(axes){
  const l=Array.isArray(axes)?axes:[];
  const parCle={}; l.forEach(a=>{ if(a&&a.cle) parCle[a.cle]=a; });
  const out={profils:[],silence:null,saillants:[],aRegarder:[],aMesurer:[],perime:[]};

  // Ce qu'il faudrait mesurer, quel que soit le reste : c'est la sortie la
  // plus utile quand il n'y a rien d'autre à dire.
  const vus={};
  l.forEach(a=>{
    if(a&&a.aMesurer&&!vus[a.aMesurer]){ vus[a.aMesurer]=1; out.aMesurer.push(a.aMesurer); }
    if(a&&a.manque==='repere-a-calibrer'){
      const t='un repère calibré pour « '+a.court+' » — il faut '+MORPHO_CALIB_MIN
        +' athlètes mesurés pour le poser';
      if(!vus[t]){ vus[t]=1; out.aMesurer.push(t); }
    }
    if(a&&a.manque==='desaccord'){
      const t='reprendre « '+a.court+' » : le mètre et la photo ne disent pas la même chose';
      if(!vus[t]){ vus[t]=1; out.aMesurer.push(t); }
    }
    if(a&&a.perime) out.perime.push(a.court);
  });

  // « Renseigné » veut dire CRU : une position posée sans confiance n'est pas
  // une donnée, et trois impressions ne valent pas mieux que deux.
  const renseignes=l.filter(a=>a&&a.position!=null&&a.confiance>=MORPHO_CONF_MIN-1e-9);
  out.saillants=l.filter(a=>a&&a.position!=null&&a.position!=='neutre'
    &&a.confiance>=MORPHO_CONF_MIN-1e-9)
    .slice().sort((x,y)=>_morphoEcart(y)-_morphoEcart(x));
  // SILENCE N° 1. Deux axes renseignés ne font pas un profil.
  if(renseignes.length<MORPHO_AXES_MIN){
    out.silence='moins-de-trois-axes';
    return out;
  }

  /** @type {any[]} */
  const trouves=[];
  for(const f of MORPHO_PROFILS){
    let ok=true, suspendu=false, confMin=1;
    for(const c of f.signature){
      const a=parCle[c.axe];
      if(!a){ ok=false; break; }
      if(c.dominance){
        if(!(a.dominances||[]).some(d=>d.cle===c.dominance)){ ok=false; break; }
      } else if(c.asymetrie){
        if(!(a.asymetries||[]).length){ ok=false; break; }
      } else {
        const p=_morphoPos(a,c.facette);
        if(p==null||c.positions.indexOf(p)<0){ ok=false; break; }
      }
      // SILENCE N° 2. Confiance sous 0,6 sur un axe de SIGNATURE — un axe
      // qu'on exige neutre ne signe rien, il conditionne : on ne lui demande
      // pas la même certitude.
      const exige=c.positions&&c.positions.indexOf('neutre')<0;
      if(exige&&a.confiance<MORPHO_CONF_MIN-1e-9){ ok=false; break; }
      if(exige) confMin=Math.min(confMin,a.confiance);
      // SILENCE N° 4. Un test périmé ne SUPPRIME pas le profil : il le
      // suspend, et l'app propose de refaire le test.
      if(_morphoPerime(a,c.facette)) suspendu=true;
    }
    if(!ok) continue;
    const ecart=f.signature.reduce((m,c)=>Math.max(m,_morphoEcart(parCle[c.axe])),0);
    trouves.push({fiche:f,suspendu,confiance:Math.round(confMin*100)/100,ecart});
  }
  // L'ORDRE DE LECTURE, puis l'écart au repère.
  trouves.sort((x,y)=>(MORPHO_ORDRE[x.fiche.nature]-MORPHO_ORDRE[y.fiche.nature])
    ||(y.ecart-x.ecart));

  // LA PHRASE DE RENVOI. Un profil osseux dont le segment porte un axe
  // fonctionnel saillant ne se lit pas seul, et le dit lui-même.
  const aSaillant=(a)=>out.saillants.indexOf(a)>=0;
  for(const t of trouves){
    const f=t.fiche;
    let avant=null;
    if(f.nature==='osseux'){
      const sujet=MORPHO_SUJET[f.cle]||'ce point';
      const ordre=MORPHO_AVANT[f.cle]||['A9'];
      // D'abord ce qui SORT : un axe saillant se nomme, avec sa valeur.
      const vu=ordre.map(k=>parCle[k]).find(a=>a&&aSaillant(a));
      if(vu) avant='Regarde '+(MORPHO_RENVOI[vu.cle]||vu.court.toLowerCase())
        +' avant de conclure sur '+sujet+' : '+vu.texte;
      else {
        // Sinon ce qui MANQUE : un levier ne s'invoque pas quand l'amplitude
        // du même segment n'a jamais été mesurée.
        const trou=ordre.find(k=>{ const a=parCle[k];
          return !a||a.position==null||a.confiance<MORPHO_CONF_MIN-1e-9; });
        if(trou&&MORPHO_RENVOI_ABSENT[trou])
          avant='Avant de conclure sur '+sujet+' : '+MORPHO_RENVOI_ABSENT[trou]+'.';
      }
    }
    out.profils.push({cle:f.cle,lib:f.lib,nature:f.nature,segment:f.segment,axes:f.axes,
      signatureTexte:f.signatureTexte,mecanique:f.mecanique,privilegier:f.privilegier,
      amenager:f.amenager,accent:f.accent,specificite:f.specificite,piege:f.piege,
      confiance:t.confiance,suspendu:t.suspendu,avant});
  }
  if(out.profils.length>MORPHO_PROFILS_MAX) out.profils.length=MORPHO_PROFILS_MAX;

  // CE QU'IL FAUT REGARDER, dans l'ordre. Les axes saillants d'abord par
  // nature, et rien d'inventé : chaque ligne est le texte d'un axe, avec sa
  // source et sa date.
  out.aRegarder=out.saillants.slice()
    .sort((x,y)=>(MORPHO_ORDRE[x.nature]-MORPHO_ORDRE[y.nature])||(_morphoEcart(y)-_morphoEcart(x)))
    .map(a=>a.court+' : '+a.texte);
  // SILENCE N° 5 ET 6 sont déjà rendus par morphoAxes — un mineur n'a aucun
  // axe osseux, une asymétrie dans le bruit n'existe pas. Il reste le cas le
  // plus fréquent, et c'est un résultat valide : aucune fiche ne correspond,
  // on présente LES AXES NUS, sans nom de profil.
  if(!out.profils.length) out.silence='aucun-profil-marque';
  return out;
}

/**
 * Les athlètes suivis par le coach courant, pour le calibrage. Non pure : elle
 * lit le cache. Le calibrage, lui, l'est — et c'est lui qui est testé.
 */
function _morphoAthletesDuCoach(){
  if(!currentUser||currentUser.role!=='coach') return [];
  const users=DB.get('users')||{};
  return Object.values(users).filter(u=>u&&u.coachId===currentUser.id&&u.role!=='coach');
}
/** Le calibrage du coach courant, calculé une fois par écran. */
function morphoCalibrageCoach(){
  try{ return morphoCalibrage(_morphoAthletesDuCoach()); }catch(e){ return {}; }
}


// ══════════════ MORPHO — LOT M5 : QUATRE ENTRÉES ══════════════
//
// Un profil qui ne change rien au programme du lundi ne sert à rien. Quatre
// endroits, et quatre seulement : la fiche coach, le choix d'exercice, le
// réglage, et le suivi du bilan.
//
// ⚠ G7 — RIEN NE DESCEND CÔTÉ ATHLÈTE, SAUF LA CONSIGNE D'EXÉCUTION.
//   « Cale de 2,5 cm sous les talons » est une consigne : utile, neutre,
//   exécutable. « Parce que tu as les fémurs longs » ne l'est pas. Un athlète
//   seul face à une phrase sur son squelette ne peut rien en faire d'autre que
//   s'en inquiéter — et le coach perd la conversation que cette phrase devait
//   ouvrir. Les fonctions de rendu de ce lot sont donc TOUTES gardées par le
//   rôle, et le réglage est la seule chose qui traverse.
//
// L'étude propose d'entrer aussi dans le bilan, côté athlète, pour lui
// rappeler « l'instrument de suivi pertinent pour son profil ». On ne le fait
// pas là : nommer un profil dans l'écran de saisie de l'athlète, c'est
// exactement ce que G7 interdit. L'instrument de suivi est rendu AU COACH,
// dans la fiche, à côté des mensurations qu'il lit.

// La largeur de prise au développé : 180 à 200 % de la largeur biacromiale.
// C'est le seul repère chiffré de programmation du document — et il ne devient
// actionnable que parce que A5 mesure la charpente. Affiché en INTERVALLE :
// « 1,9 × » donnerait une fausse précision à un repère qui est une plage.
const MORPHO_PRISE_MIN=1.8;
const MORPHO_PRISE_MAX=2.0;
// La cale sous les talons : effet à partir d'environ 2,5 cm, et effet dose
// au-delà. Elle n'est pas gratuite — elle réduit l'amplitude de hanche et de
// tronc. C'est écrit là où elle est proposée.
const MORPHO_CALE_CM=2.5;

/**
 * PURE. Les réglages que les axes rendent actionnables. Chacun porte SA
 * VALEUR, SA SOURCE et les schémas moteurs qu'il concerne — un réglage sans
 * schéma s'afficherait sur le curl comme sur le squat.
 * @param {any[]} axes  sortie de morphoAxes
 * @param {any[]} profils  sortie de morphoProfils().profils
 * @returns {{cle:string, lib:string, consigne:string, pourquoi:string, schemas:string[]}[]}
 */
function morphoReglages(axes,profils){
  const out=[];
  const l=Array.isArray(axes)?axes:[];
  const p=Array.isArray(profils)?profils:[];
  const par={}; l.forEach(a=>{ if(a&&a.cle) par[a.cle]=a; });
  const aP=(cle)=>p.some(x=>x.cle===cle);

  // LA PRISE AU DÉVELOPPÉ. Elle ne sort que si la largeur d'épaules a été
  // mesurée : un pourcentage sans la mesure qu'il multiplie est une phrase de
  // magazine.
  const a5=par['A5'];
  const largeur=(a5&&a5.epaulesCm)?a5.epaulesCm:null;
  if(largeur&&(aP('P4')||aP('P11')||aP('P5'))){
    const bas=Math.round(largeur*MORPHO_PRISE_MIN), haut=Math.round(largeur*MORPHO_PRISE_MAX);
    out.push({cle:'prise',lib:'Largeur de prise au développé',
      consigne:'Prise entre '+bas+' et '+haut+' cm, index à index.',
      pourquoi:'Le repère de performance se situe entre '+Math.round(MORPHO_PRISE_MIN*100)+' et '
        +Math.round(MORPHO_PRISE_MAX*100)+' % de la largeur d’épaules, soit '+largeur
        +' cm ici '+(a5.dateISO?'(mètre, '+_morphoJJMM(a5.dateISO)+')':'(mètre)')
        +'. À vérifier en séance : c’est une plage, pas un chiffre.',
      schemas:['poussee-horizontale']});
  }
  // LA CALE. Deux voies, et l'app dit laquelle elle propose.
  const a7=par['A7'];
  if(a7&&a7.position==='bas'){
    out.push({cle:'cale',lib:'Cale sous les talons',
      consigne:'Cale d’au moins '+String(MORPHO_CALE_CM).replace('.',',')+' cm sous les talons.',
      pourquoi:a7.texte+'. C’est un contournement, pas un traitement : la cale permet de '
        +'s’entraîner aujourd’hui, le travail d’amplitude de ne plus en avoir besoin — et les '
        +'deux se mènent en parallèle. Ce n’est pas gratuit : une élévation importante réduit '
        +'l’amplitude de hanche et de tronc — on déplace le travail vers le quadriceps, on ne l’ajoute pas.',
      schemas:['squat','fente']});
  }
  // LE STANCE. Il se trouve en salle, par paliers — pas au mètre.
  if(aP('P1')||aP('P10')){
    out.push({cle:'stance',lib:'Écartement et pointes',
      consigne:'Stance élargi, pointes ouvertes, à chercher par paliers à charge légère.',
      pourquoi:'La profondeur confortable se note à chaque palier ; on garde celle où il n’y a '
        +'pas de pincement. Le stance ne se déduit d’aucune mesure.',
      schemas:['squat']});
  }
  // LE DÉPART SURÉLEVÉ. Charger dans l'amplitude disponible, et la faire
  // remonter — pas l'inverse.
  if(aP('P12')){
    out.push({cle:'depart',lib:'Hauteur de départ au soulevé',
      consigne:'Barre surélevée jusqu’à la hauteur où le dos tient sans s’enrouler.',
      pourquoi:'L’amplitude manquante se travaille, elle ne se contourne pas par la variante : '
        +'on charge dans ce qui est disponible et on redescend la barre à mesure.',
      schemas:['charniere-hanche']});
  }
  return out;
}
/** PURE. « 12/09 » à partir d'un ISO court. */
function _morphoJJMM(iso){
  const m=/^(\d{4})-(\d{2})-(\d{2})$/.exec(String(iso||''));
  return m?m[3]+'/'+m[2]:String(iso||'');
}

/**
 * PURE. L'INSTRUMENT DE SUIVI. Sur certains profils, le centimètre ment — et
 * le dire au coach vaut mieux que de le laisser conclure à une stagnation.
 * @returns {string}
 */
function morphoInstrument(profils){
  const p=Array.isArray(profils)?profils:[];
  const a=(cle)=>p.some(x=>x.cle===cle);
  if(a('P8')&&a('P6'))
    return 'Ossature fine et charpente étroite : suivre le rapport taille/bras et la photo à '
      +'éclairage constant plutôt que les circonférences seules. Sur ce profil, le tour de bras '
      +'peut stagner pendant que la silhouette change complètement.';
  if(a('P8'))
    return 'Avec moins d’os, il faut plus de muscle pour le même chiffre au mètre : croiser avec '
      +'la photo et la charge soulevée, sinon le centimètre donnera l’impression d’une stagnation '
      +'qui n’existe pas.';
  if(a('P6'))
    return 'La charpente ne bouge pas avec le gras : suivre la photo à éclairage constant, et ne '
      +'pas lire un tour de taille comme une largeur d’épaules.';
  if(a('P7'))
    return 'À masse musculaire égale, les circonférences partent de plus haut et progressent moins '
      +'vite en pourcentage : les objectifs de tour de bras se recalibrent à la hausse.';
  if(a('P14'))
    return 'Réévaluation à trois bilans : un écart gauche / droite qui ne bouge pas malgré le '
      +'travail unilatéral n’a pas besoin d’un quatrième cycle d’insistance.';
  return '';
}

/**
 * La lecture morpho d'UN exercice, pour le coach qui le pose dans une séance.
 * Rend ce qu'il faut dire et rien d'autre : le profil concerné, son
 * aménagement AVEC son réglage, les variantes du même schéma, et le réglage
 * chiffré s'il en existe un.
 *
 * @param {any} user  l'athlète
 * @param {any} ex    l'exercice, ou son nom
 * @param {{calibrage?:any}} [opts]
 */
function morphoPourExercice(user,ex,opts){
  const vide={schema:null,lignes:[],variantes:[],reglages:[]};
  let schema=null;
  try{ schema=schemaDe(ex,user); }catch(e){ schema=null; }
  if(!schema) return vide;
  let axes=[],res={profils:[]};
  try{ axes=morphoAxes(user,opts); res=morphoProfils(axes); }catch(e){ return vide; }
  const lignes=[];
  for(const p of res.profils){
    for(const am of (p.amenager||[])){
      if(am.schema!==schema) continue;
      lignes.push({profil:p.cle,lib:p.lib,quoi:am.quoi,reglage:am.reglage,
        suspendu:!!p.suspendu,avant:p.avant||null});
    }
  }
  const reglages=morphoReglages(axes,res.profils).filter(r=>r.schemas.indexOf(schema)>=0);
  if(!lignes.length&&!reglages.length) return {schema,lignes:[],variantes:[],reglages:[]};
  let variantes=[];
  try{ variantes=_variantesSchema(schema,4).filter(n=>exKey(n)!==exKey((ex&&ex.name)||ex||'')); }catch(e){}
  return {schema,lignes,variantes:variantes.slice(0,3),reglages};
}

/**
 * Le bandeau morpho d'une carte d'exercice, dans l'éditeur de séance.
 * ⚠ CÔTÉ COACH SEULEMENT, et la garde est ICI : l'éditeur est PARTAGÉ avec
 *   l'athlète, qui y ouvre ses propres séances. Une garde qui ne vivrait que
 *   dans l'appelant n'en serait pas une.
 */
function _htmlMorphoExercice(ex){
  if(!currentUser||currentUser.role!=='coach'||!currentClientId) return '';
  let c=null;
  try{ c=getOwnedClient(currentClientId); }catch(e){ c=null; }
  if(!c) return '';
  let r=null;
  try{ r=morphoPourExercice(c,ex,{calibrage:_morphoCalCache()}); }catch(e){ return ''; }
  if(!r||(!r.lignes.length&&!r.reglages.length)) return '';
  const bloc=(titre,corps)=>'<div style="margin-bottom:7px">'
    +'<span style="color:var(--sub);font-weight:800">'+escapeHtml(titre)+' :</span> '
    +'<span style="color:var(--text-dim)">'+corps+'</span></div>';
  let h='';
  r.lignes.forEach(x=>{
    h+=bloc(x.quoi,escapeHtml(x.reglage)
      +(x.suspendu?' <span style="color:var(--orange)">(test à refaire)</span>':''));
    if(x.avant) h+='<div style="color:var(--text-faint);margin-bottom:7px">'+escapeHtml(x.avant)+'</div>';
  });
  r.reglages.forEach(x=>{
    h+=bloc(x.lib,'<span style="color:var(--text-strong);font-weight:700">'+escapeHtml(x.consigne)
      +'</span> '+escapeHtml(x.pourquoi));
  });
  if(r.variantes.length)
    h+=bloc('Variantes du même schéma',escapeHtml(r.variantes.join(', '))
      +' — à envisager à côté, jamais à la place.');
  return '<div style="background:#0c0c0c;border:1px solid var(--border);border-left:2px solid var(--arc-calm);'
    +'border-radius:var(--r-2);padding:10px 12px;margin:0 0 12px;font-size:var(--fs-xs);line-height:1.6">'
    +'<div style="color:var(--sub);letter-spacing:1.2px;font-weight:800;text-transform:uppercase;'
    +'margin-bottom:6px;font-size:var(--fs-2xs)">Proportions — pour toi, pas pour lui</div>'+h+'</div>';
}
/** Le calibrage, calculé une fois par rendu d'écran et non par carte. */
let _morphoCal=null, _morphoCalT=0;
function _morphoCalCache(){
  const now=Date.now();
  if(_morphoCal&&now-_morphoCalT<30000) return _morphoCal;
  _morphoCal=morphoCalibrageCoach(); _morphoCalT=now;
  return _morphoCal;
}

/**
 * LA FICHE COACH — premier point d'entrée. Les axes, les profils composés, et
 * ce qu'il resterait à mesurer.
 *
 * ⚠ ZONE DE LECTURE. Aucun bouton, aucun onclick, et RIEN DU TOUT quand il n'y
 *   a rien à dire : le relevé des amplitudes se fait dans l'onglet Données.
 * ⚠ Rien de ceci n'est rendu côté athlète — un test le vérifie sur le HTML
 *   produit par l'accueil et l'écran de progression.
 */
function _htmlMorphoLecture(user,cal){
  let axes=[],res=null;
  try{ axes=morphoAxes(user,{calibrage:cal||null}); res=morphoProfils(axes); }catch(e){ return ''; }
  if(!res) return '';
  // ⚠ RIEN À MONTRER, RIEN DE MONTRÉ. « Il manque la hauteur de genou »
  // est vrai de presque tous les dossiers : afficher ça seul ferait un
  // cadre permanent, et deux assertions l'interdisent depuis longtemps.
  if(!res.profils.length&&!res.aRegarder.length) return '';
  const E=escapeHtml;
  const titre=(t)=>'<div style="font-size:var(--fs-xs);color:var(--sub);letter-spacing:1.2px;'
    +'font-weight:800;text-transform:uppercase;margin:14px 0 6px">'+E(t)+'</div>';
  let h='';

  // LES PROFILS, dans l'ordre de lecture. Chacun porte sa phrase de renvoi
  // avant sa propre matière : « regarde la cheville avant de conclure ».
  if(res.profils.length){
    h+=titre('Profils composés');
    h+=res.profils.map(p=>{
      const am=(p.amenager||[]).map(a=>'<div style="margin-top:3px"><span style="color:var(--text-strong);'
        +'font-weight:700">'+E(a.quoi)+' :</span> <span style="color:var(--text-dim)">'
        +E(a.reglage)+'</span></div>').join('');
      return '<div style="border-left:2px solid var(--arc-calm);padding-left:11px;margin-bottom:14px">'
        +'<div style="font-size:var(--fs-sm);font-weight:800;color:var(--text-strong);line-height:1.5">'
        +E(p.lib)+(p.suspendu?' <span style="color:var(--orange);font-weight:700">· test à refaire</span>':'')
        +'</div>'
        +(p.avant?'<div style="font-size:var(--fs-sm);color:var(--orange);line-height:1.6;margin-top:4px;'
          +'font-weight:600">'+E(p.avant)+'</div>':'')
        +'<div style="font-size:var(--fs-xs);color:var(--text-faint);line-height:1.55;margin-top:4px">'
        +E(p.signatureTexte)+'</div>'
        +'<div style="font-size:var(--fs-sm);color:var(--text-dim);line-height:1.6;margin-top:6px">'
        +E(p.mecanique)+'</div>'
        +'<div style="font-size:var(--fs-sm);line-height:1.6;margin-top:6px"><span style="color:var(--sub);'
        +'font-weight:800">Privilégier :</span> <span style="color:var(--text-dim)">'+E(p.privilegier)+'</span></div>'
        +(am?'<div style="font-size:var(--fs-sm);line-height:1.6;margin-top:6px"><span style="color:var(--sub);'
          +'font-weight:800">Aménager, jamais retirer :</span>'+am+'</div>':'')
        +'<div style="font-size:var(--fs-sm);line-height:1.6;margin-top:6px"><span style="color:var(--sub);'
        +'font-weight:800">Accent :</span> <span style="color:var(--text-dim)">'+E(p.accent)+'</span></div>'
        // LE PIÈGE EST AFFICHÉ. C'est la partie la plus utile de la fiche, et
        // celle qu'on serait tenté de garder pour soi.
        +'<div style="font-size:var(--fs-sm);line-height:1.6;margin-top:6px;background:#0c0c0c;'
        +'border-radius:var(--r-2);padding:8px 10px"><span style="color:var(--red);font-weight:800">'
        +'Le piège :</span> <span style="color:var(--text-dim)">'+E(p.piege)+'</span></div>'
        +'</div>';
    }).join('');
  } else if(res.silence==='moins-de-trois-axes'){
    h+=titre('Profils composés');
    h+='<div style="font-size:var(--fs-sm);color:var(--text-dim);line-height:1.6">Moins de trois axes '
      +'renseignés : deux axes ne font pas un profil, ils font une impression.</div>';
  } else if(res.silence==='aucun-profil-marque'){
    h+=titre('Profils composés');
    h+='<div style="font-size:var(--fs-sm);color:var(--text-dim);line-height:1.6">Aucun profil marqué — '
      +'c’est le résultat le plus fréquent, et c’en est un.</div>';
  }

  // CE QU'IL FAUT REGARDER, dans l'ordre imposé : acquis, fonctionnel, osseux.
  if(res.aRegarder.length){
    h+=titre('À regarder, dans cet ordre');
    h+=res.aRegarder.map((t,i)=>'<div style="font-size:var(--fs-sm);color:var(--text-dim);line-height:1.6;'
      +'margin-bottom:3px">'+(i+1)+'. '+E(t)+'</div>').join('');
  }
  // CE QU'IL RESTERAIT À MESURER. « Je ne sais pas encore » est une sortie de
  // première classe, et celle-ci est actionnable.
  // ⚠ UNE SEULE LIGNE, ET NON LA LISTE (lot 6, 23/09/2026 : « c'est
  //   decourageant, et c'est faux : il en manque rarement huit »). La premiere
  //   de la liste est deja celle qui debloque le plus — morphoAMesurer les rend
  //   dans cet ordre. Les suivantes reviendront d'elles-memes, une a une.
  if(res.aMesurer.length){
    h+=titre('Il manque, pour aller plus loin');
    h+='<div style="font-size:var(--fs-sm);color:var(--text-dim);line-height:1.6;'
      +'margin-bottom:3px">'+E(res.aMesurer[0])+'</div>';
    if(res.aMesurer.length>1)
      h+='<div style="font-size:var(--fs-2xs);color:var(--text-faint);line-height:1.55;'
        +'margin-top:3px">Celle-ci d’abord : '+(res.aMesurer.length-1)+' autre'
        +(res.aMesurer.length>2?'s':'')+' suivra'+(res.aMesurer.length>2?'ont':'')
        +', une à la fois.</div>';
  }
  const inst=morphoInstrument(res.profils);
  if(inst){
    h+=titre('L’instrument de suivi');
    h+='<div style="font-size:var(--fs-sm);color:var(--text-dim);line-height:1.6">'+E(inst)+'</div>';
  }
  return h;
}


// ══════════════ MORPHO — LOT M6 : LA PHOTO, ET SES LIMITES ══════════════
//
// La photo n'apporte PAS de centimètres — voir le commentaire de mlMorphoPhoto
// dans motion-lab.js : sans le sommet du crâne, il n'y a pas d'échelle, et
// aucun coefficient crâne/taille n'est sourçable ici. Elle apporte deux
// RAPPORTS sans échelle, cuisse/jambe et humérus/avant-bras, pris d'un repère
// osseux à un repère osseux, sans ruban.
//
// ⚠ LE MÈTRE GAGNE TOUJOURS. Le rapport photo ne remplace jamais la mesure :
//   il la CONFIRME ou la CONTREDIT. Et quand il la contredit franchement —
//   l'un dit fémur dominant, l'autre tibia dominant — on ne tranche pas :
//   l'axe est suspendu et la reprise est demandée. C'est la règle §7.3 des
//   sources en désaccord, appliquée à la lettre.

/** Les deux rapports que la photo sait rendre, et l'axe qu'ils éclairent. */
const MORPHO_PHOTO_RAPPORTS=Object.freeze([
  {cle:'A2photo',axe:'A2',lib:'Cuisse sur jambe'},
  {cle:'A4photo',axe:'A4',lib:'Humérus sur avant-bras'}
]);
/** Une lecture de photo vaut ce que vaut une photo : la confiance de l'étude. */
const MORPHO_PHOTO_CONF=0.6;

/** PURE. Le rapport photo enregistré pour un axe, s'il existe. */
function _morphoRapportPhoto(user,axe){
  const src=(user&&user.morphoPhoto&&typeof user.morphoPhoto==='object')?user.morphoPhoto:null;
  const r=(src&&src.rapports&&typeof src.rapports==='object')?src.rapports:null;
  const d=MORPHO_PHOTO_RAPPORTS.find(x=>x.axe===axe);
  const v=(r&&d)?r[d.cle]:null;
  if(!v||!isFinite(Number(v.v))||!(Number(v.v)>0)) return null;
  return {cle:d.cle,lib:d.lib,valeur:Number(v.v),
    date:(isFinite(Number(v.date))&&Number(v.date)>0)?Math.round(Number(v.date)):null};
}

/**
 * Lit la photo de face du dernier bilan d'un athlète et enregistre ce qu'elle
 * dit. CÔTÉ COACH uniquement, et rien n'est écrit tant que le contrôle de
 * prise de vue n'est pas passé.
 */
async function lireMorphoPhoto(email){
  const users=DB.get('users')||{};
  const c=users[email];
  if(!c||!currentUser||c.coachId!==currentUser.id){
    toast('Élève introuvable ou non autorisé','var(--orange)'); return false;
  }
  const bl=(Array.isArray(c.bilans)?c.bilans:[]).filter(b=>b&&b.date).slice().sort((a,b)=>b.date-a.date);
  let src=null,dateBilan=null;
  for(const b of bl){
    // UNE SEULE PORTE DE LECTURE : photoBilanSrc connait les quatre
    // rangements qui ont existe, dont la reference neuve {cle,w,h,url}.
    const p=photoBilanSrc(b,'face');
    if(p){ src=p; dateBilan=b.date; break; }
  }
  if(!src){ toast('Aucune photo de face dans les bilans.','var(--orange)'); return false; }
  toast('Lecture de la photo…');
  try{ await chargerMotionLab(); }catch(e){ toast(e.message||'Motion Lab indisponible','var(--orange)'); return false; }
  const lire=/** @type {any} */(window).mlMorphoPhoto;
  if(typeof lire!=='function'){ toast('Lecture de photo indisponible','var(--orange)'); return false; }
  let r=null;
  try{ r=await lire(src); }catch(e){ r=null; }
  if(!r||!r.ok){
    toast(r&&r.code==='moteur'?'Le moteur de pose n’a pas pu se charger.'
      :r&&r.code==='personne'?'Aucune silhouette reconnue sur cette photo.'
      :'La photo n’a pas pu être lue.','var(--orange)');
    return false;
  }
  _morphoPhotoVue={email,date:dateBilan,prise:r.prise,rapports:r.rapports||[],
    pixels:r.pixels||null};
  if(!r.rapports||!r.rapports.length){
    _ampRendre();
    toast('Photo lue, mais rien n’en sort : '+(r.prise.raisons[0]||'prise de vue'),'var(--orange)');
    return false;
  }
  const out={};
  r.rapports.forEach(x=>{ out[x.cle]={v:x.valeur,date:dateBilan||Date.now()}; });
  const avant=(c.morphoPhoto&&typeof c.morphoPhoto==='object')?c.morphoPhoto:{};
  // LES PIXELS DE L'ECHELLE SONT GARDES AVEC LES RAPPORTS (lot 7) : ils ne
  // valent que pour CETTE photo, et sans eux il faudrait la relire a chaque
  // ouverture de l'ecran pour reafficher un centimetre.
  c.morphoPhoto=Object.assign({},avant,{rapports:out},
    r.pixels?{pixels:r.pixels,pixelsDate:dateBilan||Date.now()}:{});
  c.updatedAt=Date.now();
  users[email]=c;
  const ok=DB.set('users',users);
  _ampRendre();
  toastSync(ok,CLOUD.pushOne(email,c),'Photo lue ✓','la lecture de photo est');
  return true;
}
/** La dernière lecture, pour l'afficher sans la relire. @type {any} */
let _morphoPhotoVue=null;

// ══ LOT 7 : LA MESURE DU GENOU, ET L'ECHELLE DE LA PHOTO ═══════════════════
//
// Kevin, 23/09/2026 : « Une seule mesure nouvelle, au PREMIER bilan uniquement.
// Intitule exact : "Du sol au milieu de la rotule, pieds nus, dos au mur,
// jambes tendues." »
//
// POURQUOI CELLE-LA : c'est le seul repere que le ruban et la photo trouvent au
// MEME endroit. Le modele de pose rend le centre du genou, qui se projette au
// milieu de la rotule vu de face ; le sol est donne par le talon.
//
// ⚠ ET C'EST UNE MESURE NEUVE, PAS L'ANCIENNE REECRITE. `deb-genou` existe
//   depuis le lot M1 avec un tout autre protocole : « du sol au creux du
//   genou ». Le creux est DERRIERE la jambe, invisible de face, et deux a trois
//   centimetres plus bas que le centre articulaire. Changer la consigne sous la
//   meme cle aurait melange, dans la meme colonne, des mesures prises a deux
//   endroits differents — et personne n'aurait pu savoir laquelle est laquelle.
//   L'ancienne garde sa cle, ses valeurs et sa consigne ; la nouvelle porte la
//   sienne, et c'est elle qui met la photo a l'echelle.
const MORPHO_ROTULE='deb-rotule';
// LE SCHEMA DE LA MESURE, en SVG : le mur, le sol, la jambe tendue, et la
// fleche qui monte du sol au milieu de la rotule. Kevin : « avec un schema si
// tu peux ». Un protocole ecrit se lit de six facons ; un dessin en montre une.
const MORPHO_ROTULE_SCHEMA=
  '<svg viewBox="0 0 120 96" width="120" height="96" aria-hidden="true"'
  +' style="display:block;margin:2px 0 6px">'
  // le mur, a gauche, et le sol
  +'<path d="M14 4 V92" stroke="rgba(255,255,255,.22)" stroke-width="2" fill="none"/>'
  +'<path d="M6 92 H114" stroke="rgba(255,255,255,.35)" stroke-width="2" fill="none"/>'
  // la jambe : cuisse, genou, tibia, pied nu au sol
  +'<path d="M46 10 V44" stroke="#8a8a8a" stroke-width="7" stroke-linecap="round" fill="none"/>'
  +'<path d="M46 52 V86" stroke="#8a8a8a" stroke-width="6" stroke-linecap="round" fill="none"/>'
  +'<path d="M43 88 H62" stroke="#8a8a8a" stroke-width="5" stroke-linecap="round" fill="none"/>'
  // la rotule, au milieu du genou
  +'<circle cx="46" cy="48" r="7" fill="#0c0c0c" stroke="var(--red)" stroke-width="2"/>'
  +'<circle cx="46" cy="48" r="1.8" fill="var(--red)"/>'
  // la fleche du sol au milieu de la rotule
  +'<path d="M86 48 V90 M82 86 l4 5 4-5 M82 52 l4-5 4 5" stroke="var(--red)"'
  +' stroke-width="1.8" fill="none" stroke-linecap="round" stroke-linejoin="round"/>'
  +'<path d="M50 48 H86" stroke="rgba(224,32,32,.45)" stroke-width="1"'
  +' stroke-dasharray="3 3" fill="none"/>'
  +'</svg>';
// ── L'ECHELLE, ET SON GARDE-FOU ────────────────────────────────────────────
//
// ⚠ LES 93 % NE DOIVENT JAMAIS ENTRER DANS UNE VALEUR AFFICHEE. C'est un
//   GARDE-FOU, pas une mesure : la hauteur des yeux vaut « environ » 93 % de la
//   taille debout, et cet « environ » couvre plusieurs centimetres d'un
//   individu a l'autre. Multiplier une taille par 0,93 pour en tirer un
//   centimetre serait inventer une mesure que personne n'a prise. Il ne sert
//   qu'a une chose : comparer DEUX echelles et refuser la photo quand elles se
//   contredisent. Toute autre utilisation est une faute, et ce commentaire est
//   la pour qu'elle ne se fasse pas par distraction.
const MORPHO_YEUX_PART=0.93;
// Au-dela, les deux echelles ne decrivent pas la meme photo : corps de profil,
// genou flechi, talon hors cadre, objectif trop pres. On ne publie rien.
const MORPHO_ECHELLE_ECART_MAX=0.04;
// La marge d'un centimetre issu de la photo ne descend jamais sous celle du
// ruban qui a servi a l'echelle : elle en herite.
const MORPHO_PHOTO_MARGE_MIN=0.5;
/**
 * PURE. L'echelle de la photo, ou la raison de n'en pas avoir.
 *
 * cm par pixel = mesure du genou (cm) / distance talon-genou (px).
 *
 * @param {any} u le dossier de l'athlete
 * @param {any} px la sortie de mlMorphoPixels
 * @returns {{cmPx:number,genouCm:number,genouPx:number,ecart:number|null,
 *            taille:number|null}|{motif:string}}
 */
function morphoEchellePhoto(u,px){
  if(!px||!(Number(px.genou)>0)) return {motif:'pixels'};
  const m=mesureMorpho(u,MORPHO_ROTULE);
  if(m.cm==null) return {motif:'mesure'};
  const cmPx=m.cm/px.genou;
  const taille=_tailleCm(u);
  // LE CONTROLE : la seconde echelle, tiree de la taille debout deja saisie.
  let ecart=null;
  if(taille&&Number(px.yeux)>0){
    const cmPx2=(taille*MORPHO_YEUX_PART)/px.yeux;
    ecart=Math.abs(cmPx2-cmPx)/((cmPx2+cmPx)/2);
    if(ecart>MORPHO_ECHELLE_ECART_MAX)
      return {motif:'divergence',ecart:Math.round(ecart*1000)/1000,
        taille:taille,genouCm:m.cm,genouPx:px.genou};
  }
  return {cmPx:cmPx,genouCm:m.cm,genouPx:px.genou,
    ecart:(ecart==null)?null:Math.round(ecart*1000)/1000,taille:taille};
}
// Les quatre segments que la photo sait mesurer une fois a l'echelle.
const MORPHO_PHOTO_SEGMENTS=Object.freeze([
  {cle:'cuisse',lib:'Cuisse (hanche au genou)'},
  {cle:'jambe',lib:'Jambe (genou à la cheville)'},
  {cle:'bras',lib:'Bras (épaule au coude)'},
  {cle:'avantbras',lib:'Avant-bras (coude au poignet)'}
]);
/**
 * PURE. Les longueurs en centimetres, ou rien.
 *
 * ⚠ LA MARGE N'EST PAS DECORATIVE : c'est l'ecart entre les deux echelles,
 *   porte sur la longueur, et jamais moins que le demi-centimetre du ruban qui
 *   a donne l'echelle. Sans second controle (pas de taille debout), la marge
 *   prend l'ecart maximal tolere : on ne fait pas passer une echelle non
 *   verifiee pour une echelle verifiee.
 * @returns {{cm:number,marge:number,lib:string,cle:string}[]}
 */
function morphoLongueursPhoto(u,px){
  const e=morphoEchellePhoto(u,px);
  if(e.motif) return [];
  const part=(e.ecart==null)?MORPHO_ECHELLE_ECART_MAX:Math.max(e.ecart,0.005);
  const out=[];
  for(const s of MORPHO_PHOTO_SEGMENTS){
    const n=Number(px[s.cle])||0;
    if(!(n>0)) continue;
    const cm=n*e.cmPx;
    out.push({cle:s.cle,lib:s.lib,cm:Math.round(cm*10)/10,
      marge:Math.round(Math.max(cm*part,MORPHO_PHOTO_MARGE_MIN)*10)/10});
  }
  return out;
}
// CE QUE L'ECRAN DIT DE L'ECHELLE : la valeur et sa source, ou le refus et sa
// raison. Jamais un centimetre quand les deux echelles se contredisent.
function _htmlMorphoEchelle(u,px){
  const E=escapeHtml;
  const e=morphoEchellePhoto(u,px);
  const cadre=(txt,couleur)=>'<p style="font-size:var(--fs-sm);line-height:1.6;'
    +'margin-bottom:10px;color:'+couleur+'">'+txt+'</p>';
  if(e.motif==='pixels')
    return cadre('Pas d’échelle : la photo ne montre pas le talon et le genou '
      +'des deux côtés, ou le corps est tourné.','var(--text-dim)');
  if(e.motif==='mesure')
    return cadre('Pas d’échelle : il manque la hauteur du sol au milieu de la '
      +'rotule, à prendre une fois au premier bilan.','var(--text-dim)');
  if(e.motif==='divergence')
    return cadre('Photo non exploitable : les deux repères ne donnent pas la '
      +'même échelle ('+E(_synNombre(e.ecart*100))+' % d’écart, au-delà des '
      +_synNombre(MORPHO_ECHELLE_ECART_MAX*100)+' % admis). Aucun centimètre '
      +'n’est publié. À refaire de face, bien en pied, talons visibles.','var(--orange)');
  const l=morphoLongueursPhoto(u,px);
  return cadre('Échelle : '+E(_synNombre(e.genouCm))+' cm du sol au milieu de la '
      +'rotule, sur '+E(_synNombre(e.genouPx))+' pixels'
      +((e.ecart!=null)?(', vérifiée à '+E(_synNombre(e.ecart*100))+' % près par la taille debout'):'')
      +'.','var(--text-dim)')
    +(l.length?('<div style="font-size:var(--fs-sm);color:var(--text-strong);line-height:1.7;'
      +'margin-bottom:10px">'+l.map(x=>'<div>'+E(x.lib)+' : '+E(_synNombre(x.cm))
      +' cm, à ± '+E(_synNombre(x.marge))+' cm près</div>').join('')+'</div>'):'');
}
// ══ LOT 8 : L'ANALYSE MORPHO, AUTOMATIQUE ET FIGEE ═════════════════════════
//
// Kevin, 23/09/2026 : « Declenchement automatique a l'enregistrement du PREMIER
// bilan, quand les trois photos et la mesure du genou sont la. Aucun clic de
// l'athlete. Aux bilans suivants : rien. La morphologie d'un adulte ne bouge
// pas. »
//
// ⚠ CE QUI SORT : femur, tibia, humerus, avant-bras, tronc, en centimetres avec
//   leur marge, et les rapports.
// ⚠ CE QUI NE SORT PAS, ET CE N'EST PAS UN OUBLI : largeur d'epaules, largeur
//   de bassin, longueur de clavicule. Le modele de pose rend le CENTRE
//   ARTICULAIRE de l'epaule et de la hanche, pas l'acromion ni la crete
//   iliaque : une largeur prise entre deux centres articulaires est plus
//   courte de plusieurs centimetres, et la difference n'est pas constante d'un
//   corps a l'autre. La clavicule, elle, n'est detectee par rien. UNE ECHELLE
//   NE CORRIGE PAS UN POINT MAL PLACE : mise a l'echelle, une largeur fausse
//   devient une largeur fausse en centimetres. Si quelqu'un est tente d'en
//   ajouter une ici, la reponse est non, et elle est ecrite.
const MORPHO_INIT_SEGMENTS=Object.freeze([
  {cle:'femur',px:'cuisse',lib:'Fémur (hanche au genou)'},
  {cle:'tibia',px:'jambe',lib:'Tibia (genou à la cheville)'},
  {cle:'humerus',px:'bras',lib:'Humérus (épaule au coude)'},
  {cle:'avantbras',px:'avantbras',lib:'Avant-bras (coude au poignet)'},
  {cle:'tronc',px:'tronc',lib:'Tronc (épaules aux hanches)'}
]);
// Les largeurs interdites, nommees pour que la regle soit verifiable par un
// test et pas seulement lisible dans un commentaire.
const MORPHO_INIT_INTERDITS=Object.freeze(['epaules','bassin','clavicule']);
// Moins de vingt ans : il grandit encore. On PROPOSE de refaire, une fois par
// an, et seulement dans ce cas.
const MORPHO_INIT_AGE_CROISSANCE=20;
const MORPHO_INIT_AN=365*864e5;
/**
 * PURE. L'etat de l'analyse initiale d'un dossier.
 * 'gelee'   : elle a reussi, elle ne se refait plus jamais toute seule.
 * 'attente' : aucune photo n'est encore passee. On retentera au bilan suivant.
 * 'absente' : rien n'a encore ete tente.
 */
function morphoInitialeEtat(u){
  const m=u&&u.morphoInitiale;
  if(!m||typeof m!=='object') return 'absente';
  return (m.etat==='gelee')?'gelee':'attente';
}
// PURE. Vrai quand il faut (re)tenter : jamais si c'est gele.
function morphoInitialeARefaire(u){ return morphoInitialeEtat(u)!=='gelee'; }
/**
 * PURE. La photo de face sur laquelle lire, et le bilan d'ou elle vient.
 *
 * ⚠ LE PREMIER BILAN D'ABORD, MEME AU DIXIEME. C'est la morphologie INITIALE
 *   qu'on gele, et le premier bilan est celui ou la mesure du genou a ete
 *   prise. Si sa photo ne passe pas le controle, on prend la plus recente qui
 *   existe : un os ne change pas de longueur entre deux bilans, et « seulement
 *   le premier bilan » ne doit pas vouloir dire « une seule chance ».
 *
 * ⚠ ET IL FAUT LES TROIS PHOTOS, PAS SEULEMENT CELLE DE FACE. Kevin, le
 *   24/09/2026 : « garde le vert et le rouge et les 3 photos ». J'avais
 *   declenche sur la seule photo que l'analyse LIT ; la regle est qu'un bilan
 *   n'est complet qu'avec face, profil et dos, et une morphologie ne se gele
 *   pas sur un bilan a moitie rempli. Un bilan qui n'en porte que deux est
 *   saute ; l'etat reste « attente » et le suivant est essaye.
 * @returns {{src:string,date:number,depart:boolean}|null}
 */
function morphoPhotoInitiale(u,rang){
  let bl=[]; try{ bl=(Array.isArray(u&&u.bilans)?u.bilans:[]).filter(b=>b&&b.date); }catch(e){ return null; }
  bl=bl.filter(b=>{
    try{ return BILP_VUES.every(v=>photoBilanExiste(b,v)); }catch(e){ return false; }
  });
  if(!bl.length) return null;
  const dep=bl.filter(b=>b.type==='depart').sort((a,b)=>a.date-b.date);
  const reste=bl.filter(b=>b.type!=='depart').sort((a,b)=>b.date-a.date);
  const ordre=dep.concat(reste);
  const n=Math.max(0,Number(rang)||0);
  let vus=0;
  for(const b of ordre){
    let src=null;
    try{ src=photoBilanSrc(b,'face'); }catch(e){ src=null; }
    if(!src) continue;
    if(vus++<n) continue;
    return {src:src,date:Number(b.date)||0,depart:b.type==='depart'};
  }
  return null;
}
/**
 * PURE. Ce que l'analyse gele, a partir de ce que la photo a rendu.
 * Aucun octet d'image : la photo n'est designee que par la date de son bilan.
 * @returns {{etat:string,date:number,cmParPx:number,controleEcart:number|null,
 *            longueurs:Object,rapports:Object,photoRef:Object}
 *           |{etat:'attente',date:number,raison:string,essais:number}}
 */
function morphoInitialeDe(u,r,photo,essais){
  const n=Math.max(1,Number(essais)||1);
  const attente=(raison)=>({etat:'attente',date:Date.now(),raison:String(raison||''),essais:n});
  if(!r||!r.ok) return attente((r&&r.code==='personne')?'aucune silhouette reconnue'
    :(r&&r.code==='moteur')?'le moteur de pose ne s’est pas chargé':'la photo n’a pas pu être lue');
  const pr=r.prise||{};
  if(pr.verdict==='a_refaire')
    return attente('prise de vue à refaire'+((pr.raisons&&pr.raisons.length)?' : '+pr.raisons[0]:''));
  const px=r.pixels;
  if(!px) return attente('le talon et le genou ne sont pas visibles des deux côtés');
  const e=morphoEchellePhoto(u,px);
  if(e.motif==='mesure') return attente('il manque la hauteur du sol au milieu de la rotule');
  if(e.motif==='pixels') return attente('le talon et le genou ne sont pas visibles des deux côtés');
  if(e.motif==='divergence')
    return attente('les deux repères ne donnent pas la même échelle ('
      +_synNombre(e.ecart*100)+' % d’écart)');
  const longueurs={};
  const part=(e.ecart==null)?MORPHO_ECHELLE_ECART_MAX:Math.max(e.ecart,0.005);
  for(const s of MORPHO_INIT_SEGMENTS){
    const v=Number(px[s.px])||0;
    if(!(v>0)) continue;
    const cm=v*e.cmPx;
    longueurs[s.cle]={cm:Math.round(cm*10)/10,
      marge:Math.round(Math.max(cm*part,MORPHO_PHOTO_MARGE_MIN)*10)/10};
  }
  if(!Object.keys(longueurs).length) return attente('aucun segment lisible sur la photo');
  const rapports={};
  for(const x of (r.rapports||[])) if(x&&x.cle) rapports[x.cle]=x.valeur;
  return {etat:'gelee',date:Date.now(),
    cmParPx:Math.round(e.cmPx*10000)/10000,
    controleEcart:(e.ecart==null)?null:e.ecart,
    longueurs:longueurs,rapports:rapports,
    photoRef:{bilan:(photo&&photo.date)||0,vue:'face',depart:!!(photo&&photo.depart)},
    essais:n};
}
/**
 * L'analyse elle-meme : elle lit une photo, et n'ecrit rien.
 * @returns {Promise<any>} l'objet morphoInitiale a poser, ou null si rien a faire
 */
async function morphoAnalyserInitiale(u,rang){
  if(!u) return null;
  const photo=morphoPhotoInitiale(u,rang);
  if(!photo) return {etat:'attente',date:Date.now(),
    raison:'aucun bilan ne porte les trois photos',essais:(((u.morphoInitiale||{}).essais)||0)+1};
  try{ await chargerMotionLab(); }catch(e){
    return {etat:'attente',date:Date.now(),raison:'le moteur de pose ne s’est pas chargé',
      essais:(((u.morphoInitiale||{}).essais)||0)+1};
  }
  const lire=(typeof window!=='undefined')?window.mlMorphoPhoto:null;
  if(typeof lire!=='function') return {etat:'attente',date:Date.now(),
    raison:'lecture de photo indisponible',essais:(((u.morphoInitiale||{}).essais)||0)+1};
  let r=null;
  try{ r=await lire(photo.src); }catch(e){ r=null; }
  return morphoInitialeDe(u,r,photo,(((u.morphoInitiale||{}).essais)||0)+1);
}
/**
 * LE DECLENCHEMENT AUTOMATIQUE, a l'enregistrement d'un bilan.
 *
 * ⚠ IL NE BLOQUE RIEN. Le bilan est deja ecrit quand cette fonction part ; le
 *   chargement du moteur de pose prend plusieurs secondes et peut echouer.
 *   Si la page se ferme avant la fin, rien n'est ecrit et l'etat reste
 *   « attente » : on retentera au bilan suivant, ce qui est exactement la
 *   regle demandee.
 * ⚠ ET JAMAIS SUR UNE ANALYSE GELEE. « Aux bilans suivants : rien. »
 */
function morphoInitialePeutEtre(u){
  if(!u||!morphoInitialeARefaire(u)) return false;
  // La mesure du genou d'abord : sans elle il n'y a pas d'echelle, et charger
  // le moteur de pose pour s'en apercevoir serait plusieurs megaoctets pour
  // rien. Le lot 6 la reclame par ailleurs.
  if(mesureMorpho(u,MORPHO_ROTULE).cm==null) return false;
  if(!morphoPhotoInitiale(u,0)) return false;
  setTimeout(async()=>{
    try{
      const m=await morphoAnalyserInitiale(u,0);
      if(!m) return;
      const users=DB.get('users')||{};
      const cle=u.email;
      const dossier=(cle&&users[cle])||u;
      dossier.morphoInitiale=m;
      dossier.updatedAt=Date.now();
      if(cle){ users[cle]=dossier; DB.set('users',users); CLOUD.pushOne(cle,dossier); }
      if(currentUser&&currentUser.email===cle) currentUser.morphoInitiale=m;
    }catch(e){}
  },0);
  return true;
}
/**
 * LE GESTE DU COACH, et lui seul : « pour le cas ou la photo etait valide mais
 * mauvaise ». Jamais automatique, meme sur une analyse gelee.
 */
async function refaireMorphoInitiale(email){
  const users=DB.get('users')||{};
  const c=users[email];
  if(!c||!currentUser||c.coachId!==currentUser.id){
    toast('Élève introuvable ou non autorisé','var(--orange)'); return false;
  }
  if(mesureMorpho(c,MORPHO_ROTULE).cm==null){
    toast('Il manque la hauteur du sol au milieu de la rotule.','var(--orange)'); return false;
  }
  toast('Analyse de la photo…');
  // ⚠ ON PREND LA PHOTO SUIVANTE, pas la meme : « la photo etait valide mais
  //   mauvaise » veut dire qu'elle a passe le controle et qu'elle ne vaut rien.
  //   La relire donnerait le meme resultat.
  const rang=(c.morphoInitiale&&c.morphoInitiale.photoRef)?1:0;
  let m=null;
  try{ m=await morphoAnalyserInitiale(c,rang); }catch(e){ m=null; }
  if(!m||m.etat!=='gelee'){
    toast('Rien de lu : '+((m&&m.raison)||'la photo n’a pas pu être lue'),'var(--orange)');
    return false;
  }
  c.morphoInitiale=m;
  c.updatedAt=Date.now();
  users[email]=c;
  const ok=DB.set('users',users);
  try{ _ampRendre(); }catch(e){}
  toastSync(ok,CLOUD.pushOne(email,c),'Analyse refaite ✓','l’analyse est');
  return true;
}
// ── CE QUE L'ECRAN EN DIT ──────────────────────────────────────────────────
//
// ⚠ UN REPERE MANQUANT SE DIT AVEC SON COMPTE. « Un trou muet passe pour un
//   bug, un trou qui s'explique passe pour du serieux. » Et on n'importe
//   JAMAIS un repere trouve ailleurs pour debloquer un axe : on agrandit la
//   base, on ne pose pas un chiffre.
function morphoCalibrageCompte(athletes,cle){
  const l=Array.isArray(athletes)?athletes:[];
  let n=0;
  for(const u of l){
    let r=null;
    try{ r=_morphoRapportPhoto(u,cle); }catch(e){ r=null; }
    if(r) n++;
  }
  return n;
}
function _htmlMorphoInitiale(u,athletes){
  const E=escapeHtml;
  const etat=morphoInitialeEtat(u);
  const m=u&&u.morphoInitiale;
  const bouton='<button type="button" class="btn btn-outline" style="width:100%;margin:8px 0 0" '
    +'onclick="refaireMorphoInitiale(\''+escapeHtml((u&&u.email)||'')+'\')">Refaire l’analyse</button>';
  if(etat==='absente')
    return '<p style="font-size:var(--fs-sm);color:var(--text-dim);line-height:1.6;margin:0">'
      +'Analyse pas encore faite : elle part toute seule au premier bilan qui porte '
      +'une photo de face et la hauteur du sol au milieu de la rotule.</p>';
  if(etat==='attente')
    return '<p style="font-size:var(--fs-sm);color:var(--orange);line-height:1.6;margin:0">'
      +'Analyse en attente : '+E(m.raison||'la photo n’est pas exploitable')+'. '
      +'Elle sera retentée au prochain bilan, et à chaque bilan tant qu’aucune photo '
      +'ne passe.</p>'+bouton;
  const l=MORPHO_INIT_SEGMENTS.filter(s=>m.longueurs&&m.longueurs[s.cle]);
  const jour=(t)=>{ try{ return new Date(Number(t)||0).toLocaleDateString('fr-FR'); }catch(e){ return ''; } };
  let age=null; try{ age=ageActuel(u); }catch(e){ age=null; }
  const croissance=(age!=null&&age<MORPHO_INIT_AGE_CROISSANCE
    &&(Date.now()-(Number(m.date)||0))>MORPHO_INIT_AN);
  return '<div style="font-size:var(--fs-sm);color:var(--text-strong);line-height:1.7">'
    +l.map(s=>'<div>'+E(s.lib)+' : '+E(_synNombre(m.longueurs[s.cle].cm))+' cm, à ± '
      +E(_synNombre(m.longueurs[s.cle].marge))+' cm près</div>').join('')
    +'</div>'
    +'<p style="font-size:var(--fs-2xs);color:var(--text-faint);line-height:1.55;margin:6px 0 0">'
    +'Lu une fois sur la photo de face du '+E(jour((m.photoRef&&m.photoRef.bilan)||m.date))
    +', mis à l’échelle par la hauteur du sol au milieu de la rotule'
    +((m.controleEcart!=null)?(', contrôlé à '+E(_synNombre(m.controleEcart*100))+' % près par la taille debout'):'')
    +'. Figé le '+E(jour(m.date))+' : la morphologie d’un adulte ne bouge plus.</p>'
    // LES RAPPORTS, ET CE QUI LEUR MANQUE POUR ETRE SITUES.
    +MORPHO_PHOTO_RAPPORTS.map(d=>{
      const v=m.rapports&&m.rapports[d.cle];
      if(v==null) return '';
      const n=morphoCalibrageCompte(athletes,d.axe);
      return '<p style="font-size:var(--fs-sm);color:var(--text-dim);line-height:1.6;margin:6px 0 0">'
        +E(d.lib)+' : '+E(String(Math.round(v*100)/100).replace('.',','))
        +((n<MORPHO_CALIB_MIN)
          ?(' · repère en cours de calibrage, '+n+' athlète'+(n>1?'s':'')+' sur '+MORPHO_CALIB_MIN)
          :'')+'</p>';
    }).join('')
    +(croissance
      ?('<p style="font-size:var(--fs-sm);color:var(--orange);line-height:1.6;margin:8px 0 0">'
        +'Moins de '+MORPHO_INIT_AGE_CROISSANCE+' ans et l’analyse a plus d’un an : '
        +'il grandit encore, tu peux la refaire.</p>')
      :'')
    +bouton;
}
/** Le bloc « photo » de l'écran des amplitudes. Côté coach, comme le reste. */
function _htmlMorphoPhoto(){
  if(!_amp) return '';
  const E=escapeHtml;
  const c=(DB.get('users')||{})[_amp.email]||{};
  const enr=[];
  MORPHO_PHOTO_RAPPORTS.forEach(d=>{
    const r=_morphoRapportPhoto(c,d.axe);
    if(r) enr.push(d.lib+' : '+String(Math.round(r.valeur*100)/100).replace('.',',')
      +(r.date?' (photo, '+new Date(r.date).toLocaleDateString('fr-FR')+')':' (photo)'));
  });
  const vue=(_morphoPhotoVue&&_morphoPhotoVue.email===_amp.email)?_morphoPhotoVue:null;
  const pr=vue&&vue.prise;
  return '<div style="background:var(--dark);border:1px solid var(--border);border-radius:var(--r-3);padding:14px;margin-bottom:14px">'
    +'<div style="font-size:var(--fs-xs);font-weight:800;letter-spacing:1.2px;text-transform:uppercase;color:#bbb;margin-bottom:6px">'
    +'La photo de face</div>'
    +'<p style="font-size:var(--fs-sm);color:var(--text-dim);line-height:1.6;margin-bottom:10px">'
    +'Elle rend deux rapports d’un repère osseux à l’autre, cuisse sur jambe et '
    +'humérus sur avant-bras. Elle rend aussi des centimètres, mais seulement '
    +'quand une mesure au ruban lui donne son échelle : du sol au milieu de la '
    +'rotule, prise une fois au premier bilan. Le mètre reste prioritaire : la '
    +'photo le confirme, ou le contredit.</p>'
    +_htmlMorphoEchelle(c,(c.morphoPhoto&&c.morphoPhoto.pixels)||(vue&&vue.pixels)||null)
    +(pr?'<p style="font-size:var(--fs-sm);line-height:1.6;margin-bottom:10px;color:'
      +(pr.verdict==='bon'?'var(--green)':pr.verdict==='a_ameliorer'?'var(--orange)':'var(--red)')+'">'
      +'Prise de vue : '+(pr.verdict==='bon'?'bonne'
        :pr.verdict==='a_ameliorer'?'à améliorer':'à refaire')
      +(pr.raisons.length?' — '+E(pr.raisons.join(' ; ')):'')+'</p>':'')
    +(enr.length?'<div style="font-size:var(--fs-sm);color:var(--text-strong);line-height:1.6;margin-bottom:10px">'
      +enr.map(t=>'<div>'+E(t)+'</div>').join('')+'</div>'
      :'<p style="font-size:var(--fs-sm);color:var(--text-dim);line-height:1.6;margin-bottom:10px">'
      +'Rien de lu pour l’instant.</p>')
    +'<button type="button" class="btn btn-outline" style="width:100%;margin:0" '
    +'onclick="lireMorphoPhoto(\''+escapeHtml(_amp.email)+'\')">Lire la photo de face du dernier bilan</button>'
    +'</div>'
    // L'ANALYSE INITIALE, FIGEE (lot 8) : ce que la photo a donne une fois, et
    // qu'on ne recalcule plus. Le bouton « Refaire l'analyse » est cote coach,
    // et nulle part ailleurs.
    +'<div style="background:var(--dark);border:1px solid var(--border);border-radius:var(--r-3);padding:14px;margin-bottom:14px">'
    +'<div style="font-size:var(--fs-xs);font-weight:800;letter-spacing:1.2px;text-transform:uppercase;color:#bbb;margin-bottom:6px">'
    +'Ses longueurs, figées</div>'
    +_htmlMorphoInitiale(c,(function(){ try{ return getClients(); }catch(e){ return []; } })())
    +'</div>';
}

// ── LES TESTS D'AMPLITUDE (lot M1.2) ────────────────────────────────────────
//
// Quatre tests, côté COACH, avec leur protocole sous les yeux au moment de la
// saisie. Ce sont des nombres : ils tiennent sans peine dans le dossier de
// l'athlète, à côté de ses bilans.
//
// ⚠ AUCUN NE NOMME UNE CAUSE. On note ce qu'on voit — une distance, un angle,
// un arrêt net ou élastique — et rien de ce qui pourrait l'expliquer.

/** @type {{email:string, nom:string, v:any}|null} */
let _amp=null;

/**
 * Ouvre l'écran des tests pour un athlète. Même garde que partout ailleurs :
 * la fonction est globale, et une garde qui ne vit que dans l'appelant n'en
 * est pas une.
 */
function ouvrirAmplitudes(email){
  const users=DB.get('users')||{};
  const c=users[email];
  if(!c||!currentUser||c.coachId!==currentUser.id){
    toast('Élève introuvable ou non autorisé','var(--orange)'); return false;
  }
  const src=(c.morphoTests&&typeof c.morphoTests==='object')?c.morphoTests:{};
  // Une COPIE : tant que le coach n'a pas enregistré, le dossier ne bouge pas.
  _amp={email,nom:String(c.fname||c.email||''),v:JSON.parse(JSON.stringify(src))};
  go('s-coach-amplitudes');
  _ampRendre();
  return true;
}
/** @param {string} cle @param {string} champ @param {any} val */
function ampSaisie(cle,champ,val){
  if(!_amp) return false;
  const d=MORPHO_TESTS.find(x=>x.cle===cle);
  if(!d) return false;
  const o=Object.assign({},_amp.v[cle]||{});
  o[champ]=val;
  _amp.v[cle]=o;
  // Les boutons (butée, niveau) se redessinent ; les champs chiffrés, non —
  // redessiner sous les doigts ferait perdre le curseur.
  if(champ==='butee'||champ==='niveau'||champ==='mur') _ampRendre();
  else _ampMajEtat();
  return true;
}
/** PURE au sens du rendu : ce que l'écran doit dire d'un test saisi. */
function _ampEtatTest(d,v){
  const n=(x)=>{ const q=parseFloat(String(x==null?'':x).replace(',','.')); return isFinite(q)?q:null; };
  const bornes=[];
  const champs=d.champ==='paire'?['g','d']:d.champ==='cm'?['cm']:d.champ==='deg'?['deg']:[];
  let rempli=false;
  for(const k of champs){
    const q=n(v&&v[k]);
    if(q==null){ if(v&&String(v[k]||'').trim()!=='') bornes.push(k); continue; }
    rempli=true;
    if(q<d.min||q>d.max) bornes.push(k);
  }
  if(d.champ==='niveau') rempli=!!(v&&(d.niveaux||[]).includes(String(v.niveau||'')));
  if(d.mur&&v&&(v.mur==='oui'||v.mur==='non')) rempli=true;
  return {rempli,horsBornes:bornes.length>0};
}
function _ampMajEtat(){
  const b=document.getElementById('amp-enreg');
  if(!(b instanceof HTMLButtonElement)||!_amp) return;
  const mauvais=MORPHO_TESTS.some(d=>_ampEtatTest(d,_amp.v[d.cle]).horsBornes);
  b.disabled=mauvais;
  b.style.opacity=mauvais?'.4':'1';
}
function _ampRendre(){
  const z=document.getElementById('amp-contenu');
  if(!z||!_amp) return;
  const E=_amp;
  const num=(cle,champ,val,ph)=>'<input type="number" inputmode="decimal" step="any" value="'
    +escapeHtml(String(val==null?'':val))+'" placeholder="'+escapeHtml(ph||'—')+'" '
    +'oninput="ampSaisie(\''+cle+'\',\''+champ+'\',this.value)" '
    +'style="width:88px;min-height:44px;background:#0c0c0c;border:1px solid var(--border);'
    +'border-radius:var(--r-2);color:var(--text);font-family:Montserrat,sans-serif;font-weight:800;'
    +'font-size:var(--fs-md);text-align:center;padding:6px">';
  const bouton=(cle,champ,val,cour,lib)=>'<button type="button" onclick="ampSaisie(\''+cle+'\',\''+champ
    +'\',\''+cour+'\')" aria-pressed="'+(val===cour)+'" style="min-height:44px;padding:0 12px;'
    +'border-radius:var(--r-2);border:1px solid '+(val===cour?'var(--red)':'var(--border)')+';'
    +'background:'+(val===cour?'rgba(224,32,32,.12)':'none')+';color:var(--text);'
    +'font-family:Montserrat,sans-serif;font-size:var(--fs-xs);font-weight:800;cursor:pointer">'
    +escapeHtml(lib)+'</button>';
  const faits=testsMorpho((DB.get('users')||{})[E.email]);
  const htmlPhoto=(function(){ try{ return _htmlMorphoPhoto(); }catch(e){ return ''; } })();
  z.innerHTML='<div style="width:24px;height:2px;background:var(--red);margin-bottom:10px"></div>'
    +'<h1 style="font-size:20px;line-height:1.3;font-weight:900;margin-bottom:4px">Amplitudes</h1>'
    +'<p style="font-size:var(--fs-sm);color:var(--text-dim);line-height:1.6;margin-bottom:6px">'
    +escapeHtml(E.nom)+' · quatre tests, chacun avec son protocole. Tout est facultatif : '
    +'une case vide vaut mieux qu’une mesure prise autrement que ce qui est écrit.</p>'
    +'<p style="font-size:var(--fs-xs);color:var(--text-faint);line-height:1.55;margin-bottom:16px">'
    +'On note ce qu’on voit — une distance, un angle, un arrêt net ou élastique. '
    +'Rien ici ne dit d’où vient une limite, et rien ne descend côté athlète.</p>'
    +MORPHO_TESTS.map(d=>{
      const v=E.v[d.cle]||{};
      const f=faits.find(x=>x.cle===d.cle);
      const etat=_ampEtatTest(d,v);
      let saisie='';
      if(d.champ==='cm') saisie=num(d.cle,'cm',v.cm,'cm')+'<span style="font-size:var(--fs-xs);color:var(--text-dim);font-weight:700">cm</span>';
      else if(d.champ==='deg') saisie=num(d.cle,'deg',v.deg,'°')
        +'<span style="font-size:var(--fs-xs);color:var(--text-dim);font-weight:700">°</span>'
        +bouton(d.cle,'butee',v.butee,'nette','Butée nette')
        +bouton(d.cle,'butee',v.butee,'elastique','Butée élastique');
      else if(d.champ==='paire') saisie='<span style="font-size:var(--fs-xs);color:var(--sub);font-weight:800">G</span>'
        +num(d.cle,'g',v.g,'cm')+'<span style="font-size:var(--fs-xs);color:var(--sub);font-weight:800">D</span>'
        +num(d.cle,'d',v.d,'cm')
        +(d.mur?'<span style="flex-basis:100%;height:0"></span>'
          +'<span style="font-size:var(--fs-xs);color:var(--text-dim);font-weight:700">Bras au mur :</span>'
          +bouton(d.cle,'mur',v.mur,'oui','Ils touchent')
          +bouton(d.cle,'mur',v.mur,'non','Lombaires qui décollent'):'');
      else if(d.champ==='niveau') saisie=(d.niveaux||[]).map(k=>bouton(d.cle,'niveau',v.niveau,k,
        k==='haut'?'Haut du dos':k==='milieu'?'Milieu':'Bas du dos')).join('');
      return '<div style="background:var(--dark);border:1px solid var(--border);border-radius:var(--r-3);padding:14px;margin-bottom:14px">'
        +'<div style="font-size:var(--fs-xs);font-weight:800;letter-spacing:1.2px;text-transform:uppercase;color:#bbb;margin-bottom:6px">'
        +escapeHtml(d.lib)+'</div>'
        +'<p style="font-size:var(--fs-sm);color:var(--text-dim);line-height:1.6;margin-bottom:10px">'+escapeHtml(d.protocole)+'</p>'
        +'<div style="display:flex;align-items:center;gap:8px;flex-wrap:wrap">'+saisie+'</div>'
        +(etat.horsBornes?'<p style="font-size:var(--fs-xs);color:var(--orange);line-height:1.5;margin-top:8px">'
          +'Valeur hors des bornes attendues ('+d.min+' à '+d.max+' '+(d.unite||'')+') : à revérifier avant d’enregistrer.</p>':'')
        +(f&&f.date?'<p style="font-size:var(--fs-xs);color:'+(f.perime?'var(--orange)':'var(--text-faint)')
          +';line-height:1.5;margin-top:8px">Dernier relevé : '+escapeHtml(f.texte||'—')+' · '
          +new Date(f.date).toLocaleDateString('fr-FR')+(f.perime?' · périmé, à refaire':'')+'</p>':'')
        +'</div>';
    }).join('')
    +htmlPhoto
    +'<p style="font-size:var(--fs-xs);color:var(--text-faint);line-height:1.55;margin-top:4px">'
    +'Un test vaut '+MORPHO_PEREMPTION_J+' jours : une amplitude se travaille et se perd, '
    +'et passé un trimestre elle ne décrit plus l’athlète d’aujourd’hui.</p>';
  _ampMajEtat();
}
/**
 * Enregistre les tests dans le dossier de l'athlète. Chaque test rempli reçoit
 * la date du jour ; un test vidé est retiré, pas gardé avec une vieille date.
 */
function enregistrerAmplitudes(){
  if(!_amp) return false;
  const users=DB.get('users')||{};
  const c=users[_amp.email];
  if(!c||!currentUser||c.coachId!==currentUser.id){
    toast('Élève introuvable ou non autorisé','var(--orange)'); return false;
  }
  const avant=(c.morphoTests&&typeof c.morphoTests==='object')?c.morphoTests:{};
  const out={};
  const n=(x)=>{ const q=parseFloat(String(x==null?'':x).replace(',','.')); return isFinite(q)?q:null; };
  for(const d of MORPHO_TESTS){
    const v=_amp.v[d.cle]||{};
    const etat=_ampEtatTest(d,v);
    if(etat.horsBornes){ toast('Une valeur sort des bornes : reprends-la avant d’enregistrer.','var(--orange)'); return false; }
    if(!etat.rempli) continue;
    const o={};
    if(d.champ==='cm') o.cm=n(v.cm);
    else if(d.champ==='deg'){ o.deg=n(v.deg); if(v.butee==='nette'||v.butee==='elastique') o.butee=v.butee; }
    else if(d.champ==='paire'){ const g=n(v.g), dr=n(v.d); if(g!=null) o.g=g; if(dr!=null) o.d=dr;
      if(v.mur==='oui'||v.mur==='non') o.mur=v.mur; }
    else if(d.champ==='niveau') o.niveau=String(v.niveau||'');
    // LA DATE NE BOUGE QUE SI LA MESURE BOUGE : rouvrir l'écran et le
    // réenregistrer ne doit pas rajeunir un test qui n'a pas été refait.
    const vieux=avant[d.cle]||{};
    const sansDate=Object.assign({},vieux); delete sansDate.date;
    o.date=(JSON.stringify(sansDate)===JSON.stringify(o)&&vieux.date)?vieux.date:Date.now();
    out[d.cle]=o;
  }
  if(Object.keys(out).length) c.morphoTests=out; else delete c.morphoTests;
  c.updatedAt=Date.now();
  users[_amp.email]=c;
  const ok=DB.set('users',users);
  toastSync(ok,CLOUD.pushOne(_amp.email,c),'Amplitudes enregistrées','les amplitudes sont');
  _ampRendre();
  return true;
}

// PURE. Même format que risquesMicro : {cle, lib, motif, question}.
function questionsMorpho(user){
  const out=[];
  if(!user||typeof user!=='object') return out;
  // Mesures à revérifier : on le dit AVANT tout ratio, puisqu'aucun ratio ne
  // sera calculé dessus.
  [['deb-entrejambe','entrejambe'],['deb-bras','longueur de bras']].forEach(([champ,lib])=>{
    const l=longueurSegment(user,champ);
    if(l.motif==='aberrante')
      out.push({cle:'mesure_'+champ,lib:'Mesure à revérifier',
        motif:'La mesure d\'' + (lib==='entrejambe'?'entrejambe':'un bras')
          +' saisie au bilan ne tient pas debout : plus longue que la taille, ou trop courte.',
        question:'Peux-tu la reprendre avec '+
          (lib==='entrejambe'?'l\'athlète pieds nus, du sol au pubis':'le bras tendu, de l\'acromion à la styloïde')+' ?'});
  });

  // LES SIX MESURES DU LOT M1, au même endroit et pour la même raison : on le
  // dit AVANT tout rapport, puisqu'aucun rapport ne sera calculé dessus.
  for(const d of MORPHO_MESURES){
    if(d.origine==='M0') continue;
    if(mesureMorpho(user,d.cle).motif!=='aberrante') continue;
    out.push({cle:'mesure_'+d.cle,lib:'Mesure à revérifier',
      motif:'La mesure « '+d.lib.toLowerCase()+' » saisie au bilan sort des bornes attendues : '
        +'entre '+d.min+' et '+d.max+' cm.',
      question:'Peux-tu la reprendre ? '+d.consigne});
  }
  for(const c of coherencesMorpho(user)) out.push(c);
  const t=_tailleCm(user);
  const rj=ratioJambes(user);
  if(_horsMarge(rj,RATIO_JAMBES_REF)){
    const longues=rj>RATIO_JAMBES_REF;
    const v=_variantesSchema(longues?'squat':'charniere-hanche',3);
    out.push({cle:'jambes',lib:longues?'Jambes longues pour la taille':'Jambes courtes pour la taille',
      motif:'Entrejambe à '+Math.round(rj*100)+' % de la taille, pour un repère de population autour de '
        +Math.round(RATIO_JAMBES_REF*100)+' %.'
        +(v.length?' Variantes du même schéma à essayer : '+v.join(', ')+'.':''),
      question:'Est-ce que '+(longues?'la profondeur au squat':'l\'amplitude en charnière de hanche')
        +' te paraît confortable chez '+(t?'lui':'cet athlète')+' ?'});
  }
  const rb=ratioBras(user);
  if(_horsMarge(rb,RATIO_BRAS_REF)){
    const longs=rb>RATIO_BRAS_REF;
    const v=_variantesSchema(longs?'poussee-horizontale':'tirage-vertical',3);
    out.push({cle:'bras',lib:longs?'Bras longs pour la taille':'Bras courts pour la taille',
      motif:'Longueur de bras à '+Math.round(rb*100)+' % de la taille, pour un repère de population autour de '
        +Math.round(RATIO_BRAS_REF*100)+' %.'
        +(v.length?' Variantes du même schéma à essayer : '+v.join(', ')+'.':''),
      question:'Est-ce que l\'amplitude '+(longs?'au développé couché':'au tirage')
        +' pose question en séance ?'});
  }
  const d=(function(){ try{ return dominanceQuadIschio(user); }catch(e){ return null; } })();
  if(d!=null&&d>DOMINANCE_QI_SIGNAL){
    out.push({cle:'quad_ischio',lib:'Quadriceps et ischios déséquilibrés',
      motif:'Sur les dernières semaines entraînées, le volume quadriceps vaut '
        +String(d).replace('.',',')+' fois celui des ischios.',
      question:'Est-ce un choix de programmation en ce moment, ou une habitude à rééquilibrer ?'});
  }
  return out;
}

// Fiche COACH uniquement. Aucune fonction d'affichage athlète n'appelle ceci —
// un test le vérifie sur le HTML produit par l'accueil et l'écran progression.
function _htmlQuestionsMorpho(user){
  const l=(function(){ try{ return questionsMorpho(user); }catch(e){ return []; } })();
  const tests=(function(){ try{ return testsMorpho(user); }catch(e){ return []; } })();
  const faits=tests.filter(t=>t.date&&t.texte);
  const lecture=(function(){ try{ return _htmlMorphoLecture(user,_morphoCalCache()); }
    catch(e){ return ''; } })();
  // ⚠ ZONE DE LECTURE, ET RIEN D’AUTRE. Aucun bouton ici — ni fermeture, ni
  // report, ni saisie — et AUCUN bloc du tout quand il n’y a rien à dire :
  // un cadre qui s’affiche toujours finit par ne plus être lu. Le relevé des
  // amplitudes se fait dans l’onglet Données, section Amplitudes.
  if(!l.length&&!faits.length&&!lecture) return '';
  // LES TESTS, AVEC LEUR DATE ET LEUR PÉREMPTION. Une amplitude relevée il y a
  // six mois ne décrit plus l'athlète : on la montre quand même, marquée
  // « périmé », plutôt que de la faire disparaître sans un mot.
  const htmlTests=!faits.length?'':`<div style="border-top:1px solid var(--border);margin-top:4px;padding-top:12px">
    <div style="font-size:var(--fs-xs);color:var(--sub);letter-spacing:1.2px;font-weight:800;text-transform:uppercase;margin-bottom:6px">Amplitudes</div>
    ${faits.map(t=>`<div style="font-size:var(--fs-sm);color:${t.perime?'var(--orange)':'var(--text-strong)'};line-height:1.6">${escapeHtml(t.lib)} : ${escapeHtml(t.texte)} <span style="color:var(--text-faint)">(test, ${new Date(t.date).toLocaleDateString('fr-FR')}${t.perime?', périmé':''})</span></div>`).join('')}
  </div>`;
  return `<div style="background:var(--dark);border:1px solid var(--border);border-radius:var(--r-3);padding:16px;margin-bottom:20px">
    <div style="font-size:var(--fs-xs);color:var(--sub);letter-spacing:2px;font-weight:700;text-transform:uppercase;margin-bottom:5px">Proportions</div>
    <div style="font-size:var(--fs-xs);color:var(--text-dim);line-height:1.55;margin-bottom:12px">Des variantes à envisager, jamais un exercice à retirer.</div>
    ${l.length?'':`<div style="font-size:var(--fs-sm);color:var(--text-dim);line-height:1.6;margin-bottom:12px">Aucune proportion à signaler avec ce qui est mesuré aujourd’hui.</div>`}
    ${l.map(r=>`<div style="border-left:2px solid var(--border);padding-left:11px;margin-bottom:12px">
      <div style="font-size:var(--fs-xs);font-weight:800;letter-spacing:1.2px;color:#bbb;text-transform:uppercase;margin-bottom:4px">${escapeHtml(r.lib)}</div>
      <div style="font-size:var(--fs-sm);color:var(--text-strong);line-height:1.6">${escapeHtml(r.motif)}</div>
      <div style="font-size:var(--fs-sm);color:var(--text);line-height:1.6;margin-top:5px;font-weight:600">${escapeHtml(r.question)}</div>
    </div>`).join('')}
    ${lecture}
    ${htmlTests}
    <div style="font-size:var(--fs-xs);color:var(--text-dim);line-height:1.55;border-top:1px solid var(--border);padding-top:10px;margin-top:12px">${escapeHtml(MORPHO_DISCLAIMER)}</div>
  </div>`;
}

// Fiche coach UNIQUEMENT. Rien de tout ceci n'est rendu côté athlète : aucune
// fonction de l'accueil ou de l'écran nutrition n'appelle risquesMicro.
// Côté coach, le score EST montré : c'est un professionnel qui le lit, et il a
// besoin de savoir sur quoi l'app s'est fondée pour se taire. Côté athlète,
// aucun chiffre ne descend jamais.
// PURE. Le format est celui de risquesMicro — {cle, lib, motif, question} —
// mais la fonction est séparée : risquesMicro parle de micronutriments, et
// trois de ses tests épinglent la liste exacte de ses clés.
// UN OU DEUX faits seulement : une question au coach, et RIEN côté athlète.
function risqueDeficitQuestion(user,jourISO){
  let rd,pal;
  try{ rd=risqueDeficitEnergetique(user,jourISO); pal=paliersDeficit(user,jourISO); }
  catch(e){ return null; }
  if(!rd||pal!=='aucun'||rd.points<1) return null;
  return {cle:'deficit',lib:'Éléments qui se cumulent',
    motif:rd.criteres.map(x=>x.lib.toLowerCase()+' : '+x.valeur).join(' · ')+'.',
    question:'Comment se passe la récupération en ce moment — fatigue, sommeil, appétit ?'};
}
function _htmlDeficitCoach(c){
  let pal='aucun', r=null;
  try{ pal=paliersDeficit(c); r=risqueDeficitEnergetique(c); }catch(e){ return ''; }
  if(pal==='aucun'){
    // Un ou deux faits : une question, au même endroit et dans le même
    // registre que les autres. Aucun chiffre, aucun palier annoncé.
    const q=risqueDeficitQuestion(c);
    if(!q) return '';
    return `<div style="background:var(--dark);border:1px solid var(--border);border-radius:var(--r-3);padding:16px;margin-bottom:20px">
      <div style="font-size:var(--fs-xs);font-weight:800;letter-spacing:1.2px;color:#bbb;text-transform:uppercase;margin-bottom:4px">${escapeHtml(q.lib)}</div>
      <div style="font-size:var(--fs-sm);color:var(--text-strong);line-height:1.6">${escapeHtml(q.motif)}</div>
      <div style="font-size:var(--fs-sm);color:var(--text);line-height:1.6;margin-top:5px;font-weight:600">${escapeHtml(q.question)}</div>
    </div>`;
  }
  if(!r) return '';
  const bloc=(pal==='blocage');
  const col=bloc?'var(--red)':'var(--orange)';
  const leve=((c&&c.cycle)||{}).leveDeficit;
  const lignes=r.criteres.map(x=>
    `<div style="font-size:var(--fs-sm);color:var(--text-strong);line-height:1.65">· ${escapeHtml(x.lib)} — ${escapeHtml(String(x.valeur))}</div>`).join('');
  // La levée est un GESTE du coach, jamais une expiration automatique. Deux
  // motifs, pas de champ libre : on ne fait pas raconter un dossier médical.
  const boutons=bloc
    ?`<div style="display:flex;gap:8px;margin-top:11px">
        <button onclick="leverDeficit('consulte')" class="btn btn-outline btn-sm" style="flex:1;margin:0;font-size:var(--fs-2xs);letter-spacing:1px">Elle a consulté</button>
        <button onclick="leverDeficit('regles_revenues')" class="btn btn-outline btn-sm" style="flex:1;margin:0;font-size:var(--fs-2xs);letter-spacing:1px">Les règles sont revenues</button>
      </div>
      <div style="font-size:var(--fs-xs);color:var(--text-dim);line-height:1.55;margin-top:8px">Après une levée, propose une pause diététique plutôt qu'un retour direct en déficit.</div>`
    :'';
  const rappelLeve=leve
    ?`<div style="font-size:var(--fs-xs);color:var(--text-dim);line-height:1.55;margin-top:8px">Levée enregistrée le ${escapeHtml(String(leve.date))} · motif : ${escapeHtml(String(leve.motif||''))}. Une nouvelle absence déclarée la remettra en cause.</div>`
    :'';
  return `<div style="background:var(--dark);border:1px solid ${col}55;border-radius:var(--r-3);padding:16px;margin-bottom:20px">
    <div style="font-size:var(--fs-xs);color:${col};letter-spacing:2px;font-weight:700;text-transform:uppercase;margin-bottom:6px">${bloc?'Apports bloqués sous le plancher':'Faits qui se cumulent'}</div>
    <div style="font-size:var(--fs-xs);color:var(--text-dim);line-height:1.55;margin-bottom:10px">${r.points} élément${r.points>1?'s':''} relevé${r.points>1?'s':''}. Rien n'est diagnostiqué ici : ce sont des constats mesurés dans l'app.</div>
    ${lignes}
    ${bloc?`<div style="font-size:var(--fs-sm);color:var(--text);line-height:1.7;margin-top:10px;border-top:1px solid var(--border);padding-top:10px">${escapeHtml(DEF_TEXTE_BLOCAGE)}</div>`:''}
    ${boutons}${rappelLeve}
  </div>`;
}
// Écrit la levée sur le dossier de l'athlète. Aucune expiration, aucun
// décompte : elle tient jusqu'à ce qu'une nouvelle absence soit déclarée.
function leverDeficit(motif){
  const users=DB.get('users')||{};
  const c=getOwnedClient(currentClientId,users);
  if(!c) return false;
  if(['consulte','regles_revenues'].indexOf(motif)<0) return false;
  if(!c.cycle) c.cycle={};
  c.cycle.leveDeficit={date:localISODate(new Date()),motif};
  c.updatedAt=Date.now(); users[c.email]=c;
  const ok=DB.set('users',users);
  toastSync(ok,CLOUD.pushOne(c.email,c),'Levée enregistrée','la levée est');
  try{ renderCoachMicroSection(c); renderCoachNutriSection(c); }catch(e){}
  return true;
}
// ══════════════ LES TRAITEMENTS, COTE COACH ════════════════════════════
//
// ⚠ CE BLOC NE MONTRE QUE CE QUE traitementsPourCoach LAISSE PASSER. Il ne
// relit pas le dossier : c'est la meme fonction que le filtre de poussee, et
// deux lectures differentes de la meme regle finiraient par diverger — celle
// qui affiche etant, par construction, la plus tentante a elargir.
//
// Ce que le coach voit d'un traitement non partage : qu'il existe, et a quel
// moment. C'est le minimum qui lui evite de proposer un complement en conflit,
// et le maximum admissible sans le consentement de l'athlete.
function _htmlTraitementsCoach(c){
  if(!c) return '';
  let l=[];
  try{ l=traitementsPourCoach(c); }catch(e){ l=[]; }
  const lib=id=>{ const t=TIMINGS_LIST.filter(x=>x.id===id)[0]; return t?t.label.toLowerCase():id; };
  const ligne=t=>{
    const m=_tabBloc(t.moments).sort((a,b)=>_rangMoment(a)-_rangMoment(b)).map(lib).join(', ');
    const dose=(Number(t.dosage_quantite)>0)
      ? ' · '+String(t.dosage_quantite).replace('.',',')+' '+escapeHtml(t.dosage_unite||'') : '';
    const nom=t.partage
      ? escapeHtml(t.nom||'')+dose
      // ⚠ ON N'ECRIT PAS « TRAITEMENT MASQUE » : ce serait pointer une absence
      // et inviter a la demander. On dit ce qu'on sait, au present, sans
      // designer ce qu'on ignore.
      : '<span style="color:var(--text-dim)">Un traitement en cours</span>';
    return '<div style="display:flex;align-items:center;gap:9px;padding:8px 0;'
      +'border-bottom:1px solid var(--border)">'
      +'<span style="flex:1;min-width:0;font-size:var(--fs-sm);color:var(--text);line-height:1.5">'
      +nom
      +(m?'<span style="display:block;font-size:var(--fs-2xs);color:var(--sub);'
        +'margin-top:2px">'+escapeHtml(m)+'</span>':'')
      +(t.saisiPar==='coach'?'<span style="display:block;font-size:var(--fs-2xs);'
        +'color:var(--text-faint);margin-top:1px">saisi par toi</span>':'')
      +'</span>'
      // ⚠ SEUL CE QU'IL A SAISI EST MODIFIABLE PAR LUI. Ouvrir l'editeur sur un
      // traitement de l'athlete afficherait un formulaire vide — il n'en a que
      // la version masquee — et l'enregistrer ecraserait le vrai.
      +(t.saisiPar==='coach'
        ? '<button type="button" class="btn btn-outline btn-sm" style="margin:0;flex:0 0 auto;'
          +'font-size:var(--fs-2xs);padding:4px 8px" onclick="ouvrirEditeurTraitement(\''
          +escapeHtml(c.email)+'\',\''+escapeHtml(t.id)+'\',\'s-coach-client\')">Modifier</button>'
        : '')
      +'</div>';
  };
  return '<div style="background:var(--dark);border:1px solid var(--border);'
    +'border-radius:var(--r-3);padding:16px;margin-bottom:20px">'
    +'<div style="font-size:var(--fs-xs);color:var(--sub);letter-spacing:2px;'
    +'font-weight:700;text-transform:uppercase;margin-bottom:5px">Traitements</div>'
    +'<div style="font-size:var(--fs-xs);color:var(--text-dim);line-height:1.55;'
    +'margin-bottom:10px">'
    +escapeHtml('Ce que tu vois ici dépend de ce que ton athlète partage. '
      +'Sans partage, tu sais qu’un traitement est pris à tel moment, et rien de plus : '
      +'de quoi éviter de proposer un complément qui entrerait en conflit.')
    +'</div>'
    +(l.length?l.map(ligne).join('')
      :'<div style="font-size:var(--fs-sm);color:var(--text-dim);line-height:1.6;'
       +'padding:4px 0 10px">Aucun traitement en cours dans son dossier.</div>')
    +'<button type="button" class="btn btn-outline" style="width:100%;margin:12px 0 0" '
    +'onclick="ouvrirEditeurTraitement(\''+escapeHtml(c.email)
    +'\',null,\'s-coach-client\')">+ Saisir un traitement</button>'
    +'<div style="font-size:var(--fs-2xs);color:var(--text-faint);line-height:1.55;'
    +'margin-top:8px">'+escapeHtml(MICRO_DISCLAIMER)+'</div>'
    +'</div>';
}
function renderCoachMicroSection(c){
  const el=document.getElementById('ccd-micro');
  if(!el) return;
  const def=(function(){ try{ return _htmlDeficitCoach(c); }catch(e){ return ''; } })();
  const l=(function(){ try{ return risquesMicro(c); }catch(e){ return []; } })();
  // Les proportions vivent dans le même emplacement : deux blocs de questions
  // au coach, même registre, même disclaimer d'esprit.
  const morpho=_htmlQuestionsMorpho(c);
  // Restitution, pas question : elle s'affiche meme sans risque a signaler.
  // Le jour ON se lit sur le planning de L'ATHLETE, pas sur celui du coach :
  // nutIsOnDay lit currentUser, qui est le coach sur cet ecran.
  const hydra=_htmlHydratationCoach(c);
  // Restitution, comme l'hydratation : elle s'affiche sans qu'aucun seuil ne
  // soit franchi, et n'entre dans aucun score d'urgence.
  let recup=''; try{ recup=_htmlRecuperationCoach(c); }catch(e){}
  // ⚠ LES TRAITEMENTS NE SONT PAS ICI, ET DEUX ASSERTIONS DU BANC L'EXIGENT.
  // « Signaux faibles » (ex « Micro-signaux », renomme en R10) est une zone de LECTURE : aucun bouton, rien qu'on
  // puisse faire disparaitre, et AUCUN bloc du tout quand il n'y a pas de
  // question a poser. Un editeur y aurait rendu le rappel masquable et fait
  // apparaitre un cadre sur toutes les fiches. Ils vivent dans leur propre
  // section, a cote des complements — voir renderCoachTraitementsSection.
  if(!l.length&&!morpho&&!hydra&&!def&&!recup){ el.innerHTML=''; el.style.display='none'; return; }
  el.style.display='block';
  if(!l.length){ el.innerHTML=def+recup+morpho+hydra; return; }
  el.innerHTML=def+`<div style="background:var(--dark);border:1px solid var(--border);border-radius:var(--r-3);padding:16px;margin-bottom:20px">
    <div style="font-size:var(--fs-xs);color:var(--sub);letter-spacing:2px;font-weight:700;text-transform:uppercase;margin-bottom:5px">À demander en séance</div>
    <div style="font-size:var(--fs-xs);color:var(--text-dim);line-height:1.55;margin-bottom:12px">Rien n'est détecté ici : ce sont des questions que le profil rend pertinentes.</div>
    ${l.map(r=>`<div style="border-left:2px solid var(--border);padding-left:11px;margin-bottom:12px">
      <div style="font-size:var(--fs-xs);font-weight:800;letter-spacing:1.2px;color:#bbb;text-transform:uppercase;margin-bottom:4px">${escapeHtml(r.lib)}</div>
      <div style="font-size:var(--fs-sm);color:var(--text-strong);line-height:1.6">${escapeHtml(r.motif)}</div>
      <div style="font-size:var(--fs-sm);color:var(--text);line-height:1.6;margin-top:5px;font-weight:600">${escapeHtml(r.question)}</div>
    </div>`).join('')}
    <div style="font-size:var(--fs-xs);color:var(--text-dim);line-height:1.55;border-top:1px solid var(--border);padding-top:10px">${escapeHtml(MICRO_DISCLAIMER)}</div>
  </div>`+recup+morpho+hydra;
}
// L'hydratation vivait sur l'écran de PROGRESSION et dans la fiche coach, mais
// pas sur l'écran nutrition — alors que le sel et les fibres, eux, y sont.
// On l'y ajoute : c'est là qu'on la cherche. Aucun retrait ailleurs, un appel
// de plus, et le même bloc — pas une seconde implémentation.
function _htmlHydratationNut(user){
  const u=user||currentUser;
  // `u` et non currentUser : cette fonction reçoit un dossier, et il faut la
  // croire sur parole.
  try{ return _htmlHydratation(u,nutIsOnDay(localISODate(new Date()),u)); }
  catch(e){ return ''; }
}
// Meme rendu que cote athlete, mais le jour ON est celui de l'ATHLETE : sur la
// fiche coach, nutIsOnDay lirait le planning du coach et annoncerait un repere
// faux un jour sur deux.
function _htmlHydratationCoach(c){
  const cfg=(c&&c.sessions_config)||null;
  let on=false;
  if(cfg){
    const d=new Date();
    on=!!(cfg[(d.getDay()+6)%7]&&cfg[(d.getDay()+6)%7].active===true);
  }
  return _htmlHydratation(c,on);
}
function urgencyScore(c){
  const lt=(c.bilans||[]).reduce((m,b)=>Math.max(m,b.date),0);
  // ── Signaux d'entraînement, au-dessus de l'échelle administrative ──
  // La santé passe avant l'intendance : une douleur répétée prime sur un bilan
  // en retard, ce qui n'était pas le cas — l'entraînement ne pesait rien du
  // tout dans ce tri. Les branches 1 à 5 ci-dessous sont INCHANGÉES, elles ne
  // sont que repoussées d'un cran, et une batterie de non-régression le
  // vérifie sur les six cas d'origine.
  // Drapeau rouge déclaré : douleur qui irradie, perte de force, réveil
  // nocturne, choc, gonflement. C'est le signal le plus grave que
  // l'application puisse recevoir, et il passe donc devant la douleur répétée.
  // Il n'est PAS reportable : un coach ne doit pas pouvoir le faire disparaître
  // d'un clic, et seule la levée du drapeau l'éteint.
  //
  // LES DEUX FAMILLES, et non la seule musculo-squelettique. Un signe
  // GÉNÉRAL — douleur thoracique, essoufflement au repos, palpitations —
  // n’atteignait pas ce classement, alors que l’athlète lit « Ton coach a
  // été prévenu » en le déclarant. Le seuil ne bouge pas, ni les exclusions :
  // c’est ce qui ENTRE au rang 10 qui était incomplet.
  if(drapeauQuelconqueActif(c)) return 10;
  const sg=signauxEntrainement(c);
  if(sg.douleur&&!isAlertSnoozed('douleur',c.id,0,c)) return 9;
  if(sg.douleurDiffuse&&!isAlertSnoozed('douleurdiff',c.id,0,c)) return 8;
  if(sg.decrochage&&!isAlertSnoozed('decrochage',c.id)) return 7;
  // La proposition de décharge se BRANCHE ici plutôt que de créer une seconde
  // échelle : elle est dérivée de ces signaux-là, elle appartient donc au même
  // rang. Lecture d'un champ déjà écrit, aucun calcul — ce tri passe sur tous
  // les athlètes du coach à chaque rendu de liste.
  // REGLE 4 : les habitudes entrent ICI et nulle part ailleurs. Un terme de
  // plus dans une disjonction qui en comptait sept, au meme rang. La sante
  // passe avant l intendance, et cocher une case est de l intendance.
  if((sg.plateauMuscle||sg.formeBasse||sg.sousMEV||sg.volumeHaut||sg.restrictionLongue||sg.chuteAssiduite
     ||sg.habitudesBasses
     ||propositionDechargeOuverte(c))&&!isAlertSnoozed('entrainement',c.id)) return 6;
  // Même priorité que « nouveau bilan » : les deux sont mutuellement exclusifs
  // (hasNewBilan exige au moins un bilan, neverStarted exige aucun), pas d'égalité possible.
  if(neverStarted(c)&&!isAlertSnoozed('nostart',c.id)) return 5;
  if(hasNewBilan(c)&&!isAlertSnoozed('bilan',c.id,lt)) return 5;
  if(!c._fromCode&&needsAlert(c)&&!isAlertSnoozed('overdue',c.id)) return 4;
  const now=Date.now();
  if(!c._fromCode&&c.status==='COACHING_SUIVI'&&c.accessExpiry&&(c.accessExpiry-now)>0&&(c.accessExpiry-now)<14*864e5&&!isAlertSnoozed('expiring',c.id)) return 3;
  if(isActive(c)) return 2;
  return 1;
}

// ══════════════ PILOTAGE DU PORTEFEUILLE — AGRÉGATION SEULE ═══════════════
// Deux fonctions PURES posées au-dessus de l'existant. Elles ne calculent rien
// de neuf : elles comptent ce qu'urgencyScore et signauxEntrainement disent
// déjà, sur le tableau que renderClientList a DÉJÀ en mémoire. Aucune lecture
// réseau, aucune écriture.
//
// urgencyScore n'est ni lue de travers ni contournée : le seuil ci-dessous est
// un simple filtre sur sa sortie. Elle reste verrouillée par ses tests.
const PIL_SEUIL_TRAITER=7;         // « à traiter » = les motifs cliniques
const PIL_EXPIRE_JOURS=14;         // même fenêtre que le palier 3 d'urgence
const PIL_VISITE_DEFAUT_JOURS=7;   // première visite : on couvre une semaine
const PIL_CHANGEMENTS_MAX=12;
const PIL_PROGRAMME_FIGE_SEMAINES=6;

// Reprend MOT POUR MOT la condition du palier 3 d'urgencyScore. La recopier
// ailleurs ferait remonter comme « expire bientôt » tout athlète sans date,
// alors qu'une date absente vaut accès ILLIMITÉ (voir checkAccess).
// ══════════════ L'ÉCHÉANCE, CÔTÉ ATHLÈTE ══════════════
// Le coach est prévenu quatorze jours avant ; l'athlète sept. La différence
// est voulue : elle laisse une semaine pendant laquelle le coach peut
// prolonger sans que son athlète ait été alarmé pour rien.
const ACCES_PREVENIR_JOURS=7;
// PURE. Le nombre de jours restants quand il faut prévenir, null sinon.
//
// Le prédicat est celui de _pilAccesExpire, mot pour mot : une échéance
// absente vaut accès ILLIMITÉ (voir checkAccess), et un dossier _fromCode
// n'a pas d'accès à lui. Deux définitions divergentes donneraient un athlète
// prévenu que son accès se ferme alors que son coach ne voit rien.
function accesJoursRestants(u,now){
  if(!u||u._fromCode||u.status!=='COACHING_SUIVI') return null;
  const e=Number(u.accessExpiry);
  if(!isFinite(e)||e<=0) return null;
  const t=(typeof now==='number')?now:Date.now();
  // Déjà expiré : ce n'est plus un avertissement, c'est le verrou — et il a
  // son propre écran. Un bandeau « dans 0 jour » sur un accueil inatteignable
  // ne serait vu par personne.
  if(e<=t) return null;
  const j=Math.ceil((e-t)/864e5);
  return j<=ACCES_PREVENIR_JOURS?j:null;
}
// Le bandeau. Vide tant qu'il n'y a rien à dire.
function _rendreEcheanceAcces(){
  const z=document.getElementById('clh-echeance');
  if(!z) return null;
  const u=currentUser;
  const j=accesJoursRestants(u);
  // CHACUN REND SON PROPRE display. Cette fonction posait innerHTML='' sans
  // toucher au display : sans consequence tant qu'elle etait seule sur le
  // noeud, mais elle dependait alors de l'etat que personne d'autre n'etait
  // cense y laisser. Elle ne depend plus de rien.
  if(j==null){ z.innerHTML=''; z.style.display='none'; return null; }
  z.style.display='block';
  // Les deux derniers jours passent au rouge : le même bandeau orange pendant
  // une semaine finit par faire partie du décor.
  const urgent=j<=2;
  const c=urgent?'#E02020':'#f97316';
  // « dans 1 jour » serait ambigu — la veille au soir comme le matin même.
  // « moins de 24 heures » est vrai dans les deux cas.
  const quand=j===1?'dans moins de 24 heures':'dans '+j+' jours';
  const d=new Date(Number(u.accessExpiry)).toLocaleDateString('fr-FR');
  const nom=((u.coachName||'')+'').trim();
  // Le message ne porte AUCUNE donnée de santé : il ne parle que d'accès.
  const href=_coachContactHref(u.coachId,
    'Bonjour'+(nom?' '+nom:'')+", mon accès RepCore se termine le "+d+'. Peux-tu le prolonger ?');
  z.innerHTML=`<div style="position:relative;overflow:hidden;border-radius:var(--r-3);padding:13px 14px;margin-bottom:16px;
      background:repeating-linear-gradient(-50deg,transparent,transparent 11px,rgba(255,255,255,.02) 11px,rgba(255,255,255,.02) 12px),linear-gradient(168deg,#1b1b1b,#111 55%,#0b0b0b);
      border:1px solid var(--border);border-left:3px solid ${c};
      box-shadow:var(--e3)}33">
    <div style="font-size:var(--fs-xs);font-weight:800;letter-spacing:1.6px;text-transform:uppercase;color:${c};--halo-c:${c};text-shadow:var(--halo-1)66">
      Ton accès se termine ${quand}</div>
    <div style="font-size:var(--fs-xs);color:#c9c9c9;line-height:1.6;margin-top:5px">
      Il prend fin le ${escapeHtml(d)}. ${nom?escapeHtml(nom)+' peut le prolonger':'Ton coach peut le prolonger'}, préviens-le avant.</div>
    ${href?`<a href="${_safeContactUrl(href)}" target="_blank" rel="noopener" class="btn btn-red"
      style="margin-top:11px;min-height:42px;display:flex;align-items:center;justify-content:center;font-size:var(--fs-sm);letter-spacing:1px">
      Prévenir mon coach</a>`:''}
  </div>`;
  return j;
}
function _pilAccesExpire(c,now){
  return !!(c&&!c._fromCode&&c.status==='COACHING_SUIVI'&&c.accessExpiry
    &&(c.accessExpiry-now)>0&&(c.accessExpiry-now)<PIL_EXPIRE_JOURS*864e5);
}

// PURE. Les signaux qui ont produit le score de cet athlète, du plus grave au
// moins grave, chacun avec sa date de déclenchement quand elle existe.
//
// `date` vaut null quand le signal n'en porte pas — une douleur diffuse est
// une fenêtre de quatorze jours, un décrochage un ratio sur trois séances :
// aucun des deux n'a d'instant. Inventer une date serait pire que l'absence.
function expliquerUrgence(c){
  const out=[];
  if(!c) return out;
  const ajout=(motif,gravite,date)=>out.push({motif,gravite,
    date:(typeof date==='number'&&date>0)?date:null});
  // Les DEUX familles : cette explication doit dire la même chose que le
  // classement, sinon un athlète remonté au rang 10 y apparaîtrait sans motif.
  const dr=drapeauQuelconqueActif(c);
  if(dr) ajout('Drapeau rouge déclaré',10,dr.date||dr.quand);
  let sg=SIGNAUX_VIDES;
  try{ sg=signauxEntrainement(c); }catch(e){}
  const det=sg.details||{};
  if(sg.douleur){
    const d=det.douleur;
    const dates=(d&&Array.isArray(d.dates)&&d.dates.length)?Math.max.apply(null,d.dates):null;
    ajout('Douleur répétée'+(d&&d.nom?' : '+d.nom:''),9,dates);
  }
  if(sg.douleurDiffuse) ajout('Douleur diffuse',8,null);
  if(sg.decrochage) ajout('Séances écourtées',7,null);
  // Palier 6 : cliniques eux aussi, mais SOUS le seuil « à traiter ». Ils
  // figurent dans l'explication — c'est bien pourquoi l'athlète est là.
  if(sg.plateauMuscle) ajout('Plateau musculaire',6,null);
  if(sg.formeBasse) ajout('Forme déclarée basse',6,null);
  if(sg.sousMEV) ajout('Volume sous le minimum efficace',6,null);
  if(sg.volumeHaut) ajout('Volume élevé',6,null);
  if(sg.restrictionLongue) ajout('Restriction calorique prolongée',6,null);
  try{ if(propositionDechargeOuverte(c)) ajout('Décharge proposée',6,null); }catch(e){}
  const bils=(c.bilans||[]).filter(b=>b&&typeof b.date==='number');
  const dernier=bils.length?bils[bils.length-1].date:null;
  try{ if(neverStarted(c)) ajout('Jamais démarré',5,c.createdAt); }catch(e){}
  try{
    if(hasNewBilan(c)){
      // La date du bilan QUI MOTIVE l’alerte — le plus récent, celui que le
      // prédicat vient de juger. `sans[sans.length-1]` désignait le dernier
      // non répondu DANS L’ORDRE DU TABLEAU, ce qui pouvait montrer une date
      // plus ancienne que la raison réelle du signal.
      const der=dernierBilan(c);
      ajout('Bilan sans réponse',5,(der&&der.date)||dernier);
    }
  }catch(e){}
  try{ if(!c._fromCode&&needsAlert(c)) ajout('Bilan en retard',4,dernier); }catch(e){}
  if(_pilAccesExpire(c,Date.now())) ajout('Accès qui expire',3,c.accessExpiry);
  // PRIORITE BASSE, au meme rang que l'acces qui expire : une asymetrie de
  // 3 % ne se corrige pas dans la semaine, et la faire remonter au-dessus
  // d'une douleur deplacerait le regard du coach au mauvais endroit.
  try{
    const _as=signalAsymetrie(c);
    if(_as) ajout('Asymétrie gauche/droite : '+_as.phrase,ASYM_GRAVITE,dernier);
  }catch(e){}
  return out.sort((a,b)=>b.gravite-a.gravite);
}

// PURE. Le prix de l'abonnement autonome, TEL QUE LA TABLE LE PORTE.
//
// Trois textes l’annonçaient en dur : changer 9,95 dans SUB_PALIERS ne
// changeait rien à l’écran, et le produit aurait annoncé deux prix selon
// l’endroit — celui de la table sur la carte, l’ancien dans les textes.
function prixAutonomie(){
  const p=SUB_PALIERS.find(x=>x.cle==='mensuel');
  return ((p&&p.prix)||prixOffre('essentielle'))+'/mois';
}
// Les emplacements statiques qui l’annoncent. Un attribut plutôt que trois
// identifiants : un quatrième texte s’y branche sans toucher à ce code.
function _majPrixAffiches(){
  try{
    document.querySelectorAll('[data-prix-autonomie]')
      .forEach(e=>{ e.textContent=prixAutonomie(); });
  }catch(e){}
}
// PURE. Ne mute NI le tableau reçu, NI les dossiers qu'il contient.
//
// `opts.now` et `opts.depuis` existent pour les tests : sans eux, la fonction
// lit l'horloge et la dernière visite du coach.
function agregerPortefeuille(clients,opts){
  const l=Array.isArray(clients)?clients:[];
  const o=opts||{};
  const now=(typeof o.now==='number')?o.now:Date.now();
  const depuis=(typeof o.depuis==='number'&&o.depuis>0)
    ?o.depuis:(now-PIL_VISITE_DEFAUT_JOURS*864e5);
  let aTraiter=0,decrochage=0,accesExpirent=0;
  const changements=[];
  // `alertes` porte EXACTEMENT le predicat du filtre 'traiter' de
  // renderClientList — needsAlert ou bilan sans reponse. Il etait compte a
  // part dans loadCoachHome, avec le seul needsAlert : le metric-box annoncait
  // donc un nombre que la puce de filtre n ouvrait pas.
  const portefeuille={total:0,actifs:0,jamaisDemarres:0,enAttente:0,alertes:0};
  const charge={bilansSansReponse:0,videosEnAttente:0};
  for(const c of l){
    if(!c) continue;
    portefeuille.total++;
    const invite=!!(c._fromCode||!c.email);
    if(invite) portefeuille.enAttente++;
    try{ if(isActive(c)) portefeuille.actifs++; }catch(e){}
    try{ if(needsAlert(c)||hasNewBilan(c)) portefeuille.alertes++; }catch(e){}
    let jamais=false;
    try{ jamais=neverStarted(c); }catch(e){}
    if(jamais) portefeuille.jamaisDemarres++;
    try{ if(urgencyScore(c)>=PIL_SEUIL_TRAITER) aTraiter++; }catch(e){}
    // ② et ③ : mêmes exclusions qu'urgencyScore — invité non inscrit et
    // athlète jamais démarré n'ont rien à écourter ni d'accès à renouveler.
    if(_pilEligibleSignaux(c)){
      try{ if(signauxEntrainement(c).decrochage) decrochage++; }catch(e){}
      if(_pilAccesExpire(c,now)) accesExpirent++;
    }
    charge.bilansSansReponse+=bilansSansReponse(c);
    charge.videosEnAttente+=((c.videos||[]).filter(videoNonCorrigee).length);
    // ── Depuis la dernière visite ──
    const nom=((c.fname||'')+' '+(c.lname||'')).trim()||c.email||'Athlète';
    for(const b of (c.bilans||[]))
      if(b&&typeof b.date==='number'&&b.date>depuis)
        changements.push({date:b.date,qui:nom,id:c.id,quoi:'a envoyé un bilan'});
    for(const s of (c.sessions||[]))
      if(s&&typeof s.date==='number'&&s.date>depuis)
        changements.push({date:s.date,qui:nom,id:c.id,quoi:'a fait une séance'});
    for(const v of (c.videos||[]))
      if(v&&typeof v.date==='number'&&v.date>depuis)
        changements.push({date:v.date,qui:nom,id:c.id,quoi:'a envoyé une vidéo'});
    const dr=drapeauRougeActif(c);
    const drd=dr&&(dr.date||dr.quand);
    if(typeof drd==='number'&&drd>depuis)
      changements.push({date:drd,qui:nom,id:c.id,quoi:'a levé un drapeau rouge'});
  }
  changements.sort((a,b)=>b.date-a.date);
  return {aTraiter,decrochage,accesExpirent,changements,portefeuille,charge,
    depuis,max:PIL_CHANGEMENTS_MAX};
}

// ══════════════ PILOTAGE — LA BARRE, LES BANDES, L'EXPLICATION ════════════
// AUCUN nouvel écran : trois compteurs et trois volets posés en tête de la
// liste existante, qui filtrent cette liste-là. Le grief n° 1 du métier est la
// complexité : ce lot ne doit rien ajouter à parcourir, seulement raccourcir
// le chemin vers ce qui compte.
//
// L'état déplié est MÉMORISÉ : ce bloc est repeint à chaque rendu de liste, et
// un <details> se refermerait sous les doigts du coach à chaque frappe dans la
// recherche.
let _pilOuvert={};
let _pilVoirTout=false;
function pilNoterBande(cle,ouvert){ _pilOuvert[cle]=!!ouvert; }
function pilVoirTout(){ _pilVoirTout=true; renderPilotage(); }

// Un athlète compte dans ② et ③ aux MÊMES conditions que dans l'agrégation.
// Une seule définition : deux copies finiraient par donner un compteur qui ne
// correspond plus à la liste qu'il filtre.
function _pilEligibleSignaux(c){
  if(!c||c._fromCode||!c.email) return false;
  try{ if(neverStarted(c)) return false; }catch(e){}
  return true;
}

function _pilCompteur(cle,lib,n,couleur){
  const vide=!(n>0);
  const actif=(_filtreClients===cle);
  // LE RETOUR EN ARRIERE VISE LA VUE DE TRAVAIL, ET NON PLUS « Tous ».
  // Tant que 'tous' etait l'etat par defaut, re-toucher une puce allumee ne
  // pouvait que ramener a lui, et « Tous » lui-meme ne se retirait pas — s'y
  // re-cliquer l'aurait repose sur place. Depuis que la vue par defaut est
  // 'travail', « Tous » est une puce comme les autres : elle s'allume, et se
  // re-toucher la rend.
  const cible=actif?'travail':cle;
  return `<button onclick="setFiltreClients('${cible}')"
    aria-pressed="${actif?'true':'false'}"
    class="pil-compteur" data-vide="${vide?1:0}"
    style="color:${couleur};border-left-color:${actif?couleur:(vide?'var(--border)':couleur+'66')};
      ${actif?`border-color:${couleur};box-shadow:var(--e3)}33,inset 0 1px 0 rgba(255,255,255,.08)`:''}">
    <div class="pil-val" style="color:${vide?'#6a6a6a':couleur};text-shadow:${vide?'none':`0 0 16px ${couleur}99`}">${n}</div>
    <div class="pil-lib" style="color:${vide?'#8a8a8a':'#c4c4c4'}">${lib}</div>
  </button>`;
}
// N1.11 — LA BARRE D ETAT DU PORTEFEUILLE, EN UN SEUL ENDROIT.
// CHAQUE NOMBRE OUVRE SA PROPRE LISTE. C etait le grief : trois metric-box
// muets annoncaient un total, des actifs et des alertes sans offrir aucun
// chemin vers les athletes concernes ; la bande « Portefeuille » du volet
// redisait les memes nombres, repliee ; et les puces de filtre ouvraient des
// listes sans jamais dire combien elles contenaient.
//
// LES PREDICATS DE COMPTAGE ET CEUX DU FILTRAGE SONT LES MEMES, un par un —
// c est la seule chose qui rende un compteur cliquable honnete. agregerPorte-
// feuille compte, renderClientList filtre, et la table ci-dessous les apparie
// nommement. Un compteur qui n ouvrirait pas exactement sa propre liste serait
// pire que pas de compteur du tout.
//
// L ORDRE EST CELUI DE L ACTION : ce qui demande un geste d abord, ce qui
// decrit l etat ensuite, « Tous » en dernier parce qu il n est pas une
// information mais un retour en arriere.
function renderPortefeuille(clients){
  // LA MEME REPARTITION QU'AUX ARRIVEES, et volontairement la meme fonction :
  // deux facons de compter les memes gens finiraient par ne plus dire pareil.
  // Posee apres le rendu, pour ne pas avoir a connaitre le balisage interne.
  const el=document.getElementById('ch-portefeuille');
  if(!el) return;
  const l=clients||(typeof getClients==='function'?getClients():[]);
  let r;
  try{ r=agregerPortefeuille(l,{depuis:currentUser&&currentUser.lastCoachVisit}); }
  catch(e){ el.innerHTML=''; return; }
  const p=r.portefeuille;
  const cases=[
    ['pf-traiter',    'À traiter',            r.aTraiter,        '#E02020'],
    ['pf-decrochage', 'Séances écourtées',    r.decrochage,      '#f5c518'],
    ['pf-acces',      'Accès qui expirent',   r.accesExpirent,   '#22c55e'],
    ['traiter',       'Alertes',              p.alertes,         '#E02020'],
    ['pf-jamais',     'Jamais démarrés',      p.jamaisDemarres,  '#f5c518'],
    ['attente',       'En attente',           p.enAttente,       '#8a8a8a'],
    ['pf-actifs',     'Actifs 14 j',          p.actifs,          '#22c55e'],
    ['tous',          'Tous',                 p.total,           '#c4c4c4']];
  // ⚠ RIEN D'AUTRE QUE LES HUIT COMPTEURS. La repartition « avec / sans
  //   suivi » fermait cette barre : en flex, elle passait pour un neuvieme
  //   element et s'installait au bout de la ligne, poussant « Tous » et
  //   cassant l'alignement des cases. Demande de Kevin, 19/09/2026 : elle s'en
  //   va. L'information reste dite deux fois ailleurs — les titres de section
  //   « Mes athletes (avec / sans suivi) » portent chacun leur compte, et la
  //   carte des arrivees les redit avec ses deux couleurs de barre.
  el.innerHTML=cases.map(c=>_pilCompteur(c[0],c[1],c[2],c[3])).join('');
}
function _pilBande(cle,titre,corps,resume){
  return `<details class="plan-src pil-bande" style="margin:0 0 7px"${_pilOuvert[cle]?' open':''} ontoggle="pilNoterBande('${cle}',this.open)">
    <summary style="color:var(--sub)">${titre}<span class="plan-src-nb">${resume||''}</span></summary>
    <div class="plan-src-liste" style="font-size:var(--fs-xs);color:var(--text-strong);line-height:1.7"><div>${corps}</div></div>
  </details>`;
}
function renderPilotage(clients){
  const el=document.getElementById('ch-pilotage');
  if(!el) return;
  const l=clients||(typeof getClients==='function'?getClients():[]);
  let r;
  try{ r=agregerPortefeuille(l,{depuis:currentUser&&currentUser.lastCoachVisit}); }
  catch(e){ el.innerHTML=''; return; }
  // ── Bande A : depuis la dernière visite ──
  const ch=r.changements;
  const montres=_pilVoirTout?ch:ch.slice(0,r.max);
  const dateCourte=t=>new Date(t).toLocaleDateString('fr-FR',{day:'2-digit',month:'short'});
  const corpsA=ch.length
    ? montres.map(x=>`<div style="padding:2px 0"><span style="color:var(--text-faint)">${dateCourte(x.date)}</span> · <b>${escapeHtml(x.qui)}</b> ${escapeHtml(x.quoi)}</div>`).join('')
      +(ch.length>montres.length?`<button onclick="pilVoirTout()" style="background:none;border:none;color:var(--red-text);font-family:Montserrat,sans-serif;font-size:var(--fs-xs);font-weight:800;cursor:pointer;padding:8px 0 0;text-decoration:underline">Voir tout (${ch.length})</button>`:'')
    : 'Rien de neuf depuis ta dernière visite.';
  // N1.11 — LA BANDE « PORTEFEUILLE » A DISPARU D ICI. Ses quatre nombres
  // sont ceux de la barre d etat, qui les affiche en permanence et ouvre la
  // liste correspondante. Les redire dans un volet replie, sans lien, etait
  // la troisieme description du meme portefeuille dans le meme panneau.
  // ── Bande C : charge de travail ──
  // « Programmes figés » n'y figure pas : aucun horodatage de programme
  // n'existe au dossier, et l'inventer donnerait un nombre faux en silence.
  const g=r.charge;
  // LE COMPTEUR DE VIDÉOS MÈNE À LA CORRECTION. Il annonçait un chiffre juste
  // sans offrir aucun chemin : il fallait deviner quels athlètes, ouvrir leur
  // fiche une par une, et descendre jusqu’à la section Vidéos.
  //
  // Cliquable SEULEMENT s’il y en a : un bouton qui n’ouvre rien apprend à
  // cliquer dans le vide. Le texte, lui, ne change pas d’un caractère.
  const _libVid=`${g.videosEnAttente} vidéo${g.videosEnAttente>1?'s':''} en attente de correction`;
  const corpsC=(g.bilansSansReponse||g.videosEnAttente)
    ? `${g.bilansSansReponse} bilan${g.bilansSansReponse>1?'s':''} sans réponse · `
      +(g.videosEnAttente
        ?`<button type="button" onclick="_entrerFileVideos()" style="background:none;border:none;padding:0;font-family:inherit;font-size:inherit;line-height:inherit;color:var(--red-light);font-weight:800;text-decoration:underline;cursor:pointer">${_libVid}</button>`
        :_libVid)
    : 'Rien en attente de ta part.';
  // TROIS VOLETS POUR UN SEUL GESTE. Le coach les ouvrait l'un apres l'autre
  // pour se faire une idee, et devait retenir ce qu'il avait lu dans le
  // precedent. Un seul volet, trois sections separees d'un filet.
  const corpsSep='<div style="height:1px;background:#1e1e1e;margin:9px 0"></div>';
  const _tt=t=>`<div style="font-size:10px;letter-spacing:1.4px;text-transform:uppercase;color:var(--sub);font-weight:800;margin-bottom:4px">${t}</div>`;
  const corpsA2=_tt('Depuis ta dernière visite')+corpsA;
  const corpsC2=_tt('Charge de travail')+corpsC;
  // LES TROIS LIENS ONT QUITTE LE VOLET. Ils etaient la seule porte de trois
  // ecrans complets — la file de reprise, l'activite du portefeuille et la
  // decharge groupee — et ce volet est FERME a chaque ouverture de
  // l'application : _pilOuvert n'est jamais enregistre. Trois ecrans entiers
  // dependaient donc d'un depliage et d'un lien souligne de onze pixels.
  // Ils sont remontes dans la navigation du tableau de bord, au meme rang que
  // « Mes programmes » et « Charges articulaires ». On ne les DUPLIQUE pas :
  // remontes, ils quittent le volet, qui garde ce qu'il sait faire — lire une
  // periode.
  const corpsLiens=corpsSep;
  // N1.11 — LES TROIS COMPTEURS ONT REJOINT LA BARRE D ETAT. Ils y sont
  // ENTIERS, meme cle de filtre et meme couleur : ils ne sont pas dupliques,
  // ils ont demenage. Le volet garde ce qu il sait faire — lire une periode.
  el.innerHTML=`
    ${_pilBande('vue',"Vue d'ensemble",corpsA2+corpsSep+corpsC2+corpsLiens,String(g.bilansSansReponse+g.videosEnAttente))}`;
}
// La visite est horodatée À LA SORTIE de l'écran, pas à l'entrée : la datant à
// l'entrée, la bande A serait vide dès la seconde ouverture de la journée.
// C'est la SEULE écriture de tout ce lot.
function _pilMarquerVisite(){
  try{
    if(!currentUser||currentUser.role!=='coach') return;
    currentUser.lastCoachVisit=Date.now();
    _pilVoirTout=false;
    saveUser();
  }catch(e){}
}
// PURE. Le bloc « Pourquoi cet athlète est ici », sur sa fiche.
function _htmlPourquoiIci(c){
  let l=[];
  try{ l=expliquerUrgence(c); }catch(e){ return ''; }
  if(!l.length) return '';
  const dateCourte=t=>new Date(t).toLocaleDateString('fr-FR',{day:'2-digit',month:'short'});
  return `<div style="background:var(--surface-1);border:1px solid var(--border);border-left:3px solid var(--red);border-radius:var(--r-3);padding:11px 13px;margin-bottom:14px">
    <div style="font-size:var(--fs-2xs);color:var(--sub);letter-spacing:1.5px;font-weight:800;text-transform:uppercase;margin-bottom:7px">Pourquoi cet athlète est ici</div>
    ${l.map(x=>`<div style="display:flex;align-items:baseline;gap:8px;padding:3px 0">
      <span style="flex-shrink:0;font-size:var(--fs-2xs);font-weight:900;color:${x.gravite>=7?'var(--red)':'var(--sub)'};min-width:16px">${x.gravite}</span>
      <span style="flex:1;min-width:0;font-size:var(--fs-xs);color:var(--text-strong);line-height:1.5">${escapeHtml(x.motif)}</span>
      <span style="flex-shrink:0;font-size:var(--fs-2xs);color:var(--text-faint)">${x.date?dateCourte(x.date):''}</span>
    </div>`).join('')}
  </div>`;
}
// ── Liens WhatsApp pré-remplis ──────────────────────────────────────────────
// AUCUNE messagerie n'est implémentée : on ouvre le WhatsApp du coach avec le
// destinataire et le texte déjà écrits. Le coach relit et envoie lui-même.
// Sans numéro connu, wa.me accepte l'absence de destinataire et laisse choisir
// le contact ; le texte, lui, reste pré-rempli. C'est le cas de TOUS les
// athlètes inscrits avant l'ajout du champ téléphone.
// wa.me exige l'indicatif pays SANS zéro de tête. « 0612345678 » ouvre
// WhatsApp sur « numéro invalide » et le texte pré-rempli est perdu — or un
// coach français tape 06 par réflexe. On traite donc le cas plutôt que de
// fabriquer un lien mort :
//   00 33 6…  → 33 6…   (préfixe international écrit en toutes lettres)
//   +33 6…    → 33 6…
//   06 12…    → '' : numéro national, indicatif inconnu, inutilisable ici.
function _numWa(phone){
  const d=String(phone||'').replace(/\D/g,'').replace(/^00/,'');
  return /^0/.test(d)?'':d;
}
function waLink(phone,text){
  return 'https://wa.me/'+_numWa(phone)+'?text='+encodeURIComponent(text||'');
}
// Lien de contact d'un coach, vu depuis un de ses athlètes : WhatsApp si son
// numéro est exploitable, sinon son email, sinon rien. _numWa et non un replace
// brut — un numéro saisi en « 06… » produit un lien que WhatsApp refuse, et
// mieux vaut un mailto qu'un bouton mort.
// Partagé par l'accueil athlète et l'écran d'accès expiré : sur ce dernier,
// joindre son coach est la SEULE action qui débloque quoi que ce soit.
// Cle Firebase du coach de l athlete courant. coachEmailKey est pose au
// rattachement ; le repli par le dossier local sert aux comptes rattaches avant
// son introduction, et au coach lui-meme.
function cleCoachDe(u){
  if(!u) return null;
  if(u.coachEmailKey) return u.coachEmailKey;
  // Sans coachId, ne rien chercher : la comparaison users[k].id === undefined
  // était vraie pour tout dossier dépourvu d'id, et rendait sa clé comme
  // si c'était celle du coach.
  if(!u.coachId) return null;
  const users=DB.get("users")||{};
  const e=Object.keys(users).find(k=>users[k]&&users[k].id===u.coachId);
  if(e) return e.replace(/\./g,',');
  // DERNIER RECOURS, ET IL EST BORNE. Sur le telephone de l'athlete, `users` ne
  // contient QUE son propre dossier — les regles RTDB refusent celui du coach —
  // donc la recherche ci-dessus n'y rend jamais rien. La clef mise de cote avec
  // le profil public, elle, est locale et porte l'adresse du coach.
  //
  // CE QU'ELLE RATTRAPE, ET CE QU'ELLE NE RATTRAPE PAS. Le cache n'est ecrit que
  // par pullProfilCoach, qui recoit deja la clef : il ne peut donc pas la faire
  // apparaitre chez un athlete qui ne l'a JAMAIS eue. Il la rend a celui qui
  // l'avait et l'a perdue — un dossier ecrase par une copie distante plus
  // ancienne, une restauration depuis un export d'avant coachEmailKey. C'est
  // etroit, et c'est gratuit ; ce n'est pas une raison de ne pas le faire.
  //
  // APRES le garde coachId, jamais avant : un coach n'a pas de coachId et sort
  // plus haut, sans quoi il recuperait ici la clef d'un cache qui n'est pas le
  // sien.
  try{
    const b=JSON.parse(localStorage.getItem("rc_coach_profil")||"null");
    if(b&&b.key) return b.key;
  }catch(err){}
  return null;
}
// Profil public du coach, tel que rapatrie a la derniere connexion. Sert aussi
// hors ligne : c est la seule copie que l athlete possede.
function profilCoachLocal(key){
  try{
    const b=JSON.parse(localStorage.getItem("rc_coach_profil")||"null");
    return b&&(!key||b.key===key)?b.d:null;
  }catch(e){ return null; }
}

// PURE. LE DOSSIER DU COACH TEL QU'ON PEUT L'AFFICHER — et la seule façon de
// le lire.
//
// SUR LE TÉLÉPHONE DE L'ATHLÈTE, `users` NE CONTIENT QUE SON PROPRE DOSSIER :
// les règles RTDB refusent le dossier complet du coach, et pullProfilCoach
// range délibérément la photo HORS de currentUser — en base64, elle repartirait
// vers Firebase à chaque synchronisation, dupliquée autant de fois qu'il y a
// d'athlètes. Chercher `x.id === coachId` dans `users` ne rend donc RIEN chez
// un athlète, et c'est exactement pour cela que la photo du coach n'apparaissait
// pas sur l'écran nutrition : les deux rendus la cherchaient là, et nulle part
// ailleurs. Seul l'accueil lisait coach_public, par profilCoachLocal.
//
// LE DOSSIER LOCAL RESTE LU, et il sert dans un seul cas : sur l'appareil du
// COACH, où son propre dossier est bien là et où aucun profil public n'est en
// cache.
//
// LA FUSION RETIENT LA PREMIÈRE VALEUR NON VIDE, champ par champ. Un
// Object.assign laisserait le public écraser le local avec du vide — c'est la
// leçon déjà payée par ouvrirVitrineCoach, qui effaçait le dossier du coach
// sur son propre appareil.
function coachAffichable(user,usrs){
  const u=user||currentUser;
  if(!u||!u.coachId) return null;
  const map=usrs||DB.get('users')||{};
  const loc=Object.values(map).find(x=>x&&x.id===u.coachId)||{};
  let pub=null;
  try{ pub=profilCoachLocal(cleCoachDe(u)); }catch(e){ pub=null; }
  const out=Object.assign({},loc);
  const plein=v=>Array.isArray(v)?v.length>0:!!(v&&String(v).trim());
  for(const k of Object.keys(pub||{})){
    if(plein(pub[k])||out[k]===undefined) out[k]=pub[k];
  }
  return out;
}
// La photo, et rien d'autre : c'est ce que trois écrans demandent.
function photoCoachDe(user,usrs){
  const c=coachAffichable(user,usrs);
  return (c&&c.coachPhoto)||'';
}
// LA MARQUE DU COACH : son logo, ou à défaut sa signature. Kevin, 09/09/2026 :
// « soit signature ou logo, qu'il puisse mettre l'un des deux ».
//
// L'ORDRE EST UNE DECISION, pas un hasard. Le logo passe devant parce qu'il est
// fait pour être posé sur autre chose ; une signature manuscrite n'a été
// pensée que pour le bas d'une vitrine. Un coach qui remplit les deux verra
// donc son logo sur les séances de ses athlètes, et sa signature sur sa page.
//
// PURE, et elle rend toujours une chaîne : une image sans marque est un cas
// normal — l'athlète n'a pas forcément de coach.
function marqueCoachDe(user,usrs){
  const c=coachAffichable(user,usrs);
  if(!c) return '';
  return String(c.logo||c.signature||'');
}

// ══════ CONTACT COACH : UN CONSENTEMENT, PAS UN CHAMP ══════
// Le numéro personnel du coach vivait dans coach_public.phone, lisible par
// TOUS ses athlètes rattachés — la règle RTDB ne portait qu'un .validate
// d'écriture, la lecture étant ouverte par le nœud parent. Personne n'avait
// jamais dit oui.
//
// Trois états, et le défaut est le silence. Sous 'whatsapp', le numéro n'est
// publié qu'avec un consentement HORODATÉ, révocable d'un geste — RGPD
// art. 7.3 : retirer doit être aussi simple qu'accorder.
const CONTACT_MODES=Object.freeze(['aucun','whatsapp','email']);
const CONTACT_JOURNAL_MAX=100;
// MIGRATION RESTRICTIVE, et c'est le point qui compte : un phone hérité, sans
// consentAt, bascule en 'aucun'. Jamais l'inverse. Un consentement ne se
// déduit pas d'un champ rempli à une époque où la question n'était pas posée.
//
// PURE : elle ne réécrit rien, elle LIT. La bascule est un défaut de lecture,
// pas une écriture au chargement.
function contactCoach(pub){
  const c=(pub||{}).contact;
  const vide={mode:'aucun',consentAt:null,horaires:''};
  if(!c||typeof c!=='object') return vide;
  const mode=CONTACT_MODES.indexOf(c.mode)>=0?c.mode:'aucun';
  if(mode==='aucun') return vide;
  // Un mode sans consentement horodaté ne vaut rien : c'est exactement le
  // cas du phone hérité.
  if(!c.consentAt||typeof c.consentAt!=='string') return vide;
  return {mode:mode,consentAt:c.consentAt,
    horaires:typeof c.horaires==='string'?c.horaires.slice(0,200):''};
}
// PURE. Le numéro publiable, ou ''. Un numéro corrompu ou non exploitable
// par wa.me retombe silencieusement sur 'aucun' — un bouton mort vaut moins
// que pas de bouton.
function contactNumero(pub){
  const c=contactCoach(pub);
  if(c.mode!=='whatsapp') return '';
  const n=_numWa((pub||{}).phone);
  return (n&&n.length>=8)?n:'';
}
// Journal des RENVOIS : une date, un destinataire HASHÉ, rien d'autre. Ni le
// contenu de l'échange, ni le numéro, ni un identifiant en clair. RepCore ne
// reçoit pas ce qui se dit sur WhatsApp et n'a pas à le savoir.
//
// Le hash est un FNV-1a tronqué : il ne sert pas à protéger un secret — un
// identifiant d'athlète n'en est pas un — mais à éviter qu'un journal exporté
// nomme des personnes. Il suffit à dédoublonner, pas à réidentifier.
function _hashCourt(x){
  const s2=String(x||'');
  let h=2166136261;
  for(let i=0;i<s2.length;i++){ h^=s2.charCodeAt(i); h=Math.imul(h,16777619); }
  return (h>>>0).toString(36);
}
// Borné à 100 : un journal qui grossit sans fin finit par peser dans le
// document poussé à chaque synchronisation, et personne ne lit la 400e ligne.
function journaliserRenvoi(coach,athleteId,ref){
  if(!coach||typeof coach!=='object') return null;
  if(!Array.isArray(coach.journalRenvoi)) coach.journalRenvoi=[];
  const d=(ref instanceof Date?ref:new Date()).toISOString();
  coach.journalRenvoi.push({d:d,a:_hashCourt(athleteId)});
  if(coach.journalRenvoi.length>CONTACT_JOURNAL_MAX)
    coach.journalRenvoi=coach.journalRenvoi.slice(-CONTACT_JOURNAL_MAX);
  return coach.journalRenvoi;
}
// Ce que l'athlète lit avant de partir. Il quitte RepCore : le dire est la
// moindre des choses, et ça vaut mieux qu'un bouton qui ouvre une autre app
// sans prévenir.
const CONTACT_SORTIE='Tu quittes RepCore. Cet échange ne sera pas conservé '
  +'dans ton dossier.';
// Ce que le coach lit en révoquant. Une révocation empêche les FUTURS accès ;
// elle ne rappelle pas ce qui a déjà été communiqué, et prétendre le
// contraire serait mentir.
const CONTACT_REVOCATION='Tes athlètes ne verront plus ton numéro. Ceux qui '
  +'l\'ont déjà noté le gardent : une révocation ne rappelle pas ce qui a été '
  +'communiqué.';

// ══════════════ CADRE DE DISPONIBILITÉ DU COACH ═══════════════════════════
// Le coach déclare un délai de réponse HABITUEL et des plages ; l'athlète le
// lit au moment où il écrit. Un mode absence daté informe — il n'empêche
// jamais un envoi.
//
// AUCUNE PROMESSE. Le vocabulaire est « habituellement », jamais « garanti »
// ni « sous 24 h maximum » : un délai affiché ne doit pas se lire comme un
// engagement contractuel. Une assertion l'interdit littéralement.
//
// FUSEAUX. L'app ne stocke le fuseau de personne. Les heures déclarées sont
// donc comparées à l'horloge LOCALE de qui regarde — l'athlète voit son heure
// à lui, ce que demande la règle 8. Limite assumée et à dire : un coach à
// Montréal qui déclare 9 h-19 h sera lu 9 h-19 h par un athlète à Paris.
const DISPO_ABSENCE_MAX_J=90;
const DISPO_DELAI_MIN_H=1, DISPO_DELAI_MAX_H=168;   // 1 h à 7 jours
const DISPO_MEDIAN_FENETRE_J=30;

function _dispoMinutes(hhmm){
  const m=/^(\d{1,2}):(\d{2})$/.exec(String(hhmm||'').trim());
  if(!m) return null;
  const h=+m[1], mn=+m[2];
  if(!(h>=0&&h<=23&&mn>=0&&mn<=59)) return null;
  return h*60+mn;
}
// PURE. Vrai si `now` tombe dans l'une des plages déclarées.
//
// Une plage dont la fin est AVANT le début traverse minuit (22:00 → 02:00) :
// elle vaut alors du début à minuit le jour dit, et de minuit à la fin le
// LENDEMAIN. L'ignorer aurait rendu toute plage de nuit systématiquement
// fausse, sans que rien ne le signale.
function dispoEstDansPlage(dispo,now){
  const l=(dispo&&Array.isArray(dispo.plages))?dispo.plages:[];
  if(!l.length) return false;
  const d=(now instanceof Date)?now:new Date(now||Date.now());
  const jour=d.getDay(), min=d.getHours()*60+d.getMinutes();
  const veille=(jour+6)%7;
  for(const p of l){
    if(!p) continue;
    const deb=_dispoMinutes(p.debut), fin=_dispoMinutes(p.fin);
    if(deb==null||fin==null) continue;
    const j=Number(p.jour);
    if(!(j>=0&&j<=6)) continue;
    if(deb<fin){ if(j===jour&&min>=deb&&min<fin) return true; }
    else if(deb>fin){
      // Traverse minuit : la soirée du jour dit, puis le petit matin du suivant.
      if(j===jour&&min>=deb) return true;
      if(j===veille&&min<fin) return true;
    }
  }
  return false;
}
// PURE. Une absence doit porter une date de FIN : sans elle, elle ne s'éteint
// jamais et l'athlète ne sait pas quand revenir. Quatre-vingt-dix jours au
// plus, renouvelable — au-delà ce n'est plus une absence, c'est un arrêt.
function absenceValide(absence,now){
  if(!absence) return false;
  const t=(now instanceof Date)?now.getTime():(typeof now==='number'?now:Date.now());
  const au=_dispoTs(absence.au);
  if(au==null) return false;                       // date de fin OBLIGATOIRE
  const du=_dispoTs(absence.du);
  const debut=(du==null)?t:du;
  if(au<=debut) return false;                      // une fin avant le début n'est pas une absence
  return (au-debut)<=DISPO_ABSENCE_MAX_J*864e5;
}
function _dispoTs(v){
  if(v==null||v==='') return null;
  if(typeof v==='number') return isFinite(v)?v:null;
  const t=Date.parse(v);
  return isFinite(t)?t:null;
}
// L'absence s'éteint TOUTE SEULE à sa date de fin : le coach n'a rien à
// décocher au retour, et un oubli ne laisse pas un bandeau mensonger.
function absenceEnCours(dispo,now){
  const a=dispo&&dispo.absence;
  if(!a||a.actif!==true) return false;
  const t=(now instanceof Date)?now.getTime():(typeof now==='number'?now:Date.now());
  if(!absenceValide(a,t)) return false;
  const du=_dispoTs(a.du), au=_dispoTs(a.au);
  if(du!=null&&t<du) return false;
  return t<au;
}
function _dispoDateCourte(ts){
  try{ return new Date(ts).toLocaleDateString('fr-FR',{day:'2-digit',month:'2-digit'}); }
  catch(e){ return ''; }
}
// PURE. Le texte que lit l'athlète. Chaîne vide = aucun cadre déclaré, donc
// rien à afficher : mieux vaut le silence qu'un délai inventé.
function dispoLibelle(dispo,now){
  if(!dispo) return '';
  if(absenceEnCours(dispo,now)){
    const au=_dispoTs(dispo.absence.au);
    return 'Absent jusqu\'au '+_dispoDateCourte(au);
  }
  const h=Number(dispo.delaiH);
  if(!(h>=DISPO_DELAI_MIN_H&&h<=DISPO_DELAI_MAX_H)) return '';
  // « habituellement » : c'est une habitude constatée, pas un engagement.
  if(h<24) return 'Répond habituellement sous '+Math.round(h)+' h';
  const j=Math.round(h/24);
  return j<=1?'Répond habituellement sous 24 h'
             :'Répond habituellement sous '+j+' jours';
}
// PURE. Délai médian de réponse en heures, sur les trente derniers jours.
// RÉSERVÉ AU COACH : ce n'est pas un score, il ne sort jamais vers l'athlète
// ni vers un tiers. La liste blanche CHAMPS_PROFIL_COACH l'en empêche
// structurellement — il n'y figure pas, et une assertion le vérifie.
function delaiMedianReponse(echanges,now){
  const t=(now instanceof Date)?now.getTime():(typeof now==='number'?now:Date.now());
  const limite=t-DISPO_MEDIAN_FENETRE_J*864e5;
  const h=[];
  for(const e of (Array.isArray(echanges)?echanges:[])){
    if(!e) continue;
    const envoi=_dispoTs(e.date), rep=_dispoTs(e.reponseDate);
    if(envoi==null||rep==null) continue;
    if(rep<envoi) continue;                 // horodatage incohérent : on l'écarte
    if(envoi<limite) continue;
    h.push((rep-envoi)/36e5);
  }
  if(!h.length) return null;
  h.sort((a,b)=>a-b);
  const m=h.length%2
    ? h[(h.length-1)/2]
    : (h[h.length/2-1]+h[h.length/2])/2;
  return Math.round(m*10)/10;
}
// Les bilans sont le SEUL échange horodaté des deux côtés : l'athlète envoie
// (b.date), le coach répond (b.reponseDate). Le contact direct sort de l'app
// et la vidéo ne porte pas de date de réponse exploitable.
function dispoEchangesDe(clients){
  const out=[];
  for(const c of (Array.isArray(clients)?clients:[]))
    for(const b of ((c&&c.bilans)||[]))
      if(b&&b.date&&b.reponseDate) out.push({date:b.date,reponseDate:b.reponseDate});
  return out;
}
// LA SANTÉ PASSE AVANT L'INTENDANCE. Drapeau rouge ou douleur au-dessus du
// seuil : le cadre de disponibilité ne s'applique pas, et une trace est
// écrite. Elle remonte par la synchronisation ordinaire — sans serveur, c'est
// l'appareil du coach qui lèvera la notification à sa prochaine ouverture.
function dispoSanteForce(user){
  try{
    // LE SIGNE GÉNÉRAL EN PREMIER, et pas seulement en plus : _suspTextes lui
    // associe TEXTE_ARRET_GENERAL — « Arrête l’entraînement et fais-toi
    // examiner » — qui est le texte le plus protecteur du produit. Quand les
    // deux familles sont actives, c’est celui-là qu’il faut afficher.
    if(drapeauGeneralActif(user)) return 'general';
    if(drapeauRougeActif(user)) return 'drapeau';
    const sg=signauxEntrainement(user);
    if(sg&&(sg.douleur||sg.douleurDiffuse)) return 'douleur';
  }catch(e){}
  return null;
}
// PURE (au dossier pres). LES DEUX CANAUX EXTERNES DU COACH, separement.
// ⚠ EXTRAITE DE _coachContactHref SANS CHANGER UNE VIRGULE DE LA REGLE. Deux
// endroits resolvent desormais le meme coach — le lien unique de l'ecran
// d'acces expire, et les trois boutons de l'accueil : recopier la resolution
// aurait fabrique deux verites, et c'est exactement ce que le commentaire
// ci-dessous interdit depuis le debut.
function _canauxCoach(coachId,users){
  const vide={whatsapp:'',mail:''};
  if(!coachId) return vide;
  const us=users||DB.get('users')||{};
  const coach=Object.values(us).find(x=>x&&x.id===coachId);
  const _cle=cleCoachDe(currentUser);
  const _pub=profilCoachLocal(_cle);
  const email=Object.keys(us).find(k=>us[k]&&us[k].id===coachId)
    ||(_cle?_cle.replace(/,/g,'.'):null);
  const _src=contactNumero(coach)?coach:_pub;
  return {whatsapp:contactNumero(_src)||'', mail:email||'', src:_src};
}
function _coachContactHref(coachId,texte,users){
  if(!coachId) return '';
  const us=users||DB.get('users')||{};
  const coach=Object.values(us).find(x=>x&&x.id===coachId);
  // Sur le téléphone de l'athlète, le dossier du coach est absent : ni numéro
  // ni adresse. Le profil public porte le numéro, et coachEmailKey l'adresse.
  const _cle=cleCoachDe(currentUser);
  const _pub=profilCoachLocal(_cle);
  const email=Object.keys(us).find(k=>us[k]&&us[k].id===coachId)
    ||(_cle?_cle.replace(/,/g,'.'):null);
  // LE CONSENTEMENT COMMANDE. Sans lui, aucun numéro ne devient un lien —
  // ni celui du profil public, ni celui du dossier local. Le repli email
  // ci-dessous reste : joindre son coach par mail n'expose pas un numéro
  // personnel, et l'adresse sert déjà à l'authentification.
  //
  // ON CHOISIT LA SOURCE QUI PORTE UN NUMÉRO CONSENTI, pas celle qui porte
  // un numéro. L'ancien « coach?.phone ? coach : _pub » se décidait sur la
  // seule présence d'un phone : un dossier coach portant un numéro hérité,
  // sans objet `contact`, masquait le profil public qui, lui, portait le
  // consentement. contactNumero rendait '' et « Un souci ? » retombait sur
  // le mail alors que le WhatsApp était publié.
  // Aucune permission n'est relâchée : contactNumero exige toujours
  // mode==='whatsapp' ET un consentAt horodaté, sur la source retenue.
  const _src=contactNumero(coach)?coach:_pub;
  const phone=contactNumero(_src);
  if(phone) return texte?waLink(_src.phone,texte):('https://wa.me/'+phone);
  if(!email) return '';
  return 'mailto:'+email+(texte?'?subject='+encodeURIComponent('RepCore')+'&body='+encodeURIComponent(texte):'');
}
// safeUrl n'autorise que http(s) : un lien mailto: y deviendrait '#', soit
// exactement le bouton mort qu'on cherche à éviter quand le coach n'a pas
// renseigné de numéro. Allow-list resserrée sur les deux seules formes que
// _coachContactHref sait produire, et échappement d'attribut conservé.
function _safeContactUrl(u){
  const s=String(u||'').trim();
  return /^(https:\/\/wa\.me\/|mailto:)/i.test(s)?escapeHtml(s):'#';
}
function _telAthlete(c){return _numWa(c?.phone);}
// Un numéro est enregistré mais inexploitable : le dire précisément, sinon le
// coach lit « numéro non enregistré » alors qu'il vient de le saisir.
function _telInutilisable(c){return !!(c&&c.phone)&&!_numWa(c.phone);}
// Textes contextualisés par type de ligne « À traiter ». Point de départ, pas
// message final : rien n'est envoyé sans que le coach ait validé dans WhatsApp.
function _waTexteTodo(type,c){
  const p=c?.fname||'';
  const j=n=>n+' jour'+(n>1?'s':'');
  const dernier=(c?.bilans||[]).reduce((m,b)=>Math.max(m,b.date),0);
  if(type==='overdue'){
    // needsAlert se déclenche à 14 jours : le « retard » est ce qui dépasse.
    const retard=Math.max(1,Math.floor((Date.now()-dernier)/864e5)-14);
    return 'Salut '+p+', je vois que ton bilan est en retard de '+j(retard)
      +' : tu peux le remplir quand tu veux dans l\'app 💪';
  }
  if(type==='nostart'){
    const depuis=Math.max(1,Math.floor((Date.now()-(c?.createdAt||0))/864e5));
    return 'Salut '+p+', tu es inscrit depuis '+j(depuis)
      +' et je n\'ai pas encore ton premier bilan : dis-moi si tu bloques sur quelque chose, on démarre quand tu veux 💪';
  }
  if(type==='expiring'){
    const reste=Math.max(1,Math.ceil(((c?.accessExpiry||0)-Date.now())/864e5));
    return 'Salut '+p+', ton accès RepCore arrive à échéance dans '+j(reste)
      +' : pense à le renouveler pour garder ton suivi 💪';
  }
  if(type==='bilan') return 'Salut '+p+', j\'ai bien reçu ton bilan, je le regarde et je reviens vers toi rapidement 💪';
  if(type==='noprog') return 'Salut '+p+', je prépare ton programme, je te l\'envoie très vite 💪';
  // Signaux d'entraînement. Ces messages POSENT UNE QUESTION et ne donnent
  // aucun conseil : ni « arrête cet exercice », ni « baisse la charge », ni
  // quoi que ce soit qui ressemble à un avis médical. C'est au coach d'écrire
  // la suite, le texte n'est qu'une amorce qu'il relit avant d'envoyer.
  //
  // ET IL NE NOMME PAS LA DOULEUR. Même règle que _frTexteRelance : le canal
  // est NON CHIFFRÉ, aucune donnée de santé n'y entre. Ce texte disait « je
  // vois que tu as noté de la douleur sur tes dernières séances » — un fait
  // de santé, écrit en clair, sur un fil que l'athlète n'a pas choisi et que
  // n'importe qui lisant son téléphone voit. Le projet a par ailleurs retiré
  // tout lien de contact du bloc DOULEUR pour cette raison exacte.
  // Le message garde toute son utilité : il demande un point AVANT la
  // prochaine séance. Le coach sait pourquoi il écrit ; le message ne le dit
  // pas, et c'est l'athlète qui nomme ce qu'il veut nommer.
  if(type==='douleur'||type==='douleurdiff')
    return 'Salut '+p+', j\'aimerais faire un point avec toi avant ta prochaine '
      +'séance. Dis-moi quand tu es dispo 💪';
  if(type==='decrochage')
    return 'Salut '+p+', je vois que tes dernières séances n\'ont pas été terminées. '
      +'Dis-moi ce qui bloque : le temps, la fatigue, un exercice en particulier ? 💪';
  if(type==='entrainement')
    return 'Salut '+p+', ta progression marque le pas en ce moment. On regarde ça ensemble ? 💪';
  return 'Salut '+p+' 💪';
}
// Corps GÉNÉRIQUE pour l'envoi groupé : ni prénom, ni compteur de jours.
// Le texte individuel de _waTexteTodo porte les chiffres d'UN athlète ; le
// pré-remplir dans la modale groupée envoyait à tout le monde le retard du
// premier de la liste, avec son prénom. Chaque lien est ré-adressé dans
// _wagPreparer avec « Salut <prénom>, » + ce corps.
function _waCorpsGroupe(type){
  if(type==='overdue') return 'je vois que ton bilan est en retard : tu peux le remplir quand tu veux dans l\'app 💪';
  if(type==='nostart') return 'je n\'ai pas encore ton premier bilan : dis-moi si tu bloques sur quelque chose, on démarre quand tu veux 💪';
  if(type==='expiring') return 'ton accès RepCore arrive bientôt à échéance : pense à le renouveler pour garder ton suivi 💪';
  if(type==='bilan') return 'j\'ai bien reçu ton bilan, je le regarde et je reviens vers toi rapidement 💪';
  if(type==='noprog') return 'je prépare ton programme, je te l\'envoie très vite 💪';
  return '';
}
// Bouton de contact d'une ligne « À traiter ». AU TRAIT, ET NON EN EMOJI :
// une bulle emoji est verte chez Apple, grise chez Google et jaune vif sur
// certains Android — elle ne peut pas porter la couleur du bouton, et elle
// jure avec les seize signaux de la ligne, qui sont tous des traits.
// Un seul athlète → vrai lien <a> : un clic, et aucun bloqueur de fenêtres ne
// s'interpose. Plusieurs → ouvre la sélection groupée pré-cochée sur cette
// ligne, où chaque envoi reste un geste distinct.
function _waBoutonTodo(r,idx){
  const style='background:none;border:1px solid #1e3a1e;color:var(--green);border-radius:var(--r-2);'
    +'min-width:34px;min-height:34px;padding:0 8px;font-size:var(--fs-md);cursor:pointer;flex-shrink:0;'
    +'display:inline-flex;align-items:center;justify-content:center;text-decoration:none';
  if(r.list.length===1){
    const c=r.list[0];
    const tel=_telAthlete(c);
    const titre=tel?'Écrire à '+(c.fname||'')+' sur WhatsApp'
      :'Ouvrir WhatsApp avec le message pré-rempli ('+(c.fname||'cet athlète')+' n\'a pas de numéro enregistré)';
    return `<a href="${safeUrl(waLink(tel,_waTexteTodo(r.type,c)))}" target="_blank" rel="noopener"
      onclick="event.stopPropagation()" title="${escapeHtml(titre)}" aria-label="${escapeHtml(titre)}"
      style="${style}${tel?'':';opacity:.55'}">${icon('message-circle',16)}</a>`;
  }
  return `<button onclick="event.stopPropagation();openWaGroupe(${idx})"
    title="Écrire aux ${r.list.length} athlètes de cette ligne" aria-label="Écrire aux ${r.list.length} athlètes de cette ligne"
    style="${style}">${icon('message-circle',16)}</button>`;
}
// ── Envoi groupé ────────────────────────────────────────────────────────────
// Appelée sans argument depuis le dashboard, ou avec l'index d'une ligne
// « À traiter » pour pré-cocher exactement ses athlètes.
// Pas de boucle window.open : au-delà de la première, le navigateur les bloque
// et le coach croirait avoir écrit à tout le monde. Chaque destinataire reçoit
// son propre lien, donc son propre geste — rien ne peut être avalé en silence.
// ══ CANAL DU COACH ══════════════════════════════════════════════════════════
// Un fil de diffusion, pas une messagerie : le coach écrit, l'athlète lit et
// réagit. Il n'y a AUCUN champ de saisie côté athlète, et c'est délibéré — un
// fil où douze athlètes se répondent exposerait leurs prénoms les uns aux
// autres, ce que RepCore n'a jamais fait.
//
// CE MODULE REMPLACE « Mot du coach ». L'ancien recopiait le message dans le
// dossier de CHAQUE athlète : les athlètes connus par leur seul code ne le
// recevaient jamais, l'historique était perdu à chaque nouveau mot, et le texte
// repartait vers Firebase à chaque sauvegarde de dossier. Ici, un seul
// exemplaire vit dans /canaux/{coach}, et le dossier des athlètes n'est pas
// touché du tout. Le champ `annonce` des anciens dossiers devient inerte, sans
// migration — même traitement que welcomeAudio lors du retrait du message vocal.
//
// CE QUI N'EST PAS PROMIS : le téléphone ne sonnera pas. Le plan Spark ne fait
// tourner aucune Cloud Function et rien ne s'abonne au push. Un message se
// découvre à l'ouverture de l'app, et les écrans le disent.
const CANAL_TITRE_MAX=80;
const CANAL_TEXTE_MAX=1000;
const CANAL_LIEN_MAX=500;
// Le fil affiché est borné. Ce n'est pas une pagination — au-delà, les messages
// restent dans Firebase mais ne descendent plus. Vingt cartes couvrent
// largement l'usage d'un coach, et bornent ce qui transite.
const CANAL_MAX_AFFICHES=20;
const CANAL_EMOJIS=['👍','❤️','💪','🔥'];
const CANAL_VU_CLE='rc_canal_vu';

// Clé Firebase du canal à consulter. Le coach lit le sien, l'athlète celui de
// son coach. cleCoachDe() ne convient pas pour le coach : elle sort sur
// `if(!u.coachId) return null`, et un coach n'a pas de coachId.
function canalCle(u){
  if(!u||!u.email) return null;
  if(u.role==='coach') return u.email.replace(/\./g,',');
  return cleCoachDe(u);
}
// L'onglet est ouvert si — et seulement si — un coach est rattaché. LE GRISÉ
// N'EST PAS LA PROTECTION : les règles refusent la lecture de /canaux à qui n'a
// pas le coachEmailKey correspondant. Trafiquer le HTML ne donne rien.
function canalAccessible(u){
  return !!(u&&u.role==='athlete'&&(u.coachId||u.coachEmailKey));
}

// ── Lectures mémorisées SUR L'APPAREIL, jamais dans le dossier ──────────────
// Le coach ne peut donc pas voir qui a lu, et ne peut pas rallumer une pastille
// en réécrivant un dossier périmé par-dessus — ce que l'écrasement du dossier
// entier rend sinon inévitable. Même raisonnement que rc_annonce_lue.
// Contrepartie assumée : sur un appareil neuf, le fil apparaît une fois non lu.
function _canalVus(){
  try{ const v=JSON.parse(localStorage.getItem(CANAL_VU_CLE)||'{}');
    return (v&&typeof v==='object')?v:{}; }catch(e){ return {}; }
}
function _canalMarquerVu(email,at){
  const m=_canalVus();
  m[String(email||'')]=Number(at)||Date.now();
  try{ localStorage.setItem(CANAL_VU_CLE,JSON.stringify(m)); }catch(e){}
}
// PURE. Le profil coach est passé en paramètre : la règle est éprouvable sans
// toucher ni au stockage ni au réseau.
//
// canalDernier vit dans coach_public, PAS dans /canaux, et c'est ce qui rend la
// pastille gratuite : coach_public est déjà retéléchargé à chaque ouverture de
// l'accueil pour la photo et la phrase du coach. Aller chercher l'horodatage
// dans /canaux coûterait une requête par lancement d'app, à tout le monde, y
// compris à ceux qui n'ouvrent jamais l'onglet.
function canalNonLu(user,profil,vus){
  if(!canalAccessible(user)) return false;
  const dernier=Number(profil&&profil.canalDernier)||0;
  if(!dernier) return false;
  const vu=Number((vus||{})[String(user.email||'')])||0;
  return dernier>vu;
}
// PURE. Le message épinglé, tel qu'il doit s'afficher en bannière d'accueil.
function canalEpingleAAfficher(profil){
  const e=profil&&profil.canalEpingle;
  if(!e||typeof e!=='object') return null;
  const texte=String(e.texte==null?'':e.texte).trim();
  const titre=String(e.titre==null?'':e.titre).trim();
  if(!texte&&!titre) return null;
  return {id:String(e.id||''),titre,texte,lien:String(e.lien||''),at:Number(e.at)||0};
}
// PURE. L'objet Firebase → un tableau ordonné : l'épinglé d'abord, puis du plus
// récent au plus ancien. Object.keys ne garantit aucun ordre, et Firebase rend
// bien un objet, pas un tableau.
function canalTrier(messages){
  if(!messages||typeof messages!=='object') return [];
  return Object.keys(messages)
    .map(id=>Object.assign({id},messages[id]))
    .filter(m=>m&&(m.texte||m.titre))
    .sort((a,b)=>{
      if(!!a.epingle!==!!b.epingle) return a.epingle?-1:1;
      return (Number(b.at)||0)-(Number(a.at)||0);
    })
    .slice(0,CANAL_MAX_AFFICHES);
}
// PURE. Le domaine affiché sur la carte de lien. Sans serveur ni requête
// croisée, RepCore ne peut pas lire le titre d'une page distante : le domaine
// est la seule chose honnête à montrer.
function canalDomaine(lien){
  const s=String(lien==null?'':lien).trim();
  const m=/^https?:\/\/([^/?#]+)/i.exec(s);
  return m?m[1].replace(/^www\./i,''):'';
}
// ── LES PASTILLES D'ONGLET, CHIFFREES ───────────────────────────────────
// Le point rouge disait « il y a du neuf » sans dire combien : un message et
// six messages avaient exactement la meme tete. Et pour le canal, la meme
// information etait POUSSEE UNE SECONDE FOIS en banniere sur l'accueil, au
// milieu des seances, du poids et du rappel de bilan. Deux endroits pour une
// seule chose, dont un qui noyait le reste.
//
// Desormais : le compte vit sur l'icone, en bas, et nulle part ailleurs.
function _pastilleOnglet(onglet,n,libelle){
  const btn=document.querySelector('#client-tabbar .tab-btn[data-tab="'+onglet+'"]');
  if(!btn) return null;
  const dot=btn.querySelector('.tab-dot');
  const c=Math.max(0,Math.floor(Number(n)||0));
  if(dot){
    dot.classList.toggle('on',c>0);
    // La classe ET le texte : sans le texte la pastille reste un point, sans
    // la classe le chiffre deborde d'un cercle de neuf pixels.
    dot.classList.toggle('chiffre',c>0);
    dot.textContent=c>0?(c>9?'9+':String(c)):'';
  }
  // Le libelle accessible suit le chiffre : une pastille seule ne se percoit
  // qu'a l'oeil, et le lecteur d'ecran annoncerait un onglet sans rien.
  if(c>0&&typeof libelle==='function') btn.setAttribute('aria-label',libelle(c));
  else btn.removeAttribute('aria-label');
  return btn;
}
// ── COMBIEN DE MESSAGES NON LUS ─────────────────────────────────────────
// canalNonLu ne rend qu'un booleen, et il ne peut pas faire mieux : la seule
// chose que l'athlete connaisse sans ouvrir le canal est canalDernier, UN
// horodatage pose dans coach_public. Les messages, eux, vivent dans /canaux.
//
// On memorise donc les horodatages des messages A CHAQUE OUVERTURE du canal.
// Le compte devient exact des la deuxieme visite, et vaut « au moins un »
// avant : mieux vaut annoncer 1 quand il y en a 3 que de ne rien annoncer.
const CANAL_AT_CLE='rc_canal_ats';
function _canalMemoriser(cle,liste){
  if(!cle||!Array.isArray(liste)) return;
  const ats=liste.map(m=>Number(m&&m.at)||0).filter(a=>a>0)
    .sort((a,b)=>b-a).slice(0,60);
  try{
    const t=JSON.parse(localStorage.getItem(CANAL_AT_CLE)||'{}');
    t[String(cle)]=ats;
    localStorage.setItem(CANAL_AT_CLE,JSON.stringify(t));
  }catch(e){}
}
function _canalAtsMemorises(cle){
  try{
    const t=JSON.parse(localStorage.getItem(CANAL_AT_CLE)||'{}');
    const a=t&&t[String(cle)];
    return Array.isArray(a)?a:[];
  }catch(e){ return []; }
}
// PURE quant a sa decision : elle ne lit le stockage que pour affiner le
// compte, jamais pour decider s'il y a du neuf. Cette decision-la reste
// exactement celle de canalNonLu, et les deux ne peuvent pas diverger.
function canalNonLusCompte(user,profil,vus){
  if(!canalNonLu(user,profil,vus)) return 0;
  const vu=Number((vus||{})[String(user&&user.email||'')])||0;
  const n=_canalAtsMemorises(canalCle(user)).filter(a=>a>vu).length;
  return n>0?n:1;
}
// ── LE BILAN DU JOUR ────────────────────────────────────────────────────
// Meme regle que la carte de rappel de l'accueil — _bilTexteRetard rend un
// texte quand un bilan est du, rien sinon. On ne recalcule pas l'echeance
// ici : deux calculs de la meme date finiraient par ne plus dire pareil.
function _bilanAFaireAujourdhui(){
  try{ return !!_bilTexteRetard(_bilRetardJours(getNextBilanSaturday())); }
  catch(e){ return false; }
}
// L'ONGLET OUVERT VAUT LU, POUR LA JOURNEE SEULEMENT. Le bilan reste a faire
// tant qu'il n'est pas rempli, et il se rappellera demain : la pastille
// signale, elle ne harcele pas. Le jour est stocke en clair — une date lisible
// vaut mieux qu'un horodatage a comparer.
const BILAN_ONGLET_CLE='rc_bilan_onglet_vu';
function _bilanOngletVuAujourdhui(){
  try{ return localStorage.getItem(BILAN_ONGLET_CLE)===localISODate(new Date()); }
  catch(e){ return false; }
}
function bilanMarquerOngletVu(){
  try{ localStorage.setItem(BILAN_ONGLET_CLE,localISODate(new Date())); }catch(e){}
}
// ── L'onglet : verrou et pastille ───────────────────────────────────────────
function _majOngletCanal(){
  const btn=document.querySelector('#client-tabbar .tab-btn[data-tab="canal"]');
  if(!btn) return;
  const ouvert=canalAccessible(currentUser);
  btn.classList.toggle('verrou',!ouvert);
  // aria-disabled et non l'attribut disabled : le bouton reste atteignable au
  // clavier et mène à la saisie du code coach. Un onglet verrouillé qu'on ne
  // peut même pas atteindre n'expliquerait jamais comment le déverrouiller.
  if(ouvert) btn.removeAttribute('aria-disabled');
  else btn.setAttribute('aria-disabled','true');
  // LE COMPTE, ET PLUS LE SEUL FAIT. _pastilleOnglet efface le libelle quand
  // le compte est nul : le verrou repose donc le sien APRES, sinon il serait
  // retire aussitot pose.
  const n=ouvert?canalNonLusCompte(currentUser,profilCoachLocal(canalCle(currentUser)),_canalVus()):0;
  _pastilleOnglet('canal',n,c=>'Canal : '+c+' nouveau'+(c>1?'x':'')+' message'+(c>1?'s':'')+' de ton coach');
  if(!ouvert) btn.setAttribute('aria-label','Canal : réservé aux athlètes suivis');
}

// ── L'écran athlète ─────────────────────────────────────────────────────────
// TROIS SILHOUETTES A LA FORME DE .cnl-carte. Le Canal est le seul ecran
// vraiment suspendu au reseau, et il affichait une phrase sur du vide pendant
// une duree que personne ne maitrise. La classe fx-loop est OBLIGATOIRE :
// c'est elle que le bloc prefers-reduced-motion coupe, sans quoi le balayage
// tournerait a l'infini contre la preference systeme. Trois au maximum : la
// regle interne autorise deux boucles simultanees, trois cartes qui partagent
// la meme keyframe restent tenables, dix ne le seraient pas.
function _canalSquelette(fil){
  if(!fil||fil.dataset.rempli) return false;
  fil.innerHTML=Array(3).fill(
     '<div class="cnl-carte" style="pointer-events:none">'
    +'<div class="skeleton fx-loop" style="height:15px;width:62%;margin-bottom:9px"></div>'
    +'<div class="skeleton fx-loop" style="height:11px;width:88%;margin-bottom:6px"></div>'
    +'<div class="skeleton fx-loop" style="height:11px;width:35%"></div></div>').join('');
  fil._t0=Date.now();
  return true;
}
// Le plancher evite le clignotement sur une reponse instantanee. Il ne
// s'applique QU'AU squelette : une erreur doit s'afficher tout de suite.
async function _canalPlancher(fil){
  if(!fil||!fil._t0) return;
  const _r=250-(Date.now()-fil._t0);
  fil._t0=0;
  if(_r>0) await new Promise(r=>setTimeout(r,_r));
}
function loadCanal(){
  go('s-canal');
  const fil=document.getElementById('canal-fil');
  // ⚠ LA MODALE « 🔒 Canal reserve » EST PARTIE AU LOT 4. Une fenetre posee
  //   par-dessus un ecran vide se referme sans rien laisser ; le fil porte
  //   maintenant ce qui est ferme et ce qui reste possible.
  //   rcVerrouBloc ET NON rcVerrou : la porte du canal ne tient pas a la
  //   capacite seule mais au coach nomme dans le dossier, et c'est
  //   canalAccessible qui le sait.
  if(!canalAccessible(currentUser)){
    if(fil) fil.innerHTML=rcVerrouBloc('canal');
    return;
  }
  _canalSquelette(fil);
  _canalCharger();
}
// La carte proposée à l'athlète sans coach. Elle mène EXACTEMENT là où mène
// déjà la carte de l'accueil quand aucun coach n'est rattaché : deux portes
// visibles, une seule destination.
// ⚠ _canalPorteFermee A ETE SUPPRIMEE AU LOT 4, et la trace reste ici. Elle
//   posait une fenetre « 🔒 Canal reserve aux athletes suivis » par-dessus un
//   ecran vide, avec un bouton « Plus tard » qui la refermait sans rien
//   laisser. Le chantier commercial l'interdit : un ecran ferme s'affiche, et
//   dit dans son corps ce qui est ferme et ce qui reste possible. C'est
//   rcVerrouBloc('canal') qui le dit maintenant, dans le fil lui-meme.
async function _canalCharger(){
  const cle=canalCle(currentUser);
  const fil=document.getElementById('canal-fil');
  if(!fil) return;
  // ══ DEUX CAUSES, ET UN SEUL MESSAGE POUR LES DEUX ═════════════════════
  //
  // « Reviens quand tu auras du réseau » etait dit AUSSI quand le reseau allait
  // tres bien. Un athlete rattache par l'ancienne methode — coachId pose, mais
  // pas coachEmailKey — n'a aucune clef de coach : canalCle rend null, et le
  // conseil donne etait alors faux de bout en bout. Il pouvait attendre le
  // reseau indefiniment, le canal ne se serait jamais ouvert.
  //
  // LE RESEAU D'ABORD : sans lui on ne peut meme pas essayer, et c'est la
  // seule chose a faire. La clef ensuite, et elle a son propre conseil — le
  // seul qui debloque quoi que ce soit, parce que la clef ne peut revenir que
  // par un code d'acces neuf.
  if(!CLOUD.ok()){
    fil.innerHTML=_canalVide('Canal indisponible hors connexion.','Reviens quand tu auras du réseau.');
    return;
  }
  if(!cle){
    fil.innerHTML=_canalVide('Rattachement à ton coach incomplet.',
      'Ton compte est bien lié à lui, mais la référence qui ouvre son canal manque sur cet appareil. Demande-lui un nouveau code d\'accès et saisis-le : le canal s\'ouvrira.');
    return;
  }
  const moi=(currentUser.email||'').replace(/\./g,',');
  // Trois requêtes indépendantes. Elles ne peuvent PAS être fusionnées en une
  // seule sur /canaux/{coach} : il n'existe volontairement aucun .read à ce
  // niveau, sans quoi /reactions — qui porte les identifiants — serait descendu
  // par cascade chez tout le groupe.
  //
  // Les messages sont SEULS à pouvoir faire échouer l'écran. Un compteur ou une
  // réaction qui ne descend pas se remplace par zéro sans mentir à personne ;
  // un fil qui ne descend pas doit le dire, jamais s'afficher vide.
  let msgs;
  try{ msgs=await CLOUD.pullCanalMessages(cle); }
  catch(e){
    fil.innerHTML=`<div style="text-align:center;padding:44px 20px">
      <div style="font-size:var(--fs-2xl);line-height:1;margin-bottom:12px;opacity:.5">📡</div>
      <div style="font-weight:800;font-size:var(--fs-md);margin-bottom:6px">Canal injoignable</div>
      <div class="sub" style="font-size:var(--fs-sm);line-height:1.6;margin-bottom:16px">Ce n'est pas que ton coach n'a rien publié : la demande n'a pas abouti.</div>
      <button class="btn btn-outline btn-sm" style="min-height:42px;margin:0" onclick="_canalCharger()">Réessayer</button></div>`;
    return;
  }
  const [compteurs,miennes]=await Promise.all([
    CLOUD.pullCanalCompteurs(cle).catch(()=>null),
    CLOUD.pullMesReactions(cle,moi).catch(()=>null)
  ]);
  window._canalCompteurs=compteurs||{};
  window._canalMiennes=miennes||{};
  // Mémorisée : _canalRepeindre repart de cette liste après chaque réaction.
  // Sans elle, le compteur touché ne changeait jamais à l'écran.
  const liste=canalTrier(msgs);
  window._canalListe=liste;
  // Les horodatages, pour que la pastille sache COMBIEN la prochaine fois.
  try{ _canalMemoriser(cle,liste); }catch(e){}
  await _canalPlancher(fil);
  // Un rappel sur un fil deja peint — bouton « Reessayer », retour dans
  // l'onglet — ne doit pas vider l'ecran pour y remettre des silhouettes.
  fil.dataset.rempli='1';
  fil.innerHTML=liste.length
    ? liste.map(m=>_canalCarte(m,window._canalCompteurs[m.id]||{},window._canalMiennes[m.id]||'')).join('')
    : _canalVide('Rien pour le moment.','Ton coach publiera ici ses annonces et ses liens.');
  // Marqué lu au plus récent AFFICHÉ, et non à Date.now() : si un message
  // arrive pendant le chargement, l'horodater à maintenant l'enterrerait sans
  // qu'il ait jamais été montré.
  const plusRecent=liste.reduce((x,m)=>Math.max(x,Number(m.at)||0),0);
  if(plusRecent) _canalMarquerVu(currentUser.email,plusRecent);
  _majOngletCanal();
  // A partir de la cinquieme carte : les quatre premieres sont deja a l'ecran.
  try{ arcEntreeAuDefilement(fil,'.cnl-carte',4); }catch(e){}
}
function _canalVide(titre,sous){
  return `<div style="text-align:center;padding:48px 20px">
    <div style="font-size:var(--fs-2xl);line-height:1;margin-bottom:12px;opacity:.5">📭</div>
    <div style="font-weight:800;font-size:var(--fs-md);margin-bottom:6px">${escapeHtml(titre)}</div>
    <div class="sub" style="font-size:var(--fs-sm);line-height:1.6">${escapeHtml(sous)}</div></div>`;
}
// La carte d'un message. `mienne` est l'emoji déjà posé par cet athlète, ou ''.
function _canalCarte(m,compteurs,mienne){
  const lien=String(m.lien||'').trim();
  const boutons=CANAL_EMOJIS.map(e=>{
    const n=Number(compteurs[e])||0;
    const actif=mienne===e;
    return `<button onclick="basculerReaction('${escapeHtml(m.id)}','${escapeHtml(e)}')"
      aria-pressed="${actif?'true':'false'}"
      style="flex:1;display:flex;align-items:center;justify-content:center;gap:5px;min-height:38px;padding:0 4px;
        background:${actif?'var(--red-bg)':'transparent'};border:1px solid ${actif?'var(--red)':'var(--border)'};
        border-radius:var(--r-4);cursor:pointer;font-size:var(--fs-md);color:${actif?'var(--text)':'var(--text-dim)'};
        font-family:Montserrat,sans-serif;font-weight:700">
      <span aria-hidden="true">${e}</span><span style="font-size:var(--fs-xs)">${n}</span></button>`;
  }).join('');
  return `<div class="cnl-carte"${m.epingle?' data-epingle':''}>
    <div style="display:flex;align-items:center;gap:8px;margin-bottom:8px">
      ${m.epingle?'<span style="font-size:var(--fs-xs);color:var(--red-text);font-weight:800;letter-spacing:1.5px;text-transform:uppercase">📌 Épinglé</span>':''}
      <span class="sub" style="font-size:var(--fs-xs);letter-spacing:1px;text-transform:uppercase">${escapeHtml(ago(Number(m.at)||Date.now()))}</span>
    </div>
    ${m.titre?`<div class="cnl-titre">${escapeHtml(m.titre)}</div>`:''}
    ${m.texte?`<div class="cnl-texte">${escapeHtml(m.texte)}</div>`:''}
    ${lien?_canalCarteLien(lien):''}
    <div style="display:flex;gap:6px;margin-top:12px">${boutons}</div>
  </div>`;
}
// safeUrl et non escapeHtml sur le href : escapeHtml laisse passer
// « javascript: », et cette confusion exacte a déjà produit une faille sur le
// lien des bannières promo. rel="noopener" : sans lui, la page ouverte garde
// une référence sur window.opener et peut rediriger l'app.
// AUCUNE VIGNETTE, ET C'EST UN CHOIX. Une image d'apercu YouTube etait affichee
// ici : elle etait chargee depuis img.youtube.com, donc ouvrir l'onglet Canal
// transmettait l'adresse IP de l'athlete a Google SANS qu'il ait rien touche.
// C'etait le seul appel automatique a un tiers de toute l'application, dans un
// projet qui a par ailleurs retire tous ses CDN et dont une regle de test
// echoue si l'un d'eux revient. Retiree a la demande de Kevin.
// La carte montre donc le DOMAINE, et rien de plus — pour les autres liens
// (reseaux sociaux, Drive) c'etait de toute facon la seule chose affichable :
// sans serveur, un navigateur ne peut pas lire les balises Open Graph d'une
// page distante.
function _canalCarteLien(lien){
  const dom=canalDomaine(lien);
  if(safeUrlRaw(lien)==='#') return '';
  return `<a href="${safeUrl(lien)}" target="_blank" rel="noopener noreferrer"
    style="display:block;margin-top:12px;border:1px solid var(--border);border-radius:var(--r-3);overflow:hidden;text-decoration:none;background:var(--surface-2)">
    <div style="display:flex;align-items:center;gap:9px;padding:11px 13px">
      <span style="display:inline-flex;color:var(--info);flex-shrink:0">${icon('link',15)}</span>
      <span style="flex:1;min-width:0;font-size:var(--fs-sm);color:var(--info);font-weight:700;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${escapeHtml(dom||'Ouvrir le lien')}</span>
      <span class="sub" style="font-size:var(--fs-xs);flex-shrink:0">Ouvrir ↗</span>
    </div></a>`;
}

// ── Réactions ───────────────────────────────────────────────────────────────
// Deux écritures, pas une : la réaction nominative dans /reactions, fermée, et
// le compteur public dans /compteurs. C'est cette séparation qui donne le
// « 9 💪 » d'Instagram sans que les athlètes apprennent l'existence les uns des
// autres — un compteur lisible par tous ne porte aucun identifiant.
//
// L'affichage est repeint AVANT le réseau : sur mobile, attendre l'aller-retour
// donne un bouton qui semble mort. Si l'écriture échoue, on remet l'état
// d'avant et on le dit — plutôt qu'un compteur qui ment.
async function basculerReaction(msgId,emoji){
  if(!canalAccessible(currentUser)) return;
  const cle=canalCle(currentUser);
  const moi=(currentUser.email||'').replace(/\./g,',');
  // MEME DISTINCTION QU'AU CHARGEMENT, et pour la meme raison : une clef
  // absente n'est pas une panne de reseau, et le dire ainsi envoie l'athlete
  // attendre quelque chose qui n'arrivera pas.
  if(!CLOUD.ok()){ toast('Réaction impossible hors connexion','var(--orange)'); return; }
  if(!cle){ toast('Rattachement à ton coach incomplet : demande-lui un nouveau code d\'accès.','var(--orange)'); return; }
  const miennes=window._canalMiennes||(window._canalMiennes={});
  const compteurs=window._canalCompteurs||(window._canalCompteurs={});
  const avant=miennes[msgId]||'';
  const apres=(avant===emoji)?'':emoji;
  const c=compteurs[msgId]||(compteurs[msgId]={});
  // Le compteur ne descend jamais sous zéro : les règles rejettent une valeur
  // négative, et un affichage à -1 serait de toute façon absurde.
  if(avant) c[avant]=Math.max(0,(Number(c[avant])||0)-1);
  if(apres) c[apres]=(Number(c[apres])||0)+1;
  if(apres) miennes[msgId]=apres; else delete miennes[msgId];
  _canalRepeindre(msgId);
  try{
    // La réaction D'ABORD, les compteurs ENSUITE — jamais en parallèle. Lancées
    // ensemble, un échec de la réaction laissait quand même partir le « +1 » :
    // le compteur public gagnait un point que /reactions ne portait pas, et
    // seule la resynchronisation manuelle du coach pouvait le rattraper.
    // Sérialisées, un échec de la réaction n'écrit aucun compteur du tout.
    if(apres) await CLOUD.poserReaction(cle,moi,msgId,apres);
    else await CLOUD.retirerReaction(cle,moi,msgId);
    const compte=[];
    if(avant) compte.push(CLOUD.bougerCompteur(cle,msgId,avant,-1));
    if(apres) compte.push(CLOUD.bougerCompteur(cle,msgId,apres,1));
    await Promise.all(compte);
  }catch(e){
    if(avant) c[avant]=(Number(c[avant])||0)+1;
    if(apres) c[apres]=Math.max(0,(Number(c[apres])||0)-1);
    if(avant) miennes[msgId]=avant; else delete miennes[msgId];
    _canalRepeindre(msgId);
    toast('Réaction non enregistrée','var(--orange)');
  }
}
// Repeint le fil entier depuis l'état en mémoire. Repeindre la seule carte
// touchée demanderait de la retrouver dans le DOM par un identifiant, alors que
// le fil fait vingt cartes au plus : le gain serait nul et le risque de
// désynchronisation réel.
function _canalRepeindre(){
  const fil=document.getElementById('canal-fil');
  if(!fil||!window._canalListe) return;
  fil.innerHTML=window._canalListe.map(m=>
    _canalCarte(m,(window._canalCompteurs||{})[m.id]||{},(window._canalMiennes||{})[m.id]||'')).join('');
}

// ── La bannière d'accueil, alimentée par le message épinglé ─────────────────
// Elle remplace celle du « Mot du coach ». La source n'est plus un champ du
// dossier de l'athlète mais coach_public.canalEpingle — donc UN exemplaire pour
// tout le monde, mis à jour d'une écriture, et qui atteint aussi les athlètes
// connus par leur seul code, que l'ancien système ne touchait jamais.
// ── L'ACCUEIL NE REPREND PLUS LE CANAL ─────────────────────────────────
// Cette banniere reprenait le message epingle EN GRAND sur l'accueil, entre
// les seances, le poids et le rappel de bilan. La meme annonce vivait deja
// dans l'onglet Canal, avec les autres : l'accueil n'en etait que la copie,
// et cette copie poussait vers le bas ce que l'athlete vient chercher — sa
// seance du jour. Demande de Kevin, 10/09/2026 : « ca parasite les infos ».
//
// LA FONCTION RESTE, ET VIDE LA ZONE. Six appelants la nomment ; les faire
// disparaitre un par un, c'est six occasions d'en oublier un et de laisser
// une banniere orpheline. Elle garantit desormais l'inverse de ce qu'elle
// faisait : que #clh-annonce soit vide.
//
// L'annonce n'est pas perdue : canalTrier place l'epingle EN TETE du fil, et
// l'onglet Canal porte maintenant une pastille chiffree qui dit qu'il y a du
// neuf. Un endroit, un signal.
// LA ZONE SERT DESORMAIS A LA RELANCE PHOTO. Elle est en tete de l'accueil,
// elle etait libre depuis que le canal ne s'y recopie plus, et la relance a
// besoin d'exactement ca : un endroit visible, qui revient a chaque ouverture
// tant que la photo manque, sans bloquer quoi que ce soit.
//
// C'est la contrepartie de la photo rendue facultative a l'inscription : la
// grille de visages du coach se remplit en deux jours au lieu d'un, mais plus
// personne ne bute sur un selecteur de fichiers avant meme d'avoir un compte.
// Le bandeau disparait de lui-meme des que la photo est posee.
function renderEpingleAccueil(){
  const el=document.getElementById('clh-annonce');
  if(!el) return;
  const u=currentUser;
  const manque=!!(u&&u.role==='athlete'&&!u.athletePhoto);
  if(!manque){ el.innerHTML=''; el.style.display='none'; return; }
  el.style.display='block';
  el.innerHTML='<div style="background:var(--surface-1);border:1px solid var(--border);'
    +'border-radius:var(--r-3);padding:13px 14px;margin-bottom:16px">'
    +'<div style="font-size:var(--fs-sm);color:var(--text-strong);line-height:1.5;margin-bottom:9px">'
    +'Ajoute ta photo de profil : c\'est ce qui permet à ton coach de te reconnaître '
    +'d\'un coup d\'œil sur son tableau de bord.</div>'
    +'<button class="btn btn-outline btn-sm" style="width:100%" '
    +'onclick="go(\'s-athlete-profile\')">Ajouter ma photo</button></div>';
}

// ══ CANAL — CÔTÉ COACH ══════════════════════════════════════════════════════
function loadCanalCoach(){
  if(currentUser?.role!=='coach') return;
  go('s-coach-canal');
  const fil=document.getElementById('canal-coach-fil');
  _canalSquelette(fil);
  _canalChargerCoach();
}
async function _canalChargerCoach(idNeuf){
  const cle=canalCle(currentUser);
  const fil=document.getElementById('canal-coach-fil');
  if(!fil) return;
  if(!cle||!CLOUD.ok()){
    fil.innerHTML=_canalVide('Canal indisponible hors connexion.','Reconnecte-toi pour écrire.');
    return;
  }
  // Le coach seul peut lire /reactions : c'est ce qui lui donne les prénoms.
  // Même règle que côté athlète, et elle compte DAVANTAGE ici : un coach qui
  // voit son canal vide à cause d'un réseau capricieux le republierait en
  // double, chez tout le monde.
  let msgs,compteurs,reactions;
  try{
    msgs=await CLOUD.pullCanalMessages(cle);
    [compteurs,reactions]=await Promise.all([
      CLOUD.pullCanalCompteurs(cle).catch(()=>null),
      CLOUD.pullCanalReactions(cle).catch(()=>null)
    ]);
  }catch(e){
    fil.innerHTML=`<div style="text-align:center;padding:40px 20px">
      <div style="font-size:var(--fs-2xl);line-height:1;margin-bottom:12px;opacity:.5">📡</div>
      <div style="font-weight:800;font-size:var(--fs-md);margin-bottom:6px">Canal injoignable</div>
      <div class="sub" style="font-size:var(--fs-sm);line-height:1.6;margin-bottom:16px">Ne republie pas : tes messages sont peut-être déjà là. La demande n'a pas abouti.</div>
      <button class="btn btn-outline btn-sm" style="min-height:42px;margin:0" onclick="_canalChargerCoach()">Réessayer</button></div>`;
    return;
  }
  window._canalMsgsCoach=msgs||{};
  const liste=canalTrier(msgs);
  const vrai=canalDecompteVrai(reactions);
  await _canalPlancher(fil);
  fil.dataset.rempli='1';
  fil.innerHTML=liste.length
    ? liste.map(m=>_canalCarteCoach(m,(compteurs||{})[m.id]||{},vrai[m.id]||{},reactions||{},m.id===idNeuf)).join('')
    : _canalVide('Ton canal est vide.','Le premier message apparaîtra chez tous tes athlètes.');
}
// PURE. /reactions est rangé par athlète puis par message ; le décompte, lui,
// se lit par message. C'est ce pivot-là, et rien d'autre.
// Il fait autorité sur /compteurs : celui-ci peut avoir dérivé si un téléphone
// a lâché entre les deux écritures.
function canalDecompteVrai(reactions){
  const out={};
  if(!reactions||typeof reactions!=='object') return out;
  Object.keys(reactions).forEach(athleteKey=>{
    const parMsg=reactions[athleteKey];
    if(!parMsg||typeof parMsg!=='object') return;
    Object.keys(parMsg).forEach(msgId=>{
      const e=parMsg[msgId];
      if(!e) return;
      if(!out[msgId]) out[msgId]={};
      out[msgId][e]=(out[msgId][e]||0)+1;
    });
  });
  return out;
}
// PURE. Les prénoms de ceux qui ont posé un emoji donné. Le coach lit les
// dossiers de SES athlètes, ce que les règles lui accordent déjà.
function canalPrenoms(reactions,msgId,emoji){
  const users=DB.get('users')||{};
  const noms=[];
  Object.keys(reactions||{}).forEach(k=>{
    if((reactions[k]||{})[msgId]!==emoji) return;
    const c=users[k.replace(/,/g,'.')];
    noms.push((c&&(c.fname||c.email))||k.replace(/,/g,'.'));
  });
  return noms.sort((a,b)=>String(a).localeCompare(String(b)));
}
function _canalCarteCoach(m,compteurs,vrai,reactions,neuve){
  const derive=CANAL_EMOJIS.some(e=>(Number(compteurs[e])||0)!==(Number(vrai[e])||0));
  const lignes=CANAL_EMOJIS.filter(e=>(Number(vrai[e])||0)>0).map(e=>{
    const noms=canalPrenoms(reactions,m.id,e);
    return `<div style="display:flex;gap:8px;align-items:flex-start;font-size:var(--fs-sm);padding:3px 0">
      <span aria-hidden="true">${e}</span><span style="font-weight:800">${noms.length}</span>
      <span class="sub" style="flex:1;min-width:0;line-height:1.5">${escapeHtml(noms.join(', '))}</span></div>`;
  }).join('');
  const lien=String(m.lien||'').trim();
  return `<div class="cnl-carte${neuve?' cnl-neuve':''}"${m.epingle?' data-epingle':''}>
    <div style="display:flex;align-items:center;gap:8px;margin-bottom:8px">
      ${m.epingle?'<span style="font-size:var(--fs-xs);color:var(--red-text);font-weight:800;letter-spacing:1.5px;text-transform:uppercase">📌 Épinglé</span>':''}
      <span class="sub" style="font-size:var(--fs-xs);letter-spacing:1px;text-transform:uppercase">${escapeHtml(ago(Number(m.at)||Date.now()))}</span>
    </div>
    ${m.titre?`<div class="cnl-titre">${escapeHtml(m.titre)}</div>`:''}
    ${m.texte?`<div class="cnl-texte">${escapeHtml(m.texte)}</div>`:''}
    ${lien&&safeUrlRaw(lien)!=='#'?`<a href="${safeUrl(lien)}" target="_blank" rel="noopener noreferrer" style="display:inline-block;margin-top:9px;font-size:var(--fs-sm);color:var(--info);font-weight:700">${escapeHtml(canalDomaine(lien)||'lien')} ↗</a>`:''}
    ${lignes?`<div style="margin-top:11px;padding-top:10px;border-top:1px solid var(--border)">${lignes}</div>`
            :'<div class="sub" style="margin-top:11px;padding-top:10px;border-top:1px solid var(--border);font-size:var(--fs-xs)">Aucune réaction pour l\'instant.</div>'}
    ${derive?`<button class="btn btn-outline btn-sm" style="width:100%;margin:9px 0 0;min-height:38px;color:var(--orange);border-color:var(--orange)" onclick="resyncCompteursCanal('${escapeHtml(m.id)}')">Le compteur public a dérivé — resynchroniser</button>`:''}
    <div style="display:flex;gap:8px;justify-content:flex-end;margin-top:10px">
      <button class="btn btn-outline btn-sm" style="width:auto;padding:0 14px;min-height:34px;font-size:10.5px;margin:0" onclick="openMessageCanal('${escapeHtml(m.id)}')">Modifier</button>
      <button class="btn btn-outline btn-sm" style="width:auto;padding:0 14px;min-height:34px;font-size:10.5px;margin:0;color:var(--sub)" onclick="supprimerMessageCanal('${escapeHtml(m.id)}')">Supprimer</button>
    </div></div>`;
}
// Le compteur public est ramené sur le décompte vrai. Les règles laissent le
// coach écrire la valeur qu'il veut — précisément pour cette réparation-là.
async function resyncCompteursCanal(msgId){
  const cle=canalCle(currentUser);
  if(!cle) return;
  try{
    const reactions=await CLOUD.pullCanalReactions(cle);
    const vrai=(canalDecompteVrai(reactions))[msgId]||{};
    await Promise.all(CANAL_EMOJIS.map(e=>CLOUD.fixerCompteur(cle,msgId,e,Number(vrai[e])||0)));
    toast('Compteurs resynchronisés');
    _canalChargerCoach();
  }catch(e){ toast('Resynchronisation impossible : '+e.message,'var(--orange)'); }
}

// `brouillon` est OPTIONNEL et n'existe que pour la liste « Jamais demarre » :
// {texte, nomme}. Les deux appelants historiques ne passent qu'un identifiant et
// ne changent pas d'un caractere.
//
// ⚠ CE CANAL EST UNE DIFFUSION, PAS UN MESSAGE PRIVE. Les regles RTDB ouvrent
// /canaux/{coach}/messages en lecture a TOUT athlete dont coachEmailKey designe
// ce coach : il n'existe aucun adressage par athlete dans ce produit, et le
// commentaire de ces memes regles pose le principe — « RepCore n'a jamais
// laisse un athlete apprendre l'existence d'un autre ».
// Un brouillon qui commence par « Salut Marie » nomme donc Marie a tout le
// groupe, ET apprend au groupe qu'elle n'a pas commence. Le coach doit le
// savoir AU MOMENT OU IL ECRIT, pas apres : d'ou l'avertissement ci-dessous,
// pose seulement quand le brouillon porte un prenom.
// ⚠ PLUS DE PARAMETRE `brouillon`, ET PLUS D'AVERTISSEMENT ORANGE. Un seul
//   appelant en posait un : la relance « jamais demarre », qui ouvrait ce
//   canal avec un texte nominatif. L'ecran prevenait alors que « le brouillon
//   nomme Jean » et que l'envoyer tel quel l'apprendrait a tout le groupe.
//   Depuis le 19/09/2026 cette relance part en WhatsApp ou en mail : la cause
//   a disparu, l'avertissement avec elle. On ne garde pas un garde-fou pour
//   un chemin qui n'existe plus — il ferait croire que le chemin existe.
function openMessageCanal(msgId){
  document.getElementById('modal-overlay')?.remove();
  const m=(msgId&&(window._canalMsgsCoach||{})[msgId])||{};
  window._canalEdite=msgId||'';
  document.body.insertAdjacentHTML('beforeend',
  `<div id="modal-overlay" onclick="closeModal()" style="position:fixed;inset:0;background:var(--scrim);z-index:var(--z-modal);display:flex;align-items:flex-end;justify-content:center">
  <div onclick="event.stopPropagation()" role="dialog" aria-modal="true" style="background:var(--surface-2);border-radius:var(--r-4) var(--r-4) 0 0;padding:16px 20px 20px;width:100%;max-width:480px;max-height:88vh;overflow-y:auto">
    <h2 style="margin-bottom:4px">${msgId?'Modifier le message':'Nouveau message'}</h2>
    <p class="sub" style="font-size:var(--fs-sm);margin-bottom:12px;line-height:1.55">Il apparaît dans le canal de tous tes athlètes suivis, à leur prochaine ouverture de l'app. Ce n'est pas une notification : leur téléphone ne sonnera pas.</p>
    <label for="cm-titre">Titre (optionnel) · ${CANAL_TITRE_MAX} caractères</label>
    <input id="cm-titre" type="text" maxlength="${CANAL_TITRE_MAX}" value="${escapeHtml(m.titre||'')}" placeholder="Nouvelle vidéo technique">
    <label for="cm-texte" style="margin-top:12px">Message · ${CANAL_TEXTE_MAX} caractères</label>
    <textarea id="cm-texte" rows="5" maxlength="${CANAL_TEXTE_MAX}" style="resize:none" placeholder="J'ai publié une nouvelle vidéo sur le soulevé de terre. Regardez-la avant jeudi.">${escapeHtml(m.texte||'')}</textarea>
    <label for="cm-lien" style="margin-top:12px">Lien (optionnel)</label>
    <input id="cm-lien" type="url" maxlength="${CANAL_LIEN_MAX}" value="${escapeHtml(m.lien||'')}" placeholder="Colle ici l'adresse de ta publication">
    <div class="sub" style="font-size:var(--fs-xs);margin-top:5px;line-height:1.5">Réseaux sociaux, vidéo, Drive, tableur… Tes athlètes voient le nom du site et ouvrent le lien d'un tap, dans leur navigateur. Aucune image d'aperçu n'est chargée : rien n'est demandé à un autre site tant que personne n'a touché le lien.</div>
    <label style="display:flex;align-items:center;gap:10px;margin-top:14px;cursor:pointer">
      <input id="cm-epingle" type="checkbox" ${m.epingle?'checked':''} style="width:18px;height:18px;accent-color:var(--red);cursor:pointer;flex-shrink:0">
      <span style="font-size:var(--fs-sm);line-height:1.5">Épingler à l'accueil<br><span class="sub" style="font-size:var(--fs-xs)">Un seul message à la fois : celui-ci remplacera l'épinglé actuel.</span></span>
    </label>
    <div style="display:flex;gap:8px;margin-top:16px">
      <button class="btn btn-outline btn-sm" style="flex:1;margin:0;min-height:44px" onclick="closeModal()">Annuler</button>
      <button class="btn btn-red btn-sm" style="flex:1;margin:0;min-height:44px" onclick="enregistrerMessageCanal()">${msgId?'Enregistrer':'Publier'}</button>
    </div>
  </div></div>`);
}

async function enregistrerMessageCanal(){
  const titre=(document.getElementById('cm-titre')?.value||'').trim().slice(0,CANAL_TITRE_MAX);
  const texte=(document.getElementById('cm-texte')?.value||'').trim().slice(0,CANAL_TEXTE_MAX);
  const lienBrut=(document.getElementById('cm-lien')?.value||'').trim().slice(0,CANAL_LIEN_MAX);
  const epingle=!!document.getElementById('cm-epingle')?.checked;
  if(!titre&&!texte){ toast('Écris au moins un titre ou un message','var(--orange)'); return; }
  // Un lien saisi mais invalide est REFUSÉ, pas silencieusement vidé : le coach
  // croirait l'avoir publié, et l'athlète ne verrait jamais rien.
  if(lienBrut&&safeUrlRaw(lienBrut)==='#'){
    toast('Le lien doit commencer par https://','var(--orange)'); return;
  }
  const cle=canalCle(currentUser);
  if(!cle||!CLOUD.ok()){ toast('Publication impossible hors connexion','var(--orange)'); return; }
  // Date.now() seul ne suffit pas : deux publications dans la même milliseconde
  // partageraient un identifiant et l'une écraserait l'autre.
  const id=window._canalEdite||('m'+Date.now()+'-'+Math.random().toString(36).slice(2,7));
  const ancien=(window._canalMsgsCoach||{})[id]||{};
  const msg={at:Number(ancien.at)||Date.now(),titre,texte,lien:lienBrut,epingle};
  // LE BOUTON PORTE L'ATTENTE, et la feuille ne part QU'AU SUCCES. closeModal()
  // etait appele AVANT patcherMessagesCanal, ecrireMessageCanal et
  // pushProfilCoach — trois allers-retours reseau enchaines : le coach venait
  // d'envoyer un message a ses vingt eleves et rien ne le lui disait pendant
  // 300 ms a 2 s. En cas d'echec, la feuille reste ouverte avec le texte saisi ;
  // aujourd'hui il etait perdu.
  const _b=document.querySelector('#modal-overlay .btn-red');
  if(_b){
    _b.disabled=true;
    _b.dataset.lib=_b.textContent;
    _b.textContent='Envoi…';
    _b.classList.add('cnl-envoi');
  }
  try{
    // Dépingler les autres AVANT d'épingler celui-ci, et d'un seul PATCH : deux
    // bannières empilées sur l'accueil, personne ne les lit.
    if(epingle){
      const patch={};
      Object.keys(window._canalMsgsCoach||{}).forEach(k=>{
        if(k!==id&&(window._canalMsgsCoach[k]||{}).epingle) patch[k+'/epingle']=false;
      });
      if(Object.keys(patch).length) await CLOUD.patcherMessagesCanal(cle,patch);
    }
    await CLOUD.ecrireMessageCanal(cle,id,msg);
    // La sonde de pastille et la copie épinglée vivent dans coach_public, qui
    // est déjà téléchargé à chaque ouverture d'accueil : c'est ce qui rend la
    // bannière et la pastille gratuites côté athlète.
    // SUR L'HORODATAGE DU MESSAGE, jamais sur « maintenant ». Une MODIFICATION
    // garde le `at` d'origine : poser Date.now() faisait passer la sonde
    // au-dessus de tout ce que l’athlète peut voir, et canalNonLu — qui compare
    // canalDernier au plus récent AFFICHÉ — ne pouvait plus jamais
    // s'équilibrer. La pastille restait allumée, ouverture après ouverture.
    //
    // Math.max et non une affectation : éditer un vieux message ne doit pas
    // faire RECULER la sonde sous un message plus récent, sinon la pastille
    // s’éteindrait pour une publication que personne n’a lue.
    currentUser.canalDernier=Math.max(Number(currentUser.canalDernier)||0,msg.at);
    if(epingle) currentUser.canalEpingle={id,at:msg.at,titre,texte,lien:lienBrut};
    else if(currentUser.canalEpingle&&currentUser.canalEpingle.id===id) delete currentUser.canalEpingle;
    saveUser();
    await CLOUD.pushProfilCoach(currentUser);
    closeModal();
    toast(window._canalEdite?'Message modifié':'Message publié');
  }catch(e){
    if(_b){
      _b.disabled=false;
      _b.classList.remove('cnl-envoi');
      if(_b.dataset.lib!=null) _b.textContent=_b.dataset.lib;
    }
    toast('Non publié : '+e.message,'var(--orange)');
    return;                       // la feuille reste ouverte, le texte aussi
  }
  window._canalEdite='';
  // L'identifiant du message neuf voyage jusqu'au rendu : la carte qu'on vient
  // d'ecrire entre seule et marquee, au lieu d'etre indistincte au milieu d'un
  // rechargement complet du fil.
  _canalChargerCoach(id);
}

async function supprimerMessageCanal(msgId){
  if(!await rcConfirm('Supprimer ce message du canal ? Il disparaîtra chez tous tes athlètes.',null,'Supprimer')) return;
  const cle=canalCle(currentUser);
  if(!cle) return;
  try{
    await CLOUD.supprimerMessageCanal(cle,msgId);
    if(currentUser.canalEpingle&&currentUser.canalEpingle.id===msgId){
      delete currentUser.canalEpingle;
      saveUser();
      await CLOUD.pushProfilCoach(currentUser);
    }
    toast('Message supprimé');
  }catch(e){ toast('Suppression impossible : '+e.message,'var(--orange)'); }
  _canalChargerCoach();
}

// ══ LE CARNET D'ADRESSES ═════════════════════════════════════════════════
//
// Demande de Kevin, 08/09/2026 : « un petit CRM ou on retrouve tous les mails
// de chacun avec le nom, le genre et le numero de telephone ». Ces trois
// informations existaient deja, eparpillees sur autant de fiches qu'il y a
// d'athletes : les reunir sur un ecran, c'est tout ce qu'il manquait.
//
// ⚠ IL N'ENVOIE RIEN, IL OUVRE. Comme le message groupe : RepCore n'a pas de
// serveur de courrier, et se mettre a en avoir un ferait entrer l'application
// dans un metier qui n'est pas le sien. Un tap ouvre le client mail, le
// telephone ou WhatsApp de l'appareil — c'est le coach qui envoie.
//
// PURE. La ligne d'un athlete, sortie a part pour etre eprouvable sans DOM.
function _crmLigne(c){
  const nom=((c.fname||'')+' '+(c.lname||'')).trim()||'Sans nom';
  const femme=isFemale(c.gender);
  const genre=c.gender?(femme?'Femme':'Homme'):'—';
  const mail=String(c.email||'').trim();
  const tel=String(c.phone||'').trim();
  const coul=femme?VIG_ROSE:VIG_BLEU;
  const lien=(url,txt,titre)=>url
    ?`<a href="${escapeHtml(url)}" ${/^https/.test(url)?'target="_blank" rel="noopener"':''}
        style="color:var(--link);text-decoration:none;word-break:break-all">${escapeHtml(txt)}</a>`
    :`<span class="sub" style="font-size:var(--fs-2xs)">${escapeHtml(titre)}</span>`;
  return `<div style="display:grid;grid-template-columns:1fr;gap:3px;padding:10px 0;
    border-bottom:1px solid var(--border)">
    <div style="display:flex;align-items:center;gap:7px">
      <span style="color:${coul};font-size:14px;line-height:1">${c.gender?(femme?'♀':'♂'):'·'}</span>
      <span style="font-weight:800;font-size:var(--fs-sm)">${escapeHtml(nom)}</span>
      <span class="sub" style="font-size:var(--fs-2xs)">${escapeHtml(genre)}</span>
    </div>
    <div style="font-size:var(--fs-xs)">${lien(mail?'mailto:'+mail:'',mail,'pas d\'adresse')}</div>
    <div style="font-size:var(--fs-xs);display:flex;gap:12px;flex-wrap:wrap">
      ${lien(tel?'tel:'+tel.replace(/[^+0-9]/g,''):'',tel,'pas de numéro')}
      ${tel?lien('https://wa.me/'+tel.replace(/[^0-9]/g,''),'WhatsApp',''):''}
    </div>
  </div>`;
}
// PURE. Toutes les adresses, séparées par des points-virgules — la forme que
// tous les clients mail savent coller dans un champ « À ».
function _crmAdresses(clients){
  return (clients||[]).map(c=>String((c&&c.email)||'').trim())
    .filter(e=>e.indexOf('@')>0).join('; ');
}
function ouvrirCrmCoach(){
  if(!peutConsulterBanque()&&currentUser.role!=='coach'){ toast('Réservé aux coachs.','var(--orange)'); return false; }
  const l=getClients().slice().sort((a,b)=>
    String((a.fname||'')+(a.lname||'')).localeCompare(String((b.fname||'')+(b.lname||''))));
  const adresses=_crmAdresses(l);
  const html=`<div id="modal-overlay" onclick="closeModal()" style="position:fixed;inset:0;background:var(--scrim);z-index:var(--z-modal);display:flex;align-items:flex-end;justify-content:center">
  <div class="mdl-large" onclick="event.stopPropagation()" style="background:var(--surface-2);border-radius:var(--r-4) var(--r-4) 0 0;padding:16px 20px 22px;width:100%;max-width:480px;max-height:90vh;overflow-y:auto">
    <h2 style="margin-bottom:4px;font-size:var(--fs-lg)">CARNET D'ADRESSES</h2>
    <div class="sub" style="font-size:var(--fs-xs);margin-bottom:12px">${l.length} athlète${l.length>1?'s':''}. Un tap ouvre ton mail, ton téléphone ou WhatsApp — RepCore n'envoie rien à ta place.</div>
    ${adresses?`<button class="btn btn-outline btn-sm" style="width:100%;margin:0 0 12px" onclick="_crmCopierAdresses()">Copier toutes les adresses</button>`:''}
    ${l.length?_htmlSectionsSuivi(l,_crmLigne):'<div class="sub" style="text-align:center;padding:24px 0">Aucun athlète pour l\'instant.</div>'}
    <button class="btn btn-outline" style="margin-top:16px" onclick="closeModal()">Fermer</button>
  </div></div>`;
  document.body.insertAdjacentHTML('beforeend',html);
  return true;
}
async function _crmCopierAdresses(){
  const a=_crmAdresses(getClients());
  if(!a){ toast('Aucune adresse à copier.','var(--orange)'); return false; }
  try{ await navigator.clipboard.writeText(a); toast('Adresses copiées','var(--green)'); return true; }
  catch(e){ toast('Copie refusée par le navigateur.','var(--orange)'); return false; }
}
function openWaGroupe(rowIdx){
  // RepCore n envoie rien : il ouvre des conversations, une par athlete.
  // Le plafond protege d un geste qu on ne pourrait plus arreter.
  try{
    if(!currentUser.journalGroupe) currentUser.journalGroupe=[];
    const _dest=getClients().filter(c=>c&&!c._fromCode);
    const _g=templateEnvoiGroupe(_dest,currentUser.journalGroupe);
    if(!_g.ok){
      toast(_g.demandes+' athlètes : au-delà de '+_g.max+', prépare-les en deux fois.','var(--orange)');
      return false;
    }
    if(currentUser.journalGroupe.length>50) currentUser.journalGroupe=currentUser.journalGroupe.slice(-50);
    saveUser();
  }catch(e){}
  const source=(typeof rowIdx==='number'&&window._todoRows&&window._todoRows[rowIdx])
    ?window._todoRows[rowIdx]:null;
  const tous=getClients().filter(c=>!c._fromCode);
  if(!tous.length){toast('Aucun athlète à contacter.','var(--orange)');return;}
  const preCoches=new Set((source?source.list:tous).map(c=>c.id));
  const lignes=tous.map(c=>{
    const tel=_telAthlete(c);
    const nom=((c.fname||'')+' '+(c.lname||'')).trim()||c.email||'Athlète';
    return `<label style="display:flex;align-items:center;gap:10px;padding:11px 0;border-bottom:1px solid #181818;cursor:pointer">
      <input type="checkbox" class="wag-cb" value="${escapeHtml(c.id)}" data-tel="${escapeHtml(tel)}" data-nom="${escapeHtml(c.fname||'')}"
        ${preCoches.has(c.id)?'checked':''} style="width:18px;height:18px;accent-color:var(--red);cursor:pointer;flex-shrink:0">
      <div style="flex:1;min-width:0">
        <div style="font-weight:700;font-size:var(--fs-md)">${escapeHtml(nom)}</div>
        <div class="sub" style="font-size:var(--fs-xs)">${tel?'📱 '+escapeHtml(tel):'<span style="color:var(--orange)">aucun numéro : le contact sera à choisir dans WhatsApp</span>'}</div>
      </div>
    </label>`;
  }).join('');
  const html=`<div id="modal-overlay" onclick="closeModal()" style="position:fixed;inset:0;background:var(--scrim);z-index:var(--z-modal);display:flex;align-items:flex-end;justify-content:center">
  <div onclick="event.stopPropagation()" style="background:var(--surface-2);border-radius:var(--r-4) var(--r-4) 0 0;padding:16px 20px 20px;width:100%;max-width:480px;animation:fadeIn var(--t-3) var(--c-out);max-height:88vh;overflow-y:auto">
    <h2 style="margin-bottom:4px">💬 Message groupé</h2>
    <p class="sub" style="font-size:var(--fs-sm);margin-bottom:10px">Rien n'est envoyé d'ici : chaque nom ouvrira ta conversation WhatsApp avec le texte déjà écrit.</p>
    <label for="wag-texte" style="margin-top:0">Message : chacun le recevra précédé de « Salut &lt;son prénom&gt;, »</label>
    <textarea id="wag-texte" rows="3" style="resize:none" placeholder="petit point d'étape cette semaine 💪">${escapeHtml(source?_waCorpsGroupe(source.type):'')}</textarea>
    <div style="display:flex;gap:8px;margin:10px 0 4px">
      <button class="btn btn-outline btn-sm" style="flex:1;margin:0;min-height:44px" onclick="_wagTout(true)">Tout cocher</button>
      <button class="btn btn-outline btn-sm" style="flex:1;margin:0;min-height:44px" onclick="_wagTout(false)">Tout décocher</button>
    </div>
    <div id="wag-liste">${lignes}</div>
    <div style="display:flex;gap:8px;margin-top:14px">
      <button class="btn btn-outline btn-sm" style="flex:1;margin:0;min-height:44px" onclick="_wagCopierNumeros()">Copier les numéros</button>
      <button class="btn btn-red btn-sm" style="flex:1;margin:0;min-height:44px" onclick="_wagPreparer()">Préparer les envois</button>
    </div>
    <div id="wag-liens" style="margin-top:12px"></div>
    <button class="btn btn-outline" style="margin-top:12px" onclick="closeModal()">Fermer</button>
  </div></div>`;
  document.body.insertAdjacentHTML('beforeend',html);
}
function _wagTout(v){document.querySelectorAll('.wag-cb').forEach(cb=>cb.checked=v);}
function _wagSelection(){
  return [...document.querySelectorAll('.wag-cb:checked')].map(cb=>({
    id:cb.value,tel:cb.dataset.tel||'',nom:cb.dataset.nom||''
  }));
}
function _wagCopierNumeros(){
  const avecTel=_wagSelection().filter(s=>s.tel);
  if(!avecTel.length){toast('Aucun numéro enregistré parmi les athlètes cochés.','var(--orange)');return;}
  const liste=avecTel.map(s=>s.tel).join('\n');
  try{
    navigator.clipboard.writeText(liste)
      .then(()=>toast(avecTel.length+' numéro'+(avecTel.length>1?'s copiés':' copié'),'var(--green)'))
      .catch(()=>toast('Copie refusée par le navigateur : sélectionne les numéros à la main.','var(--orange)'));
  }catch(e){toast('Copie impossible sur cet appareil.','var(--orange)');}
}
function _wagPreparer(){
  const sel=_wagSelection();
  const zone=document.getElementById('wag-liens');
  if(!zone) return;
  if(!sel.length){zone.innerHTML='';toast('Coche au moins un athlète.','var(--orange)');return;}
  const texte=(document.getElementById('wag-texte')?.value||'').trim();
  if(!texte){toast('Écris le message à envoyer.','var(--orange)');return;}
  const sansTel=sel.filter(s=>!s.tel).length;
  // Ré-adressage par destinataire : sans lui, tout le monde recevait le prénom
  // et les chiffres du premier athlète de la liste.
  const pour=s=>(s.nom?'Salut '+s.nom+', ':'Salut ! ')+texte;
  zone.innerHTML=`<div class="sub" style="font-size:var(--fs-xs);margin-bottom:8px">Touche chaque nom pour ouvrir WhatsApp : ${sel.length} conversation${sel.length>1?'s':''} à ouvrir${sansTel?`, dont ${sansTel} sans numéro utilisable (contact à choisir)`:''}.</div>`
    +sel.map(s=>`<a href="${safeUrl(waLink(s.tel,pour(s)))}" target="_blank" rel="noopener"
      style="display:flex;align-items:center;gap:8px;min-height:44px;padding:0 12px;margin-bottom:6px;background:#0a1a0a;border:1px solid #1e3a1e;border-radius:var(--r-2);color:var(--green);text-decoration:none;font-size:var(--fs-md);font-weight:700"
      onclick="this.style.opacity='.5';this.style.borderColor='var(--border)'">💬 ${escapeHtml(s.nom||'Athlète')}${s.tel?'':' <span style="color:var(--orange);font-weight:400;font-size:var(--fs-xs)">(contact à choisir)</span>'}</a>`).join('');
}

// Rendu de la liste d'athletes. La recherche et le filtre sont lus dans le
// DOM au moment du rendu : le rafraichissement periodique rappelle simplement
// cette fonction, et retrouve donc l'etat courant sans qu'on ait a le stocker.
// Sans argument, elle recalcule la liste elle-meme — c'est ce qui permet a
// l'oninput de la barre de recherche de l'appeler directement.
function norm(s){
  // Insensible aux accents ET a la casse : « jul » doit trouver « Julien »,
  // et « joel » doit trouver « Joel » comme « Joël ».
  return (s||'').toString().normalize('NFD').replace(/[̀-ͯ]/g,'').toLowerCase().trim();
}
// ⚠ 'travail' N'EST PAS 'tous', ET LA DISTINCTION EST TOUTE LA DIFFICULTE DE
// CE LOT. La vue par defaut masque desormais ce qui dort — invitations jamais
// honorees, comptes jamais demarres, athletes endormis — parce que ces trois
// familles ont leur propre cadre en bas de page. Mais la puce « Tous » affiche
// le nombre p.total : si elle ouvrait cette vue-la, elle annoncerait dix et en
// montrerait trois. Le fichier pose la regle deux fois en toutes lettres — un
// compteur qui n'ouvre pas exactement sa propre liste est pire que pas de
// compteur. Il fallait donc deux etats, et non un seul relu differemment.
//
// 'travail' n'a PAS de puce, et c'est normal : ce n'est pas un filtre qu'on
// choisit, c'est l'ecran tel qu'il s'ouvre. Re-toucher une puce allumee y
// ramene.
let _filtreClients='travail';
function setFiltreClients(f){
  _filtreClients=f;
  // N1.11 — plus de puces a marquer : renderClientList repeint la barre
  // d etat, qui lit _filtreClients pour son propre aria-pressed. Un seul
  // endroit ou l etat actif est ecrit, un seul endroit ou il est lu.
  renderClientList();
}

// PURE. Le taux tel qu il s affiche : un chiffre, une fleche, et la fenetre
// ECRITE A COTE. Aucune couleur d alerte, aucun palier, aucun libelle
// qualitatif - la fleche dit le sens, elle ne dit pas si c est bien.
function htmlTauxCompletion(u,compact){
  let r=null;
  try{ r=tauxCompletion(u,Date.now()); }catch(e){}
  if(!r) return '';
  const val=tauxCompletionLib(r), fl=tauxCompletionFleche(r);
  const gris=!r.interpretable;
  if(compact) return `<span title="${escapeHtml(r.fenetre)}" style="font-size:var(--fs-xs);font-weight:800;
    color:${gris?'var(--text-faint)':'var(--text-strong)'};white-space:nowrap">${escapeHtml(val)}`
    +`${fl?' '+fl:''}</span>`;
  // TROIS LIGNES DANS UNE BOITE QUI EN AFFICHE DEUX PARTOUT AILLEURS cassaient
  // l alignement de toute la rangee. La fenetre passe en title, comme le fait
  // deja la branche compacte.
  // LES MEMES CLASSES QUE SES TROIS VOISINES. Ecrite en styles en ligne, cette
  // tuile ignorait le resserrement de la rangee : elle gardait ses 32 px de
  // chiffre et son libelle sur deux mots, qui passait a la ligne et decalait
  // toute la rangee. « Faites » suffit : les trois autres disent deja de quoi
  // il s'agit.
  return `<div style="text-align:center" title="${escapeHtml(r.fenetre)}">
    <div class="metric-val" style="color:${gris?'var(--text-faint)':'var(--text)'}">${escapeHtml(val)}<span style="font-size:.56em;color:var(--sub)">${fl?' '+fl:''}</span></div>
    <div class="metric-label">Faites</div>
  </div>`;
}
// Tri du portefeuille. L urgence reste le tri PAR DEFAUT : le taux est une
// mesure, pas une file d action.
let _triClients='urgence';
const TRIS_CLIENTS=Object.freeze(['urgence','taux','charge','progression']);
// LE BOUTON ACTIF EST DESIGNE PAR SON `data-tri`, plus par ses voisins. Les
// deux boutons se renvoyaient à nextElementSibling / previousElementSibling :
// à deux, ça tenait ; à quatre, chacun n’en éteint qu’un seul et il en reste
// deux allumés. Le tri est un état, il se lit dans l’état.
// LA REORGANISATION SE VOIT. setTriClients basculait la classe puis
// reconstruisait toutes les lignes : l'ordre changeait d'un coup, et rien ne
// disait a qui l'ancienne troisieme ligne etait devenue la huitieme — or c'est
// exactement l'information que le coach cherche en changeant de tri.
// UNIQUEMENT AU CHANGEMENT DE TRI : pas a la frappe dans la recherche (les
// lignes disparaissent, un FLIP n'a rien a interpoler), pas au reveil de
// synchro, pas au changement de filtre.
// BORNEE A 20 LIGNES : vingt getBoundingClientRect tiennent dans une frame,
// cinquante non. Au-dela, le comportement est celui d'avant.
// La garde matchMedia est OBLIGATOIRE : le bloc CSS ne couvre pas
// element.animate(). will-change n'est POSE NULLE PART — l'animation dure
// 260 ms, le navigateur promeut de lui-meme, et le poser a demeure sur vingt
// lignes ferait tomber l'appareil qu'il pretendait aider.
function setTriClients(t){
  _triClients=TRIS_CLIENTS.indexOf(t)>=0?t:'urgence';
  try{
    document.querySelectorAll('#s-coach-home [data-tri]').forEach(b=>{
      b.classList.toggle('actif',b.dataset.tri===_triClients);
    });
  }catch(e){}
  const el=document.getElementById('ch-clients-list');
  const anime=!!el&&!arcReduit()&&el.querySelectorAll('.client-row').length<=20;
  const avant=new Map();
  if(anime) el.querySelectorAll('.client-row').forEach(n=>{
    avant.set(n.dataset.cid,n.getBoundingClientRect().top);
  });
  renderClientList();
  if(!anime) return;
  requestAnimationFrame(()=>{
    el.querySelectorAll('.client-row').forEach(n=>{
      const y0=avant.get(n.dataset.cid);
      if(y0==null) return;
      const d=y0-n.getBoundingClientRect().top;
      if(Math.abs(d)<2) return;
      _animer(n,[{transform:'translateY('+d+'px)'},{transform:'translateY(0)'}],
        {duration:260,easing:ARC.discharge,fill:'none'});
    });
  });
}
function _triTaux(c){
  let r=null; try{ r=tauxCompletion(c,Date.now()); }catch(e){}
  return (r&&r.interpretable)?r.taux:-1;   // les non-interpretables en fin de liste
}

// ══════════════ RITE DE FIN DE CYCLE — 28 JOURS ══════════════════════════
// Un point d'étape chiffré, et un nouveau départ. AUCUN objet de
// périodisation n'est créé : nommer une période, c'est écrire une chaîne dans
// `rites[]`, rien de plus. Pas de programme, pas de phase, pas de cycle dans
// le modèle de données.
//
// AUCUN INDICATEUR N'EST RECALCULÉ : tout est lu des fonctions existantes
// (tauxCompletion, e1rm, volumeSemaine, REPERES_VOLUME, mm7).
const RITE_JOURS=28;
const RITE_INACTIF_MAX_J=14;      // au-delà, ce n'est plus un cycle, c'est une reprise

// PURE. L'échéance se calcule sur l'ÉCART EN JOURS depuis l'inscription,
// jamais sur le quantième : un athlète inscrit un 31 janvier a son rite au
// 28 février + 0 jour d'écart, pas « le 31 » d'un mois qui n'en a pas.
function riteEcheance(u,now){
  const t=(typeof now==='number')?now:Date.now();
  const c=Number(u&&u.createdAt)||0;
  if(!c||t<c) return {cycle:0,echu:false,jours:0};
  const jours=Math.floor((t-c)/864e5);
  const cycle=Math.floor(jours/RITE_JOURS);
  return {cycle,echu:cycle>=1,jours};
}
// PURE. Le rite a-t-il déjà été tenu pour ce cycle ?
function riteTenu(u,cycle){
  for(const r of ((u&&u.rites)||[])) if(r&&Number(r.cycle)===Number(cycle)) return true;
  return false;
}
// PURE. Faut-il l'afficher ? Rend {ok, raison}.
//
// Il ne s'affiche PAS sur un drapeau rouge, une grossesse-suspension, une
// inactivité de plus de quatorze jours, ou une période sans la moindre
// séance. Dans ces quatre cas, un point d'étape chiffré serait au mieux vide,
// au pire déplacé.
function riteAAfficher(u,now){
  const t=(typeof now==='number')?now:Date.now();
  const e=riteEcheance(u,t);
  if(!e.echu) return {ok:false,raison:'pas_echu',cycle:e.cycle};
  if(riteTenu(u,e.cycle)) return {ok:false,raison:'deja_tenu',cycle:e.cycle};
  try{ if(drapeauRougeActif(u)) return {ok:false,raison:'drapeau',cycle:e.cycle}; }catch(err){}
  const g=u&&u.grossesse&&u.grossesse.etat;
  if(g==='enceinte'||g==='allaitement') return {ok:false,raison:'suspendu',cycle:e.cycle};
  const ses=((u&&u.sessions)||[]).filter(s=>s&&s.date>0);
  let dernier=0;
  for(const s of ses) if(s.date>dernier) dernier=s.date;
  // Plus de quatorze jours sans rien : ce cas relève de la file de reprise,
  // pas d'un bilan de cycle.
  if(!dernier||(t-dernier)>RITE_INACTIF_MAX_J*864e5)
    return {ok:false,raison:'inactif',cycle:e.cycle};
  const debut=t-RITE_JOURS*864e5;
  if(!ses.some(s=>s.date>=debut&&s.date<=t))
    return {ok:false,raison:'aucune_seance',cycle:e.cycle};
  return {ok:true,raison:null,cycle:e.cycle,depuis:debut};
}
// ══════════════ LE RITE, CÔTÉ COACH ══════════════
//
// L'athlète ferme son cycle et écrit parfois une question. Elle partait dans
// `rites[]` et personne ne la lisait : le tableau de bord signalait « Bilan de
// 4 semaines à lire » pour quelque chose qu’aucun écran n’affichait.
//
// PURE. Le dernier rite SANS réponse. La ligne du tableau de bord, elle, ne
// regarde que le TOUT DERNIER — sa règle de relance unique fait qu'un cycle
// déjà laissé sans réponse ne redemande rien. La fiche, elle, montre ce qui
// reste ouvert : consulter un dossier n’est pas une relance, et ça ne réarme
// rien.
function _riteSansReponse(c){
  const l=((c&&c.rites)||[]).filter(r=>r&&r.date&&!r.reponseCoach);
  return l.length?l[l.length-1]:null;
}
// L'identifiant du champ dérive du cycle, comme celui des bilans dérive de
// l’identifiant du bilan : un id fixe redeviendrait ambigu le jour où deux
// rites seraient affichés ensemble.
function _taIdRite(cycle){ return 'rr-texte_'+cycle; }
function _htmlRiteCoach(c){
  const r=_riteSansReponse(c);
  if(!r) return '';
  const d=r.date?new Date(r.date).toLocaleDateString('fr-FR',{day:'numeric',month:'long',year:'numeric'}):'';
  let nom=''; try{ nom=riteNomPeriode(c,r.cycle); }catch(e){ nom=''; }
  const ta=_taIdRite(r.cycle);
  // La question est ÉCRITE PAR L'ATHLÈTE : elle est échappée, comme le prénom
  // dans le tableau de bord. Elle est aussi FACULTATIVE — fermerRite n’écrit
  // que la date. On dit alors qu’il n’y a pas de question plutôt que de rendre
  // un bloc vide qui laisserait croire à un rendu cassé.
  const q=String(r.question||'').trim();
  return `<div style="background:var(--surface-1);border:1px solid var(--border);border-left:3px solid var(--sub);border-radius:var(--r-3);padding:14px">
    <div style="font-size:var(--fs-xs);font-weight:800;letter-spacing:2px;color:var(--sub);text-transform:uppercase;margin-bottom:6px">📆 Bilan de 4 semaines</div>
    <div style="font-size:var(--fs-sm);color:var(--text-dim);margin-bottom:10px">${escapeHtml(nom)}${d?' · '+escapeHtml(d):''}</div>
    ${q
      ?`<div style="background:var(--surface-2);border-radius:var(--r-2);padding:10px 12px;font-size:var(--fs-sm);color:var(--text);line-height:1.6">${escapeHtml(q)}</div>`
      :`<div style="font-size:var(--fs-xs);color:var(--text-faint);line-height:1.6">Cycle clôturé sans question écrite.</div>`}
    <textarea id="${ta}" rows="3" placeholder="Ce que tu retiens de ce cycle, et ce qu'on ajuste." style="width:100%;box-sizing:border-box;margin-top:10px"></textarea>
    <button class="btn btn-red btn-sm" onclick="saveReponseRite('${escapeHtml(c.email||'')}','${escapeHtml(String(r.cycle))}','${ta}')"
      style="margin-top:8px;letter-spacing:1px">Envoyer ma réponse</button>
  </div>`;
}
function renderRiteCoach(c){
  const z=document.getElementById('ccd-rite');
  if(!z) return;
  let h=''; try{ h=_htmlRiteCoach(c); }catch(e){ h=''; }
  z.innerHTML=h;
  z.style.display=h?'':'none';
}
// L’ÉCRITURE PASSE PAR users[email], JAMAIS PAR saveUser(). _riteEnregistrer
// s’exécute côté ATHLÈTE sur currentUser ; ici currentUser est le COACH, et
// saveUser() écrirait la réponse dans le dossier du coach.
//
// Même patron que saveReponseBilan : garde-fou de modèle en tête, plafond de
// 2000 caractères, DB.set puis CLOUD.pushOne.
//
// HORODATÉ, et c’est nécessaire : _mergeUser n’applique le dossier distant que
// si son updatedAt est au moins aussi récent que le local, et _doPushOne peut
// refuser un envoi que le distant dépasse. Sans ça, la réponse partirait pour
// ne jamais arriver.
function saveReponseRite(email,cycle,taId){
  const _ta=taId||_taIdRite(cycle||'');
  if(!tplVerifierAvantEnvoi(_ta)) return false;
  const ta=document.getElementById(_ta);
  const txt=((ta&&ta.value)||'').trim();
  if(!txt){ toast('Écris ta réponse avant d\'envoyer.','var(--orange)'); return false; }
  const users=DB.get('users')||{};
  const c=users[email];
  if(!c||!Array.isArray(c.rites)){ toast('Athlète introuvable','var(--red)'); return false; }
  // Le cycle est UNIQUE dans rites[] : _riteEnregistrer refuse d’en écrire un
  // second pour le même, via riteTenu.
  const r=c.rites.find(x=>x&&Number(x.cycle)===Number(cycle)&&!x.reponseCoach);
  if(!r){ toast('Bilan de cycle introuvable','var(--red)'); return false; }
  const _avant=c.rites.length;
  r.reponseCoach=txt.slice(0,2000);
  r.reponseDate=Date.now();
  // On ne pousse RIEN dans rites[] : le plafond de 24 ne peut pas bouger.
  if(c.rites.length!==_avant) c.rites.length=_avant;
  c.updatedAt=Date.now();
  users[email]=c;
  const ok=DB.set('users',users);
  const envoi=CLOUD.pushOne(email,c);
  toastSync(ok,envoi,'Réponse envoyée. '+(c.fname||'Ton athlète')+' la verra à sa prochaine ouverture.',
    'la réponse est');
  try{ openClientDetail(c.id,true); }catch(e){}
  return true;
}
// Entrée par la ligne du tableau de bord : on ouvre la fiche ET on amène le
// bloc sous les yeux. Une alerte qui ouvre un écran de deux mètres de haut
// sans dire où regarder ne vaut guère mieux qu’une alerte muette.
function _ouvrirRiteClient(id){
  if(!id) return;
  openClientDetail(id);
  try{
    setTimeout(()=>{
      try{
        const z=document.getElementById('ccd-rite');
        if(z&&z.innerHTML) _defiler(z);
      }catch(e){}
    },80);
  }catch(e){}
}
// PURE. Le nom de la période suivante. Le coach peut la nommer ; sinon un
// numéro. Ce nom est une ÉTIQUETTE, il ne pilote rien.
function riteNomPeriode(u,cycle){
  const r=((u&&u.rites)||[]).slice().reverse().find(x=>x&&x.nom);
  return (r&&r.nom)?String(r.nom):('Cycle '+(Number(cycle)+1));
}
// PURE. Les records de la fenêtre, lus avec l'e1rm EXISTANT : meilleure
// performance de la période contre la meilleure d'avant, par exercice.
function _riteRecords(u,debut,fin){
  const av={},ap={};
  for(const s of ((u&&u.sessions)||[])){
    if(!s||!s.date) continue;
    const cible=(s.date>=debut&&s.date<=fin)?ap:((s.date<debut)?av:null);
    if(!cible) continue;
    for(const ex of ((s.exercises)||[])){
      const nom=ex&&ex.name; if(!nom) continue;
      for(const set of ((ex.sets)||[])){
        if(!set||set.done===false) continue;
        const w=parseFloat(set.weight)||0, r=parseFloat(set.repsDone!=null?set.repsDone:set.reps)||0;
        if(!(w>0&&r>0)) continue;
        let v=0; try{ v=e1rm(w,r,(set.rir==='echec')?0:(parseInt(set.rir)||0)); }catch(err){ v=w; }
        if(!(cible[nom]>v)) cible[nom]=v;
      }
    }
  }
  const out=[];
  for(const nom in ap) if(!(av[nom]>=ap[nom])) out.push({nom,valeur:Math.round(ap[nom])});
  out.sort((a,b)=>b.valeur-a.valeur);
  return out;
}
// PURE. Le contenu du rite. Il LIT, il ne calcule pas.
function riteContenu(u,now){
  const t=(typeof now==='number')?now:Date.now();
  const debut=t-RITE_JOURS*864e5;
  const ses=((u&&u.sessions)||[]).filter(s=>s&&s.date>=debut&&s.date<=t);
  let taux=null; try{ taux=tauxCompletion(u,t); }catch(e){}
  // Le volume par muscle contre MEV/MAV/MRV, lu tel quel.
  let vol=null;
  try{ vol=volumeSemaine(u,localISODate(new Date(t))); }catch(e){}
  const muscles=[];
  // ⚠ CETTE LIGNE LISAIT LA TABLE EN DIRECT, ET ELLE LISAIT `mav` — un champ
  // qui n'existe PAS dans REPERES_VOLUME, dont les bornes sont mavMin et
  // mavMax. Le rite annonçait donc un MAV undefined depuis l'origine. Passer
  // par reperesEffectifs corrige les deux d'un coup : le repère de l'athlète
  // au lieu de celui de la table, et une borne qui existe.
  if(vol) for(const m in vol){
    let rep=null; try{ rep=reperesEffectifs(u,m); }catch(e){ rep=null; }
    muscles.push({muscle:m,series:vol[m],mev:rep&&rep.mev,
      mav:rep&&rep.mavMin,mrv:rep&&rep.mrv,source:rep&&rep.source});
  }
  // PHASE LUTÉALE : aucune minoration n'existe dans le fichier (le facteur de
  // charge y vaut 1,00, seule la SÉRIE est réduite). On ne minore donc rien —
  // on MENTIONNE la phase, pour que la lecture se fasse en contexte.
  let mentionPhase=false;
  try{ mentionPhase=(typeof phaseCycle==='function')
    &&phaseCycle(u,localISODate(new Date(t)))==='luteal_late'; }catch(e){}
  return {seances:ses.length,taux:taux,records:_riteRecords(u,debut,t),
    muscles:muscles,mentionPhase:mentionPhase,depuis:debut,jusqua:t};
}
// Le bilan bimensuel de la même semaine, s'il existe : on le RÉFÉRENCE, on ne
// le rejoue pas. À fréquence hebdomadaire, la coïncidence arrive une fois sur
// quatre — ce n'est pas un cas rare.
function riteBilanDeLaSemaine(u,now){
  const t=(typeof now==='number')?now:Date.now();
  const sem=7*864e5;
  const l=((u&&u.bilans)||[]).filter(b=>b&&b.type!=='depart'&&b.date>t-sem&&b.date<=t);
  return l.length?l[l.length-1]:null;
}

// ── L'écran du rite ───────────────────────────────────────────────────────
// NON BLOQUANT : il se ferme, il ne se subit pas. Aucune notification — il
// s'affiche à l'ouverture de l'app, et seulement si riteAAfficher le permet.
//
// AUCUNE ÉCRITURE AU CHARGEMENT : `rites[]` n'est écrit qu'à la fermeture, et
// ne porte alors que la date si l'athlète n'a rien répondu.
function _riteLigne(lib,val,note){
  return `<div style="display:flex;justify-content:space-between;gap:12px;align-items:baseline;
    padding:7px 0;border-top:1px solid rgba(255,255,255,.06)">
    <span style="font-size:var(--fs-xs);color:var(--sub)">${escapeHtml(lib)}</span>
    <span style="font-size:var(--fs-md);font-weight:800;color:var(--text);text-align:right">${val}${note?`<span style="font-size:var(--fs-2xs);color:var(--text-faint);font-weight:400"> ${escapeHtml(note)}</span>`:''}</span>
  </div>`;
}
function ouvrirRite(cycle){
  const u=currentUser;
  const c=riteContenu(u,Date.now());
  const bil=riteBilanDeLaSemaine(u,Date.now());
  const nom=riteNomPeriode(u,cycle);
  window._riteCycle=cycle;
  // Tendance de poids : LUE, jamais recalculee.
  let vit=null;
  try{ vit=vitesseHebdo(serieWeight(u)); }catch(e){}
  const tauxLib=(c.taux&&c.taux.interpretable)?(c.taux.taux+' %'):'—';
  const muscles=c.muscles.filter(m=>m.mev!=null).slice(0,14);
  const html=`<div id="modal-overlay" onclick="fermerRite()" style="position:fixed;inset:0;background:var(--scrim);z-index:var(--z-modal);display:flex;align-items:flex-end;justify-content:center">
  <div onclick="event.stopPropagation()" style="background:var(--surface-2);border-radius:var(--r-4) var(--r-4) 0 0;padding:16px 18px 22px;width:100%;max-width:480px;max-height:90vh;overflow-y:auto">
    <div style="display:flex;align-items:center;justify-content:space-between;gap:10px;margin-bottom:2px">
      <h2 style="margin:0">4 semaines</h2>
      <button onclick="fermerRite()" aria-label="Fermer" style="min-width:44px;min-height:44px;background:none;border:none;color:var(--sub);font-size:var(--fs-xl);cursor:pointer">×</button>
    </div>
    <p class="sub" style="font-size:var(--fs-xs);margin-bottom:14px;line-height:1.6">Un point d'étape, pas une note. Tu peux fermer cet écran à tout moment.</p>

    <div style="background:var(--surface-1);border:1px solid var(--border);border-radius:var(--r-3);padding:11px 13px;margin-bottom:10px">
      ${_riteLigne('Séances réalisées',c.seances)}
      ${_riteLigne('Séances faites sur prévues',tauxLib,c.taux?c.taux.fenetre:'')}
      ${vit&&vit.pctSem!=null?_riteLigne('Tendance de poids',(vit.pctSem>0?'+':'')+String(Math.round(vit.pctSem*100)/100).replace('.',',')+' %/sem'):''}
    </div>

    <div style="background:var(--surface-1);border:1px solid var(--border);border-radius:var(--r-3);padding:11px 13px;margin-bottom:10px">
      <div style="font-size:var(--fs-2xs);color:var(--sub);letter-spacing:1.5px;font-weight:800;text-transform:uppercase;margin-bottom:6px">Records battus</div>
      ${c.records.length
        ? c.records.slice(0,6).map(r=>_riteLigne(r.nom,r.valeur+' <span style="font-size:var(--fs-2xs);color:var(--sub);font-weight:400">e1RM</span>')).join('')
        : '<div style="font-size:var(--fs-xs);color:var(--text-dim);line-height:1.6">Aucun record sur la période. Ce n\'est pas un échec : la progression n\'est pas linéaire.</div>'}
      ${c.mentionPhase?'<div style="font-size:var(--fs-2xs);color:var(--text-faint);line-height:1.55;margin-top:8px">Relevé en phase lutéale tardive : une baisse y est attendue, et n\'a pas la même signification qu\'une régression.</div>':''}
    </div>

    ${muscles.length?`<div style="background:var(--surface-1);border:1px solid var(--border);border-radius:var(--r-3);padding:11px 13px;margin-bottom:10px">
      <div style="font-size:var(--fs-2xs);color:var(--sub);letter-spacing:1.5px;font-weight:800;text-transform:uppercase;margin-bottom:6px">Volume par muscle</div>
      ${muscles.map(m=>_riteLigne(m.muscle,m.series+' séries','MEV '+m.mev+' · MAV '+m.mav+' · MRV '+m.mrv)).join('')}
    </div>`:''}

    ${bil?`<div style="background:var(--info-bg);border:1px solid var(--info-border);border-radius:var(--r-3);padding:11px 13px;margin-bottom:10px;font-size:var(--fs-xs);color:var(--text-strong);line-height:1.6">
      Ton bilan de cette semaine est déjà enregistré : il n'est pas redemandé ici.</div>`:''}

    <label style="margin-top:0">Une question à ton coach&nbsp;?</label>
    <textarea id="rite-question" rows="2" placeholder="Facultatif — ce que tu veux lui demander pour la suite"></textarea>

    <div style="margin-top:12px;border-top:1px solid var(--border);padding-top:12px">
      <div style="font-size:var(--fs-sm);font-weight:800;color:var(--text);margin-bottom:2px">${escapeHtml(nom)}</div>
      <div style="font-size:var(--fs-xs);color:var(--text-dim);line-height:1.55;margin-bottom:9px">Tes jours et ton heure d'entraînement pour les 4 prochaines semaines. Nommer cette période ne crée aucun programme : c'est une étiquette.</div>
      <div id="rite-jours" style="display:flex;gap:5px;flex-wrap:wrap;margin-bottom:9px">
        ${['L','Ma','Me','J','V','S','D'].map((j,i)=>`<button type="button" data-j="${i}" onclick="riteJour(${i},this)"
          style="flex:1;min-width:40px;min-height:44px;border-radius:var(--r-2);cursor:pointer;background:#111;border:1px solid var(--border);color:var(--sub);font-family:Montserrat,sans-serif;font-size:var(--fs-xs);font-weight:800">${j}</button>`).join('')}
      </div>
      <div style="display:flex;align-items:center;gap:8px">
        <span style="font-size:var(--fs-xs);color:var(--sub)">Heure</span>
        <input id="rite-heure" type="number" min="0" max="23" value="${(currentUser._woReminderHour??18)}"
          style="width:70px;font-size:var(--fs-lg);padding:9px 10px;text-align:center;box-sizing:border-box">
      </div>
    </div>

    <button class="btn btn-red" style="margin-top:14px;width:100%" onclick="validerRite()">Enregistrer et repartir</button>
    <button class="btn btn-outline" style="margin-top:8px;width:100%" onclick="fermerRite()">Plus tard</button>
  </div></div>`;
  document.body.insertAdjacentHTML('beforeend',html);
  window._riteJours=(currentUser._woReminderDays||[]).slice();
  (window._riteJours||[]).forEach(i=>{
    const b=document.querySelector('#rite-jours button[data-j="'+i+'"]');
    if(b) riteJour(i,b,true);
  });
}
function riteJour(i,el,forcer){
  if(!window._riteJours) window._riteJours=[];
  const k=window._riteJours.indexOf(i);
  const actif=forcer?true:(k<0);
  if(actif&&k<0) window._riteJours.push(i);
  if(!actif&&k>=0) window._riteJours.splice(k,1);
  el.style.background=actif?'rgba(224,32,32,.14)':'#111';
  el.style.borderColor=actif?'var(--red)':'var(--border)';
  el.style.color=actif?'var(--text)':'var(--sub)';
}
// LES CYCLES REPORTES DANS CETTE SESSION. Un Set en mémoire, JAMAIS une
// écriture au dossier : c’est toute la différence entre « pas maintenant »
// et « c’est fait ».
//
// Il disparaît à la fermeture de l’app, et le rite se represente à la
// prochaine ouverture — c’est ce que « Plus tard » promet.
const _riteReportes=new Set();
// LA CLÉ PORTE LE COMPTE, pas seulement le cycle. RepCore assume plusieurs
// comptes sur le même téléphone : deux athlètes au même numéro de cycle
// partageaient leur report, et le rite du second ne s’affichait pas sans que
// rien ne le dise. Un numéro de cycle n’est pas un identifiant.
//
// L’email quand il existe, l’identifiant sinon : un compte créé par code
// n’a pas toujours d’email.
function _riteCle(u,cycle){
  const qui=(u&&(u.email||u.id))||'?';
  return qui+'#'+Number(cycle);
}
// FERMETURE SANS ÉCRITURE. Elle inscrivait le cycle dans rites[], donc le
// rendait « tenu » pour riteTenu : la modale ne revenait plus avant 28 jours.
// Or cette fonction est appelée par le bouton « Plus tard » ET par le clic
// sur le fond de la modale — un geste qui, partout ailleurs dans ce produit,
// ne décide de rien.
//
// SEUL « Enregistrer et repartir » écrit désormais.
function fermerRite(){
  try{ _riteReportes.add(_riteCle(currentUser,window._riteCycle)); }catch(e){}
  closeModal();
}
function validerRite(){
  const q=((document.getElementById('rite-question')||{}).value||'').trim();
  _riteEnregistrer(q,true);
  closeModal();
  toast('Nouveau cycle noté.');
}
function _riteEnregistrer(question,avecReglages){
  try{
    const u=currentUser;
    if(!u) return false;
    if(!Array.isArray(u.rites)) u.rites=[];
    if(riteTenu(u,window._riteCycle)) return false;
    const e={cycle:window._riteCycle,date:Date.now(),reponseCoach:null};
    if(question) e.question=question;
    u.rites.push(e);
    if(u.rites.length>24) u.rites=u.rites.slice(-24);
    // Les jours et l'heure vont dans les CHAMPS DE RAPPEL EXISTANTS : aucun
    // objet de périodisation n'est créé.
    if(avecReglages){
      const h=parseInt((document.getElementById('rite-heure')||{}).value,10);
      if(Array.isArray(window._riteJours)&&window._riteJours.length){
        u._woReminderDays=window._riteJours.slice().sort((a,b)=>a-b);
        u._woReminderEnabled=true;
      }
      if(h>=0&&h<=23) u._woReminderHour=h;
    }
    saveUser();
    return true;
  }catch(e){ return false; }
}
// Appelé à l'ouverture de l'accueil athlète. Ne s'affiche que si TOUT est
// réuni, et ne bloque jamais l'accès à l'application.
// PURE. Le dernier bilan de fin de cycle portant une réponse du coach que
// l’athlète n’a pas encore lue, ou null.
//
// `reponseVue!==true` ET NON `===false` : les rites écrits avant ce lot ne
// portent aucun drapeau, et une réponse déjà envoyée doit pouvoir être lue.
function riteReponseNonVue(u){
  const l=((u&&u.rites)||[]).filter(r=>r&&r.reponseCoach&&r.reponseVue!==true);
  return l.length?l[l.length-1]:null;
}
// LE PATRON EXACT de la réponse de bilan — cadre var(--surface-2), filet
// gauche vert, titre « Réponse de ton coach ». La ligne de cycle en plus :
// une réponse sans son objet ne se rattache à rien, là où celle du bilan est
// rendue DANS la carte du bilan qu’elle commente.
function _htmlRiteReponse(r){
  if(!r||!r.reponseCoach) return '';
  const _c=Number(r.cycle);
  const _d=r.reponseDate?new Date(r.reponseDate).toLocaleDateString('fr-FR',{day:'2-digit',month:'2-digit'}):'';
  const _sous=[Number.isFinite(_c)&&_c>0?('Bilan de fin de cycle '+_c):'',_d].filter(Boolean).join(' · ');
  return `<div style="margin-bottom:18px;background:var(--surface-2);border-left:3px solid var(--green);border-radius:var(--r-2);padding:10px 12px">
    <div style="font-size:var(--fs-xs);letter-spacing:1.5px;text-transform:uppercase;color:var(--green);font-weight:800;margin-bottom:4px">Réponse de ton coach</div>
    ${_sous?`<div style="font-size:var(--fs-xs);color:var(--text-dim);margin-bottom:5px">${escapeHtml(_sous)}</div>`:''}
    <div style="font-size:var(--fs-sm);color:var(--text-strong);line-height:1.6">${escapeHtml(r.reponseCoach)}</div>
  </div>`;
}
// MARQUÉ LU À L’AFFICHAGE, comme `b.reponseVue` pour les bilans : le bloc a
// été rendu, il ne revient pas à chaque ouverture.
//
// L’écriture ne touche QUE ce drapeau : `rites` n’est ni allongé ni
// réordonné, donc le plafond de 24 de _riteEnregistrer ne peut pas bouger.
function renderRiteReponse(){
  const el=document.getElementById('clh-rite-reponse');
  if(!el) return false;
  let r=null; try{ r=riteReponseNonVue(currentUser); }catch(e){ r=null; }
  let h=''; try{ h=_htmlRiteReponse(r); }catch(e){ h=''; }
  el.innerHTML=h;
  el.style.display=h?'':'none';
  // APRÈS le rendu : si l’écriture échouait, le bloc serait quand même à
  // l’écran, et c’est ce qui compte.
  if(h&&r&&r.reponseVue!==true){ r.reponseVue=true; try{ saveUser(); }catch(e){} }
  return !!h;
}
function riteAfficherSiBesoin(){
  try{
    if(!currentUser||currentUser.role==='coach') return false;
    if(document.getElementById('modal-overlay')) return false;   // une modale suffit
    const v=riteAAfficher(currentUser,Date.now());
    if(!v.ok) return false;
    // REPORTÉ DANS CETTE SESSION : on ne le repose pas à chaque navigation.
    // Lu ICI et non dans riteAAfficher, qui est PURE et doit le rester — une
    // lecture d’état de session la rendrait dépendante du navigateur.
    if(_riteReportes.has(_riteCle(currentUser,v.cycle))) return false;
    ouvrirRite(v.cycle);
    return true;
  }catch(e){ return false; }
}
// ══ LA GRILLE DE VIGNETTES ═══════════════════════════════════════════════
//
// Ce que le coach voit en ouvrant l'application, ce sont SES ATHLETES. L'ecran
// s'ouvrait sur un titre, trois boutons et une barre de code : quatre elements
// avant le premier visage. Maquette de Kevin du 08/09/2026, reproduite ici.
//
// UN ROND, UN NOM, UNE PETITE CARTE. Le rond porte un anneau de couleur —
// rose pour une femme, bleu pour un homme — et c'est la seule chose qui les
// distingue a distance ; la carte redit le sexe en toutes lettres pour qui ne
// lit pas la couleur. Rien derriere : pas de fond, pas de bordure autour de la
// vignette. La photo est le sujet.
//
// L'AGE VIENT DE LA DATE DE NAISSANCE quand elle est la. `age` n'en est qu'une
// vue, figee a l'inscription : l'afficher tel quel ferait vieillir tout le
// monde d'un an en retard.
const VIG_ROSE='#ff2d78', VIG_BLEU='#2196f3';
function _vigAge(c){
  let a=null;
  try{ if(c&&c.birthdate) a=_ageRevolu(c.birthdate); }catch(e){}
  if(!(a>0)&&c&&Number(c.age)>0) a=Number(c.age);
  return (a>0)?a:null;
}
// PURE. Le HTML d'une vignette. Sortie a part pour etre eprouvable sans DOM.
function htmlVignetteAthlete(c){
  if(!c) return '';
  const femme=isFemale(c.gender);
  const couleur=femme?VIG_ROSE:VIG_BLEU;
  const nom=((c.fname||'')+' '+(c.lname||'')).trim()||c.email||'Sans nom';
  const age=_vigAge(c);
  const but=String(c.objective||c.bilanGoals||'').trim();
  // La photo, ou les initiales. Le rond garde sa taille dans les deux cas :
  // une grille dont les tuiles changent de hauteur selon la presence d'une
  // photo se lit en escalier.
  const dedans=c.athletePhoto
    ?`<img src="${escapeHtml(c.athletePhoto)}" alt="" style="width:100%;height:100%;object-fit:cover">`
    :`<span style="font-size:34px;font-weight:900;color:var(--text-faint);letter-spacing:1px">${escapeHtml(ini(c.fname,c.lname))}</span>`;
  // ⚠ MEME RAISON QUE LE BOUTON DE LA LIGNE. Le libelle d'accessibilite dit
  // « Ouvrir la fiche de … » : il doit l'ouvrir. Ces vignettes sont en HAUT de
  // l'ecran, loin de la liste — le tiroir qu'elles ouvraient apparaissait a
  // cote d'un tableau que le coach ne regardait meme pas.
  return `<button type="button" class="vig-ath" onclick="openClientDetail('${escapeHtml(String(c.id||''))}',false,true)"
    aria-label="Ouvrir la fiche de ${escapeHtml(nom)}">
    <span class="vig-rond" style="border-color:${couleur}">${dedans}</span>
    <span class="vig-nom">${escapeHtml(nom)}</span>
    <span class="vig-carte">
      <span class="vig-l1"><span class="vig-sexe" style="color:${couleur}">${femme?'♀':'♂'}</span>
        <span class="vig-sx">${femme?'Femme':'Homme'}</span>${age?`<span class="vig-sep">|</span><span class="vig-age">${age} ans</span>`:''}</span>
      ${but?`<span class="vig-but">${escapeHtml(but)}</span>`:''}
    </span>
  </button>`;
}
// Rendue par renderClientList : la grille suit EXACTEMENT le filtre, la
// recherche et le tri de la liste. Deux jeux differents sur le meme ecran
// feraient chercher un athlete present dans l'un et absent de l'autre.
function _rendreVignettesAthletes(vus){
  const z=document.getElementById('ch-vignettes');
  if(!z) return false;
  if(!vus||!vus.length){ z.innerHTML=''; return false; }
  // Les titres de section sont poses EN GRILLE (grid-column:1/-1) : la grille
  // les traite comme une ligne pleine largeur, sans casser les colonnes.
  z.innerHTML='<div class="vig-grille">'+_htmlSectionsSuivi(vus,htmlVignetteAthlete)+'</div>';
  return true;
}
// LES DEUX SECTIONS. Elles ne paraissent QUE s'il y a des deux cotes : tant
// que le coach n'a bascule personne, tout le monde est « avec suivi » et un
// titre unique au-dessus d'une liste complete n'apprendrait rien.
// Une recherche ou un filtre qui ne laisse qu'un camp retombe donc sur la
// liste simple, sans en-tete orpheline.
// UN SEUL DECOUPAGE, TROIS EMPLOIS : la liste, la grille de vignettes et le
// CRM. Trois copies auraient fini par diverger — un ecran segmente et l'autre
// pas, sur la meme donnee, c'est pire que pas de segmentation du tout.
// `rendu` est la fonction qui sait peindre UNE fiche ; ce decoupage ne sait
// rien d'autre que trier et titrer.
function _htmlSectionsSuivi(vus,rendu,enTete){
  const peindre=rendu||renderClientRow;
  // L'EN-TETE N'EST PASSE QUE PAR LA LISTE. Les vignettes et le CRM partagent
  // ce decoupage mais n'ont pas de colonnes : leur poser une ligne
  // d'intitules n'aurait rien a surmonter.
  const tete=typeof enTete==='function'?enTete():'';
  const avec=(vus||[]).filter(estSuivi),sans=(vus||[]).filter(c=>!estSuivi(c));
  // LES DEUX SECTIONS PARAISSENT TOUJOURS, meme vides — et c'est un
  // changement du 14/09/2026. La regle d'avant les masquait tant qu'un seul
  // camp existait : comme tout le monde est « avec suivi » par defaut,
  // PERSONNE ne voyait jamais de titre, donc personne ne pouvait deviner que
  // le curseur existait. Une fonctionnalite qu'on ne voit pas n'existe pas.
  // La section vide dit quoi faire ; c'est elle qui apprend le geste.
  if(!(vus||[]).length) return '';
  // EN ROUGE, LES DEUX. Demande de Kévin. Ces titres sont les seuls repères
  // d'une liste qui peut faire trente fiches : en gris, ils se confondaient
  // avec le sous-texte des fiches elles-mêmes et on défilait sans voir qu'on
  // avait changé de camp.
  //
  // `--red-text` ET NON `--red` : le rouge de la marque est conçu pour des
  // aplats et des boutons, pas pour du texte de douze pixels sur du noir.
  // `--red-text` est sa variante éclaircie, celle du bandeau « Mes
  // notifications ».
  //
  // ⚠ LE COMPTE RESTE PÂLE, et c'est voulu : il dit combien, pas quoi. En
  //   rouge lui aussi, on lirait « 17 » avant « avec suivi ».
  const titre=(t,n)=>'<div style="grid-column:1/-1;display:flex;align-items:baseline;gap:8px;'
    +'margin:18px 0 6px;padding-bottom:6px;border-bottom:1px solid var(--border)">'
    +'<span style="font-size:var(--fs-xs);font-weight:800;letter-spacing:2px;text-transform:uppercase;color:var(--red-text)">'
    // `sec-suivi` : la prise que _majComptesSectionsSuivi saisit pour
    // recompter les deux sections sans repeindre la liste entiere.
    +escapeHtml(t)+'</span><span class="sec-suivi" style="font-size:var(--fs-2xs);color:var(--text-faint)">'+n+'</span></div>';
  const vide=t=>'<div style="grid-column:1/-1;font-size:var(--fs-xs);color:var(--text-dim);'
    +'line-height:1.6;padding:10px 2px 14px">'+t+'</div>';
  // L'EN-TETE SUIT LE TITRE ET PRECEDE LA PREMIERE LIGNE — et seulement
  // quand il y a une ligne a surmonter : au-dessus d'un « Personne ici pour
  // l'instant », une rangee d'intitules ne designerait rien.
  return titre('Mes athlètes (avec suivi)',avec.length)
    +(avec.length?tete+avec.map(peindre).join('')
       :vide('Personne ici pour l\'instant.'))
    +titre('Mes athlètes (sans suivi)',sans.length)
    +(sans.length?tete+sans.map(peindre).join('')
       :vide('Personne ici pour l\'instant. Touche le curseur SUIVI sur une fiche pour l\'y basculer.'));
}
/**
 * L'EN-TETE DU TABLEAU, POSE AU-DESSUS DE CHAQUE SECTION. Demande de Kevin,
 * 19/09/2026. Il n'y en avait qu'un, tout en haut : arrive au titre
 * « Mes athletes (sans suivi) », le coach avait dix lignes de colonnes
 * au-dessus de lui et plus aucun intitule en vue. Chaque section porte
 * desormais le sien.
 *
 * UNE LIGNE ROUGE, et pas un simple texte gris : c'est ce qui la fait lire
 * comme la tete d'un tableau plutot que comme une premiere ligne de donnees.
 * Le texte est presque noir dessus — sur l'aplat rouge, du blanc tombe sous
 * quatre pour un et ces intitules font onze pixels.
 *
 * ONZE CELLULES, DANS L'ORDRE EXACT DE LA LIGNE : case, avatar, nom,
 * objectif, assiduite, diete, charge, bilans, bouton, suivi, etat. Toute
 * cellule ajoutee a la ligne doit en ajouter une ici, et une assertion
 * compare les deux comptes a celui des pistes de la grille.
 *
 * ⚠ `cr-assidu` ET `cr-diete` SONT PORTES PAR LEURS INTITULES : c'est ce qui
 *   les eteint avec leurs cellules quand le tiroir prend la place, sans quoi
 *   l'en-tete aurait onze intitules pour neuf pistes et repasserait a la ligne.
 * @returns {string}
 */
function _htmlEnteteTableau(){
  return '<div class="cr-head"><span></span><span></span><span>Athlète</span>'
    +'<span>Objectif</span>'
    +'<span class="cr-assidu" title="Séances faites sur séances prévues">Assiduité</span>'
    +'<span class="cr-diete" title="Jours où la cible a été tenue">Diète</span>'
    +'<span title="Charge de la semaine, sur la moyenne des 4 précédentes">Charge</span>'
    +'<span title="Bilans sans réponse">Bilans</span>'
    +'<span>Accès profil</span><span>Suivi</span><span>État</span></div>';
}
function renderClientList(clients){
  const el=document.getElementById('ch-clients-list');
  if(!el) return;
  const tous=clients||getClients();
  const q=norm((document.getElementById('ch-search')||{}).value||'');
  let vus=tous;
  if(q) vus=vus.filter(c=>norm((c.fname||'')+' '+(c.lname||'')).includes(q));
  // QUI ENTRE DANS QUEL FILTRE. Demande de Kevin, 11/09/2026 : une alerte de
  // seance ou de charge ne concerne que quelqu'un qu'on suit ; une echeance
  // d'acces concerne tout le monde, puisqu'elle porte sur le paiement.
  //   seances, alertes, charges groupees -> avec suivi seulement
  //   acces, jamais demarre, en attente, actifs, tous -> les deux
  if(_filtreClients==='traiter') vus=vus.filter(c=>needsAlert(c)||hasNewBilan(c));
  else if(_filtreClients==='attente') vus=vus.filter(c=>_enAttenteInscription(c));
  // Les trois compteurs de la barre. MEMES predicats que agregerPortefeuille :
  // un compteur qui n'ouvre pas exactement sa propre liste serait pire que pas
  // de compteur du tout.
  else if(_filtreClients==='pf-traiter') vus=vus.filter(c=>estSuivi(c)&&urgencyScore(c)>=PIL_SEUIL_TRAITER);
  else if(_filtreClients==='pf-decrochage') vus=vus.filter(c=>estSuivi(c)&&_pilEligibleSignaux(c)&&signauxEntrainement(c).decrochage);
  else if(_filtreClients==='pf-acces') vus=vus.filter(c=>_pilEligibleSignaux(c)&&_pilAccesExpire(c,Date.now()));
  // N1.11 — les deux etats que les metric-box decrivaient sans les ouvrir.
  // MEMES predicats que agregerPortefeuille, aux memes fonctions.
  else if(_filtreClients==='pf-jamais') vus=vus.filter(c=>neverStarted(c));
  else if(_filtreClients==='pf-actifs') vus=vus.filter(c=>isActive(c));
  // ── LA VUE PAR DEFAUT GARDE TOUS CEUX QUI ONT UN COMPTE ─────────────
  //
  // Demande de Kevin, 19/09/2026 : « fais apparaitre tous les athletes qui ont
  // cree leur compte, juste ne mets pas ceux en attente ». Cette ligne
  // excluait trois familles le 16/09, deux le 18/09, une seule desormais.
  // Voir _enAttenteInscription pour le pourquoi de chaque retrait.
  //
  // ⚠ SEULEMENT EN VUE PAR DEFAUT, et cette garde reste. Une recherche, ou
  // n'importe quelle puce de filtre, RAMENE tout le monde : « En attente » est
  // precisement la puce qui sert a retrouver ceux-la, et un filtre qui
  // ouvrirait une liste vide serait pire que pas de filtre.
  //
  // L'EXCLUSION EST LA DERNIERE : posee avant les puces, elle les aurait
  // videes ; posee ici, elle ne mord que sur le jeu complet.
  else if(_filtreClients==='travail'&&!q) vus=vus.filter(c=>!_enAttenteInscription(c));
  if(_triClients==='taux') vus.sort((a,b)=>_triTaux(b)-_triTaux(a));
  else if(_triClients==='charge') vus.sort((a,b)=>_triCharge(b)-_triCharge(a));
  else if(_triClients==='progression') vus.sort((a,b)=>_triProgres(b)-_triProgres(a));
  // LA GRILLE SUIT, juste apres le tri : meme jeu, meme ordre.
  // Elle est rendue plus bas, une fois `vus` definitivement arrete.
  // L’URGENCE RESTE LE DÉFAUT : c’est le seul tri qui réponde à « qui
  // dois-je regarder », et les trois autres sont des questions qu’on se pose
  // ensuite.
  else vus.sort((a,b)=>urgencyScore(b)-urgencyScore(a));
  // Bilans auxquels le coach n'a pas encore ecrit. « Sans reponse » et non
  // « non lus » : ouvrir ne compte plus.
  // LA GRILLE DE VIGNETTES, sur le MEME jeu que la liste : meme recherche,
  // meme filtre, meme tri. Deux jeux differents sur le meme ecran feraient
  // chercher un athlete present dans l'un et absent de l'autre.
  try{ _rendreVignettesAthletes(vus); }catch(e){}
  renderPilotage(tous);
  renderPortefeuille(tous);
  // N4.13 — la selection est ELAGUEE de ce qui n'existe plus, puis la barre
  // est repeinte. On elague sur `tous` et non sur `vus` : un athlete masque
  // par un filtre reste selectionne, c'est le filtre qui change, pas lui.
  try{ _selElaguer(tous); _selMaj(); }catch(e){}
  // La ligne « Bilans sans reponse » a demenage dans le volet « Vue
  // d'ensemble » du pilotage. L'element qu'on vidait ici n'existe plus.
  const cnt=document.getElementById('ch-count');
  if(cnt) cnt.textContent=vus.length+'/'+tous.length+' athlete'+(tous.length>1?'s':'');
  // Position de defilement preservee : reecrire innerHTML la remet a zero.
  const pan=document.getElementById('ct-dashboard');
  const scr=pan?pan.scrollTop:0;
  if(!vus.length){
    // TROIS SITUATIONS, TROIS PHRASES. « Aucun athlète ne correspond » etait
    // juste pour une recherche et faux pour la vue par defaut : un coach dont
    // tout le portefeuille dort aurait lu que ses athletes n'existent pas,
    // alors qu'ils sont tous dans les cadres du bas.
    el.innerHTML=q
      ? '<div class="sub" style="text-align:center;padding:28px 12px;font-size:var(--fs-sm)">Aucun athlète ne correspond.</div>'
      : (_filtreClients==='travail'
        ? (tous.length
          ? '<div class="sub" style="text-align:center;padding:28px 12px;font-size:var(--fs-sm);line-height:1.6">'
            +'Personne en activité cette quinzaine.<br>Tes '+tous.length+' athlète'+(tous.length>1?'s sont':' est')
            +' dans les listes en bas de page.</div>'
          : el.innerHTML)
        : '<div class="sub" style="text-align:center;padding:28px 12px;font-size:var(--fs-sm)">Aucun athlète ne correspond.</div>');
  } else {
    // L'EN-TETE EST EMIS TOUJOURS, une fois par section : c'est le CSS qui
    // decide de l'afficher, et seulement au-dela de 1360 px. Le sortir du
    // rendu demanderait au JS de connaitre la largeur de la fenetre.
    el.innerHTML=_htmlSectionsSuivi(vus,null,_htmlEnteteTableau);
    // LA CASCADE NE JOUE QU'AU PREMIER REMPLISSAGE de la visite. Les rendus
    // suivants — frappe, filtre, tri, synchro — posent le contenu sans un
    // mouvement : une entree qui se rejoue n'est plus une entree, c'est un
    // clignotement pendant qu'on filtre. Le drapeau est remis a zero dans
    // go(), et nulle part ailleurs. 420 ms couvrent le dernier retard (90 ms)
    // plus la duree (200 ms) avec de la marge.
    if(!el.dataset.deja){
      el.dataset.deja='1';
      el.setAttribute('data-entree','');
      setTimeout(()=>{ try{ el.removeAttribute('data-entree'); }catch(e){} },420);
    }
  }
  // APRES l'ecriture de l'innerHTML, comme aujourd'hui.
  if(pan&&scr) pan.scrollTop=scr;
  // L'entree au defilement pour tout ce qui est sous le pli, a partir de la
  // septieme ligne : les six premieres ont deja la cascade.
  try{ arcEntreeAuDefilement(el,'.client-row',6); }catch(e){}
  return vus.length;
}

// ── Lignes d'alerte d'entraînement ──────────────────────────────────────────
// Les cinq lignes administratives sont GROUPÉES par type (« 3 bilans à lire ·
// Marc, Julie +1 »). Les signaux d'entraînement ne peuvent pas l'être : chacun
// porte une donnée propre à l'athlète — un nom d'exercice, des chiffres, un
// muscle. Une ligne par athlète, donc, au-dessus des lignes groupées.
const TODO_MAX_LIGNES=8;
// Rappel de la contre-indication à côté d'une alerte de douleur. C'est le
// croisement que contreIndications permettait depuis toujours sans avoir
// jamais été fait : le coach lisait « douleur épaule » d'un côté et « épaule
// droite opérée en 2023 » de l'autre, sans que rien ne les rapproche.

// ══════════════ FILE DE REPRISE ══════════════════════════════════════════
// Une file d'ASSIDUITÉ, et rien d'autre. Elle lit urgencyScore sans le
// modifier, et n'accepte que les niveaux où le sujet est la présence : 7
// (séances écourtées), 5 (jamais démarré, nouveau bilan), 4 (bilan en retard).
//
// CE QUI N'Y ENTRE JAMAIS : le drapeau rouge (10) et les douleurs (9, 8). Ils
// gardent leur ligne propre dans « À traiter », non reportable, dont la
// formulation est un renvoi médical. Le palier 6 est exclu lui aussi : il
// mélange du volume d'entraînement et de la restriction calorique prolongée,
// qui est de la santé. Une file de relance n'est pas le bon endroit.
//
// AUCUN CANAL D'ENVOI n'est créé : RepCore prépare un texte, l'humain envoie.
const FR_NIVEAUX=Object.freeze([7,5,4]);
const FR_MAX_LIGNES=TODO_MAX_LIGNES;      // même plafond que « À traiter »
const FR_VEILLE_DEFAUT_J=7;

// PURE. Ce dossier a-t-il sa place dans la file ?
// Trois exclusions dures : la santé, la pause déclarée, l'invité non inscrit.
function _frEligible(c){
  if(!c||c._fromCode||!c.email) return false;
  try{ if(drapeauRougeActif(c)) return false; }catch(e){}        // règle 1
  try{ if(_estEnPause(c)) return false; }catch(e){}              // règle 6
  let s=0;
  try{ s=urgencyScore(c); }catch(e){ return false; }
  return FR_NIVEAUX.indexOf(s)>=0;
}
// PURE. Jours écoulés depuis la dernière séance enregistrée, ou null.
function _frAnciennete(c,now){
  const t=(typeof now==='number')?now:Date.now();
  let dernier=0;
  for(const s of ((c&&c.sessions)||[])) if(s&&s.date>dernier) dernier=s.date;
  if(!dernier) return null;
  return Math.max(0,Math.floor((t-dernier)/864e5));
}
// PURE. Jours depuis la dernière relance notée par le coach, ou null.
// Le repère vit dans le dossier du COACH : rien n'est écrit chez l'athlète.
function _frRelanceDepuis(coach,c,now){
  const t=(typeof now==='number')?now:Date.now();
  const r=((coach&&coach.relances)||{})[c&&c.id];
  if(!(r>0)) return null;
  return Math.max(0,Math.floor((t-r)/864e5));
}
// PURE. La file, ordonnée par urgence décroissante puis par ancienneté.
function fileReprise(clients,coach,now){
  const t=(typeof now==='number')?now:Date.now();
  const l=(Array.isArray(clients)?clients:[]).filter(_frEligible);
  const rows=l.map(c=>{
    let sg=null; try{ sg=signauxEntrainement(c); }catch(e){}
    let texte='';
    try{ texte=_texteSignal(_frType(c,sg),c,sg)||''; }catch(e){}
    return {id:c.id,prenom:(c.fname||'').trim(),score:urgencyScore(c),
      signal:texte,jours:_frAnciennete(c,t),relanceDepuis:_frRelanceDepuis(coach,c,t)};
  });
  rows.sort((a,b)=>(b.score-a.score)||((b.jours||0)-(a.jours||0)));
  return {lignes:rows.slice(0,FR_MAX_LIGNES),reste:Math.max(0,rows.length-FR_MAX_LIGNES),
    total:rows.length};
}
// Le type de signal à faire décrire par _texteSignal, qu'on ne réécrit pas.
function _frType(c,sg){
  if(sg&&sg.decrochage) return 'decrochage';
  try{ if(neverStarted(c)) return 'nostart'; }catch(e){}
  try{ if(hasNewBilan(c)) return 'bilan'; }catch(e){}
  return 'overdue';
}
// PURE. Le texte pré-rempli.
//
// RÈGLE RGPD DURE : le canal est NON CHIFFRÉ. Aucune donnée de santé n'entre
// ici — ni douleur, ni cycle, ni SOPK, ni thyroïde, ni PES, ni grossesse. Le
// texte ne parle que de PRÉSENCE, et il est construit à partir d'un gabarit
// fixe : il ne recopie jamais _texteSignal, qui, lui, peut nommer une douleur.
function _frTexteRelance(c,now){
  const p=((c&&c.fname)||'').trim();
  const j=_frAnciennete(c,now);
  const nom=p?p:'toi';
  if(j==null) return 'Salut '+nom+", je n'ai pas encore vu de séance de ta part. "
    +"Dis-moi si tu veux qu'on cale ça ensemble.";
  return 'Salut '+nom+", je n'ai pas vu de séance depuis "+j+" jour"+(j>1?'s':'')+'. '
    +"Dis-moi où tu en es, on ajuste si besoin.";
}
// Marquage « relancé ». Écrit UNIQUEMENT dans le dossier du coach, et met le
// signal en veille par le mécanisme EXISTANT — aucun second système.
function frMarquerRelance(coach,c,jours){
  if(!coach||!c) return false;
  if(!coach.relances) coach.relances={};
  coach.relances[c.id]=Date.now();
  if(!coach.journalRelance) coach.journalRelance=[];
  coach.journalRelance.push({at:Date.now(),clientId:c.id});
  if(coach.journalRelance.length>200) coach.journalRelance=coach.journalRelance.slice(-200);
  return true;
}
// PURE. Nombre d'athlètes relancés depuis lundi.
function frRelancesSemaine(coach,now){
  const t=(typeof now==='number')?now:Date.now();
  const d=new Date(t);
  const lundi=new Date(d.getFullYear(),d.getMonth(),d.getDate()-((d.getDay()+6)%7)).getTime();
  const vus=new Set();
  for(const e of ((coach&&coach.journalRelance)||[]))
    if(e&&e.at>=lundi&&e.at<=t) vus.add(e.clientId);
  return vus.size;
}

// ── L'écran de la file ────────────────────────────────────────────────────
// Écran du COACH seul. Il ne modifie jamais le dossier d'un athlète : les
// trois actions écrivent dans le dossier du coach (alertStatus, relances,
// journalRelance) et nulle part ailleurs.
const FR_DUREES=Object.freeze([7,14,30]);
let _frDuree=FR_DUREES[0];
function frSetDuree(j){ _frDuree=Number(j)||FR_DUREES[0]; }

function _frClient(id){
  try{ return getClients().find(c=>c&&c.id===id)||null; }catch(e){ return null; }
}
// (a) RELANCER. RepCore ne connaît pas le numéro de l'athlète : le lien porte
// le TEXTE, le contact se choisit dans WhatsApp. Sur poste fixe, où wa.me et
// sms: n'ouvrent rien d'utile, le texte part dans le presse-papiers.
function frRelancer(id){
  const c=_frClient(id);
  if(!c) return false;
  const texte=_frTexteRelance(c,Date.now());
  try{
    window.open('https://wa.me/?text='+encodeURIComponent(texte),'_blank','noopener');
  }catch(e){}
  frCopier(texte);
  return true;
}
function frCopier(texte){
  const fini=()=>toast('Texte copié : colle-le dans ta conversation.');
  try{
    if(navigator.clipboard&&navigator.clipboard.writeText){
      navigator.clipboard.writeText(texte).then(fini,()=>_frCopieRepli(texte));
      return true;
    }
  }catch(e){}
  return _frCopieRepli(texte);
}
function _frCopieRepli(texte){
  try{
    const z=document.createElement('textarea');
    z.value=texte; z.style.position='fixed'; z.style.left='-9999px';
    document.body.appendChild(z); z.select();
    document.execCommand('copy'); z.remove();
    toast('Texte copié : colle-le dans ta conversation.');
    return true;
  }catch(e){ toast('Copie impossible sur cet appareil.','var(--orange)'); return false; }
}
// (b) MARQUER RELANCÉ : le repère chez le coach, PLUS la mise en veille par le
// mécanisme existant. (c) REPORTER : la mise en veille seule.
function frMarquer(id,avecRelance){
  const c=_frClient(id);
  if(!c) return false;
  let sg=null; try{ sg=signauxEntrainement(c); }catch(e){}
  const type=_frType(c,sg);
  try{ reporterAlerte(type,c,_frDuree); }catch(e){}
  if(avecRelance) frMarquerRelance(currentUser,c,_frDuree);
  toastEcriture(saveUser(),
    avecRelance?('Relance notée · en veille '+_frDuree+' j'):('Reporté de '+_frDuree+' j'),
    'le report est');
  renderFileReprise();
  return true;
}
function renderFileReprise(){
  const el=document.getElementById('cfr-body');
  if(!el) return;
  let ath=[];
  try{ ath=getClients(); }catch(e){
    el.innerHTML='<div class="sub" style="font-size:var(--fs-sm);padding:16px 2px">Impossible de lire ton portefeuille pour l\'instant.</div>';
    return;
  }
  const f=fileReprise(ath,currentUser,Date.now());
  const sem=frRelancesSemaine(currentUser,Date.now());
  const tete=`<div style="display:flex;align-items:center;justify-content:space-between;gap:10px;
      background:var(--surface-1);border:1px solid var(--border);border-radius:var(--r-3);padding:11px 13px;margin-bottom:12px">
      <span style="font-size:var(--fs-xs);color:var(--text-strong);line-height:1.5">Relancés cette semaine</span>
      <span style="font-family:var(--pile-titre);font-size:var(--fs-xl);color:var(--red-text);
        --halo-c:rgba(224,32,32,.6);text-shadow:var(--halo-1)">${sem}</span>
    </div>
    <div style="display:flex;align-items:center;gap:8px;margin-bottom:12px">
      <span style="font-size:var(--fs-2xs);color:var(--sub);letter-spacing:1.2px;font-weight:800;text-transform:uppercase">Mettre en veille</span>
      <select onchange="frSetDuree(this.value)" aria-label="Durée de mise en veille"
        style="min-height:38px;padding:6px 9px;border-radius:var(--r-2);background:#101010;border:1px solid var(--border);
          color:var(--text-strong);font-family:Montserrat,sans-serif;font-size:var(--fs-xs)">
        ${FR_DUREES.map(j=>`<option value="${j}"${j===_frDuree?' selected':''}>${j} jours</option>`).join('')}
      </select>
    </div>`;
  if(!f.lignes.length){
    el.innerHTML=tete+_htmlCalendrierAcces()+`<div style="background:var(--surface-1);border:1px solid var(--border);border-radius:var(--r-3);
      padding:22px 16px;text-align:center;font-size:var(--fs-sm);color:var(--text-dim);line-height:1.6">
      Personne à relancer. Les athlètes en pause déclarée et ceux qui portent un signal de santé n'entrent jamais ici — ils gardent leur ligne dans « Mes notifications ».</div>`;
    return;
  }
  const bouton=(lib,act,fort)=>`<button type="button" onclick="${act}"
    style="flex:1;min-width:0;min-height:44px;padding:8px 6px;border-radius:var(--r-2);cursor:pointer;
      font-family:Montserrat,sans-serif;font-size:var(--fs-2xs);font-weight:800;letter-spacing:.3px;
      background:${fort?'rgba(224,32,32,.14)':'#111'};border:1px solid ${fort?'var(--red)':'var(--border)'};
      color:${fort?'var(--text)':'var(--sub)'}">${escapeHtml(lib)}</button>`;
  el.innerHTML=tete+_htmlCalendrierAcces()+f.lignes.map(r=>`<div style="background:linear-gradient(180deg,#151515,#0e0e0e);
      border:1px solid var(--border);border-left:3px solid var(--red);border-radius:var(--r-3);
      padding:11px 12px;margin-bottom:9px;box-shadow:var(--e2)">
      <div style="display:flex;align-items:baseline;gap:8px">
        <span style="font-size:var(--fs-md);font-weight:900;color:var(--text)">${escapeHtml(r.prenom||'Athlète')}</span>
        <span style="margin-left:auto;font-size:var(--fs-2xs);color:var(--text-faint);flex-shrink:0">${r.jours==null?'aucune séance':r.jours+' j sans séance'}</span>
      </div>
      ${r.signal?`<div style="font-size:var(--fs-xs);color:#bbb;line-height:1.55;margin-top:4px">${escapeHtml(r.signal)}</div>`:''}
      ${r.relanceDepuis!=null?`<div style="font-size:var(--fs-2xs);color:var(--green);margin-top:4px">Relancé il y a ${r.relanceDepuis} j</div>`:''}
      <div style="display:flex;gap:6px;margin-top:9px">
        ${bouton('Relancer',"frRelancer('"+r.id+"')",true)}
        ${bouton('Marquer relancé',"frMarquer('"+r.id+"',true)")}
        ${bouton('Reporter',"frMarquer('"+r.id+"',false)")}
      </div>
    </div>`).join('')
    +(f.reste?`<div class="sub" style="font-size:var(--fs-xs);padding:6px 2px">et ${f.reste} autre${f.reste>1?'s':''} — traite ceux-ci d'abord.</div>`:'')
    +`<div style="font-size:var(--fs-2xs);color:var(--text-faint);line-height:1.6;margin-top:10px">Le message est préparé, pas envoyé : tu choisis le contact et tu relis avant d'appuyer. Il ne contient aucune information de santé — le canal n'est pas chiffré.</div>`;
}
function loadFileReprise(){
  go('s-coach-file');
  renderFileReprise();
}
function _rappelContreIndication(c){
  let ci=[];
  try{ ci=contreIndications(c.bilans); }catch(e){ ci=[]; }
  if(!ci.length) return '';
  return ' Contre-indication au dossier : '+ci.map(x=>x.txt).join(' · ')+'.';
}
function _texteSignal(type,c,sg){
  const d=(sg&&sg.details)||{};
  if(type==='douleur'&&d.douleur){
    const x=d.douleur;
    return 'douleur déclarée '+x.painMax+'/6 sur '+x.nom+', '+x.seances+' séances sur les 3 dernières.'
      +_rappelContreIndication(c);
  }
  if(type==='douleurdiff'&&d.douleurDiffuse){
    const x=d.douleurDiffuse;
    return x.series+' séries douloureuses sur '+x.jours+' jours, '+x.exercices.length
      +' exercice'+(x.exercices.length>1?'s':'')+' concerné'+(x.exercices.length>1?'s':'')+'.'
      +_rappelContreIndication(c);
  }
  if(type==='decrochage'&&d.decrochage){
    const x=d.decrochage;
    return x.faits+' séries réalisées sur '+x.prevus+' prévues sur les '+x.seances+' dernières séances.';
  }
  if(type==='blocfini'&&d.blocPrioriteFini){
    const x=d.blocPrioriteFini;
    const noms=(x.hauts||[]).map(m=>((MUSCLES[m]||{}).lib||m).toLowerCase()).join(' et ');
    // LE RAPPROCHEMENT FERME LA BOUCLE : le volume a bouge, est-ce que le
    // corps a suivi ? Sans mesure, on le DIT — annoncer un bloc « reussi »
    // sans rien pour l'etayer serait une conclusion sans donnee.
    // ⚠ PAS volAffiche ICI : elle arrondit au demi pres, ce qui convient a des
    // SERIES et detruit une mesure — +0,8 cm devenait « +1 cm », soit un
    // quart de plus que ce qui a ete mesure. Un centimetre se dit au dixieme.
    const _cm=v=>String(Math.round(Number(v)*10)/10).replace('.',',');
    const mes=x.mesure
      ? ' Mesures : '+(x.mesure.delta>=0?'+':'')+_cm(x.mesure.delta)+' cm ('
        +x.mesure.lib.toLowerCase()+').'
      : ' Aucune mensuration ne suit ce muscle sur la période.';
    return 'bloc '+(noms||'de priorité')+' terminé ('+x.semaines+' semaines).'+mes
      +' À reconduire, inverser, ou revenir à plat.';
  }
  if(type==='saut_charge'&&d.sautDeCharge){
    const x=d.sautDeCharge;
    // LE CHIFFRE BRUT NE DIT RIEN — « ratio 1,7 » demande de savoir ce qu'est
    // un ratio. La phrase dit le fait : la semaine pese la moitie de plus que
    // le mois.
    return 'la charge de la semaine dépasse de '
      +Math.round((x.ratio-1)*100)+' % la moyenne du mois, deux semaines de suite.';
  }
  if(type==='calibrage'&&d.calibrageDu){
    const x=d.calibrageDu;
    // ON DIT CE QUE CA COUTE DE NE PAS LE FAIRE, pas seulement qu'il est du :
    // « calibrage à refaire » ne dit pas au coach pourquoi il devrait s'en
    // occuper. Le RIR alimente l'e1RM, le plateau et ses propres consignes.
    return x.n===0
      ? 'perception de l\'effort jamais mesurée après '+x.seances+' séances : ce qui est noté série par série sert à estimer ses maximums et à repérer les plateaux, sans avoir jamais été vérifié.'
      : 'dernier calibrage de la perception de l\'effort il y a '+Math.floor(x.jours/30)+' mois. Elle change avec l\'entraînement : le repère mérite d\'être repris.';
  }
  if(type==='entrainement'){
    if(d.restrictionLongue) return 'sèche depuis '+d.restrictionLongue.semaines
      +' semaines à '+d.restrictionLongue.kcal+' kcal, pour un plancher de '
      +d.restrictionLongue.plancher+' kcal. Une pause dans la restriction est à envisager.';
    if(d.plateauMuscle) return d.plateauMuscle.lib.toLowerCase()+' en plateau : '
      +d.plateauMuscle.bloques+' exercices sans nouveau maximum depuis '
      +d.plateauMuscle.semaines+' semaines.';
    if(d.formeBasse) return 'forme déclarée à '+d.formeBasse.moy+'/10, contre '
      +d.formeBasse.base+' habituellement.';
    if(d.sousMEV) return d.sousMEV.lib.toLowerCase()+' sous le volume minimum deux semaines de suite ('
      +volAffiche(d.sousMEV.s1)+' et '+volAffiche(d.sousMEV.s2)+' séries pour un minimum de '
      +volAffiche(d.sousMEV.mev)+').';
    if(d.volumeHaut) return d.volumeHaut.lib.toLowerCase()+' au-dessus du repère haut depuis 2 semaines ('
      +volAffiche(d.volumeHaut.s1)+' et '+volAffiche(d.volumeHaut.s2)+' séries, repère '
      +volAffiche(d.volumeHaut.mrv)+').';
  }
  return '';
}
// ══════════════ AJUSTER DEPUIS L'ALERTE ══════════════
// Corriger l'exercice à l'origine d'un signal sans quitter l'accueil coach.
// AUCUN NOUVEAU CHAMP : ce lot n'écrit que dans sessions_config, par le chemin
// déjà employé par les autres écritures dans le dossier d’un athlète —
// resolveClient, DB.set, CLOUD.pushOne. (Ce commentaire citait removeCoachPdf,
// retirée le 08/09/2026 avec le dépôt de PDF ; le chemin, lui, n’a pas bouge.) Ce
// n'est pas un second chemin d'écriture : saveCoachSessions, lui, lit
// _coachEditClient et finit par un go() qui ferait quitter l'écran.
// N6.6 — 'ajouter_serie' rejoint les deux autres. Elle n'est OFFERTE que
// devant un volume insuffisant : les signaux de douleur, de decrochage et de
// volume eleve gardent exactement leurs deux actions.
// B3.4 — QUATRE GESTES, DONT UN QUI PORTE SUR L'INTENSITE.
//
// Les trois premiers agissent sur le VOLUME ou sur le choix du mouvement. Or
// devant un plateau — le signal qui appelle le plus souvent une reponse
// d'intensite — le seul geste disponible restait « retirer une serie » ou
// « substituer ». Le levier d'intensite venait d'etre cree pour l'editeur, et
// il n'etait branche nulle part sur l'aide a la decision.
const AJ_ACTIONS=Object.freeze(['substituer','retirer_serie','ajouter_serie','durcir_rir']);
// UN CRAN, ET UN SEUL, PAR GESTE. Le coach peut le rejouer ; l'outil ne
// descend pas tout seul un athlete de RIR 3 a RIR 0.
const AJ_RIR_PAS=1;
// LE PLANCHER EST 1, ET NON 0. RIR 0 est l'echec : le proposer comme
// ajustement automatique devant un plateau reviendrait a prescrire l'echec a
// chaque serie, ce qu'aucun coach ne ferait d'un clic.
const AJ_RIR_MIN=1;
// Au-dela, on ne repare plus un manque de volume : on en fabrique un autre.
// Le coach garde la main — il peut rappeler l'action — mais l'outil ne monte
// pas tout seul un exercice a douze series.
const AJ_SERIES_MAX=8;
// PURE. La clé de rapprochement, et la SEULE correcte.
//
// Le nom porté par un signal vient de sessions[n].data — le nom tel qu'il a
// été JOURNALISÉ — et pas de sessions_config. Mesuré : un programme portant
// « DÉVELOPPÉ COUCHÉ BARRE » le lundi et « DEVELOPPE COUCHE BARRE » le jeudi
// produit un signal sur « developpe couche barre ». Les trois chaînes sont
// différentes et les trois exKey sont identiques. Comparer des chaînes ne
// trouverait rien, silencieusement.
function _ajCle(nom){
  const k=exKey(nom||'');
  if(!k) return '';
  try{ return resoudreAlias(k)||k; }catch(e){ return k; }
}
// PURE. L'exercice à l'origine d'un signal, ou null.
//
// DEUX SIGNAUX SUR HUIT PORTENT UN NOM, et c'est une propriété du signal, pas
// une lacune à combler : une séance écourtée, une forme basse ou une sèche
// longue ne désignent aucun mouvement. Pour ceux-là, null est la vérité, et
// la feuille n'offrira que le report.
//
// Le plateau est le cas intermédiaire : details.plateauMuscle ne porte qu'un
// COMPTE d'exercices bloqués, mais _listeEtats — la source AMONT du même
// calcul, déjà mise en cache — porte leurs noms. `user` est donc un troisième
// argument FACULTATIF : sans lui la fonction garde exactement le contrat
// (type, details), avec lui elle sait aussi remonter un plateau.
function exerciceDuSignal(type,details,user){
  const d=details||{};
  if(type==='douleur'&&d.douleur&&d.douleur.nom)
    return {nom:d.douleur.nom,tous:((d.douleurTous||[]).map(x=>x&&x.nom).filter(Boolean))||[]};
  if(type==='douleurdiff'&&d.douleurDiffuse&&(d.douleurDiffuse.exercices||[]).length)
    return {nom:d.douleurDiffuse.exercices[0],tous:d.douleurDiffuse.exercices.slice()};
  // N6.6 — LE VOLUME INSUFFISANT DESIGNE UN EXERCICE. Sans cela, la feuille
  // d'ajustement s'ouvrait sans cible et n'offrait aucune action : le signal
  // se voyait, et rien ne permettait d'y repondre.
  // On vise les exercices dont ce muscle est le PRIMAIRE : ajouter une serie
  // sur un exercice ou il n'est que secondaire ne remonterait presque pas son
  // volume, et gonflerait celui d'un autre.
  if(type==='entrainement'&&!d.plateauMuscle&&d.sousMEV&&user){
    try{
      const m=d.sousMEV.muscle;
      const noms=[];
      for(const sc of ((user.sessions_config)||[])){
        if(!sc||!sc.active||!Array.isArray(sc.exercises)) continue;
        for(const e of sc.exercises){
          if(!e||!e.name||isCardio(e)) continue;
          let cls=null;
          try{ cls=resoudreMusclesLecture(e.name,e,user); }catch(err){ continue; }
          if(!cls||cls===VOL_CARDIO) continue;
          if((cls.p||[]).indexOf(m)>=0&&noms.indexOf(e.name)<0) noms.push(e.name);
        }
      }
      if(noms.length) return {nom:noms[0],tous:noms};
    }catch(e){}
  }
  if(type==='entrainement'&&d.plateauMuscle&&user){
    try{
      const m=d.plateauMuscle.muscle;
      const bloques=_listeEtats(user).filter(x=>x&&(x.etat==='plateau'||x.etat==='regression'));
      const dans=bloques.filter(x=>{
        let cls=null;
        try{ cls=resoudreMusclesLecture(x.nom,{name:x.nom},user); }catch(e){ return false; }
        return cls&&cls!==VOL_CARDIO&&(cls.p||[]).indexOf(m)>=0;
      });
      if(dans.length) return {nom:dans[0].nom,tous:dans.map(x=>x.nom)};
    }catch(e){}
  }
  return null;
}
// PURE. TOUS les créneaux où un exercice apparaît, actifs ou non — un créneau
// désactivé reste un créneau du programme, et l'omettre ferait mentir le choix
// « ce jour / tous les jours ».
function creneauxDeLExercice(sessionsConfig,nom){
  const out=[];
  const cible=_ajCle(nom);
  if(!cible||!Array.isArray(sessionsConfig)) return out;
  sessionsConfig.forEach((sc,slot)=>{
    ((sc&&sc.exercises)||[]).forEach((ex,idxExercice)=>{
      if(ex&&_ajCle(ex.name)===cible)
        out.push({slot,idxExercice,jour:(sc.day||''),nomSeance:(sc.name||''),
          active:!!sc.active,nomEcrit:ex.name||''});
    });
  });
  return out;
}
// PURE. Les substituts, AVEC ceux qui ne conviennent pas.
//
// Un exercice écarté est rendu, marqué compatible:false et motivé — jamais
// retiré en silence. Le coach doit voir que la variante à laquelle il pense a
// été examinée et pourquoi elle est écartée ; une liste amputée le laisserait
// croire qu'elle n'existe pas.
//
// Deux familles, dans cet ordre : les variantes du MÊME schéma moteur, qui
// gardent l'effet d'entraînement, puis — seulement si une contrainte pèse —
// les schémas dont la charge sur la zone est STRICTEMENT plus basse. La
// seconde famille réutilise la grille du coach, elle n'en invente pas une.
function substitutsPour(nom,contraintes){
  const out=[];
  let sch=null;
  try{ sch=schemaDe({name:nom}); }catch(e){ sch=null; }
  const zones=((contraintes||[]).filter(c=>c&&c.zone&&c.actif!==false).map(c=>c.zone));
  // Le verdict d'un schéma face aux zones contraintes. Une charge NON NOTÉE
  // ne déclenche rien : tant que le coach n'a pas jugé, l'app ne juge pas.
  const juger=(s)=>{
    for(const z of zones){
      let ch=null;
      try{ ch=chargeSchema(s,z); }catch(e){ ch=null; }
      if(ch!=null&&ch>=SEUIL_CONTRAINTE_EX)
        return {compatible:false,motif:'sollicite '+libZone(z)+' ('+ch+'/3), zone déclarée sensible'};
    }
    return {compatible:true,motif:''};
  };
  const cible=_ajCle(nom);
  const vus=new Set();
  if(sch){
    const v=juger(sch);
    for(const n of ((SCHEMAS_BRUT[sch]||'').split('~'))){
      if(!n) continue;
      const k=_ajCle(n);
      if(!k||k===cible||vus.has(k)) continue;
      vus.add(k);
      out.push({nom:n,compatible:v.compatible,motif:v.motif,schema:sch,memeSchema:true});
    }
  }
  // Si le schéma d'origine est écarté, on va chercher ailleurs — sinon la
  // liste ne contiendrait que des exercices grisés.
  if(sch&&zones.length&&!juger(sch).compatible){
    for(const s2 in SCHEMAS_META){
      if(s2===sch) continue;
      const v2=juger(s2);
      if(!v2.compatible) continue;
      // Une charge NOTÉE et plus basse : un schéma jamais jugé n'est pas
      // proposé comme refuge, on ne sait pas ce qu'il vaut.
      let connue=false;
      for(const z of zones){ let c2=null; try{ c2=chargeSchema(s2,z); }catch(e){} if(c2!=null) connue=true; }
      if(!connue) continue;
      for(const n of ((SCHEMAS_BRUT[s2]||'').split('~')).slice(0,6)){
        if(!n) continue;
        const k=_ajCle(n);
        if(!k||k===cible||vus.has(k)) continue;
        vus.add(k);
        out.push({nom:n,compatible:true,motif:'',schema:s2,memeSchema:false});
      }
    }
  }
  return out;
}
// ── Ce qui ne survit pas à un remplacement d’exercice ──────────────────────
//
// MUTE SON ENTRÉE, délibérément : les trois appelants tiennent déjà l’objet
// qu’ils veulent modifier, chacun dans son contexte — une copie du programme
// pour le coach, `progEx` pour l’éditeur, `woState.exercises` pour la séance.
//
// UNE SEULE LISTE POUR LES TROIS. Elle n’existait que dans la version coach ;
// les deux versions athlète ne nettoyaient rien, et l’encart CONSIGNE
// réaffichait en séance le matériel, la description, le tempo, la vidéo et la
// bannière de technique du mouvement qu’on venait d’abandonner. Trois copies
// d’une même règle, dont une seule écrite.
//
// CE QUI RESTE, ET POURQUOI :
//   `series`, `reps`, `repos` — la prescription du coach. Le remplacement
//      change le MOUVEMENT, pas le travail demandé.
//   `ss` et le rang — on écrit À LA MÊME POSITION : le chaînage de superset
//      et l’ordre de la séance tiennent tout seuls.
//   `rir` — une consigne d’EFFORT, pas une description du mouvement.
//      « Arrête-toi à deux répétitions de l’échec » garde le même sens sur le
//      mouvement de remplacement, là où quatre-vingts kilos, non.
function _oublierAncienMouvement(ex){
  if(!ex) return ex;
  // L’image base64 ne suit JAMAIS : elle montrerait le mouvement qu’on vient
  // justement de retirer.
  delete ex.image;
  // Tout ce qui DÉCRIVAIT l’ancien mouvement ne décrit plus le nouveau.
  delete ex.description; delete ex.note; delete ex.tempo;
  // Un banc à smith ne sert pas à des fentes haltères, et les deux vidéos
  // montrent encore le geste qu’on vient de retirer.
  delete ex.materiel; delete ex.videoUrl; delete ex.videoUrl2;
  // Quatre-vingts kilos sur un squat ne sont pas quatre-vingts kilos sur une
  // presse : un poids est attaché à un mouvement.
  delete ex.charge; delete ex.poids;
  // ET LA PROGRAMMATION AVEC, pour exactement la même raison — en plus fort.
  // Elle repose sur une charge maximale sur UNE répétition, mesurée sur le
  // mouvement qu'on vient de retirer : la garder ferait suggérer, semaine après
  // semaine, des charges calculées depuis un maximum que l'athlète n'a jamais
  // soulevé sur ce mouvement-là. Un poids faux une fois est une note à
  // corriger ; un maximum faux est une progression entière qui part de travers.
  //
  // ON LE DIT, parce que ce n'est pas une note mais du travail : un 1RM et N
  // semaines de séries, répétitions et RPE. La règle du projet vaut ici — rien
  // ne disparaît en silence. Le geste de remplacement, lui, reste celui du
  // coach : on ne le bloque pas, on l'informe.
  if(ex.prog){
    delete ex.prog;
    try{ toast('La programmation de cet exercice a été retirée : elle reposait sur un maximum mesuré sur l’ancien mouvement.','var(--orange)'); }catch(e){}
  }
  // La technique et les séries qu’elle visait décrivaient l’ancien geste.
  delete ex.methode; delete ex.methodeSeries;
  // Et la justification portait sur une contrainte évaluée pour l’ancien nom.
  delete ex.justificationContrainte;
  return ex;
}
// PURE, NE MUTE PAS SON ENTRÉE. Rend un nouveau sessions_config.
//
// « Seances » et non « appliquerAjustement » tout court : ce dernier nom etait
// deja pris par l ajustement de MACROS nutritionnelles. Deux declarations de
// fonction du meme nom ne produisent aucune erreur — la seconde ecrase la
// premiere en silence, et c est la mienne qui disparaissait.
function appliquerAjustementSeances(sessionsConfig,cibles,action){
  const src=Array.isArray(sessionsConfig)?sessionsConfig:[];
  const out=src.map(sc=>Object.assign({},sc,{
    exercises:((sc&&sc.exercises)||[]).map(x=>Object.assign({},x))}));
  const type=(action||{}).type;
  if(AJ_ACTIONS.indexOf(type)<0) return out;
  for(const c of (cibles||[])){
    if(!c) continue;
    const sc=out[c.slot];
    if(!sc||!Array.isArray(sc.exercises)) continue;
    const ex=sc.exercises[c.idxExercice];
    if(!ex) continue;
    if(type==='retirer_serie'){
      const n=Math.max(0,parseInt(ex.series,10)||0);
      // Jamais zéro : un exercice à zéro série n'est pas un exercice allégé,
      // c'est un exercice supprimé — et ce lot ne supprime rien.
      ex.series=Math.max(1,n-1);
    }else if(type==='ajouter_serie'){
      // N6.6 — LE SYMETRIQUE EXACT du retrait, plafond compris.
      const n=Math.max(0,parseInt(ex.series,10)||0);
      ex.series=Math.min(AJ_SERIES_MAX,n+1);
    }else if(type==='durcir_rir'){
      // B3.4 — ON DESCEND LE RIR : moins de repetitions en reserve, donc plus
      // d'intensite. C'est le sens inverse de l'intuition, et c'est pour cela
      // que le libelle dit « pousser plus fort » et non « -1 RIR ».
      //
      // L'ABSENCE DE CONSIGNE RESTE UNE ABSENCE : un exercice sans RIR
      // prescrit n'en recoit pas un par la bande. Zero signifierait
      // « jusqu'a l'echec », et ce serait le contresens le plus grave.
      const r0=_rirPrescrit(ex);
      if(r0==='') continue;
      const r=Math.max(AJ_RIR_MIN,Number(r0)-AJ_RIR_PAS);
      ex.rir=String(r);
      // rirCible est l'ancien champ, encore lu par _rirPrescrit : le laisser
      // en place ferait gagner l'ancienne valeur sur la nouvelle.
      if(ex.rirCible!=null) ex.rirCible=String(r);
    }else if(type==='substituer'){
      const nv=String((action.nom||'')).trim();
      if(!nv) continue;
      ex.name=nv;
      // LA MÊME LISTE QUE LES DEUX VERSIONS ATHLÈTE. Elle n’était écrite
      // qu’ici, et c’est ce qui a permis aux deux autres de s’en écarter.
      _oublierAncienMouvement(ex);
    }
  }
  return out;
}

// ── La feuille ─────────────────────────────────────────────────────────────
let _ajCtx=null;
// Le bouton n'apparaît QUE sur les lignes de signal d'entraînement : elles
// portent un athlète et sa donnée (list:[c]), là où les lignes administratives
// portent un groupe. Aucune action de masse n'est donc possible — la règle
// « un athlète, un geste » se tient par la structure des lignes.
function _ajBouton(r,idx){
  if(!r||!r.texte||r.type==='drapeau') return '';
  return '<button class="hit44" onclick="event.stopPropagation();ouvrirAjustement('+idx+')"'
    +' title="Ajuster le programme" aria-label="Ajuster le programme"'
    +' style="background:none;border:none;color:var(--sub);font-size:var(--fs-lg);cursor:pointer;'
    +'min-width:44px;min-height:44px;flex-shrink:0;border-radius:var(--r-1)">⚙</button>';
}
function ouvrirAjustement(idx){
  const r=window._todoRows&&window._todoRows[idx];
  if(!r||!r.list||!r.list.length) return false;
  const c=r.list[0];
  let sg=null;
  try{ sg=signauxEntrainement(c); }catch(e){ sg=null; }
  const ex=sg?exerciceDuSignal(r.type,sg.details,c):null;
  _ajCtx={idx,type:r.type,clientId:c.id,exercice:ex,portee:'jour',
    creneaux:ex?creneauxDeLExercice(c.sessions_config,ex.nom):[],
    slotChoisi:null,liste:false};
  if(_ajCtx.creneaux.length) _ajCtx.slotChoisi=_ajCtx.creneaux[0].slot;
  closeModal();
  document.body.insertAdjacentHTML('beforeend',
    '<div id="modal-overlay" onclick="closeModal()" style="position:fixed;inset:0;background:var(--scrim);z-index:var(--z-modal);display:flex;align-items:flex-end;justify-content:center">'
    +'<div onclick="event.stopPropagation()" style="background:var(--dark);border:1px solid var(--border);border-radius:var(--r-4) var(--r-4) 0 0;padding:18px;width:100%;max-width:480px;max-height:88vh;display:flex;flex-direction:column">'
    +'<div id="aj-corps" style="flex:1;overflow:auto;-webkit-overflow-scrolling:touch"></div>'
    +'</div></div>');
  _ajRendre();
  return true;
}
function _ajClient(){
  if(!_ajCtx) return null;
  try{ return getOwnedClient(_ajCtx.clientId); }catch(e){ return null; }
}
function _ajCibles(){
  if(!_ajCtx) return [];
  const l=_ajCtx.creneaux||[];
  if(_ajCtx.portee==='tous') return l;
  return l.filter(x=>x.slot===_ajCtx.slotChoisi);
}
function _ajRendre(){
  const z=document.getElementById('aj-corps');
  if(!z||!_ajCtx) return false;
  const c=_ajClient();
  if(!c){ z.innerHTML='<div style="font-size:var(--fs-sm);color:var(--sub);line-height:1.6">Athlète introuvable.</div>'; return false; }
  const nom=((c.fname||'')+' '+(c.lname||'')).trim()||'Athlète';
  let sg=null; try{ sg=signauxEntrainement(c); }catch(e){}
  const txt=sg?_texteSignal(_ajCtx.type,c,sg):'';
  let h='<div style="font-size:var(--fs-lg);font-weight:800;margin-bottom:3px">'+escapeHtml(nom)+'</div>'
    +'<div style="font-size:var(--fs-xs);color:var(--sub);line-height:1.6;margin-bottom:12px">'+escapeHtml(txt)+'</div>';
  // RÈGLE 1. Sous drapeau rouge, AUCUNE action de programmation. Le produit
  // suspend et renvoie ; il ne prescrit pas par-dessus. La garde est ici et
  // pas seulement dans l'ordre des lignes du tableau de bord : rien ne
  // garantit cet ordre à l'avenir.
  let drap=null; try{ drap=drapeauRougeActif(c); }catch(e){}
  if(drap||(function(){try{return drapeauQuelconqueActif(c);}catch(e){return false;}})()){
    z.innerHTML=h+'<div style="background:var(--warning-bg);border:1px solid var(--warning-border);border-radius:var(--r-3);padding:12px 13px">'
      +'<div style="font-size:var(--fs-sm);color:var(--text);line-height:1.6">Un drapeau est levé sur ce dossier. '
      +'Aucun ajustement de programme n\'est proposé tant qu\'il n\'est pas levé.</div>'
      +blocDisclaimerSante()+'</div>';
    return true;
  }
  const ci=_rappelContreIndication(c);
  if(ci) h+='<div style="font-size:var(--fs-xs);color:var(--orange);line-height:1.6;margin-bottom:12px">'+escapeHtml(ci.trim())+'</div>';
  const ex=_ajCtx.exercice;
  const cr=_ajCtx.creneaux||[];
  if(!ex){
    h+='<div style="font-size:var(--fs-xs);color:var(--sub);line-height:1.6;margin-bottom:12px">'
      +'Ce signal ne désigne aucun exercice en particulier : il porte sur l\'ensemble '
      +'de la semaine. Il n\'y a rien à substituer ici.</div>';
  }else if(!cr.length){
    h+='<div style="font-size:var(--fs-xs);color:var(--sub);line-height:1.6;margin-bottom:12px">'
      +'<b>'+escapeHtml(ex.nom.toLowerCase())+'</b> ne figure plus dans le programme actuel : '
      +'il a été fait, puis retiré ou renommé. Rien à ajuster.</div>';
  }else{
    h+='<div style="font-size:var(--fs-xs);color:var(--sub);line-height:1.6;margin-bottom:6px">Exercice concerné</div>'
      +'<div style="font-size:var(--fs-md);font-weight:800;margin-bottom:8px">'+escapeHtml(ex.nom.toLowerCase())+'</div>';
    // RÈGLE 5 : présent deux jours, le choix est EXPLICITE. Jamais implicite.
    if(cr.length>1){
      h+='<div style="font-size:var(--fs-xs);color:var(--sub);line-height:1.6;margin-bottom:6px">'
        +'Présent sur '+cr.length+' créneaux. Sur lequel agir ?</div>'
        +'<div style="display:flex;gap:6px;flex-wrap:wrap;margin-bottom:12px">'
        +cr.map(x=>'<button onclick="ajPortee(\'jour\','+x.slot+')" class="hit44" style="min-height:44px;'
          +'background:'+((_ajCtx.portee==='jour'&&_ajCtx.slotChoisi===x.slot)?'var(--red)':'var(--surface-1)')+';'
          +'border:1px solid var(--border);border-radius:var(--r-2);padding:8px 11px;font-size:var(--fs-xs);color:var(--text-strong);cursor:pointer">'
          +escapeHtml((x.jour||('créneau '+(x.slot+1)))+(x.active?'':' (inactif)'))+'</button>').join('')
        +'<button onclick="ajPortee(\'tous\',null)" class="hit44" style="min-height:44px;'
        +'background:'+(_ajCtx.portee==='tous'?'var(--red)':'var(--surface-1)')+';'
        +'border:1px solid var(--border);border-radius:var(--r-2);padding:8px 11px;font-size:var(--fs-xs);color:var(--text-strong);cursor:pointer">Tous les jours</button>'
        +'</div>';
    }else{
      h+='<div style="font-size:var(--fs-xs);color:var(--text-faint);line-height:1.6;margin-bottom:12px">'
        +escapeHtml(cr[0].jour||('Créneau '+(cr[0].slot+1)))+(cr[0].active?'':' · créneau inactif')+'</div>';
    }
    h+='<div style="display:flex;gap:6px;flex-wrap:wrap;margin-bottom:10px">'
      +'<button class="btn btn-outline btn-sm" style="flex:1;min-width:120px;margin:0;min-height:44px;letter-spacing:.5px;font-size:var(--fs-2xs)" onclick="ajListeSubstituts()">Substituer</button>'
      +_ajBoutonAjouter(c)
      +_ajBoutonDurcir(c)
      +'<button class="btn btn-outline btn-sm" style="flex:1;min-width:120px;margin:0;min-height:44px;letter-spacing:.5px;font-size:var(--fs-2xs)" onclick="ajRetirerSerie()">Retirer une série</button>'
      +'</div>';
    // « Baisser l'intensité » n'est PAS rendu : aucun champ d'intensité
    // prescrite n'existe sur un exercice de sessions_config. L'action
    // apparaîtra le jour où le champ existera, pas avant.
    if(_ajCtx.liste){
      let subs=[];
      try{ subs=substitutsPour(ex.nom,contraintesActives(c)); }catch(e){ subs=[]; }
      if(!subs.length){
        h+='<div style="font-size:var(--fs-xs);color:var(--sub);line-height:1.6;padding:6px 0">'
          +'Aucun substitut à proposer : le schéma moteur de cet exercice n\'est pas renseigné.</div>';
      }else{
        // Les utilisables d'abord. Sans ce tri, une contrainte qui écarte tout
        // un schéma remplissait la fenêtre de lignes grises et repoussait les
        // seuls exercices cliquables hors de l'écran.
        const ordonnes=subs.slice().sort((a,b)=>(b.compatible?1:0)-(a.compatible?1:0));
        const vus=ordonnes.slice(0,30);
        h+=vus.map(x=>'<button '+(x.compatible?'onclick="ajSubstituer('+JSON.stringify(x.nom).replace(/"/g,'&quot;')+')"':'disabled')
          +' class="hit44" style="display:block;width:100%;text-align:left;min-height:44px;'
          +'background:var(--surface-1);border:1px solid var(--border);border-radius:var(--r-2);padding:9px 12px;'
          +'margin-bottom:6px;font-size:var(--fs-sm);cursor:'+(x.compatible?'pointer':'not-allowed')+';'
          +'color:'+(x.compatible?'var(--text-strong)':'var(--text-faint)')+';opacity:'+(x.compatible?'1':'.55')+'">'
          +escapeHtml(x.nom.toLowerCase())
          // RÈGLE 7 : écarté, GRISÉ, motivé — jamais masqué en silence.
          +(x.compatible?'':'<div style="font-size:var(--fs-2xs);color:var(--orange);line-height:1.5;margin-top:3px">'+escapeHtml(x.motif)+'</div>')
          +'</button>').join('');
        if(ordonnes.length>vus.length)
          h+='<div style="font-size:var(--fs-2xs);color:var(--text-faint);line-height:1.6;padding:2px 0 6px">'
            +(ordonnes.length-vus.length)+' autres mouvements ne sont pas affichés, tous écartés '
            +'pour la même raison.</div>';
      }
    }
  }
  h+='<button class="btn btn-outline btn-sm" style="width:100%;margin:4px 0 0;min-height:44px;letter-spacing:.5px;font-size:var(--fs-2xs)" onclick="ajReporter()">Reporter 7 jours</button>'
    +'<div style="font-size:var(--fs-2xs);color:var(--text-faint);line-height:1.6;margin-top:9px">'
    +'Chaque modification archive le programme précédent : tu peux revenir en arrière depuis la fiche.</div>';
  z.innerHTML=h;
  return true;
}
function ajPortee(mode,slot){
  if(!_ajCtx) return false;
  _ajCtx.portee=(mode==='tous')?'tous':'jour';
  if(mode!=='tous') _ajCtx.slotChoisi=slot;
  _ajRendre();
  return true;
}
function ajListeSubstituts(){ if(!_ajCtx) return false; _ajCtx.liste=true; _ajRendre(); return true; }
// Le seul point d'écriture du lot.
function _ajEcrire(action){
  if(!_ajCtx) return false;
  const res=(function(){ try{ return resolveClient(_ajCtx.clientId); }catch(e){ return null; } })();
  if(!res) return false;
  const c=res.c, users=res.users;
  // La garde de la règle 1 est reposée ICI : entre l'ouverture de la feuille
  // et le clic, un drapeau a pu être levé sur un autre appareil.
  let bloque=false;
  try{ bloque=drapeauQuelconqueActif(c); }catch(e){}
  if(bloque){ toast('Un drapeau est levé : aucun ajustement.','var(--orange)'); return false; }
  const cibles=_ajCibles();
  if(!cibles.length){ toast('Aucun créneau à modifier.','var(--orange)'); return false; }
  // RÈGLE 2 : instantané AVANT modification. Aucune exception.
  _pushSessionsHistory(c);
  c.sessions_config=appliquerAjustementSeances(c.sessions_config,cibles,action);
  c.updatedAt=Date.now();
  users[c.email]=c;
  const ok=DB.set('users',users);
  // RÈGLE 6 : le signal ne s'éteint QUE si l'action a porté sur l'exercice qui
  // l'a déclenché. La douleur vit dans l'HISTORIQUE : changer le programme ne
  // la fera pas disparaître du calcul, et le seul levier d'extinction existant
  // est le report. On le pose donc, mais seulement dans ce cas.
  const vise=_ajCtx.exercice&&_ajCtx.exercice.nom;
  const touche=cibles.some(x=>_ajCle(x.nomEcrit)===_ajCle(vise));
  if(vise&&touche){ try{ reporterAlerte(_ajCtx.type,c); saveUser(); }catch(e){} }
  closeModal();
  _ajCtx=null;
  try{ renderTodoBlock(getClients()); }catch(e){}
  toastSync(ok,CLOUD.pushOne(c.email,c),'Programme ajusté','l\'ajustement est');
  return true;
}
function ajRetirerSerie(){ return _ajEcrire({type:'retirer_serie'}); }
// N6.6 — L'ACTION ADDITIVE, OFFERTE SEULEMENT DEVANT UN VOLUME INSUFFISANT.
// Devant une douleur, un decrochage ou un volume deja eleve, ajouter une serie
// serait exactement le contraire de ce que le signal demande.
function _ajVolumeInsuffisant(c){
  if(!_ajCtx||_ajCtx.type!=='entrainement') return false;
  let sg=null; try{ sg=signauxEntrainement(c); }catch(e){ return false; }
  // Le plateau et la restriction prolongee partagent le type 'entrainement' et
  // ne reclament pas plus de volume : on exige le signal LUI-MEME.
  return !!(sg&&sg.sousMEV&&!sg.volumeHaut&&!sg.plateauMuscle);
}
// B3.4 — QUAND LE SIGNAL APPELLE UNE REPONSE D'INTENSITE, ET LA SEULEMENT.
//
// Un plateau, ou un volume deja haut : dans les deux cas, ajouter du volume
// serait la mauvaise reponse — c'est l'intensite qu'il faut reprendre.
// PAS UNE DOULEUR, PAS UN DECROCHAGE : devant l'une on allege, devant l'autre
// on reprend contact. Durcir y serait au mieux inutile, au pire nuisible.
// Meme forme de garde que _ajVolumeInsuffisant, pour la meme raison.
function _ajIntensiteAReprendre(c){
  if(!_ajCtx||_ajCtx.type!=='entrainement') return false;
  let sg=null; try{ sg=signauxEntrainement(c); }catch(e){ return false; }
  if(!sg) return false;
  if(sg.douleur||sg.decrochage) return false;
  return !!(sg.plateauMuscle||sg.volumeHaut);
}
// ET IL FAUT QU'IL Y AIT UNE CONSIGNE A DURCIR. Proposer le geste sur des
// exercices qui n'en portent aucune afficherait un bouton qui ne fait rien.
function _ajRirPrescritSurCible(c){
  try{
    const cfg=Array.isArray(c&&c.sessions_config)?c.sessions_config:[];
    return _ajCibles().some(x=>{
      const sc=cfg[x.slot];
      const ex=sc&&Array.isArray(sc.exercises)&&sc.exercises[x.idxExercice];
      return !!(ex&&_rirPrescrit(ex)!=='');
    });
  }catch(e){ return false; }
}
function _ajBoutonDurcir(c){
  if(!_ajIntensiteAReprendre(c)||!_ajRirPrescritSurCible(c)) return '';
  // LA DIRECTION EST MOTIVEE A L'ECRAN : le coach doit pouvoir refuser en
  // connaissance de cause, pas deviner ce que le bouton va faire.
  return '<button class="btn btn-outline btn-sm" style="flex:1;min-width:120px;margin:0;min-height:44px;'
    +'letter-spacing:.5px;font-size:var(--fs-2xs)" onclick="ajDurcirRir()" '
    +'title="Une répétition de moins en réserve : plus d’intensité, à volume égal">'
    +'Pousser plus fort</button>';
}
function ajDurcirRir(){
  const c=_ajClient();
  if(!c||!_ajIntensiteAReprendre(c)) return false;
  return _ajEcrire({type:'durcir_rir'});
}
function _ajBoutonAjouter(c){
  if(!_ajVolumeInsuffisant(c)) return '';
  return '<button class="btn btn-outline btn-sm" style="flex:1;min-width:120px;margin:0;min-height:44px;'
    +'letter-spacing:.5px;font-size:var(--fs-2xs)" onclick="ajAjouterSerie()">Ajouter une série</button>';
}
function ajAjouterSerie(){
  const c=_ajClient();
  if(!c||!_ajVolumeInsuffisant(c)) return false;
  return _ajEcrire({type:'ajouter_serie'});
}
function ajSubstituer(nom){ return _ajEcrire({type:'substituer',nom}); }
function ajReporter(){
  const c=_ajClient();
  if(!c||!_ajCtx) return false;
  try{ reporterAlerte(_ajCtx.type,c); saveUser(); }catch(e){ return false; }
  closeModal();
  _ajCtx=null;
  try{ renderTodoBlock(getClients()); }catch(e){}
  toast('Reporté 7 jours');
  return true;
}

// Lignes par athlète, dans l'ordre de priorité. Un athlète n'apparaît qu'une
// fois : son signal le plus grave. Sinon un athlète qui cumule douleur,
// décrochage et plateau occuperait trois des huit lignes à lui seul.
function _lignesEntrainement(clients){
  const out=[], vus=new Set();
  const NIV=[
    {type:'douleur',    cle:'douleur',       icon:icon('activity',16),color:'var(--red)',   lib:'Douleur répétée'},
    {type:'douleurdiff',cle:'douleurDiffuse',icon:icon('activity',16),color:'var(--red)',   lib:'Douleurs diffuses'},
    {type:'decrochage', cle:'decrochage',    icon:icon('trending-down',16),color:'var(--orange)',lib:'Séances écourtées'},
    // LA CHARGE PASSE DEVANT LE PLATEAU. Un plateau se corrige la semaine
    // prochaine ; une charge qui a saute de moitie deux semaines de suite se
    // regarde maintenant.
    {type:'saut_charge', cle:'sautDeCharge',  icon:icon('trending-up',16),color:'var(--orange)',lib:'Charge en hausse marquée'},
    {type:'entrainement',cle:null,           icon:icon('chart-bar',16),color:'var(--orange)',lib:'Progression bloquée'},
    // DERNIER RANG, ET C'EST SA PLACE. `vus` fait que l'athlete deja remonte
    // pour une douleur, un decrochage ou un plateau n'apparait pas ici : on ne
    // parle pas d'entretien a un coach qui a un probleme de sante a traiter.
    // Gris et non orange : rien ne va mal, il manque juste une mesure.
    {type:'calibrage',  cle:'calibrageDu',   icon:icon('target',16),color:'var(--sub)',   lib:'Calibrage de la perception à faire'},
    // ECHEANCE DE BLOC : une decision a prendre, pas une alerte. Dernier rang,
    // gris, et hors d'urgencyScore comme le calibrage — un bloc qui se termine
    // ne remonte personne dans la liste.
    {type:'blocfini',   cle:'blocPrioriteFini',icon:icon('check-circle',16),color:'var(--sub)', lib:'Bloc de priorité terminé'}
  ];
  for(const n of NIV){
    for(const c of clients){
      if(vus.has(c.id)) continue;
      let sg; try{ sg=signauxEntrainement(c); }catch(e){ continue; }
      const actif=n.cle?sg[n.cle]:(sg.plateauMuscle||sg.formeBasse||sg.sousMEV||sg.volumeHaut||sg.restrictionLongue);
      if(!actif) continue;
      if(isAlertSnoozed(n.type,c.id,0,c)) continue;
      const txt=_texteSignal(n.type,c,sg);
      if(!txt) continue;
      vus.add(c.id);
      // Le rang est commun, mais l'intitulé ne peut pas l'être : un volume
      // au-dessus du repère haut n'est pas une progression bloquée. Même
      // précédence que _texteSignal, pour que le titre et la phrase parlent
      // toujours du même signal.
      const lib=n.cle?n.lib
        :(sg.restrictionLongue?'Restriction prolongée'
          :((sg.plateauMuscle||sg.formeBasse||sg.sousMEV)?n.lib:'Volume élevé'));
      out.push({type:n.type,icon:n.icon,color:n.color,label:lib,list:[c],
        texte:txt,sante:ALERTES_SANTE.includes(n.type)});
    }
  }
  return out;
}
// ── Bloc « Douleur » de la fiche client ─────────────────────────────────────
// Trente jours d'historique, par exercice, trié par nombre d'occurrences. La
// donnée existait depuis toujours dans sessions[n].data et ne remontait nulle
// part : elle colorait la ligne pendant la séance, puis disparaissait.
function blocDouleurCoach(c){
  const l=douleurParExercice(c,SIG_DOULEUR_JOURS);
  if(!l.length) return '';
  const dat=t=>t?new Date(t).toLocaleDateString('fr-FR',{day:'2-digit',month:'2-digit'}):'';
  return `<div style="background:var(--surface-1);border:1px solid var(--border);border-radius:var(--r-3);padding:13px;margin-bottom:16px">
    <div style="display:flex;align-items:baseline;justify-content:space-between;gap:8px;margin-bottom:9px">
      <span style="font-size:var(--fs-xs);font-weight:800;letter-spacing:2px;color:var(--sub);text-transform:uppercase">Douleur · 30 jours</span>
      <span style="font-size:var(--fs-2xs);color:var(--text-faint)">niveau 4 et plus</span>
    </div>
    ${l.map(x=>`<div style="display:flex;align-items:baseline;justify-content:space-between;gap:8px;margin-bottom:6px">
      <span style="font-size:var(--fs-xs);font-weight:800;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${escapeHtml(x.nom)}</span>
      <span style="font-size:var(--fs-2xs);color:var(--sub);white-space:nowrap;flex-shrink:0">${x.n} série${x.n>1?'s':''} · max ${x.painMax}/6${_fragmentSiValeur(' · ',dat(x.derniere))}</span>
    </div>`).join('')}
    ${blocDisclaimerDouleur()}
  </div>`;
}
function renderDouleurCoach(c){
  // Le panneau de bloc suit le meme rendu que la douleur : meme ecran, meme
  // instant, et une seule fonction a appeler chez l'appelant.
  try{ renderBlocPriorite(c); }catch(e){}
  const z=document.getElementById('ccd-douleur');
  if(!z) return;
  let html='';
  try{ html=c?blocDouleurCoach(c):''; }catch(e){ html=''; }
  z.innerHTML=html;
}

// ── Carte athlète ───────────────────────────────────────────────────────────
// Symétrie obligatoire : alerter le coach sans rien dire à l'athlète serait
// incohérent. On lui dit ce qu'il a lui-même saisi, on lui dit de ne pas
// forcer, et on lui donne le lien pour joindre son coach. Aucun conseil
// médical, aucune modification de son programme.
// UNE DOULEUR DÉCLARÉE NE DÉBOUCHE PLUS SUR UN RENVOI HORS DE L'APP.
// Le lien pré-remplissait un message WhatsApp décrivant la douleur et
// l'exercice concerné : une donnée de santé partant vers Meta, à l'initiative
// du produit, sans que personne l'ait demandé.
//
// Ce qui reste est ce qui aide : le constat, la consigne de ne pas forcer, le
// bouton pour STRUCTURER la gêne dans l'app, et le disclaimer. Le chemin de
// sécurité existant prime toujours et n'est pas touché.
function blocDouleurAthlete(user){
  let sg; try{ sg=signauxEntrainement(user); }catch(e){ return ''; }
  if(!sg.douleur||!sg.details.douleur) return '';
  const x=sg.details.douleur;
  return `<div style="background:var(--warning-bg);border:1px solid var(--warning-border);border-radius:var(--r-3);padding:13px;margin-bottom:14px">
    <div style="font-size:var(--fs-xs);font-weight:800;letter-spacing:2px;color:var(--warning);text-transform:uppercase;margin-bottom:7px">Douleur signalée</div>
    <div style="font-size:var(--fs-sm);color:var(--text);line-height:1.6">
      Tu as signalé une douleur sur <b>${escapeHtml(x.nom)}</b> lors de tes ${x.seances} dernières séances.
      Ne force pas dessus. Préviens ton coach.
    </div>
    <button class="btn btn-outline btn-sm" onclick="ouvrirFormContrainte('','moi')" style="margin-top:10px;letter-spacing:1px;font-size:var(--fs-2xs)">Préciser où ça fait mal</button>
    ${blocDisclaimerDouleur()}
  </div>`;
}
function renderDouleurAthlete(){
  const z=document.getElementById('clh-douleur');
  if(!z) return;
  let html='';
  try{ html=currentUser?blocDouleurAthlete(currentUser):''; }catch(e){ html=''; }
  z.innerHTML=html;
}

// Trois actions, et pas une de plus : un coach qui vient d'ouvrir son compte
// ne sait pas par où commencer, et une liste de dix liens ne l'aide pas.
//
// L'IMPORT PASSE PAR UN ATHLÈTE, et c'est dit. L'analyse d'une fiche PDF ou
// photo vit dans s-coach-program, l'éditeur du programme D'UN athlète
// (prog-photo2, analyzeProgPhotos) : sans athlète, l'écran n'est pas
// atteignable. Plutôt que d'inventer une quatrième porte, la carte annonce
// l'ordre réel des opérations.
const PREMIERS_PAS=Object.freeze([
  Object.freeze({icone:'👤', titre:'Inviter mon premier athlète',
    detail:'Un code à lui transmettre, et il te rejoint.',
    action:'openAddAthlete()'}),
  Object.freeze({icone:'🗂️', titre:'Créer un programme',
    detail:'Un modèle Homme/Femme, réutilisable pour tous.',
    action:'openCoachPrograms()'}),
  Object.freeze({icone:'📄', titre:'Importer une fiche existante',
    detail:'PDF ou photo. L\'import se fait dans le programme d\'un athlète : commence par en ajouter un.',
    action:'openAddAthlete()'}),
]);
// `clients` est injectable : la suite l'éprouve sans toucher au stockage.
function _renderPremiersPas(clients){
  const z=document.getElementById('ch-premiers-pas');
  if(!z) return false;
  const n=(clients||[]).length;
  // Un seul athlète suffit à faire disparaître le bloc : il a compris.
  if(n>0){ z.innerHTML=''; return false; }
  z.innerHTML='<div style="background:var(--surface-1);border:1px solid var(--border);'
    +'border-radius:var(--r-4);padding:18px;margin-bottom:18px">'
    +'<div style="font-size:var(--fs-xs);color:var(--red-text);letter-spacing:3px;font-weight:800;'
    +'text-transform:uppercase;margin-bottom:6px">Premiers pas</div>'
    +'<div style="font-size:var(--fs-xs);color:var(--sub);line-height:1.6;margin-bottom:14px">'
    +escapeHtml(PROMESSE_COACH)+'</div>'
    +PREMIERS_PAS.map(a=>'<div onclick="'+a.action+'" role="button" tabindex="0" '
      +'onkeydown="if(event.key===\'Enter\'||event.key===\' \'){event.preventDefault();this.click()}" '
      +'style="display:flex;align-items:flex-start;gap:12px;background:var(--surface-2);'
      +'border:1px solid var(--border);border-radius:var(--r-3);padding:13px 14px;margin-bottom:9px;'
      +'cursor:pointer;min-height:44px">'
      +'<div style="font-size:var(--fs-xl);line-height:1.2;flex-shrink:0">'+a.icone+'</div>'
      +'<div style="flex:1;min-width:0">'
      +'<div style="font-weight:800;font-size:var(--fs-md)">'+escapeHtml(a.titre)+'</div>'
      +'<div class="sub" style="font-size:var(--fs-xs);margin-top:3px;line-height:1.5">'+escapeHtml(a.detail)+'</div>'
      +'</div><div style="color:var(--sub);font-size:var(--fs-xl);flex-shrink:0">›</div></div>').join('')
    +'</div>';
  return true;
}
// LA FILE DES BILANS A LIRE. Posée quand le coach entre par la ligne
// « Nouveaux bilans à lire », et par elle seulement : c’est le seul endroit
// qui connaisse la liste complète et son ordre.
//
// Elle porte des IDENTIFIANTS, pas des dossiers : entre deux réponses, les
// dossiers changent — c’est même tout l’objet de l’exercice.
let _fileBilans=[];
// LA FILE DES VIDEOS A CORRIGER. Posée quand le coach clique le compteur de la
// bande C, et par lui seulement.
//
// Chaque entrée porte l’adresse, l’identifiant de la vidéo, ET l’identifiant
// du client : c’est lui qui alimente currentClientId, sans quoi le retour à la
// fiche après la DERNIÈRE vidéo atterrirait sur l’athlète précédemment ouvert
// — ou nulle part.
let _fileVideos=[];
// Entrée par le compteur. Toutes les vidéos non corrigées du portefeuille,
// dans l’ordre des athlètes puis des vidéos.
function _entrerFileVideos(){
  let l=[];
  try{ l=(typeof getClients==='function')?(getClients()||[]):[]; }catch(e){ l=[]; }
  _fileVideos=[];
  for(const c of l){
    if(!c||!c.email) continue;
    for(const v of ((c.videos)||[])){
      try{ if(v&&v.id&&videoNonCorrigee(v)) _fileVideos.push({email:c.email,cid:c.id,id:v.id}); }
      catch(e){}
    }
  }
  if(!_fileVideos.length){ try{ toast('Aucune vidéo en attente'); }catch(e){} return false; }
  return _allerVideoSuivante(_fileVideos[0]);
}
// PURE-ish : elle ne fait que regarder. Les vidéos de la file placées APRÈS
// celle qu’on vient de corriger, et qui sont ENCORE à corriger.
//
// Le filtre par videoNonCorrigee rend le compte honnête, et celui sur coachId
// reprend la garde d’openVideoCorrection : une vidéo dont l’athlète n’est plus
// à moi ne doit pas s’enchaîner.
//
// Une vidéo absente de la file rend un tableau vide : entré par la fiche, le
// coach retrouve le comportement d’avant, une vidéo et puis c’est tout.
function _fileVideosSuivantes(email,videoId){
  const i=_fileVideos.findIndex(x=>x&&x.email===email&&x.id===videoId);
  if(i<0) return [];
  const users=DB.get('users')||{};
  return _fileVideos.slice(i+1).filter(x=>{
    try{
      const c=users[x.email];
      if(!c||c.coachId!==(currentUser&&currentUser.id)) return false;
      const v=(c.videos||[]).find(y=>y&&y.id===x.id);
      return !!(v&&videoNonCorrigee(v));
    }catch(e){ return false; }
  });
}
// Va à la suivante : la fiche de son propriétaire devient la fiche courante,
// pour que le retour après la dernière atterrisse au bon endroit.
function _allerVideoSuivante(x){
  if(!x||!x.email||!x.id) return false;
  if(x.cid) currentClientId=x.cid;
  try{ openVideoCorrection(x.email,x.id); }catch(e){ return false; }
  return true;
}
// Entrée par la ligne du tableau de bord. Fait ce que faisait le clic — ouvrir
// la fiche du premier — et retient les autres au passage.
function _entrerFileBilans(idx){
  const r=(window._todoRows||[])[idx];
  const l=(r&&r.list)||[];
  _fileBilans=l.map(c=>c&&c.id).filter(Boolean);
  if(!_fileBilans.length) return;
  openClientDetail(_fileBilans[0]);
}
// PURE-ish : elle ne fait que regarder. Les athlètes de la file placés APRÈS
// celui qu’on vient de traiter, et qui ont ENCORE un bilan sans réponse.
//
// Le filtre par hasNewBilan rend le compte HONNÊTE : sans lui, « 3 restants »
// pourrait mener sur un athlète auquel on a déjà répondu depuis un autre
// chemin. Et l’athlète courant en sort de lui-même, puisqu’il vient d’être
// répondu — aucun décompte à tenir à la main.
//
// Un athlète absent de la file rend un tableau vide : entré par un autre
// chemin, le coach retrouve exactement le comportement d’avant.
function _fileBilansSuivants(idApres){
  const i=_fileBilans.indexOf(idApres);
  if(i<0) return [];
  return _fileBilans.slice(i+1).filter(id=>{
    try{
      const c=getOwnedClient(id);
      return !!(c&&hasNewBilan(c));
    }catch(e){ return false; }
  });
}
// Va au suivant : exactement le chemin que le coach aurait pris à la main.
// LA RELEVE D'ATHLETE, EN DEUX TEMPS DE 260 ms. _allerBilanSuivant appelle
// viewClientBilans() -> go('s-coach-bilan-evo') ALORS QU'ON Y EST DEJA : go()
// fait display:none puis display:flex dans la meme tache, sans purge de style
// entre les deux, donc l'animation d'ecran ne rejoue pas. Dix bilans a la
// chaine, dix fois le meme ecran qui change de contenu sans que rien ne dise
// « on a tourne la page ».
// Les 110 ms ne retardent rien de perceptible : la reponse est deja enregistree
// quand le bouton est touche, et le rendu du bilan suivant coute deja plus.
function _allerBilanSuivant(id){
  if(!id) return false;
  const _z=document.getElementById('evo-content');
  const _tb=document.querySelector('#s-coach-bilan-evo .topbar');
  if(!arcReduit()&&_z){
    _z.classList.add('cx-sort');
    setTimeout(()=>{ _bilanSuivantCorps(id,_z,_tb); },110);
    return true;
  }
  return _bilanSuivantCorps(id,null,null);
}
function _bilanSuivantCorps(id,_z,_tb){
  currentClientId=id;
  // LE CONTEXTE DE MODELE SUIT L ATHLETE. Il n’est posé que par
  // openClientDetail, et ce chemin-ci ne passe pas par elle : le prénom du
  // PRÉCÉDENT restait en place, un modèle contenant {prénom} le résolvait
  // avec lui, et tplVerifierAvantEnvoi ne bloquait rien — la variable avait
  // bien été remplie, simplement avec la mauvaise valeur.
  //
  // SANS CIBLE, comme openClientDetail et pour la même raison : le prénom
  // vaut pour tous les blocs de réponse de la fiche, il y en a un par bilan.
  try{
    const c=getOwnedClient(id);
    tplContexte({prenom:c&&c.fname},null);
  }catch(e){}
  try{ viewClientBilans(); }catch(e){ return false; }
  if(_z){
    _z.classList.remove('cx-sort');
    _z.classList.add('cx-entre');
    _z.addEventListener('animationend',e=>{ if(e.target===_z) _z.classList.remove('cx-entre'); },{once:true});
  }
  if(_tb){
    _tb.classList.remove('cx-trait');
    void _tb.offsetWidth;
    _tb.classList.add('cx-trait');
    _tb.addEventListener('animationend',e=>{ if(e.target===_tb) _tb.classList.remove('cx-trait'); },{once:true});
  }
  try{ evoTab('reponses'); }catch(e){}
  try{ setTimeout(()=>{ try{ _renderQuickCommentChips('bilan'); }catch(e){} },0); }catch(e){}
  return true;
}
// Pose le bouton en tête du volet « Réponses », là où le coach vient de taper.
// Rend false s’il n’y a pas de volet — le coach a navigué ailleurs entre-temps,
// et l’appelant retombe alors sur le retour à la fiche.
function _proposerBilanSuivant(restants){
  const suivant=restants&&restants[0];
  if(!suivant) return false;
  // Le bilan qu’on vient d’enregistrer doit s’afficher COMME ENREGISTRÉ : on
  // redessine avant de proposer la suite, sinon le coach quitte un écran qui
  // montre encore l’état d’avant.
  try{
    const c=getOwnedClient(currentClientId);
    if(c) renderBilanEvolution(c);
    evoTab('reponses');
    // Le redessin a vidé les conteneurs de chips : sans ça, les autres bilans
    // de cet athlète perdraient leurs commentaires rapides.
    _renderQuickCommentChips('bilan');
  }catch(e){}
  const pane=document.querySelector('#evo-content [data-evo-pane="reponses"]');
  if(!pane) return false;
  const n=restants.length;
  const z=document.createElement('div');
  z.id='file-bilans-suivant';
  z.style.cssText='margin-bottom:12px';
  const b=document.createElement('button');
  b.className='btn btn-red';
  b.style.cssText='width:100%;letter-spacing:1px';
  b.textContent='Athlète suivant → ('+n+' restant'+(n>1?'s':'')+')';
  // L’écouteur est posé en JS et non dans un attribut : l’identifiant ne
  // traverse alors aucune chaîne de balisage, et il n’y a rien à échapper.
  b.onclick=()=>{ _allerBilanSuivant(suivant); };
  z.appendChild(b);
  pane.insertBefore(z,pane.firstChild);
  try{ z.scrollIntoView({block:'nearest'}); }catch(e){}
  return true;
}
function renderTodoBlock(clients){
  _renderPremiersPas(clients);
  const el=document.getElementById('ch-todo');if(!el) return;
  const now=Date.now(),SOON=14*864e5;
  const lt=c=>(c.bilans||[]).reduce((m,b)=>Math.max(m,b.date),0);
  const newBil=clients.filter(c=>hasNewBilan(c)&&!isAlertSnoozed('bilan',c.id,lt(c)));
  const overdue=clients.filter(c=>!c._fromCode&&needsAlert(c)&&!isAlertSnoozed('overdue',c.id));
  const expiring=clients.filter(c=>!c._fromCode&&c.status==='COACHING_SUIVI'&&c.accessExpiry&&(c.accessExpiry-now)>0&&(c.accessExpiry-now)<SOON&&!isAlertSnoozed('expiring',c.id));
  const noProg=clients.filter(c=>!c._fromCode&&!hasProgram(c)&&(c.bilans||[]).some(b=>b.type==='depart')&&!isAlertSnoozed('noprog',c.id));
  const noStart=clients.filter(c=>neverStarted(c)&&!isAlertSnoozed('nostart',c.id));
  // Drapeau rouge d'abord : c'est le seul signal que le coach ne peut pas
  // reporter d'un clic. Une ligne par athlete, avec les signes declares.
  //
  // LES DEUX FAMILLES. Un signe général n’arrivait pas jusqu’ici : l’athlète
  // le déclarait, lisait « Ton coach a été prévenu », et rien ne montait.
  const rows=clients.filter(c=>drapeauQuelconqueActif(c)).map(c=>{
    const d=drapeauQuelconqueActif(c);
    // libelleDrapeau couvre LES DEUX TABLES : chercher dans DRAPEAUX_ROUGES
    // seulement rendait la clef brute — « thoracique » — pour un signe général.
    const lib=d.cases.map(libelleDrapeau);
    // LA ZONE N EST AFFICHÉE QUE QUAND C EN EST UNE. `general` n’est pas une
    // zone du corps, et « Général · une douleur dans la poitrine » nommerait
    // une région qui n’existe pas.
    const _z=(d.zone&&d.zone!==DRAPEAU_ZONE_GENERALE)?(libZone(d.zone)+' · '):'';
    return {type:'drapeau',icon:icon('flag',16),color:'var(--red)',label:'Drapeau rouge santé signalé',
      list:[c],sante:true,nonReportable:true,
      texte:_z+lib.join(' · ')+". Aucun exercice de remplacement n'est proposé."};
  });
  // Puis les signaux d'entrainement : la sante avant l'intendance.
  rows.push.apply(rows,_lignesEntrainement(clients));
  // En tête des lignes administratives : relancer un inscrit qui n'a jamais démarré prime sur tout le reste.
  if(noStart.length) rows.push({type:'nostart',icon:icon('user-plus',16),color:'var(--red)',label:'Inscrit, n\'a jamais commencé',list:noStart});
  if(newBil.length) rows.push({type:'bilan',icon:icon('download',16),color:'var(--orange)',label:'Nouveau'+(newBil.length>1?'x bilans à lire':' bilan à lire'),list:newBil});
  if(overdue.length) rows.push({type:'overdue',icon:icon('alert-triangle',16),color:'var(--red)',label:'Bilan'+(overdue.length>1?'s':'')+' en retard',list:overdue});
  // N6.8 — LES VIDEOS A CORRIGER REMONTENT ICI. La donnee existait,
  // videoNonCorrigee disait deja lesquelles attendent, et agregerPortefeuille
  // les comptait pour le volet « Vue d'ensemble » — un volet ferme a chaque
  // ouverture. Un athlete pouvait deposer une video et attendre une semaine.
  // Entre les bilans et les acces qui expirent : c'est du travail de coach,
  // pas de l'intendance, mais ca ne prime pas sur un bilan en retard.
  const _vids=clients.filter(c=>{
    try{ return (c.videos||[]).some(videoNonCorrigee)&&!isAlertSnoozed('videos',c.id); }
    catch(e){ return false; }
  });
  if(_vids.length) rows.push({type:'videos',icon:icon('video',16),color:'var(--orange)',
    label:'Vidéo'+(_vids.length>1?'s':'')+' à corriger',list:_vids});
  // N6.13 — LES NOTES DONT L'ECHEANCE EST ATTEINTE. Niveau administratif,
  // comme le rite : urgencyScore ne les connait pas et ne les connaitra pas —
  // la ligne se voit, elle ne remonte personne dans le tri.
  // REPORTABLE de sept jours comme les autres lignes de ce niveau, via
  // dismissTodoRow, qui n'ecrit que dans alertStatus du COACH.
  const _notes=clients.filter(c=>{
    try{ return notesEchues(currentUser&&currentUser.coachNotes,c.id).length
      &&!isAlertSnoozed('notes',c.id); }
    catch(e){ return false; }
  });
  if(_notes.length) rows.push({type:'notes',icon:icon('pencil',16),color:'var(--sub)',
    label:'Note'+(_notes.length>1?'s':'')+' à revoir',list:_notes});
  if(expiring.length) rows.push({type:'expiring',icon:icon('clock',16),color:'var(--orange)',label:'Accès expire dans <14j',list:expiring});
  // RITE DE FIN DE CYCLE : niveau administratif. urgencyScore ne le connaît
  // pas et ne le connaîtra pas — la ligne se voit, elle ne remonte personne.
  // Elle se reporte comme les autres, via dismissTodoRow, qui n'écrit que dans
  // alertStatus du COACH : le dossier de l'athlète n'est jamais touché.
  // Relance UNIQUE : si le cycle précédent est déjà resté sans réponse, le
  // suivant ne redemande rien.
  const _rites=clients.filter(c=>{
    if(!c||c._fromCode) return false;
    // SEULS LES RITES PORTEURS D UNE QUESTION. Un cycle clôturé sans question
    // n’attend aucune réponse : l’annoncer « à lire » envoyait le coach vers
    // un écran où il n’y a rien à lire. La règle de relance unique ci-dessous
    // s’applique alors à cette liste-là, celle des rites qui demandent
    // vraiment quelque chose.
    const l=(c.rites||[]).filter(r=>r&&r.date&&String(r.question||'').trim());
    if(!l.length) return false;
    const der=l[l.length-1];
    if(der.reponseCoach) return false;
    const avant=l[l.length-2];
    return !(avant&&!avant.reponseCoach);      // deja relance une fois : plus rien
  });
  if(_rites.length) rows.push({type:'rite',icon:icon('calendar',16),color:'var(--sub)',
    label:'Bilan de 4 semaines à lire',list:_rites});
  if(noProg.length) rows.push({type:'noprog',icon:icon('clipboard',16),color:'var(--sub)',label:'Sans programme',list:noProg});
  if(!rows.length){ window._todoRows=[]; el.innerHTML=''; return; }
  // Un tableau de bord qui affiche trente alertes n'oriente plus rien. Les
  // lignes sont deja triees par gravite : on coupe la queue et on l'annonce.
  const restant=Math.max(0,rows.length-TODO_MAX_LIGNES);
  const vues=rows.slice(0,TODO_MAX_LIGNES);
  window._todoRows=vues;
  const unique=new Set(rows.flatMap(r=>r.list.map(c=>c.id))).size;
  // Le disclaimer est rendu des qu'une ligne de douleur est visible, et il
  // vient de la constante unique partagee avec les deux autres affichages.
  const aDouleur=vues.some(r=>r.sante&&r.type!=='drapeau');
  // Un drapeau rouge n'a rien a voir avec l'echelle de douleur de 1 a 6 : le
  // disclaimer qui convient est celui des contraintes de sante.
  const aDrapeau=vues.some(r=>r.type==='drapeau');
  // ══ TROIS BANDES, PAS UNE PILE ═══════════════════════════════════════════
  //
  // Huit lignes d'affilée ne se lisent pas : le coach cherche d'abord ce qui
  // ne peut pas attendre, et il devait pour cela relire la couleur de chaque
  // intitulé. La couleur portait déjà le niveau — elle ne faisait que le
  // colorier. Elle RANGE maintenant.
  //
  // ⚠ LE TRI ET LE PLAFOND NE BOUGENT PAS. `rows` reste ordonné par gravité,
  //   `vues` reste les huit premières, et `window._todoRows` reste `vues` :
  //   c'est l'index dans CE tableau que dismissTodoRow, ouvrirAjustement et
  //   _entrerFileBilans reçoivent. On range à l'affichage, on ne renumérote
  //   rien.
  const BANDES=[
    {titre:'Urgent',    couleur:'var(--red)',    test:(/** @type {any} */ r)=>r.color==='var(--red)'},
    {titre:'Important', couleur:'var(--orange)', test:(/** @type {any} */ r)=>r.color==='var(--orange)'},
    // VERT, ET NON GRIS — demande de Kévin, 19/09/2026. Ces lignes ne sont pas
    // des alertes éteintes : ce sont des décisions à prendre — un calibrage,
    // un bloc terminé, une note à revoir. Le gris les faisait lire comme du
    // bruit de fond, et elles restaient au fond du bloc pour toujours.
    {titre:'À traiter', couleur:'var(--green)',  test:()=>true}
  ];
  const _bande=(/** @type {any} */ r)=>BANDES.findIndex(b=>b.test(r));
  // LE COMPTE D'UNE BANDE VIENT DE TOUTES LES LIGNES, pas des seules affichées.
  // Le plafond de huit coupe la queue, donc la bande verte en premier : sans
  // ce total, une colonne vidée par le plafond dirait « Rien » alors qu'il
  // reste du travail dedans.
  const _cols=BANDES.map((b,i)=>({...b,
    total:rows.filter(r=>_bande(r)===i).length,
    // On garde l'index d'origine avec la ligne : la colonne n'est qu'une vue.
    lignes:vues.map((r,idx)=>({r,idx})).filter(x=>_bande(x.r)===i)}));
  el.innerHTML=`<div style="background:#0c0000;border:1px solid #2a0000;border-left:3px solid var(--red);border-radius:var(--r-card);margin-bottom:20px;overflow:hidden;box-shadow:var(--elev-3)">
    <div style="padding:9px 14px;display:flex;align-items:center;justify-content:space-between;background:#0f0000;border-bottom:1px solid #1e0000">
      <span style="font-size:13px;font-weight:800;color:var(--red-text);text-transform:uppercase;letter-spacing:2.4px">Mes notifications</span>
      <span style="background:var(--red);color:var(--text);font-size:14px;font-weight:400;padding:1px 9px;border-radius:var(--r-3);font-family:var(--pile-titre);letter-spacing:1px">${unique}</span>
    </div>
    <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(272px,1fr));gap:10px;padding:10px">
    ${_cols.map(b=>`<div style="min-width:0;background:#0a0000;border:1px solid #1e0000;border-radius:0;overflow:hidden">
      <div style="padding:7px 11px;display:flex;align-items:center;justify-content:space-between;gap:8px;background:${b.couleur}">
        <!-- LE TEXTE EST PRESQUE NOIR SUR LE BANDEAU PLEIN, et non blanc : sur
             l'orange et sur le vert, du blanc tombe sous trois pour un de
             contraste et ne se lit plus au soleil d'une salle. Le noir tient
             les trois — 4,8 sur le rouge, 7,2 sur l'orange, 8,7 sur le vert. -->
        <span style="font-size:var(--fs-2xs);font-weight:800;color:#0a0000;text-transform:uppercase;letter-spacing:1.8px">${b.titre}</span>
        <span style="font-size:var(--fs-2xs);font-weight:800;color:#0a0000;opacity:.72">${b.total}</span>
      </div>
      ${b.lignes.length?renderDataList(b.lignes,(x)=>{
      const r=x.r, idx=x.idx, coul=b.couleur;
      // XSS stocké : le prénom est saisi par l'athlète lui-même et atterrissait
      // brut dans le tableau de bord de son coach. Trouvé en testant les liens
      // WhatsApp avec un prénom hostile — le défaut est antérieur.
      const names=r.list.slice(0,2).map(c=>escapeHtml(c.fname||'')).join(', ')+(r.list.length>2?' +'+(r.list.length-2):'');
      // Ligne d'entrainement : elle porte un nom d'athlete et SA donnee, pas
      // un groupe. Le corps differe donc de celui des lignes administratives,
      // qui restent rendues exactement comme avant.
      const _n0=r.list[0]||{};
      const _ini=(_n0.lname||'').charAt(0);
      const nomA=escapeHtml(((_n0.fname||'')+(_ini?' '+_ini+'.':'')).trim()||'Athlète');
      const corps=r.texte
        ? `<div style="flex:1;min-width:0"><span style="font-size:var(--fs-sm);font-weight:800;color:var(--text)">${nomA}</span><span style="font-size:var(--fs-sm);font-weight:700;color:${coul}"> · ${r.label}</span><div style="font-size:var(--fs-xs);color:var(--sub);line-height:1.5;margin-top:2px">${escapeHtml(r.texte)}</div></div>`
        : `<div style="flex:1;min-width:0"><span style="font-size:var(--fs-sm);font-weight:700;color:var(--text)">${r.list.length>1?r.list.length+' ':''}</span><span style="font-size:var(--fs-sm);font-weight:700;color:${coul}">${r.label}</span><span style="font-size:var(--fs-xs);color:var(--sub)"> · ${names}</span></div>`;
      // L'ICÔNE EST BLANCHE ET ELLE RAYONNE, quelle que soit la bande : la
      // couleur est déjà portée par la colonne et par l'intitulé. Une icône
      // colorée de plus ferait trois rouges côte à côte et plus rien ne
      // ressortirait. Deux halos, un serré et un large : c'est ce qui fait le
      // néon plutôt qu'un simple trait clair.
      return{html:`<span style="flex-shrink:0;align-self:flex-start;margin-top:2px;display:inline-flex;color:#fff;filter:drop-shadow(0 0 4px rgba(255,255,255,.7)) drop-shadow(0 0 11px rgba(255,255,255,.3))">${r.icon}</span>${corps}${_ajBouton(r,idx)}${_waBoutonTodo(r,idx)}${r.nonReportable?'':`<button onclick="event.stopPropagation();dismissTodoRow(${idx})" title="Snoozer 7 jours" style="background:none;border:none;color:var(--text-dim);font-size:var(--fs-lg);cursor:pointer;padding:4px 8px;flex-shrink:0;transition:color var(--t-1);border-radius:var(--r-1)" onmouseover="this.style.color='var(--sub)'" onmouseout="this.style.color='#444'">✕</button>`}`,
      // LA LIGNE DES BILANS POSE LA FILE au passage. Les autres lignes ouvrent
      // la fiche comme avant : elles ne décrivent pas une série à traiter.
      onClick:r.type==='bilan'?`_entrerFileBilans(${idx})`
        // La file de correction des videos est deja ecrite : la ligne y entre,
        // elle n'ouvre pas une fiche que le coach devrait ensuite fouiller.
        :r.type==='videos'?`_entrerFileVideos()`
        :r.type==='rite'?`_ouvrirRiteClient('${r.list[0].id}')`
        :`openClientDetail('${r.list[0].id}')`,
      style:'cursor:pointer;transition:background var(--t-1);'};
    },{pad:'9px 11px',gap:9,border:'#180000',hover:'#140000'})
      // UNE COLONNE VIDE LE DIT, et dit laquelle des deux raisons : il n'y a
      // rien à ce niveau, ou le plafond de huit lignes a coupé ici.
      :`<div style="padding:10px 11px;font-size:var(--fs-xs);color:var(--text-faint)">${b.total?'+ '+b.total+' plus bas':'Rien ici'}</div>`}
    </div>`).join('')}
    </div>
    ${restant?`<div style="padding:8px 14px;font-size:var(--fs-xs);color:var(--sub);border-top:1px solid #180000">+ ${restant} autre${restant>1?'s':''}</div>`:''}
    ${aDrapeau?`<div style="padding:8px 14px;border-top:1px solid #180000">${blocDisclaimerSante()}</div>`:''}
    ${aDouleur?`<div style="padding:8px 14px;border-top:1px solid #180000">${blocDisclaimerDouleur()}</div>`:''}
  </div>`;
}
// status 'FREE' = aucun accès : l'athlète se heurte au paywall à chaque
// ouverture. Le badge d'activité seul affichait « Inactif », ce qui se lisait
// comme un manque d'assiduité alors que l'élève ne peut tout simplement pas
// entrer. Le coach doit savoir ce qu'il reste à faire.
// ⚠ PAS PENDANT L'ESSAI. Le commentaire ci-dessus dit la raison d'etre de ce
// signal : « l'eleve ne peut tout simplement pas entrer ». Pendant ses trois
// seances libres, il entre — et afficher au coach qu'il est bloque serait lui
// faire relancer quelqu'un qui est en train de s'entrainer.
function _enAttenteAbonnement(c){
  return !c._fromCode&&c.status==='FREE'&&!essaiActif(c);
}
// R-03 : accès expiré = LECTURE SEULE, jamais suppression. Le dossier, les
// séances, les bilans et l'historique restent intacts et consultables par le
// coach ; c'est l'athlète qui ne peut plus entrer tant qu'un nouveau code ne
// lui a pas été donné. Rien ici n'efface quoi que ce soit — et un test le
// vérifie, parce qu'une suppression est irréversible et qu'un jour quelqu'un
// trouvera plus simple de « nettoyer ».
//
// PURE, et distincte de _enAttenteAbonnement : un athlète FREE n'a jamais eu
// d'accès, un athlète expiré en a eu un. Les deux méritent des mots
// différents sur la fiche.
function _accesExpire(c){
  if(!c||c._fromCode||c.role==='coach') return false;
  if((c.status||'FREE')!=='COACHING_SUIVI') return false;
  return !!c.accessExpiry&&Date.now()>=c.accessExpiry;
}
// ── Les trois mesures de la liste ────────────────────────────────────────
//
// PURES. Chacune rend '' quand il n'y a rien à dire : _chargeHebdo demande
// cinq semaines d’historique, _exercicesEnProgres un couple comparable, et un
// athlète sans bilan en attente n’a rien à afficher. Un « 0 » ou un « — » se
// lirait comme un constat, alors que c’est une absence de mesure.
// N6.5 — LE RAPPORT AIGU / CHRONIQUE RECOIT ENFIN UNE LECTURE.
// Le pourcentage etait calcule, affiche a la ligne d'athlete et a la fiche, et
// jamais interprete : le coach lisait « +38 % » sans savoir si c'etait normal.
//
// LES DEUX BANDES, EN UN SEUL ENDROIT. Au-dela de +30 %, la charge de la
// semaine depasse d'un tiers la moyenne des quatre precedentes : c'est le seuil
// au-dela duquel la litterature sur le rapport charge aigue / charge chronique
// situe l'augmentation du risque de blessure. En dessous de -30 %, la semaine
// est un creux — decharge voulue, ou semaine manquee, et le coach doit savoir
// laquelle. Entre les deux, rien ne se dit : une variation ordinaire n'a pas
// besoin d'etre commentee.
//
// PAS DE QUATRIEME TEINTE SUR LA LIGNE. Le filet gauche porte deja l'etat de
// l'athlete ; la lecture se fait par un MOT, a cote du chiffre, qui reste
// ecrit. Ajouter une couleur affaiblirait le filet — voir le commentaire de
// _etatAthlete.
const CHARGE_BANDE=30;   // % d'ecart a la moyenne des 4 semaines precedentes
// B3.6 — LA DERIVE DU RIR, EN UN MOT.
//
// La carte affichait « 2,1 · ▼ 0,4 sur les 4 precedentes » : le coach lisait
// une fleche sans savoir si elle etait bonne. Un RIR qui baisse peut etre une
// montee d'intensite VOULUE ou une fatigue qui s'installe — et c'est le
// croisement avec le volume qui tranche. Le rapport aigu/chronique a recu ce
// traitement ; la derive du RIR ne l'avait pas recu.
//
// LE SEUIL EST UN DEMI-POINT DE RIR. En deca, sur quatre seances, l'ecart
// tient a la facon dont l'athlete a estime ses series ce jour-la : ce n'est pas
// une derive, c'est du bruit. Le silence est donc le comportement par defaut —
// une variation ordinaire ne se commente pas.
const RIR_DERIVE_BANDE=0.5;
// PURE. `d` est la derive du RIR (positive = plus facile), `dVol` la variation
// de volume sur la meme fenetre, en pourcentage, ou null si on ne la connait
// pas. Rend '' quand il n'y a rien a dire.
function lectureDeriveRir(d,dVol){
  if(d==null||!isFinite(d)) return '';
  if(Math.abs(d)<RIR_DERIVE_BANDE) return '';
  // UN RIR QUI BAISSE = ON POUSSE PLUS FORT. Reste a savoir si c'est voulu.
  if(d<0){
    // Le volume monte AUSSI : les deux leviers montent ensemble, et c'est la
    // definition d'une surcharge. On le dit, prudemment.
    if(dVol!=null&&isFinite(dVol)&&dVol>=CHARGE_BANDE) return 'surcharge';
    return 'intensification';
  }
  // UN RIR QUI MONTE = on pousse moins. Avec un volume qui baisse aussi, c'est
  // un relachement ; sinon, un affaissement de l'intensite seule.
  if(dVol!=null&&isFinite(dVol)&&dVol<=-CHARGE_BANDE) return 'allègement';
  return 'affaissement';
}
function lectureChargeHebdo(pct){
  if(pct==null||!isFinite(pct)) return '';
  if(pct>=CHARGE_BANDE) return 'pic';
  if(pct<=-CHARGE_BANDE) return 'creux';
  return '';
}
function _crCharge(c){
  let r=null; try{ r=_chargeHebdo(c); }catch(e){ r=null; }
  // `pct` peut être null alors que l’objet existe : moyenne de référence à
  // zéro, aucun pourcentage n’a alors de sens.
  if(!r||r.pct==null) return '';
  // La colonne du tableau est etroite : le mot y tient en abrege, et le
  // chiffre reste ecrit a cote — c'est lui qu'on compare d'une ligne a l'autre.
  const l=lectureChargeHebdo(r.pct);
  return (r.pct>0?'+':'')+r.pct+' %'+(l?' · '+l:'');
}
function _crProgres(c){
  let r=null; try{ r=_exercicesEnProgres(c); }catch(e){ r=null; }
  if(!r) return '';
  return r.enProgres+'/'+r.total;
}
function _crBilans(c){
  let n=0; try{ n=bilansSansReponse(c); }catch(e){ n=0; }
  return n>0?String(n):'';
}
// N6.4 — L'ASSIDUITE. tauxCompletion rend deja un objet qui dit s'il est
// interpretable : sans programme, en reprise, sous suspension, il ne l'est pas
// et tauxCompletionLib rend « — ». On prefere le VIDE au tiret : dans une
// colonne de tableau, un tiret par ligne fait une colonne de tirets.
function _crAssidu(c){
  let r=null; try{ r=tauxCompletion(c); }catch(e){ r=null; }
  if(!r||!r.interpretable||r.taux==null) return '';
  return r.taux+' %';
}
// N6.4 — LE POIDS. vitesseHebdo rend des kilos par semaine, ou null tant qu'il
// n'y a pas deux semaines de recul depuis la derniere reprise. Le signe est
// ECRIT : « 0,3 » sans signe se lit comme une prise autant que comme une perte.
function _crPoids(c){
  // vitesseHebdo rend un OBJET — {kgSem, pctSem, points, regime} — et non un
  // nombre : c'est `kgSem` qu'on affiche, la meme grandeur que la fiche.
  let r=null;
  try{ r=vitesseHebdo(serieWeight(c)); }catch(e){ r=null; }
  const v=r?r.kgSem:null;
  if(v==null||!isFinite(v)) return '';
  const n=Math.round(v*10)/10;
  // « kg » ET NON « kg/sem » : la colonne fait 74 px, et l'intitule dit deja
  // qu'il s'agit d'une vitesse. Le titre du survol porte la phrase entiere.
  return (n>0?'+':(n<0?'−':''))+String(Math.abs(n)).replace('.',',')+' kg';
}
// N6.4 — LA DIETE. _tauxDieteRespectee rend null quand aucun jour n'a pu etre
// juge — pas de cible, pas de journal — et c'est un silence, pas un zero.
function _crDiete(c){
  let r=null; try{ r=_tauxDieteRespectee(c); }catch(e){ r=null; }
  if(!r||r.pct==null) return '';
  return r.pct+' %';
}
// LES NON MESURABLES EN FIN DE LISTE. Un sentinelle très négative et non -1 :
// une charge peut légitimement valoir -20 %, et -1 la placerait AU-DESSUS
// d’un athlète dont on ne sait rien. Pas -Infinity non plus — la soustraction
// de deux infinis rend NaN, et un comparateur qui rend NaN désordonne la
// liste au lieu de la trier.
const TRI_SANS_MESURE=-1e9;
function _triCharge(c){
  let r=null; try{ r=_chargeHebdo(c); }catch(e){}
  return (r&&r.pct!=null)?r.pct:TRI_SANS_MESURE;
}
function _triProgres(c){
  let r=null; try{ r=_exercicesEnProgres(c); }catch(e){}
  return (r&&r.total>0)?(r.enProgres/r.total):TRI_SANS_MESURE;
}
// L ETAT D UN ATHLETE, EN UN SEUL ENDROIT. Trois ecrans le lisent maintenant :
// la liste du portefeuille, l assignation de programme et la decharge groupee.
// Le duplique aurait suffi a ce que deux ecrans finissent par se contredire.
//
// L ORDRE EST CELUI DU BADGE, cas par cas : abonnement a souscrire, puis
// lecture seule, puis nouveau bilan, puis alerte, puis actif. Un ordre
// different donnerait un badge orange sur un filet rouge — deux signaux
// contradictoires, et le plus visible serait le faux.
function etatAthlete(c){
  return _enAttenteAbonnement(c)?'attente'
    :_accesExpire(c)?'lecture'
    :hasNewBilan(c)?'bilan'
    :needsAlert(c)?'alerte'
    :isActive(c)?'actif':'dormant';
}
// La couleur du filet, par etat. Meme table pour les trois ecrans.
const ETAT_FILET=Object.freeze({alerte:'#E02020',bilan:'#f97316',attente:'#f97316',
  actif:'#22c55e',lecture:'#8a8a8a',dormant:'#666666'});
// ══════ N4.13 — COCHER DES ATHLETES SANS QUITTER LA LISTE ═════════════════
// Les cases a cocher existaient, mais sur deux ecrans separes et mono-usage :
// l'un pour assigner un programme, l'autre pour la decharge groupee. Toute
// action en lot demandait donc de quitter la liste, d'aller sur un ecran
// special et de re-selectionner — deux navigations par action, et une seule
// action par ecran.
//
// LA SELECTION VIT HORS DU CONTENEUR REECRIT. #ch-clients-list est reecrit
// toutes les trente secondes par la boucle de synchro : c'est exactement pour
// cela que la recherche et les filtres sont places au-dessus de lui. Meme
// discipline ici — la selection est un Set en memoire, et chaque ligne rendue
// y relit son etat. Cocher puis attendre une minute ne perd rien.
//
// ON NE REECRIT PAS LES ACTIONS GROUPEES : elles existent, elles sont
// eprouvees, et elles ont leur ecran. La barre les OUVRE avec la selection
// deja cochee — ce qui etait la seule chose qui manquait.
const SEL_ATHLETES=new Set();
function selAthleteBascule(id,ev){
  // La ligne entiere ouvre la fiche : sans ce coup d'arret, cocher ouvrirait
  // l'athlete qu'on voulait seulement designer.
  if(ev&&ev.stopPropagation) ev.stopPropagation();
  if(SEL_ATHLETES.has(id)) SEL_ATHLETES.delete(id);
  else SEL_ATHLETES.add(id);
  _selMaj();
  return true;
}
function selAthleteVider(){
  SEL_ATHLETES.clear();
  try{ renderClientList(); }catch(e){ _selMaj(); }
  return true;
}
// Les identifiants d'athletes qui ne sont PLUS dans la liste sortent : un
// athlete libere ou supprime ne doit pas continuer a compter dans la barre.
function _selElaguer(vus){
  if(!Array.isArray(vus)) return;
  const presents=new Set(vus.map(c=>c&&c.id).filter(Boolean));
  for(const id of Array.from(SEL_ATHLETES)) if(!presents.has(id)) SEL_ATHLETES.delete(id);
}
function _selMaj(){
  const z=document.getElementById('ch-selection');
  if(!z) return;
  const n=SEL_ATHLETES.size;
  // ELLE N'APPARAIT QUE COCHEE : une barre d'actions permanente sur un
  // tableau de bord deja dense serait un bandeau de plus a lire.
  if(!n){ z.innerHTML=''; z.style.display='none'; return; }
  z.style.display='';
  z.innerHTML='<div style="display:flex;align-items:center;gap:8px;flex-wrap:wrap;'
    +'padding:9px 11px;background:var(--surface-1);border:1px solid var(--red);'
    +'border-radius:var(--r-3)">'
    +'<span style="font-size:var(--fs-xs);font-weight:800;color:var(--text-strong);letter-spacing:.4px">'
    +n+' athlète'+(n>1?'s':'')+' sélectionné'+(n>1?'s':'')+'</span>'
    +'<div style="flex:1"></div>'
    +'<button class="btn btn-outline btn-sm" style="margin:0;letter-spacing:1px;font-size:var(--fs-2xs)" onclick="selVersDecharge()">Décharge</button>'
    +'<button class="btn btn-outline btn-sm" style="margin:0;letter-spacing:1px;font-size:var(--fs-2xs)" onclick="selVersProgramme()">Programme</button>'
    +'<button type="button" onclick="selAthleteVider()" title="Tout décocher" style="background:none;border:none;color:var(--sub);font-family:inherit;font-size:var(--fs-xs);cursor:pointer;padding:4px 6px;min-height:30px">✕</button>'
    +'</div>';
}
// Les cases de l'ecran de destination sont cochees APRES son rendu : c'est lui
// qui les fabrique, et il les fabrique toutes decochees.
function _selCocherSur(conteneur){
  let n=0;
  try{
    document.querySelectorAll('#'+conteneur+' input[type=checkbox]').forEach(cb=>{
      const veut=SEL_ATHLETES.has(cb.value);
      cb.checked=veut;
      if(veut) n++;
    });
  }catch(e){}
  return n;
}
function selVersDecharge(){
  if(!SEL_ATHLETES.size) return false;
  openDechargeGroupee();
  setTimeout(()=>{ _selCocherSur('cdg-athletes'); try{ _cdgMajBouton(); }catch(e){} },0);
  return true;
}
function selVersProgramme(){
  if(!SEL_ATHLETES.size) return false;
  const progs=(currentUser&&currentUser.coachPrograms)||[];
  if(!progs.length){
    toast('Tu n’as encore aucun programme à assigner.','var(--orange)');
    return false;
  }
  // L'ecran d'assignation demande QUEL programme : on ouvre la liste des
  // programmes, ou le coach choisit, et la selection l'attend a l'arrivee.
  openCoachPrograms();
  toast(SEL_ATHLETES.size+' athlète'+(SEL_ATHLETES.size>1?'s':'')
    +' en attente : choisis le programme à leur assigner.','var(--info)');
  return true;
}
// ══ AVEC SUIVI / SANS SUIVI ════════════════════════════════════════════
// Un portefeuille melange deux populations qui ne se pilotent pas pareil :
// ceux que le coach suit vraiment, et ceux qui ont un acces sans
// accompagnement. Les memes alertes pour les deux noient les premieres.
//
// LE DEFAUT EST « AVEC SUIVI », et c'est deliberé : un dossier existant n'a
// pas ce champ, et rien ne doit changer pour lui tant que le coach n'a rien
// dit. C'est LUI qui bascule, athlete par athlete — aucune deduction
// automatique, aucune surprise.
function estSuivi(c){ return !!c && c.suivi!==false; }
// ══ LE TRI ATTEND QUE LE DOIGT AIT FINI ═════════════════════════════════════
//
// ⚠ LA PANNE QUE CECI CORRIGE, et elle ne ressemblait pas a ce qu'elle etait.
//   Kevin : « le bouton on/off de suivi n'est pas tout le temps cliquable ».
//   Le clic partait toujours. C'est la SUITE qui trompait : basculer un
//   athlete le fait changer de section, la liste se repeignait aussitot, et il
//   descendait de trois rangs. Mesure sur douze athletes — a3 bascule, passe
//   du rang 3 au rang 6, et sous le point exact ou l'on venait de cliquer se
//   trouvait desormais le curseur de a4. Un second clic au meme endroit
//   basculait a4 : de la chaise du coach, le premier clic « n'avait rien
//   fait » et un autre athlete changeait tout seul.
//
// LE TRI EST DONC DIFFERE. La bascule ecrit tout de suite — donnee, nuage,
// message — et le curseur bascule sous le doigt, comme une case a cocher
// ordinaire. Le reordonnancement, lui, attend que plus rien ne se touche. Le
// coach qui fait passer cinq athletes d'un coup les touche tous les cinq, et
// la liste se range UNE fois, quand il a fini.
//
// UNE SECONDE ET DEMIE : au-dela, le desordre dure assez pour qu'on s'y perde ;
// en-deca, on retombe dans le saut sous le doigt.
const SUIVI_REORDRE_MS=1500;
let _suiviReordre=0;
/**
 * Range la liste, une fois que la salve de bascules est finie. Chaque appel
 * repousse l'echeance : c'est ce qui rend la salve possible.
 */
function _suiviRangerPlusTard(){
  try{ clearTimeout(_suiviReordre); }catch(e){}
  _suiviReordre=setTimeout(()=>{ try{ renderClientList(); }catch(e){} },SUIVI_REORDRE_MS);
}
function coachBasculerSuivi(id,ev){
  if(ev&&ev.stopPropagation) ev.stopPropagation();
  const users=DB.get('users')||{};
  const c=getOwnedClient(id,users);
  if(!c) return;
  c.suivi=!estSuivi(c);
  if(c.email) users[c.email]=c;
  const ok=DB.set('users',users);
  const envoi=CLOUD.pushOne(c.email,c);
  // LES COMPTEURS ET LES TITRES DE SECTION, EUX, SUIVENT TOUT DE SUITE : ils
  // ne sont pas sous le doigt, et les laisser mentir pendant une seconde et
  // demie ferait douter du clic qu'on vient justement de rendre fiable.
  try{ renderPortefeuille(); }catch(e){}
  try{ _majComptesSectionsSuivi(); }catch(e){}
  _suiviRangerPlusTard();
  try{ if(currentClientId===id) openClientDetail(id,true,true); }catch(e){}
  toastSync(ok,envoi,estSuivi(c)?'Passé en suivi':'Passé sans suivi',"le changement est");
}
/**
 * Recompte « Mes athletes (avec / sans suivi) » sans repeindre la liste. Les
 * deux titres portent la classe `.sec-suivi`, et leur compte est le second
 * <span> — c'est _htmlSectionsSuivi qui les ecrit, et lui seul.
 */
function _majComptesSectionsSuivi(){
  const z=document.getElementById('ch-clients-list');
  if(!z) return;
  const lignes=[...z.querySelectorAll('.client-row')];
  const suivi=id=>{ try{ return estSuivi(getOwnedClient(id,DB.get('users')||{})||{}); }catch(e){ return false; } };
  const avec=lignes.filter(l=>suivi(l.dataset.cid)).length;
  const t=[...z.querySelectorAll('.sec-suivi')];
  if(t[0]) t[0].textContent=String(avec);
  if(t[1]) t[1].textContent=String(lignes.length-avec);
}
// Le curseur, tel qu'il apparait sur la ligne et sur la fiche.
// ══ LE SUIVI EST UN INTERRUPTEUR, PLUS UNE PILULE ═══════════════════════
//
// Demande de Kevin, 14/09/2026 : « j'aurais aimé un curseur type on/off pour
// activer le suivi ». Il avait raison au-dela de l'esthetique : « ● SUIVI » et
// « ○ SANS SUIVI » sont deux libelles de LONGUEURS DIFFERENTES dans une colonne
// de tableau — la ligne changeait de largeur selon l'etat de l'athlete, et
// l'oeil qui descend la liste voyait la colonne respirer. Un interrupteur a une
// seule largeur, et sa position dit l'etat sans qu'on lise un mot.
//
// LE VOCABULAIRE EST CELUI DE .tbk-swi, l'interrupteur des macros du coach :
// meme gabarit, meme course, meme pastille. Seul l'accent change — rouge, le
// domaine de cette liste, la ou les macros sont en orange.
//
// `taille` GARDE SON SENS pour les appelants hors tableau : ils demandent
// « grand », ils obtiennent un interrupteur accompagne de son mot.
function _htmlCurseurSuivi(c,taille){
  const on=estSuivi(c);
  const nom=((c&&c.fname)||'')+' '+((c&&c.lname)||'');
  const lbl='Suivi de '+(nom.trim()||'cet athlète');
  // stopPropagation : la ligne entiere est cliquable, et sans lui basculer le
  // suivi ouvrirait aussi la fiche.
  return '<label class="cr-swi'+(taille==='grand'?' cr-swi-g':'')+'"'
    +' title="Suivi actif ou non" onclick="event.stopPropagation()">'
    +'<input type="checkbox"'+(on?' checked':'')
    +' onchange="coachBasculerSuivi(\''+c.id+'\',event)"'
    +' aria-label="'+escapeHtml(lbl)+'">'
    +'<span class="cr-swi-p"></span>'
    +(taille==='grand'?'<span class="cr-swi-t">'+(on?'Suivi':'Sans suivi')+'</span>':'')
    +'</label>';
}
function renderClientRow(c){
  // Le `title` porte le texte ENTIER : en mode tableau le badge se coupe a la
  // largeur de sa colonne, et « Abonnement a souscrire » n'y tiendra jamais.
  const _bdg=(cls,txt)=>'<span class="badge '+cls+'" title="'+escapeHtml(txt)+'">'+escapeHtml(txt)+'</span>';
  const badge=_enAttenteAbonnement(c)?_bdg('badge-orange','⏳ Abonnement à souscrire')
    :_accesExpire(c)?_bdg('badge-gray','Lecture seule')
    :hasNewBilan(c)?_bdg('badge-orange','Nouveau bilan'):needsAlert(c)?_bdg('badge-red','Alerte'):isActive(c)?_bdg('badge-green','Actif'):_bdg('badge-gray','Inactif');
  const lastSession=c.sessions?.length?c.sessions[c.sessions.length-1].date:0;
  const lastBilan=c.bilans?.length?c.bilans[c.bilans.length-1].date:0;
  const lastActivity=Math.max(lastSession,lastBilan);
  const activityLine=lastActivity?'Dernière activité : '+ago(lastActivity):'Aucune activité encore';
  const avatarHtml=c.athletePhoto
    ?`<img src="${escapeHtml(c.athletePhoto)}" style="width:100%;height:100%;object-fit:cover;border-radius:var(--r-full)">`
    :escapeHtml(ini(c.fname,c.lname));
  const _objDisplay=c.objective||c.bilanGoals||'';
  // Objectif et phase sont emis MEME absents, avec un contenu vide. Sur grand
  // ecran la ligne devient une ligne de tableau, et une cellule qui disparait
  // sur les seules lignes sans objectif decalerait toutes les colonnes qui la
  // suivent. `.cr-obj:empty{display:none}` les efface sous 1025 px : la carte
  // empilee du telephone est rigoureusement celle d'avant.
  const objLine=`<div class="cr-obj" style="font-size:var(--fs-xs);color:var(--sub);margin-top:2px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis">${_objDisplay?escapeHtml(_objDisplay):''}</div>`;
  // ⚠ PHASE, POIDS ET PROGRES ONT QUITTE LA LIGNE le 19/09/2026, a la demande
  //   de Kevin. Ils n'ont pas disparu de l'application : le tiroir de
  //   contexte les affiche pour l'athlete qu'on regarde, avec leur intitule
  //   en toutes lettres — `_crPoids` et `_crProgres` y servent toujours. Ce
  //   qui partait ici, c'est trois colonnes de plus a balayer sur une ligne
  //   qu'on lit en diagonale.
  // Les trois mesures, EMISES MEME VIDES, pour la même raison que l’objectif
  // et la phase : sur grand écran la ligne devient une ligne de tableau, et
  // une cellule absente décalerait toutes les colonnes suivantes.
  //
  // Aucun seuil, aucune couleur par valeur : la liste porte déjà un filet
  // d’état et un badge, et une quatrième teinte à interpréter les affaiblirait
  // tous les trois.
  const _cel=(cls,txt,titre)=>`<div class="${cls}" title="${escapeHtml(titre)}" style="font-size:var(--fs-xs);color:var(--sub);margin-top:2px;white-space:nowrap">${txt?escapeHtml(txt):''}</div>`;
  const chLine=_cel('cr-charge',_crCharge(c),'Charge de la semaine, sur la moyenne des 4 précédentes');
  const biLine=_cel('cr-bilans',_crBilans(c),'Bilans sans réponse');
  // N6.4 — les trois mesures qui manquaient, sur le meme patron : emises MEME
  // VIDES, effacees sous le seuil du tableau par la regle :empty existante.
  const asLine=_cel('cr-assidu',_crAssidu(c),'Séances faites sur séances prévues');
  const diLine=_cel('cr-diete',_crDiete(c),'Jours où la cible a été tenue');
  const _nm=(escapeHtml(c.fname||'')+' '+escapeHtml(c.lname||'')).trim()||'Profil incomplet';
  // L'ETAT est porte par un attribut plutot que par une classe : il pilote la
  // couleur du filet gauche, et c est ce qui permet de balayer la liste sans
  // lire un seul badge. Le classement suit CELUI DU BADGE, a la lettre — deux
  // regles differentes donneraient une carte rouge a badge vert.
  const _etat=etatAthlete(c);
  // N4.13 — LA CASE RELIT LE Set A CHAQUE RENDU : c'est ce qui la fait
  // survivre a la reecriture du conteneur toutes les trente secondes.
  const _coche=SEL_ATHLETES.has(c.id)?' checked':'';
  return `<div class="client-row${!hasNewBilan(c)&&!needsAlert(c)&&!isActive(c)?' row-inactive':''}" data-etat="${_etat}" data-cid="${c.id}" onclick="openClientDetail('${c.id}')" role="button" tabindex="0" onkeydown="if(event.key==='Enter'||event.key===' '){event.preventDefault();this.click()}">
    <input type="checkbox" class="cr-coche"${_coche} value="${c.id}"
      onclick="selAthleteBascule('${c.id}',event)"
      aria-label="Sélectionner ${escapeHtml(((c.fname||'')+' '+(c.lname||'')).trim()||'cet athlète')}">
    <div class="avatar" style="width:44px;height:44px;font-size:var(--fs-lg);overflow:hidden;flex-shrink:0">${avatarHtml}</div>
    <div style="flex:1;min-width:0"><div class="cr-nom" title="${_nm}">${_nm}</div>${objLine}${asLine}${diLine}${chLine}${biLine}</div>
    <!-- ══ LE BOUTON EST DANS LA LIGNE, A COTE DU NOM ═══════════════════
         Demande de Kevin, 08/09/2026 : « je vois Claire Boumar, je peux
         cliquer directement sur ouvrir la fiche a cote de son prenom ».
         Il REMPLACE la ligne « Derniere activite », qui disait la meme chose
         que le badge d'etat deux colonnes plus loin.
         stopPropagation : la ligne entiere est deja cliquable, et sans lui le
         clic partirait deux fois. -->
    <!-- ⚠ IL FORCE L'OUVERTURE, ET C'EST TOUT SON PROPOS. Sans le troisieme
         argument, ce bouton passait par le tiroir : on cliquait « OUVRIR LA
         FICHE » et on obtenait un panneau qui proposait… « Ouvrir la fiche ».
         Signale par Kevin le 08/09/2026, capture a l'appui. Un bouton qui
         porte un verbe fait ce que le verbe dit, du premier coup.
         Le clic sur le RESTE de la ligne, lui, garde l'apercu : c'est le
         geste vague, et il merite un apercu. -->
    <button class="btn btn-red btn-sm cr-fiche" onclick="event.stopPropagation();openClientDetail('${c.id}',false,true)"
      title="Ouvrir la fiche de ${_nm}" aria-label="Ouvrir la fiche de ${_nm}"
      style="margin:0;flex-shrink:0;letter-spacing:1px;padding:8px 12px;min-height:36px;font-size:var(--fs-2xs);white-space:nowrap"><span class="cr-fiche-l">Ouvrir la fiche</span><span class="cr-fiche-c">Voir profil</span></button>
    ${_htmlCurseurSuivi(c)}
    <div style="display:flex;flex-direction:column;align-items:flex-end;gap:4px;flex-shrink:0">${badge}</div>
  </div>`;
}
// ══════ ANNUAIRE : LES DEUX DÉCISIONS, SORTIES DU RÉSEAU ═══════════════════
// Elles vivaient dans le corps de pullAnnuaire et de _rapatrierElevesInconnus,
// derrière un `await` — donc intestables depuis une suite synchrone. Ce sont
// pourtant elles qui décident QUI apparaît sur le tableau de bord : autant les
// mettre là où on peut les éprouver.
//
// PURES : ni DOM, ni réseau, ni currentUser.

// Les adresses d'un nœud d'annuaire, tel que Firebase le rend.
// LA CLEF EST L'ADRESSE, virgules à la place des points. On lit quand même le
// champ `email` quand il est là : inverser la clef marche, mais dépendre d'une
// inversion là où la valeur est écrite noir sur blanc serait fragile pour rien.
// L'inversion reste le REPLI — une entrée écrite par une version antérieure,
// ou tronquée, ne doit pas faire disparaître l'élève de la liste.
function _annuaireAdresses(noeud){
  if(!noeud||typeof noeud!=='object') return [];
  return Object.keys(noeud).map(k=>{
    const v=noeud[k];
    const e=(v&&typeof v.email==='string'&&v.email)?v.email:String(k).replace(/,/g,'.');
    return String(e).toLowerCase();
  }).filter(Boolean);
}
// Celles dont cet appareil n'a pas encore le dossier.
// SANS CE FILTRE, 40 ATHLÈTES FONT 40 ALLERS-RETOURS à chaque ouverture du
// tableau de bord, pour retélécharger ce qu'on a déjà. La comparaison est
// insensible à la casse : les adresses servent de clefs de stockage, et une
// majuscule saisie à l'inscription suffirait à créer un doublon.
function _annuaireManquants(adresses,connues){
  const vus=new Set((connues||[]).map(k=>String(k||'').toLowerCase()));
  const out=[];
  for(const a of (adresses||[])){
    // TRIM : une entree d'annuaire faite d'espaces passait le filtre — elle
    // est non vide au sens de JavaScript — et partait en synchronisation
    // vers /users/  .json. Trouve par l'assertion, pas en production.
    const e=String(a||'').trim().toLowerCase();
    if(!e||vus.has(e)) continue;
    vus.add(e);                       // et pas deux fois la même dans un lot
    out.push(e);
  }
  return out;
}

// Releve des codes consommes. Un athlete qui saisit un code sur un appareil
// neuf n'existe nulle part chez le coach : ni dans ses users locaux, ni dans
// sa liste clients. Le seul lien est le noeud /rc_codes/{token}, que l'athlete
// marque redeemed en y inscrivant son email. On le relit donc a chaque
// ouverture du tableau de bord, et on tire le dossier correspondant.
// Sans reseau, la fonction ne fait rien et n'affiche pas d'erreur : ce n'est
// pas une action demandee par le coach.
// Rapatrie les élèves que cet appareil n'a jamais vus.
//
// Le tableau de bord ne montrait que les athlètes DÉJÀ dans le stockage local :
// ceux venus d'une invitation par lien, et ceux inscrits sur ce même appareil.
// Un élève qui a créé son compte sur son propre téléphone n'était nulle part —
// c'est le cas signalé par Kevin le 25/08/2026.
//
// L'annuaire donne les ADRESSES ; c'est syncUser qui va chercher les dossiers,
// un par un, exactement comme pour les autres. Les règles décident : un dossier
// qui ne désigne pas ce coach répond 401 et n'entre pas.
//
// SANS AWAIT DANS L'APPELANT : le tableau de bord s'affiche tout de suite avec
// ce qu'on a, et se complète quand le réseau répond. Même traitement que
// _rafraichirCodesEleves, juste à côté.
async function _rapatrierElevesInconnus(){
  if(!currentUser||currentUser.role!=='coach'||!CLOUD.ok()) return 0;
  let adresses=[];
  try{ adresses=await CLOUD.pullAnnuaire(currentUser); }catch(e){ return 0; }
  if(!adresses.length) return 0;
  const manquants=_annuaireManquants(adresses,Object.keys(DB.get('users')||{}));
  if(!manquants.length) return 0;
  let venus=0;
  for(const e of manquants){
    // Un échec ne doit pas arrêter les suivants : un dossier peut avoir été
    // supprimé, ou son rattachement défait, pendant que les autres vont bien.
    try{ if(await CLOUD.syncUser(e)) venus++; }catch(err){}
  }
  // Re-rendu seulement si le coach est encore sur son tableau de bord : la
  // requête est longue, il a pu naviguer ailleurs entre-temps.
  if(venus&&document.getElementById('s-coach-home')?.classList.contains('active'))
    loadCoachHome();
  return venus;
}
async function _rafraichirCodesEleves(){
  const codes=(currentUser&&currentUser.studentCodes)||[];
  const actifs=codes.filter(c=>c&&c.token&&c.active!==false);
  if(!actifs.length||!CLOUD.ok()) return;
  let tok=null;
  try{tok=await CLOUD._getToken();}catch(e){return;}
  let change=false;
  for(const c of actifs){
    let data=null;
    try{
      const r=await fetch(_rcCodesUrl(c.token)+(tok?'?auth='+tok:''));
      if(!r.ok) continue;
      data=await r.json();
    }catch(e){continue;}
    if(!data) continue;
    // L'ÉTAT D'OUVERTURE D'ABORD, et AVANT la sortie sur `redeemed` : c’est
    // précisément quand l’athlète a ouvert le lien SANS avoir encore créé son
    // compte que `etat:'ouvert'` existe. La sortie plus bas l’écartait donc
    // dans le seul cas où il avait quelque chose à dire, et « Ouverte » était
    // littéralement inatteignable.
    //
    // etatProgresse GARDE LE SENS UNIQUE : un aperçu tardif ne fait pas reculer
    // un compte déjà créé, et etatInvitation fait primer `redeemed`.
    if(etatProgresse(etatInvitation(c),data.etat)){
      c.etat=data.etat;
      if(data.ouvertLe) c.ouvertLe=data.ouvertLe;
      change=true;
    }
    if(!data.redeemed||!data.athleteEmail) continue;
    // Le dossier n'est lisible que si l'athlete a bien inscrit coachEmailKey :
    // c'est la condition posee par database.rules.json. Un echec ici signifie
    // que le rattachement n'est pas alle au bout, pas que le code est faux.
    try{await CLOUD.syncUser(data.athleteEmail);}catch(e){}
    if(c.redeemed!==true||c.athleteEmail!==data.athleteEmail){
      c.redeemed=true;
      c.athleteEmail=data.athleteEmail;
      if(data.usedBy) c.usedBy=data.usedBy;
      change=true;
    }
  }
  if(change){
    saveUser();
    // Re-rendu seulement si le coach est encore sur son tableau de bord : la
    // requete est longue, il a pu naviguer ailleurs entre-temps.
    if(document.getElementById('s-coach-home')?.classList.contains('active')) loadCoachHome();
  }
}

// ══════════════ ACTIVITÉ DU PORTEFEUILLE — 13 MOIS GLISSANTS ══════════════
// Six fonctions PURES, sans DOM, sans réseau. Elles ne lisent que le tableau
// d'athlètes déjà en mémoire (getClients → localStorage), et n'ajoutent aucun
// champ : tout est dérivé de sessions[], createdAt et phase.
//
// AUCUN CHIFFRE D'ARGENT, aucun classement, aucune moyenne de marché :
// RepCore ne connaît ni le prix de vente du coach, ni les autres coachs.
//
// AUCUNE DONNÉE DE SANTÉ NE SORT D'ICI. _estEnPause rend un booléen et rien
// d'autre : ni la cause, ni le champ qui l'a déclenchée. C'est volontaire —
// « en pause » se dit, « enceinte » ne se dit pas.
const ACT_MOIS=13;
const ACT_SORTIE_JOURS=60;      // sans séance depuis ce délai = sortie
const ACT_MIN_ATHLETES=5;       // en dessous, ni médiane ni tendance
const ACT_FENETRE_SEM=4;        // fenêtre de complétion

function _actMoisCle(d){
  const p=n=>(n<10?'0':'')+n;
  return d.getFullYear()+'-'+p(d.getMonth()+1);
}
function _actDebutMois(d){ return new Date(d.getFullYear(),d.getMonth(),1).getTime(); }
function _actSessions(a){
  const l=(a&&a.sessions)||[];
  return Array.isArray(l)?l.filter(s=>s&&typeof s.date==='number'&&s.date>0):[];
}
// PURE. Au moins une séance loggée dans [debut, fin[. C'est LA définition
// d'« actif », elle n'existe qu'ici, et l'écran l'affiche mot pour mot.
function _estActifSurPeriode(a,debut,fin){
  for(const s of _actSessions(a)) if(s.date>=debut&&s.date<fin) return true;
  return false;
}
// PURE. Vrai si l'athlète est en pause DÉCLARÉE, quelle qu'en soit la cause.
// La cause n'est jamais rendue : quatre situations, un seul booléen.
//
// LIMITE ASSUMÉE : une grossesse NON PARTAGÉE est retirée du dossier avant
// qu'il n'arrive chez le coach (CLOUD, « if(!safe.grossessePartagee) delete
// safe.grossesse »). Elle est donc invisible ici, et l'athlète sera comptée
// comme sortie. On ne la devine pas — l'écran dit la limite au lieu de la
// contourner.
function _estEnPause(a){
  if(!a) return false;
  try{ if(pauseActive(a)) return true; }catch(e){}
  try{ if(drapeauRougeActif(a)) return true; }catch(e){}
  const g=a.grossesse;
  if(g&&(g.etat==='enceinte'||g.etat==='allaitement'||g.actif===true)) return true;
  const e=a.etatGrossesse;
  if(e==='enceinte'||e==='allaitement') return true;
  return false;
}
// PURE. Treize entrées au plus, la plus ancienne d'abord. La fenêtre s'arrête
// au premier mois où le coach avait au moins un athlète : un coach de trois
// mois voit trois barres, pas dix à zéro suivies de trois.
function _actifsParMois(athletes,now){
  const l=Array.isArray(athletes)?athletes.filter(Boolean):[];
  // AUCUN athlète : aucune barre. Sans ce retour, `plusVieux` restait à
  // l'infini, le garde-fou ci-dessous ne se déclenchait jamais, et un coach
  // qui vient de s'inscrire lisait treize mois à zéro — soit exactement le
  // faux effondrement que cette fenêtre doit éviter.
  if(!l.length) return [];
  const d=(now instanceof Date)?new Date(now):new Date(now||Date.now());
  let plusVieux=Infinity;
  for(const a of l){
    const c=Number(a.createdAt);
    if(isFinite(c)&&c>0&&c<plusVieux) plusVieux=c;
    for(const s of _actSessions(a)) if(s.date<plusVieux) plusVieux=s.date;
  }
  const out=[];
  for(let i=ACT_MOIS-1;i>=0;i--){
    const m=new Date(d.getFullYear(),d.getMonth()-i,1);
    const debut=m.getTime();
    const fin=new Date(d.getFullYear(),d.getMonth()-i+1,1).getTime();
    // Rien avant le premier athlète : on n'affiche pas des zéros trompeurs.
    if(isFinite(plusVieux)&&fin<=plusVieux) continue;
    let n=0;
    for(const a of l) if(_estActifSurPeriode(a,debut,fin)) n++;
    out.push({mois:_actMoisCle(m),actifs:n});
  }
  return out;
}
// ══════════════════ CROISSANCE HEBDOMADAIRE DU COACH ══════════════════════
// Combien d'athlètes sont arrivés semaine par semaine, d'après la date de
// création de leur dossier, et où en est le total.
const CROISSANCE_SEMAINES=12;
// Le lundi de la semaine contenant t. getDay() rend 0 pour dimanche : le
// décalage remet lundi à 0, sans quoi une arrivée du dimanche basculerait
// dans la semaine suivante.
function _lundiDe(t){
  const d=new Date(t); d.setHours(0,0,0,0);
  d.setDate(d.getDate()-((d.getDay()+6)%7));
  return d;
}
// ══════════ N JOURS APRES, EN CALENDRIER ET NON EN MILLISECONDES ═══════
//
// LE DERNIER DIMANCHE D'OCTOBRE DURE VINGT-CINQ HEURES. Ajouter 7 x 864e5 a un
// lundi de minuit rend donc le dimanche a 23 h, pas le lundi suivant — et tout
// ce qui range cette date dans une semaine la range dans la PRECEDENTE. Le
// commentaire de croissanceHebdo le dit deja pour ses propres bornes ; cette
// fonction-ci le rend disponible partout, pour que la lecon n'ait pas a etre
// reapprise a chaque nouveau calcul.
//
// setDate ACCEPTE LES DEBORDEMENTS et les negatifs : le 35 janvier devient le
// 4 fevrier, le 0 janvier le 31 decembre. C'est le moteur de dates du langage
// qui fait le calendrier, avec ses mois inegaux, ses annees bissextiles et ses
// changements d'heure — on ne le refait pas.
//
// setHours APRES setDate, et pas avant : c'est le decalage du jour d'ARRIVEE
// qui compte, pas celui du depart.
function _datePlusJours(t,n){
  const d=new Date(t);
  d.setDate(d.getDate()+Math.round(Number(n)||0));
  d.setHours(0,0,0,0);
  return d;
}
// PURE. Une entrée par semaine, de la plus ancienne à la semaine en cours.
//
// Les bornes sont calculées EN DATES et non en millisecondes : ajouter
// 7 × 864e5 traverse mal un changement d'heure, la frontière dérive d'une
// heure et un dossier créé dans cet intervalle change de semaine.
//
// Les dossiers SANS date de création sont antérieurs au champ — le reste du
// fichier les traite déjà comme anciens. Ils entrent donc dans le total dès
// le premier point mais ne font naître aucune barre : on ne leur invente pas
// une semaine d'arrivée.
function croissanceHebdo(athletes,now,nbSemaines){
  const l=Array.isArray(athletes)?athletes.filter(Boolean):[];
  const n=Math.max(1,Math.floor(nbSemaines||CROISSANCE_SEMAINES));
  const t=(now instanceof Date)?now.getTime():(typeof now==='number'?now:Date.now());
  const base=_lundiDe(t);
  // k est un nombre de SEMAINES, d'ou le x7 : sans lui la fenetre de douze
  // semaines couvrait douze JOURS, et presque toutes les arrivees tombaient
  // hors du graphique sans que rien ne le signale.
  const lundi=k=>{ const d=new Date(base); d.setDate(d.getDate()+k*7); d.setHours(0,0,0,0); return d.getTime(); };
  let socle=0; const dates=[];
  for(const a of l){
    const c=Number(a&&a.createdAt);
    // ⚠ LE SUIVI EST GARDÉ AVEC LA DATE, et c'est lui qui donne les deux
    //   couleurs de la barre. Le repli sur « avec suivi » n'est pas un aveu
    //   d'ignorance : estSuivi rend vrai par défaut dans l'application, et une
    //   barre entière vaut mieux qu'une barre amputée si la fonction manque.
    let s=true;
    try{ if(typeof estSuivi==='function') s=!!estSuivi(a); }catch(e){ s=true; }
    if(isFinite(c)&&c>0&&c<=t) dates.push({t:c,suivi:s}); else socle++;
  }
  const debutFenetre=lundi(-(n-1));
  let cumul=socle+dates.filter(x=>x.t<debutFenetre).length;
  const out=[];
  for(let i=0;i<n;i++){
    const debut=lundi(i-(n-1)), fin=lundi(i-(n-1)+1);
    const dans=dates.filter(x=>x.t>=debut&&x.t<fin);
    const nouveaux=dans.length, avec=dans.filter(x=>x.suivi).length;
    cumul+=nouveaux;
    // `nouveaux` ET `cumul` NE BOUGENT PAS : ce sont eux que lisent l'échelle
    // de gauche, la ligne du total et les trois phrases de la carte. `avec` et
    // `sans` s'ajoutent, ils ne remplacent rien.
    out.push({debut,fin,nouveaux,avec,sans:nouveaux-avec,cumul});
  }
  return out;
}
// Le tracé. Deux échelles : les barres comptent les arrivées de la semaine,
// la ligne compte le total. Sur une échelle commune, une barre de 1 face à un
// total de 40 ferait un pixel de haut.
function _dessinerCroissance(id,pts){
  const c=_setupCanvas(id,150); if(!c||!pts||!pts.length) return;
  const{ctx,w,h}=c;
  const gL=26,gR=24,gT=12,gB=26;
  const iw=Math.max(1,w-gL-gR), ih=Math.max(1,h-gT-gB);
  const maxN=Math.max(1,...pts.map(p=>p.nouveaux));
  const maxC=Math.max(1,...pts.map(p=>p.cumul));
  const yN=v=>gT+ih-(v/maxN)*ih;
  const yC=v=>gT+ih-(v/maxC)*ih;
  const pas=iw/pts.length;
  // Un voile sous la zone tracée : sans lui, le graphique flotte sur le noir
  // et rien ne dit où commence la surface de lecture.
  const voile=ctx.createLinearGradient(0,gT,0,gT+ih);
  voile.addColorStop(0,'rgba(255,255,255,.030)');voile.addColorStop(1,'rgba(255,255,255,.004)');
  ctx.fillStyle=voile;ctx.fillRect(gL,gT,iw,ih);
  // La grille : pointillés, sauf le socle. Les repères de GAUCHE comptent les
  // arrivées, ceux de DROITE le total.
  ctx.font='600 8.5px Montserrat,sans-serif';ctx.textBaseline='middle';
  [0,.5,1].forEach(f=>{
    const y=gT+ih-f*ih;
    ctx.strokeStyle=f===0?_tok('--border','#242424'):_tok('--border','#242424');ctx.lineWidth=1;
    ctx.setLineDash(f===0?[]:[3,4]);
    ctx.beginPath();ctx.moveTo(gL,y);ctx.lineTo(gL+iw,y);ctx.stroke();ctx.setLineDash([]);
    ctx.fillStyle='rgba(255,90,90,.55)';ctx.textAlign='right';
    ctx.fillText(String(Math.round(f*maxN)),gL-5,y);
    ctx.fillStyle='rgba(255,255,255,.42)';ctx.textAlign='left';
    ctx.fillText(String(Math.round(f*maxC)),gL+iw+5,y);
  });
  // LES BARRES, EN DEUX TEINTES. Demande de Kévin, 19/09/2026 : rouge pour
  // ceux qu'on suit, blanc pour les autres. La carte disait déjà la
  // répartition en une ligne de texte ; elle se lit maintenant semaine par
  // semaine, là où la question se pose — « ce mois-ci, j'ai recruté quoi ? ».
  //
  // EMPILÉES, ET NON CÔTE À CÔTE. La hauteur totale reste le nombre
  // d'arrivées, donc l'échelle de gauche continue de se lire et la ligne du
  // total reste cohérente avec les barres. Deux barres jumelles auraient
  // divisé la largeur par deux sur douze semaines : trois pixels chacune.
  //
  // LE ROUGE AU SOL. C'est la part qu'on veut voir grandir, et une base de
  // référence commune se compare d'une semaine à l'autre ; posée en haut,
  // elle flotterait à une altitude différente chaque fois.
  const bw=Math.max(3,Math.min(18,pas*0.52));
  pts.forEach((pt,i)=>{
    if(!pt.nouveaux) return;
    const x=gL+i*pas+(pas-bw)/2;
    // ⚠ REPLI SUR UNE SEULE TEINTE quand la série ne porte pas la répartition.
    //   Sans lui, un appelant d'avant ce lot aurait dessiné des barres VIDES :
    //   Number(undefined)||0 vaut zéro, et zéro plus zéro ne fait aucune barre.
    const deux=isFinite(Number(pt.avec))&&isFinite(Number(pt.sans));
    const avec=deux?Math.max(0,Number(pt.avec)):pt.nouveaux;
    const sans=deux?Math.max(0,Number(pt.sans)):0;
    const segs=[];
    if(avec) segs.push({n:avec,a:'#ff4a4a',b:'#6d0000',
      lueur:'rgba(224,32,32,.75)',arete:'rgba(255,255,255,.35)'});
    if(sans) segs.push({n:sans,a:'#ffffff',b:'#8f8f8f',
      lueur:'rgba(255,255,255,.55)',arete:'rgba(255,255,255,.95)'});
    let socle=0;
    segs.forEach((s,k)=>{
      const yBas=yN(socle), yHaut=yN(socle+s.n), bh=yBas-yHaut;
      const g=ctx.createLinearGradient(0,yHaut,0,yBas);
      g.addColorStop(0,s.a);g.addColorStop(1,s.b);
      ctx.fillStyle=g;ctx.shadowColor=s.lueur;ctx.shadowBlur=10;
      ctx.beginPath();
      // SEUL LE SEGMENT DU HAUT porte les coins arrondis : les arrondir tous
      // creuserait une encoche à la jonction des deux couleurs.
      const r=(k===segs.length-1)?[3,3,0,0]:[0,0,0,0];
      if(ctx.roundRect) ctx.roundRect(x,yHaut,bw,bh,r); else ctx.rect(x,yHaut,bw,bh);
      ctx.fill();ctx.shadowBlur=0;
      // Un liseré clair sur l'arête haute : c'est lui qui donne le relief.
      ctx.strokeStyle=s.arete;ctx.lineWidth=1;
      ctx.beginPath();ctx.moveTo(x+1,yHaut+.5);ctx.lineTo(x+bw-1,yHaut+.5);ctx.stroke();
      socle+=s.n;
    });
  });
  // LA LIGNE DU TOTAL, sur les milieux de semaine.
  const ptsC=pts.map((pt,i)=>({x:gL+i*pas+pas/2,y:yC(pt.cumul)}));
  if(ptsC.length>1){
    const g=ctx.createLinearGradient(0,gT,0,gT+ih);
    g.addColorStop(0,'rgba(255,255,255,.26)');g.addColorStop(1,'rgba(255,255,255,.02)');
    ctx.beginPath();ctx.moveTo(ptsC[0].x,gT+ih);
    ptsC.forEach(q=>ctx.lineTo(q.x,q.y));
    ctx.lineTo(ptsC[ptsC.length-1].x,gT+ih);ctx.closePath();
    ctx.fillStyle=g;ctx.fill();
    ctx.strokeStyle=_tok('--text','#efefef');ctx.lineWidth=2;ctx.lineJoin='round';ctx.lineCap='round';
    ctx.shadowColor='rgba(255,255,255,.85)';ctx.shadowBlur=9;
    ctx.beginPath();ptsC.forEach((q,i)=>i?ctx.lineTo(q.x,q.y):ctx.moveTo(q.x,q.y));ctx.stroke();
    ctx.shadowBlur=0;
  }
  // Le dernier point seul est marqué : c'est la valeur d'aujourd'hui.
  const dern=ptsC[ptsC.length-1];
  ctx.fillStyle=_tok('--text','#efefef');ctx.shadowColor='rgba(255,255,255,.9)';ctx.shadowBlur=12;
  ctx.beginPath();ctx.arc(dern.x,dern.y,3.5,0,Math.PI*2);ctx.fill();
  ctx.shadowBlur=0;ctx.strokeStyle='#0b0b0b';ctx.lineWidth=1.5;
  ctx.beginPath();ctx.arc(dern.x,dern.y,3.5,0,Math.PI*2);ctx.stroke();
  // Les dates, une sur deux quand la place manque.
  ctx.fillStyle='#555';ctx.font='700 8.5px Montserrat,sans-serif';
  ctx.textAlign='center';ctx.textBaseline='alphabetic';
  const saut=pas<26?2:1;
  pts.forEach((pt,i)=>{
    if((pts.length-1-i)%saut) return;
    const d=new Date(pt.debut);
    ctx.fillText(d.getDate()+'/'+(d.getMonth()+1),gL+i*pas+pas/2,h-4);
  });
}
// La carte. Elle n'apparaît pas sans athlète : un graphique vide n'apprend
// rien et occupe la place de ce qui compte quand on démarre.
// QUI EST SUR L'APPLI, EN UNE LIGNE — les totaux, sous le titre de la carte.
// LE CHANTIER ANNONCE ICI A ETE FAIT le 19/09/2026 : ce commentaire disait que
// repeindre les barres en deux teintes demanderait de passer deux series a
// _dessinerCroissance. C'est exactement ce que croissanceHebdo rend desormais
// — `avec` et `sans` a cote de `nouveaux` — et les barres sont empilees, rouge
// pour les suivis, blanc pour les autres. Cette ligne de totaux reste : elle
// dit le portefeuille ENTIER, la ou les barres disent semaine par semaine.
// ══ LES ACCES QUI ARRIVENT A TERME, PAR MOIS ═══════════════════════════
// « A relancer » dit qui est en train de decrocher. Il ne dit pas ce qui
// tombe le mois prochain — or c'est la meme decision : qui rappeler, et quand.
// Demande de Kevin, 11/09/2026 : « je peux me projeter, tiens, a cette date-la
// j'ai ca qui arrive ».
//
// Groupe par mois plutot qu'en grille de jours : une echeance d'acces se lit
// en « courant novembre », pas en « le 14 ». Les dates passees sont ecartees —
// un acces deja expire releve du filtre « acces qui expire », pas d'une
// projection. Suivis et non suivis sont tous deux presents, avec leur pastille
// de couleur : une echeance porte sur le paiement, pas sur l'accompagnement.
function _htmlCalendrierAcces(){
  let l=[];
  try{ l=getClients()||[]; }catch(e){ return ''; }
  const auj=Date.now();
  const ech=l.map(c=>({c,t:Date.parse(c&&c.accessExpiry)}))
             .filter(x=>isFinite(x.t)&&x.t>=auj)
             .sort((a,b)=>a.t-b.t);
  if(!ech.length) return '';
  const mois={};
  for(const x of ech){
    const d=new Date(x.t),k=d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0');
    (mois[k]=mois[k]||[]).push(x);
  }
  const libMois=k=>{
    const [a,m]=k.split('-');
    const t=new Date(Number(a),Number(m)-1,1).toLocaleDateString('fr-FR',{month:'long',year:'numeric'});
    return t.charAt(0).toUpperCase()+t.slice(1);
  };
  const jour=t=>new Date(t).toLocaleDateString('fr-FR',{day:'2-digit',month:'2-digit'});
  const blocs=Object.keys(mois).sort().map(k=>
    '<div style="margin-bottom:10px">'
    +'<div style="font-size:var(--fs-2xs);font-weight:800;letter-spacing:1.5px;text-transform:uppercase;'
    +'color:var(--sub);margin-bottom:5px">'+escapeHtml(libMois(k))+' · '+mois[k].length+'</div>'
    +mois[k].map(x=>'<div style="display:flex;align-items:center;gap:8px;padding:5px 0;'
      +'border-top:1px solid rgba(255,255,255,.05);font-size:var(--fs-xs)">'
      +'<span style="width:8px;height:8px;border-radius:var(--r-full);flex-shrink:0;background:'
      +(estSuivi(x.c)?'#E02020':'#f5a524')+'"></span>'
      +'<span style="flex:1;min-width:0;color:var(--text-strong);overflow:hidden;text-overflow:ellipsis;'
      +'white-space:nowrap">'+escapeHtml(((x.c.fname||'')+' '+(x.c.lname||'')).trim()||'—')+'</span>'
      +'<span style="color:var(--sub);flex-shrink:0">'+jour(x.t)+'</span></div>').join('')
    +'</div>').join('');
  return '<div style="background:var(--surface-1);border:1px solid var(--border);'
    +'border-radius:var(--r-3);padding:13px 14px;margin-bottom:16px">'
    +'<div style="font-size:var(--fs-xs);font-weight:800;letter-spacing:2px;text-transform:uppercase;'
    +'color:var(--sub);margin-bottom:9px">Accès arrivant à terme</div>'+blocs
    +'<div style="font-size:var(--fs-2xs);color:var(--text-faint);line-height:1.5;margin-top:4px">'
    +'Rouge : avec suivi. Jaune : sans suivi.</div></div>';
}
// `_htmlRepartitionSuivi` VIVAIT ICI. Elle rendait « 17 avec suivi · 13 sans
// suivi » en deux pastilles, pour la barre du portefeuille et pour la carte des
// arrivees. La carte l'a absorbee le 19/09 — ses barres portent les deux
// couleurs, et les comptes sont passes dans leur legende ; la barre l'a perdue
// le meme jour, parce qu'elle y cassait l'alignement des huit compteurs. Plus
// aucun appelant : on la retire plutot que de la laisser dormir.
function _htmlCroissanceCoach(athletes){
  const l=Array.isArray(athletes)?athletes.filter(Boolean):[];
  if(!l.length) return '';
  const pts=croissanceHebdo(l,Date.now(),CROISSANCE_SEMAINES);
  const total=pts[pts.length-1].cumul;
  // Sur les quatre dernières semaines : la fenêtre que lit un coach pour
  // savoir si ça bouge, sans être trop courte pour dire quoi que ce soit.
  const recent=pts.slice(-4).reduce((n,p)=>n+p.nouveaux,0);
  const meilleure=pts.reduce((m,p)=>p.nouveaux>m.nouveaux?p:m,pts[0]);
  // LE PORTEFEUILLE ENTIER, pas la somme des barres : les arrivées d'avant la
  // fenêtre de douze semaines comptent aussi, et ce sont elles qui font la
  // différence entre « 3 sur le graphique » et « 30 dans mes athlètes ».
  const avecSuivi=l.filter(estSuivi).length, sansSuivi=l.length-avecSuivi;
  const dt=d=>new Date(d).toLocaleDateString('fr-FR',{day:'2-digit',month:'short'});
  return `<div class="evo-carte" style="padding:15px 14px 12px">
    <div style="display:flex;align-items:baseline;justify-content:space-between;gap:8px;margin-bottom:2px">
      <div class="evo-titre" style="margin-bottom:0">Arrivées par mois</div>
      <div style="font-size:var(--fs-xs);font-weight:800;color:${recent>0?'var(--text)':'var(--sub)'}">${recent>0?'+':''}${recent} sur 4 semaines</div>
    </div>
    <div style="font-size:var(--fs-2xs);color:var(--text-faint);letter-spacing:.4px;margin-bottom:9px">
      D'après la date de création de chaque dossier.</div>
    <!-- ⚠ UNE SEULE LIGNE, ET LES COMPTES SONT DEDANS. La carte portait la
         répartition du portefeuille juste au-dessus de la légende des barres :
         depuis que les deux parlent la même langue — rouge suivi, blanc sans
         suivi — c'étaient les mêmes quatre mots, écrits deux fois, l'un sur
         l'autre. Les nombres rejoignent donc les pastilles qu'ils décrivent. -->
    <div style="display:flex;align-items:center;gap:14px;margin-bottom:6px;flex-wrap:wrap">
      <span style="display:inline-flex;align-items:center;gap:5px;font-size:var(--fs-2xs);font-weight:800;letter-spacing:1.2px;text-transform:uppercase;color:var(--red-text)">
        <span style="width:9px;height:9px;border-radius:var(--r-1);background:linear-gradient(180deg,#ff4a4a,#6d0000);box-shadow:0 0 7px rgba(224,32,32,.8)"></span>${avecSuivi} avec suivi</span>
      <span style="display:inline-flex;align-items:center;gap:5px;font-size:var(--fs-2xs);font-weight:800;letter-spacing:1.2px;text-transform:uppercase;color:var(--text)">
        <span style="width:9px;height:9px;border-radius:var(--r-1);background:linear-gradient(180deg,#ffffff,#8f8f8f);box-shadow:0 0 7px rgba(255,255,255,.6)"></span>${sansSuivi} sans suivi</span>
      <span style="display:inline-flex;align-items:center;gap:5px;font-size:var(--fs-2xs);font-weight:800;letter-spacing:1.2px;text-transform:uppercase;color:var(--text)">
        <span style="width:11px;height:2px;border-radius:var(--r-1);background:#ffffff;box-shadow:0 0 7px rgba(255,255,255,.8)"></span>Total (${total})</span>
    </div>
    <canvas id="ch-croissance-toile" height="150" style="width:100%;display:block"></canvas>
    <div style="font-size:var(--fs-2xs);color:var(--text-faint);line-height:1.5;margin-top:7px">
      ${meilleure.nouveaux>0?`Meilleure semaine : ${meilleure.nouveaux} arrivée${meilleure.nouveaux>1?'s':''} le ${dt(meilleure.debut)}.`:'Aucune arrivée sur les 12 dernières semaines.'}
    </div>
  </div>`;
}
// PURE. Entrées et sorties du TRIMESTRE en cours.
// Une pause déclarée n'est JAMAIS une sortie : c'est tout l'objet du compteur
// séparé — un coach qui lit « 4 sorties » alors que trois sont des pauses
// prend une décision sur un chiffre faux.
function _entreesSorties(athletes,now){
  const l=Array.isArray(athletes)?athletes.filter(Boolean):[];
  const d=(now instanceof Date)?new Date(now):new Date(now||Date.now());
  const t=d.getTime();
  const trim=Math.floor(d.getMonth()/3);
  const debut=new Date(d.getFullYear(),trim*3,1).getTime();
  const limite=t-ACT_SORTIE_JOURS*864e5;
  let entrees=0,sorties=0,pauses=0;
  for(const a of l){
    const c=Number(a.createdAt);
    if(isFinite(c)&&c>=debut&&c<=t) entrees++;
    if(_estEnPause(a)){ pauses++; continue; }
    const ses=_actSessions(a);
    if(!ses.length) continue;                 // jamais démarré : pas une sortie
    let dernier=0;
    for(const s of ses) if(s.date>dernier) dernier=s.date;
    if(dernier<limite) sorties++;
  }
  return {entrees,sorties,pauses,depuis:debut,seuilJours:ACT_SORTIE_JOURS};
}
function _actMediane(l){
  if(!l.length) return null;
  const t=l.slice().sort((a,b)=>a-b);
  return t.length%2?t[(t.length-1)/2]:(t[t.length/2-1]+t[t.length/2])/2;
}
// PURE. Ancienneté médiane en SEMAINES. null sous cinq athlètes : une médiane
// sur trois personnes ne dit rien et se lirait comme un fait.
function _ancienneteMediane(athletes,now){
  const l=Array.isArray(athletes)?athletes.filter(Boolean):[];
  if(l.length<ACT_MIN_ATHLETES) return null;
  const t=(now instanceof Date)?now.getTime():(typeof now==='number'?now:Date.now());
  const sem=[];
  for(const a of l){
    const c=Number(a.createdAt);
    if(isFinite(c)&&c>0&&c<=t) sem.push((t-c)/(7*864e5));
  }
  const m=_actMediane(sem);
  return m==null?null:Math.round(m);
}
// PURE. Taux de complétion moyen sur quatre semaines, et sa tendance face aux
// quatre précédentes. null sous cinq athlètes, pour la même raison.
//
// « tendance » vaut 'hausse' | 'stable' | 'baisse' — jamais un pourcentage de
// progression, qui se lirait comme une projection.
// DELEGUE a tauxCompletion. Cette fonction calculait son propre taux sur quatre
// semaines, avec une regle differente : elle ecartait l athlete ENTIER s il
// etait en pause, la ou tauxCompletion ecarte les SEMAINES suspendues. Deux
// chiffres pour la meme question, sur deux ecrans. Il n en reste qu un.
function _completionMoyenne(athletes,now){
  const l=Array.isArray(athletes)?athletes.filter(Boolean):[];
  if(l.length<ACT_MIN_ATHLETES) return null;
  const t=(now instanceof Date)?now.getTime():(typeof now==='number'?now:Date.now());
  const moy=(instant)=>{
    let somme=0,n=0;
    for(const a of l){
      let r=null;
      try{ r=tauxCompletion(a,instant); }catch(e){}
      if(r&&r.interpretable){ somme+=r.taux; n++; }
    }
    return n?(somme/n):null;
  };
  const recent=moy(t);
  if(recent==null) return null;
  const avant=moy(t-TC_JOURS*864e5);
  let tendance='stable';
  if(avant!=null){
    const ecart=recent-avant;
    if(ecart>5) tendance='hausse';
    else if(ecart<-5) tendance='baisse';
  }
  return {taux:Math.round(recent),tendance:(avant==null?null:tendance),
    semaines:TC_SEMAINES};
}


// ── L'écran, quatre cartes, barres en CSS pur ─────────────────────────────
// Aucune bibliothèque, aucun canevas : des <div> dont la hauteur est un
// pourcentage. Aucune notification n'est émise, aucun état n'est modifié —
// cet écran LIT, il n'écrit rien.
const ACT_MOIS_LIB=['janv.','févr.','mars','avr.','mai','juin','juil.','août',
  'sept.','oct.','nov.','déc.'];
function _actLibMois(cle){
  const m=/^(\d{4})-(\d{2})$/.exec(String(cle||''));
  if(!m) return String(cle||'');
  return ACT_MOIS_LIB[+m[2]-1]+' '+m[1].slice(2);
}
function _actCarte(titre,corps,note){
  return `<div style="background:var(--surface-1);border:1px solid var(--border);border-radius:var(--r-3);padding:13px 14px;margin-bottom:12px">
    <div style="font-size:var(--fs-xs);color:var(--sub);letter-spacing:1.5px;font-weight:800;text-transform:uppercase;margin-bottom:9px">${escapeHtml(titre)}</div>
    ${corps}
    ${note?`<div style="font-size:var(--fs-2xs);color:var(--text-faint);line-height:1.55;margin-top:9px">${note}</div>`:''}
  </div>`;
}
function _actChiffre(n,lib,couleur){
  return `<div style="flex:1;min-width:0;text-align:center">
    <div style="font-family:var(--pile-titre);font-size:var(--fs-2xl);line-height:1;color:${couleur||'var(--text)'}">${n}</div>
    <div style="font-size:var(--fs-2xs);color:var(--sub);letter-spacing:1px;font-weight:800;text-transform:uppercase;margin-top:5px;line-height:1.25">${escapeHtml(lib)}</div>
  </div>`;
}
function renderCoachActivite(){
  const el=document.getElementById('cact-body');
  if(!el) return;
  // ── État « chargement » ──
  // Le cache local peut être vide sur un appareil neuf : afficher 0 serait un
  // faux effondrement. countActiveAthletesFiable existe exactement pour ça.
  let fiable=true;
  try{ fiable=countActiveAthletesFiable(currentUser,DB.get('users')||{}); }catch(e){}
  let ath=[];
  try{ ath=getClients().filter(c=>c&&!c._fromCode); }catch(e){
    el.innerHTML=`<div style="background:var(--warning-bg);border:1px solid var(--warning-border);border-radius:var(--r-3);padding:14px;font-size:var(--fs-sm);color:var(--text);line-height:1.6">Impossible de lire ton portefeuille pour l'instant. Reviens dans un moment.</div>`;
    return;
  }
  if(!fiable&&!ath.length){
    el.innerHTML=`<div style="background:var(--surface-1);border:1px solid var(--border);border-radius:var(--r-3);padding:22px 14px;text-align:center;font-size:var(--fs-sm);color:var(--text-dim);line-height:1.6">Synchronisation en cours…<div style="font-size:var(--fs-xs);color:var(--text-faint);margin-top:6px">Tes dossiers arrivent sur cet appareil. Les chiffres seraient faux avant.</div></div>`;
    return;
  }
  // ── État « 0 athlète » ──
  if(!ath.length){
    el.innerHTML=`<div style="background:var(--surface-1);border:1px solid var(--border);border-radius:var(--r-3);padding:22px 16px;text-align:center">
      <div style="font-size:var(--fs-md);font-weight:800;color:var(--text);margin-bottom:6px">Pas encore d'athlète</div>
      <div style="font-size:var(--fs-xs);color:var(--text-dim);line-height:1.6">Cet écran se remplira tout seul dès qu'un athlète aura rejoint ton suivi et enregistré sa première séance.</div>
    </div>`;
    return;
  }
  const now=Date.now();
  const mois=_actifsParMois(ath,now);
  const es=_entreesSorties(ath,now);
  const anc=_ancienneteMediane(ath,now);
  const comp=_completionMoyenne(ath,now);
  const partiel=ath.length<ACT_MIN_ATHLETES;
  // ── Carte 1 : actifs par mois ──
  const maxi=mois.reduce((m,x)=>Math.max(m,x.actifs),0)||1;
  const barres=mois.map(x=>{
    const h=Math.round(x.actifs/maxi*100);
    return `<div style="flex:1;min-width:0;display:flex;flex-direction:column;align-items:center;gap:4px">
      <div style="font-size:var(--fs-2xs);color:${x.actifs?'var(--text-strong)':'var(--text-faint)'};font-weight:800">${x.actifs}</div>
      <div style="width:100%;height:64px;display:flex;align-items:flex-end">
        <div style="width:100%;height:${Math.max(h,2)}%;background:${x.actifs?'linear-gradient(180deg,var(--red),#8d0000)':'#242424'};border-radius:var(--r-1) var(--r-1) 0 0"></div>
      </div>
      <div style="font-size:var(--fs-2xs);color:var(--text-faint);letter-spacing:.2px;white-space:nowrap;transform:rotate(-45deg);transform-origin:center;height:22px">${escapeHtml(_actLibMois(x.mois))}</div>
    </div>`;
  }).join('');
  const c1=_actCarte('Athlètes actifs par mois',
    `<div style="display:flex;gap:3px;align-items:flex-end">${barres}</div>`,
    'Fenêtre réellement disponible : '+mois.length+' mois. <b>Actif</b> veut dire : au moins une séance enregistrée dans le mois.');
  // ── Carte 2 : entrées et sorties du trimestre ──
  const c2=_actCarte('Ce trimestre',
    `<div style="display:flex;gap:8px">
      ${_actChiffre(es.entrees,'Arrivées','var(--green)')}
      ${_actChiffre(es.sorties,'Sans séance','var(--orange)')}
      ${_actChiffre(es.pauses,'En pause','#8a8a8a')}
    </div>`,
    '« Sans séance » : aucune séance depuis '+es.seuilJours+' jours. Un athlète en pause déclarée n\'y figure jamais — et la raison de sa pause n\'est pas affichée ici.');
  // ── Carte 3 : ancienneté ──
  const c3=_actCarte('Ancienneté',
    anc==null
      ? `<div style="font-size:var(--fs-sm);color:var(--text-dim);line-height:1.6">${ath.length} athlète${ath.length>1?'s':''} suivi${ath.length>1?'s':''}. La médiane n'a pas de sens en dessous de ${ACT_MIN_ATHLETES} : elle reste masquée.</div>`
      : `<div style="display:flex;gap:8px">${_actChiffre(anc,'Semaines (médiane)')}${_actChiffre(ath.length,'Athlètes')}</div>`,
    anc==null?null:'La moitié de tes athlètes te suit depuis plus longtemps, l\'autre moitié depuis moins.');
  // ── Carte 4 : complétion ──
  const fleche=comp&&comp.tendance==='hausse'?'▲':comp&&comp.tendance==='baisse'?'▼':'=';
  const coulT=comp&&comp.tendance==='hausse'?'var(--green)':comp&&comp.tendance==='baisse'?'var(--orange)':'var(--sub)';
  const c4=_actCarte('Séances faites sur séances prévues',
    comp==null
      ? `<div style="font-size:var(--fs-sm);color:var(--text-dim);line-height:1.6">Masqué en dessous de ${ACT_MIN_ATHLETES} athlètes, ou tant qu'aucun programme n'est configuré.</div>`
      : `<div style="display:flex;gap:8px;align-items:center">
          ${_actChiffre(comp.taux+' %','sur '+comp.semaines+' semaines')}
          <div style="flex:1;min-width:0;text-align:center">
            <div style="font-size:var(--fs-xl);line-height:1;color:${coulT}">${comp.tendance?fleche:'—'}</div>
            <div style="font-size:var(--fs-2xs);color:var(--sub);letter-spacing:1px;font-weight:800;text-transform:uppercase;margin-top:6px">${comp.tendance?escapeHtml(comp.tendance):'pas de repère'}</div>
          </div>
        </div>`,
    comp==null?null:'Comparé aux '+comp.semaines+' semaines précédentes. Les athlètes en pause n\'y comptent pas.');
  el.innerHTML=c1+c2+c3+c4+_actParagraphe(ath,mois,es,anc,comp,partiel);
}
// UN SEUL paragraphe, FACTUEL. Il décrit ce qui est mesuré, il ne prédit rien,
// ne compare à personne et ne chiffre aucun revenu.
function _actParagraphe(ath,mois,es,anc,comp,partiel){
  const p=[];
  p.push('Tu suis '+ath.length+' athlète'+(ath.length>1?'s':'')+'.');
  if(mois.length>=2){
    const d=mois[mois.length-1].actifs, v=mois[mois.length-2].actifs;
    p.push(d===v?('Autant d\'athlètes actifs ce mois-ci que le mois dernier ('+d+').')
      :('Ce mois-ci, '+d+' athlète'+(d>1?'s':'')+' actif'+(d>1?'s':'')+', contre '+v+' le mois dernier.'));
  }
  if(es.sorties) p.push(es.sorties+' athlète'+(es.sorties>1?'s n\'ont':' n\'a')+' plus enregistré de séance depuis '+es.seuilJours+' jours.');
  if(es.pauses) p.push(es.pauses+' '+(es.pauses>1?'sont':'est')+' en pause déclarée.');
  if(partiel) p.push('En dessous de '+ACT_MIN_ATHLETES+' athlètes, les médianes et les tendances restent masquées : elles se liraient comme des faits alors qu\'elles n\'en sont pas.');
  p.push('Ces chiffres décrivent ce qui a été enregistré dans RepCore, rien d\'autre.');
  return `<div style="background:var(--dark);border:1px solid var(--border);border-radius:var(--r-3);padding:13px 14px;font-size:var(--fs-xs);color:var(--text-strong);line-height:1.7">${escapeHtml(p.join(' '))}
    <div style="font-size:var(--fs-2xs);color:var(--text-faint);line-height:1.55;margin-top:8px">Une pause non déclarée — ou déclarée sans être partagée avec toi — n'est pas visible ici : elle apparaîtra comme une absence de séance.</div>
  </div>`;
}
function loadCoachActivite(){
  go('s-coach-activite');
  renderCoachActivite();
}
// REPUBLICATION DE RATTRAPAGE. Un coach qui a rempli sa vitrine AVANT que
// son navigateur ne charge la version qui sait la publier garde ses textes
// en local sans qu ils atteignent jamais coach_public : la liste blanche du
// code d alors ne les connaissait pas. Mesure sur le dossier de Kevin : bio
// de 226 caracteres en local, absente du profil publie.
// Rien ne le rattrapait — il fallait re-enregistrer a la main, sans que rien
// ne le dise. On compare donc ce qu on a a ce qui est publie, et on repousse
// une seule fois si l ecart existe. Idempotent : sans ecart, aucun trafic.
async function _rattraperProfilCoach(){
  try{
    if(!currentUser||currentUser.role!=='coach') return;
    const aPublier=['bio','vision','photoVitrine','signature','logo','cartePro','diplomes']
      .filter(k=>{const v=currentUser[k];
        return Array.isArray(v)?v.length>0:!!(v&&String(v).trim());});
    if(!aPublier.length) return;
    if(!CLOUD.ok||!CLOUD.ok()) return;
    // `/\./g` et non `/./g` : sans la barre oblique inverse, le point est le
    // joker des expressions régulières et TOUS les caractères devenaient des
    // virgules. La clé interrogée n’existait donc jamais, `publie` valait {},
    // et la comparaison ci-dessous déclarait tout manquant — ce rattrapage
    // « idempotent » republiait le profil ENTIER à chaque passage.
    const cle=(currentUser.email||'').replace(/\./g,',');
    const tok=await CLOUD._getToken(); if(!tok) return;
    const r=await fetch(CLOUD._urlProfilCoach(cle)+'?auth='+tok);
    if(!r.ok) return;
    const publie=await r.json()||{};
    const manquants=aPublier.filter(k=>{const v=publie[k];
      return Array.isArray(v)?!v.length:!(v&&String(v).trim());});
    if(!manquants.length) return;
    // .catch et non try/catch : la fonction est asynchrone, et un try
    // synchrone ne rattrape pas un rejet. Le rattrapage est silencieux par
    // nature — personne ne l’a demandé — mais l’échec ENFILE, donc il repart.
    CLOUD.pushProfilCoach(currentUser).catch(()=>{});
  }catch(e){}
}
function loadCoachHome(){
  // Même mémorisation que côté athlète : les deux accueils sont les deux
  // écrans que le changement de jour doit rafraîchir.
  _jourAffiche=localISODate(new Date());
  // UNE FOIS PAR SESSION, et pas à chaque appel : loadCoachHome est rappelée
  // par la boucle de synchronisation toutes les 5 minutes, et par chaque
  // retour vers le tableau de bord.
  //
  // Le drapeau est celui de go(), QUI GARDE DÉJÀ CETTE FONCTION. Un second
  // pour la même question finirait par dire autre chose que le premier —
  // c’est la faute que ce fichier a déjà corrigée ailleurs.
  if(!window._ratProfilFait){ window._ratProfilFait=true;
    try{ _rattraperProfilCoach(); }catch(e){} }
  // Publication de rattrapage : les coachs qui ont rempli leur profil AVANT
  // l existence du nud public n auraient rien a montrer tant qu ils ne
  // reenregistrent pas. Une fois par session suffit.
  // LE GARDE RESTE : cette publication de rattrapage n’a lieu qu’une fois par
  // session. Il ne bloque PAS le rejeu de la file — viderFile appelle
  // pushProfilCoach directement, sans passer par ici.
  if(!window._profilCoachPublie){ window._profilCoachPublie=true;
    CLOUD.pushProfilCoach(currentUser).catch(()=>{}); }
  go('s-coach-home');
  // Pousser les données locales vers Firebase dès l'ouverture (récupère les saves pré-v144)
  // UNE seule lecture du cache pour tout l'ecran : elle sert a la poussee
  // ci-dessous ET au bandeau de paliers. Mesure : 130 ms a 40 athletes,
  // c'est le JSON.parse qui pese, pas le comptage.
  const _cacheUsers=DB.get('users')||{};
  if(CLOUD.canWrite()) CLOUD.push(_cacheUsers);
  // Sans await : le tableau de bord s'affiche tout de suite avec ce qu'on a,
  // et se complete quand les codes ont repondu.
  _rafraichirCodesEleves();
  // ET LES ELEVES QUE CET APPAREIL N A JAMAIS VUS. Ceux qui se sont inscrits
  // sur leur propre telephone n entraient dans aucune des deux voies
  // existantes : ils n avaient ni invitation par lien, ni dossier local.
  _rapatrierElevesInconnus();
  const u=currentUser;
  // Entrée du tunnel : chiffres du produit, donc créateur uniquement. Le
  // masquage n'est qu'un confort d'affichage — loadMetrics refait le contrôle.
  const _lt=document.getElementById('ch-lien-tunnel');
  if(_lt) _lt.style.display=(u.email===CREATOR_EMAIL)?'block':'none';
  const fullName=((u.fname||'')+' '+(u.lname||'')).trim()||'Profil incomplet';
  const el=document.getElementById('ch-name');if(el)el.textContent=fullName;
  const elSb=document.getElementById('ch-name-sidebar');if(elSb)elSb.textContent=fullName;
  const codeEl=document.getElementById('ch-code-small');
  if(codeEl){
    codeEl.textContent=u.code?('Code: '+u.code):'';
    // ⚠ SANS CODE, LE BOUTON DISPARAIT. Du temps ou c'etait une ligne de
    //   texte, une chaine vide suffisait a ne rien montrer. Un bouton vide,
    //   lui, garde sa surface rouge et son clic : il ouvrirait un ecran qui
    //   n'a aucun code a afficher.
    codeEl.hidden=!u.code;
  }
  const codeSb=document.getElementById('ch-code-sidebar');if(codeSb)codeSb.textContent=u.code||'';
  // Show desktop sidebar if wide screen
  const sidebar=document.getElementById('ch-sidebar');
  const mobileHeader=document.getElementById('ch-mobile-header');
  const tabsBar=document.getElementById('coach-tabs-bar');
  // Sidebar always hidden, tabs always visible
  if(sidebar) sidebar.style.display='none';
  if(mobileHeader) mobileHeader.style.display='flex';
  if(tabsBar){tabsBar.style.display='flex';tabsBar.style.visibility='visible';}
  const clients=getClients();
  try{
    const _zp=document.getElementById('ch-paliers');
    // ⚠ LE BANDEAU « N / M ATHLETES ACTIFS » NE S'AFFICHE PLUS ICI.
    // Demande de Kevin, 08/09/2026 : « c'est pas forcement une information
    // interessante ». Il occupait la premiere ligne utile de l'ecran pour un
    // compteur que le coach connait deja.
    // LA FONCTION RESTE, ET L'ALERTE DE DEPASSEMENT AUSSI : elle est rendue
    // par _htmlAlertePalier juste en dessous, et c'est elle qui compte. On
    // retire un compteur permanent, pas un garde-fou.
    if(_zp) _zp.innerHTML='';
    // Le comptage de cycles se fait ICI, une fois par ouverture du tableau
    // de bord, avec le cache deja lu. Il n ecrit dans le dossier que quand
    // le mois change : un enregistrement par mois, pas un par affichage.
    if(majCyclesPaliers(u,_cacheUsers)) try{ saveUser(); }catch(e){}
    const _za=document.getElementById('ch-alerte-palier');
    if(_za) _za.innerHTML=_htmlAlertePalier(u,_cacheUsers);
    _rendreInvitations();
  }catch(e){}
  // N1.11 — les trois compteurs sont comptes par agregerPortefeuille, avec
  // les memes fonctions, et rendus par renderPortefeuille depuis
  // renderClientList. Un seul comptage, un seul rendu.
  try{ const _av=avancementCharges(), _e=document.getElementById('ch-charges-av');
    if(_e) _e.textContent=_av.pose+'/'+_av.total+(_av.pose<_av.total?', à compléter':' ✓'); }catch(e){}
  const elList=document.getElementById('ch-clients-list');
  if(!clients.length){
    renderTodoBlock([]);
    _rendreJamaisDemarre([]);
    _rendreInactifs([]);
    elList.innerHTML=emptyState('users','Aucun athlète pour l\'instant. Ils apparaîtront ici dès qu\'ils te rejoignent.'+(u.code?'<br>Partage ton code : <strong style="color:var(--red-text)">'+u.code+'</strong>':''),'Inviter un athlète','openAddAthlete()');return;
  }
  clients.sort((a,b)=>urgencyScore(b)-urgencyScore(a));
  try{ _majResumeTunnel(clients); }catch(e){}
  renderTodoBlock(clients);
  _rendreJamaisDemarre(clients);
  _rendreInactifs(clients);
  // La toile est tracée APRÈS son insertion : _setupCanvas mesure la largeur
  // du conteneur, et un élément pas encore dans le document en mesure zéro.
  try{
    const _zc=document.getElementById('ch-croissance');
    if(_zc){ _zc.innerHTML=_htmlCroissanceCoach(clients);
      if(clients.length) setTimeout(()=>{ try{ _dessinerCroissance('ch-croissance-toile',croissanceHebdo(clients,Date.now(),CROISSANCE_SEMAINES)); }catch(e){} },0); }
  }catch(e){}
  // Reecrire innerHTML remet le panneau en haut : le coach qui parcourait sa
  // liste y etait ramene a chaque reveil. On releve la position avant, on la
  // repose apres.
  renderClientList(clients);
  // Preserve current tab if already on coach home, otherwise default to dashboard
  const _alreadyHere=document.getElementById('s-coach-home')?.classList.contains('active');
  const _activeTab=_alreadyHere?(['dashboard','codes','monetisation','profil'].find(t=>{const e=document.getElementById('ct-'+t);return e&&e.style.display!=='none';})||'dashboard'):'dashboard';
  coachTab(_activeTab);
  // TIRER POUR RAFRAICHIR, sur le tableau de bord et lui seul. La primitive est
  // deja eprouvee cote athlete et porte son propre repli ; elle n'etait armee
  // que sur un ecran. C'est pourtant ici que le besoin est le plus fort : vingt
  // dossiers qui bougent pendant que le coach travaille, et une boucle de 30 s
  // qui n'annonce rien.
  // CIBLE #ct-dashboard ET PAS #s-coach-home : ce dernier est en overflow:hidden,
  // le conteneur qui defile est le panneau d'onglet. Les trois autres onglets
  // contiennent des champs de saisie — un rafraichissement pendant une frappe
  // est deja proscrit ailleurs. La garde interne zone._arcTirage empeche le
  // rearmement, donc l'appel peut rester ici.
  try{
    arcTirerPourRafraichir(document.getElementById('ct-dashboard'),()=>{
      try{
        if(CLOUD.ok()) CLOUD.syncRelevantUsers().then(()=>loadCoachHome()).catch(()=>loadCoachHome());
        else loadCoachHome();
      }catch(e){ loadCoachHome(); }
    });
  }catch(e){}
  // Sync athlètes depuis Firebase puis re-render pour afficher photos/objectifs à jour
  if(CLOUD.ok()) CLOUD.syncRelevantUsers().then(()=>{
    const freshClients=getClients();
    freshClients.sort((a,b)=>urgencyScore(b)-urgencyScore(a));
    renderTodoBlock(freshClients);
    // ET APRES LA SYNCHRO AUSSI. Un athlete rapatrie par syncRelevantUsers
    // n'existait pas au premier rendu : sans ce second appel, il n'apparaitrait
    // qu'au prochain retour sur le tableau de bord.
    _rendreJamaisDemarre(freshClients);
    _rendreInactifs(freshClients);
    const el2=document.getElementById('ch-clients-list');
    if(!el2||!freshClients.length) return;
    // LA PULSATION NE PART QUE SI LA LISTE A REELLEMENT CHANGE. Posee a chaque
    // tour de boucle, elle ne dirait plus rien — et la synchro tourne toutes
    // les 30 secondes. Deux signaux suffisent : le nombre d athletes, et
    // l identite du premier, qui bouge des que le tri par urgence bascule.
    const _av=(typeof clients!=='undefined'&&clients)||[];
    const _change=freshClients.length!==_av.length
      ||(freshClients[0]&&_av[0]&&freshClients[0].id!==_av[0].id);
    // LA SIGNATURE D'UNE LIGNE, relevee AVANT le rendu : c'est elle qui dit
    // quelle ligne a bouge, et pas seulement que la liste a bouge.
    const _sig=c=>{ try{ return urgencyScore(c)+'|'+(hasNewBilan(c)?1:0)+'|'+etatAthlete(c); }
                    catch(e){ return ''; } };
    const _avantMap=new Map(_av.map(c=>[c.id,_sig(c)]));
    // Meme precaution apres la synchro distante, qui reecrit la meme liste.
    renderClientList(freshClients);
    // APRES renderClientList, qui restaure la position de defilement : poser
    // l animation avant la ferait sauter la liste sous les yeux du coach.
    if(_change&&!arcReduit()){
      let _n=0;
      for(const c of freshClients){
        if(_n>=3) break;                 // au-dela, plus rien ne designe personne
        const _a=_avantMap.get(c.id);
        if(_a!=null&&_a===_sig(c)) continue;
        const _l=el2.querySelector('.client-row[data-cid="'+c.id+'"]');
        if(_l){ _l.classList.add('cr-neuve'); _n++; }
      }
    }
  }).catch(()=>{});
}
// UN ATHLÈTE EST RATTACHÉ PAR L'UN OU L'AUTRE DE DEUX CHAMPS, ET LE TABLEAU
// DE BORD N'EN REGARDAIT QU'UN.
//
// Signalé par Kevin le 25/08/2026 : deux élèves rattachés, un seul affiché.
//
// `coachId` désigne l'identifiant du compte coach. `coachEmailKey` désigne son
// adresse. Les deux sont posés au rattachement — mais pas par tous les chemins,
// et pas toujours ensemble :
//   • _appliquerPayloadCode pose les deux, et coachEmailKey depuis le PAYLOAD
//     et non depuis le cache local ; son propre commentaire le dit : « c'est la
//     seule valeur qui ouvre le dossier au coach côté serveur ».
//   • Le repli qu'il porte dérive coachEmailKey de coachEmail pour les codes
//     émis avant son existence — donc pour des dossiers où coachId peut être
//     absent.
//   • Un coach qui recrée son compte change d'id : les dossiers déjà rattachés
//     gardent l'ancien, alors que l'adresse, elle, n'a pas bougé.
//
// C'est bien coachEmailKey que database.rules.json exige pour ouvrir le
// dossier au coach. Un athlète que le coach PEUT LIRE porte donc forcément ce
// champ — et pouvait n'apparaître nulle part sur son tableau de bord.
//
// canalAccessible admettait déjà les deux (`u.coachId||u.coachEmailKey`).
// C'est cette lecture-là qui fait foi ; getClients était en retard.
//
// `role!=='coach'` ET NON `role==='athlete'` : c'est le prédicat qu'emploient
// déjà les trois autres endroits qui parcourent les athlètes d'un coach
// (syncRelevantUsers, la liste des modèles, le transfert de portefeuille). Un
// dossier sans rôle explicite y était compté, et ne l'était pas ici.
function _estMonAthlete(u,coach){
  if(!u||!coach||u.role==='coach') return false;
  if(u.coachId&&coach.id&&u.coachId===coach.id) return true;
  const k=coach.email?String(coach.email).toLowerCase().replace(/\./g,','):'';
  return !!(k&&u.coachEmailKey&&String(u.coachEmailKey).toLowerCase()===k);
}
function getClients(){
  const users=DB.get('users')||{};
  const allUsers=Object.values(users);

  // 1. Athlètes enregistrés sur cet appareil liés à ce coach
  const registered=allUsers.filter(u=>_estMonAthlete(u,currentUser));
  const registeredNames=new Set(registered.map(u=>((u.fname||'')+' '+(u.lname||'')).toLowerCase().trim()));

  // 2. Élèves issus des codes (même si pas encore enregistrés / autre appareil)
  //
  // `active!==false` ET NON `active` : _rafraichirCodesEleves emploie déjà ce
  // prédicat-là. Un code créé sans le drapeau — undefined, et non false — était
  // donc rafraîchi depuis le réseau à chaque ouverture, puis écarté de la liste
  // qu'il venait d'alimenter. L'élève n'apparaissait jamais.
  const codes=currentUser.studentCodes||[];
  codes.filter(c=>c&&c.active!==false).forEach(c=>{
    const name=(c.studentName||'').toLowerCase().trim();
    // ON NE PERD PLUS UN CODE SANS NOM. `if(name && ...)` écartait en silence
    // toute invitation créée sans nommer l'élève : elle n'apparaissait sur
    // aucune ligne, alors que c'est précisément le cas où le coach a besoin de
    // la voir pour la relancer. Sans nom, on affiche l'adresse, sinon le code.
    const dejaLa=name?registeredNames.has(name)
      :(c.athleteEmail&&registered.some(u=>(u.email||'').toLowerCase()===String(c.athleteEmail).toLowerCase()));
    if(dejaLa) return;
    const libelle=(c.studentName||c.usedBy||c.athleteEmail||'Élève sans nom').trim();
    // Créer un profil minimal depuis le code
    registered.push({
      id:'_code_'+c.codeId,
      fname:libelle.split(' ')[0],
      lname:libelle.split(' ').slice(1).join(' '),
      email:c.athleteEmail||'',
      role:'athlete',
      coachId:currentUser.id,
      status:'COACHING_SUIVI',
      sessions:[],bilans:[],streak:0,
      _fromCode:true,
      _codeInfo:c
    });
    if(name) registeredNames.add(name);
  });

  return registered;
}
function isActive(c){
  const lastSession=c.sessions?.length?c.sessions[c.sessions.length-1].date:0;
  const lastBilan=c.bilans?.length?c.bilans[c.bilans.length-1].date:0;
  const lastActivity=Math.max(lastSession,lastBilan,c.createdAt||0);
  return Date.now()-lastActivity<14*864e5;
}
function needsAlert(c){
  if(!c.bilans?.length) return !!c.questionnaireComplete;
  return Date.now()-c.bilans[c.bilans.length-1].date>14*864e5;
}
// Le signal ne retombe plus a la simple OUVERTURE du bilan mais a l'ECRITURE
// d'une reponse. Consequence assumee : un bilan lu sans reponse reste en
// alerte. C'est le but — repondre sur WhatsApp ne laissait aucune trace, et
// l'athlete ne voyait jamais rien revenir.
// seenBilans reste ecrit par ailleurs : il sert encore a distinguer un bilan
// jamais ouvert d'un bilan lu, ce que la fiche client affiche.
// PURE. Le bilan le plus RÉCENT, choisi par sa DATE et non par sa position.
//
// Rien ne garantit que `bilans` soit trié : _mergeUser le trie, les écritures
// locales non. Prendre le dernier élément du tableau ferait dépendre un signal
// d’un ordre que personne ne maintient — et un tri qui se relâche éteindrait
// le signal sans que rien ne le dise.
function dernierBilan(c){
  const l=(c&&c.bilans)||[];
  let der=null, dDer=-Infinity;
  for(const b of l){
    if(!b) continue;
    const d=Number(b.date);
    const v=Number.isFinite(d)?d:-Infinity;
    if(!der||v>=dDer){ der=b; dDer=v; }
  }
  return der;
}
// LE SIGNAL PORTE SUR LE DERNIER BILAN, PAS SUR L’HISTORIQUE ENTIER.
//
// « un bilan quelconque sans réponse » ne retombait jamais : un bilan de
// février resté sans réponse gardait le badge allumé et l’athlète dans « À
// traiter » même après dix réponses. Un signal qui ne s’éteint pas cesse
// d’être lu — et la fiche athlète, elle, affichait « Actif » au même moment.
//
// Ce qui reste dû sur les bilans PLUS ANCIENS est compté par
// bilansSansReponse, qui mesure une charge de travail et non une nouveauté :
// les deux notions sont distinctes et le restent.
function hasNewBilan(c){
  if(!c.bilans?.length||c._fromCode) return false;
  const der=dernierBilan(c);
  return !!der&&!der.reponseCoach;
}
// Athlète rattaché depuis plus de 3 jours qui n'a jamais rempli le moindre bilan.
// Utilisé à deux endroits (la ligne « À traiter » et urgencyScore) : un seul
// prédicat pour que le tri de la liste et l'alerte ne puissent pas diverger.
// createdAt absent (comptes antérieurs au champ) → traité comme ancien, donc signalé.
function neverStarted(c){
  return !c._fromCode&&!(c.bilans||[]).length&&(Date.now()-(c.createdAt||0))>3*864e5;
}

// ══════════ TROISIEME LISTE : « JAMAIS DEMARRE » ═══════════════════════
//
// ⚠ TROIS LISTES, TROIS NATURES, AUCUNE FUSION.
//   « A traiter »   — ce qui demande une decision : sante, bilans, acces.
//   « A relancer »  — l'assiduite, et elle seule (ecran s-coach-file).
//   « Jamais demarre » — celle-ci. Un athlete sans UNE SEULE seance n'a pas
//                    d'assiduite : il n'a rien dont on puisse mesurer le
//                    relachement. Il n'apparaissait donc nulle part.
//
// ET SURTOUT PAS DANS neverStarted, JUSTE AU-DESSUS. Celui-la compte les
// BILANS, pas les seances : un athlete qui a rempli son bilan de depart et
// n'a jamais ouvert une seance en sort — c'est exactement le trou. Les deux
// predicats se ressemblent et ne disent pas la meme chose ; ils restent
// separes, et aucune ligne de l'un n'est reecrite pour servir l'autre.
//
// CE QUE CETTE LISTE NE REGARDE PAS : la douleur, les drapeaux, l'assiduite,
// les programmes, le statut d'acces. Un seul fait — aucune seance — et un
// seul delai.
const JAMAIS_DEMARRE_DELAI=48*3600e3;

// PURE. La date d'entree de cet athlete dans le portefeuille du coach.
//
// ⚠ IL N'EXISTE AUCUNE DATE DE RATTACHEMENT DANS LE SCHEMA. Verifie le
// 15/09/2026 : ni linkToCoach, ni la consommation de code, ni le lien RCLINK
// n'ecrivent quand le lien s'est fait. `createdAt` est donc le seul repere
// disponible — et pour la grande majorite c'est le meme instant, un athlete
// se rattachant au moment ou il cree son compte.
// `coachSince` est lu D'ABORD pour que le jour ou ce champ existera, cette
// fonction devienne exacte sans qu'on y retouche. L'ecrire releverait du
// parcours ATHLETE, jamais du coach : le coach n'ecrit pas dans ce dossier.
function dateRattachement(c){
  if(!c) return 0;
  const s=Number(c.coachSince)||0;
  return s||Number(c.createdAt)||0;
}
/**
 * PURE. Le rang d'arrivee de cet athlete dans le portefeuille du coach, du
 * plus ancien au plus recent. Rend 0 quand la question n'a pas de sens.
 *
 * Kevin, 20/09/2026 : « mets "athlete n°__ : Kevin Guellec" selon son
 * arrivee ». Le rang se lit sur la carte d'identite, en tete de sa fiche.
 *
 * ⚠ LE RANG EST CALCULE, PAS STOCKE, et c'est un choix. Un numero ecrit dans
 *   le dossier serait plus stable — mais il faudrait l'attribuer a
 *   l'inscription, donc le faire exister pour les athletes deja la, donc
 *   deviner leur rang. Le calcul le donne tout de suite et pour tout le monde,
 *   au prix d'une consequence assumee : un athlete qui quitte le portefeuille
 *   fait remonter d'un cran tous ceux arrives apres lui.
 *
 * ⚠ LES INVITATIONS PAS ENCORE CONSOMMEES N'EN ONT PAS. Un code n'est arrive
 *   nulle part. Lui donner un rang aurait decale tout le monde le jour ou il
 *   expire sans etre utilise — et aurait numerote quelqu'un qui n'existe pas.
 *
 * ⚠ L'EGALITE SE TRANCHE PAR L'ADRESSE, et pas au hasard. Deux comptes creees
 *   dans la meme milliseconde — deux imports, une restauration — auraient
 *   sinon echange leurs numeros d'un rendu a l'autre, sous les yeux du coach.
 * @param {any} c          le dossier de l'athlete
 * @param {any[]} [clients] le portefeuille, si on l'a deja sous la main
 * @returns {number} le rang a partir de 1, ou 0
 */
function rangArrivee(c,clients){
  if(!c||c._fromCode) return 0;
  let liste=clients;
  if(!Array.isArray(liste)){ try{ liste=getClients(); }catch(e){ liste=[]; } }
  const vrais=(liste||[]).filter(x=>x&&!x._fromCode);
  vrais.sort((a,b)=>(dateRattachement(a)-dateRattachement(b))
    ||String(a.email||a.id||'').localeCompare(String(b.email||b.id||'')));
  const clef=x=>String((x&&(x.id||x.email))||'');
  const moi=clef(c);
  if(!moi) return 0;
  const i=vrais.findIndex(x=>clef(x)===moi);
  return i<0?0:i+1;
}
// PURE. Le nombre de jours REVOLUS depuis le rattachement.
function joursDepuisRattachement(c,maintenant){
  const d=dateRattachement(c);
  const t=Number(maintenant)||0;
  if(!d||!t||t<d) return 0;
  return Math.floor((t-d)/864e5);
}
// PURE. Le critere, et rien d'autre : rattache depuis plus de 48 h, aucune
// seance.
//
// ⚠ UNE DOULEUR OU UN DRAPEAU ROUGE N'ARRIVE JAMAIS ICI. Les deux gardent
// leur ligne dans « A traiter », qui est le seul endroit d'ou le coach ne
// peut pas les reporter d'un clic. Un drapeau se declare au questionnaire,
// donc SANS avoir jamais pose une seance : l'exclusion mord pour de vrai, et
// elle n'est pas decorative. Une douleur, elle, se declare en seance et ne
// peut pas coexister avec « aucune seance » — on l'ecarte quand meme, pour
// que la regle soit vraie par construction et non par chance.
//
// `_fromCode` EST EXCLU, et c'est important : ces dossiers-la sont des
// pastilles fabriquees par getClients depuis un code, avec `sessions:[]` pose
// en dur. Leur tableau vide n'est pas un fait, c'est un remplissage — les
// compter dirait « n'a jamais demarre » d'athletes qui s'entrainent peut-etre
// depuis un mois sur leur propre telephone. neverStarted les ecarte pour la
// meme raison.
function jamaisDemarre(c,maintenant){
  if(!c||c._fromCode||c.role==='coach') return false;
  if((c.sessions||[]).length) return false;
  try{ if(drapeauQuelconqueActif(c)) return false; }catch(e){}
  try{ const sg=signauxEntrainement(c); if(sg&&(sg.douleur||sg.douleurDiffuse)) return false; }catch(e){}
  const d=dateRattachement(c);
  const t=Number(maintenant)||0;
  if(!d||!t) return false;
  return (t-d)>JAMAIS_DEMARRE_DELAI;
}
// ══════════════ QUATRIEME LISTE : « INACTIFS » ═════════════════════════
//
// Demande de Kevin, 16/09/2026 : « les personnes inactives, ne les fais pas
// apparaitre dans les ronds ni dans la liste de mes athletes, mais seulement
// dans une liste en bas de page ».
//
// ⚠ QUATRE LISTES, QUATRE NATURES, TOUJOURS AUCUNE FUSION. Celle-ci s'insere
// entre « A traiter » et « Jamais demarre », et elle ne recouvre NI l'une NI
// l'autre :
//   « En attente »      — le compte n'existe pas encore (_fromCode).
//   « Jamais demarre »  — le compte existe, aucune seance n'a jamais ete posee.
//   « Inactifs »        — celle-ci. Le compte existe, l'athlete a DEJA pose au
//                         moins une seance, et plus rien depuis quatorze jours.
//
// LA SEANCE EST LA CONDITION D'ENTREE, et c'est elle qui rend les trois listes
// disjointes. Sans elle, tout athlete endormi aurait figure a la fois ici et
// dans « Jamais demarre » — deux lignes pour une personne, dans deux cadres qui
// disent deux choses differentes.
//
// ⚠ ET C'EST POURQUOI UN DRAPEAU ROUGE SANS SEANCE NE DISPARAIT PAS DE L'ECRAN.
// jamaisDemarre ecarte deja les drapeaux et les douleurs — ils restent dans
// « A traiter », le seul endroit d'ou le coach ne peut pas les reporter d'un
// clic. Si « inactif » avait accepte les dossiers sans seance, un athlete a
// drapeau rouge serait sorti de la grille sans entrer dans aucune des listes du
// bas : il aurait simplement cesse d'exister a l'ecran. La condition « au moins
// une seance » l'empeche par construction.
//
// QUATORZE JOURS, LE MEME DELAI QUE isActive, et ce n'est pas une coincidence :
// la puce « Actifs 14 j » de la barre de portefeuille compte exactement le
// complement. Deux delais differents pour la meme idee auraient fini par
// afficher « 8 actifs » au-dessus d'une liste de neuf.
const INACTIF_DELAI=14*864e5;
// PURE. Le dernier signe de vie : une seance, ou un bilan. PAS createdAt —
// isActive le compte, et il le doit, pour qu'un compte tout neuf ne soit pas
// declare mort avant d'avoir servi. Ici c'est l'inverse qu'on cherche : un
// compte neuf n'a pas de seance, il ne peut donc pas entrer dans cette liste,
// et compter sa date de creation n'aurait servi qu'a rajeunir indefiniment un
// dossier qui dort.
function dernierSigneDeVie(c){
  if(!c) return 0;
  const s=(c.sessions||[]).reduce((m,x)=>Math.max(m,(x&&Number(x.date))||0),0);
  const b=(c.bilans||[]).reduce((m,x)=>Math.max(m,(x&&Number(x.date))||0),0);
  return Math.max(s,b);
}
// PURE. Le critere, et rien d'autre : un compte, au moins une seance, et plus
// rien depuis quatorze jours.
function inactif(c,maintenant){
  if(!c||c._fromCode||c.role==='coach') return false;
  if(!(c.sessions||[]).length) return false;   // « jamais demarre » : autre liste
  const d=dernierSigneDeVie(c);
  const t=Number(maintenant)||0;
  if(!d||!t||t<d) return false;
  return (t-d)>INACTIF_DELAI;
}
// PURE. Du plus endormi au moins endormi : celui qu'on n'a pas vu depuis deux
// mois passe avant celui qui manque depuis quinze jours.
function listeInactifs(clients,maintenant){
  return (clients||[]).filter(c=>inactif(c,maintenant))
    .sort((a,b)=>dernierSigneDeVie(a)-dernierSigneDeVie(b));
}
// PURE. Le nombre de jours REVOLUS depuis le dernier signe de vie.
function joursDepuisSigne(c,maintenant){
  const d=dernierSigneDeVie(c);
  const t=Number(maintenant)||0;
  if(!d||!t||t<d) return 0;
  return Math.floor((t-d)/864e5);
}
// PURE. « En attente d'inscription » : quelqu'un que le coach a rattache par un
// code et qui n'a PAS encore cree son compte. C'est la SEULE famille que la
// grille de vignettes et la liste d'athletes laissent en bas de page.
//
// ⚠ « JAMAIS DEMARRE » N'EST PLUS DORMANT. Demande de Kevin, 18/09/2026 :
// remonter dans les ronds les gens qui se sont connectes, meme sans avoir
// commence a utiliser l'app, des lors qu'ils ont AU MOINS fait leur compte ;
// seuls ceux qui n'ont pas encore de compte restent en bas.
// Un compte cree EST une presence : la personne est entree, elle a un visage,
// un prenom et un age, et c'est precisement le moment ou le coach peut encore
// faire quelque chose. La masquer jusqu'a sa premiere seance revenait a la
// rendre invisible pendant la seule fenetre qui compte.
//
// LE DOUBLON EST ASSUME. Elle garde sa ligne dans le cadre « Jamais demarre »
// du bas, qui porte le bouton de relance et le nombre de jours depuis le
// rattachement — rien de tout cela ne tient dans un rond. Mieux vaut une
// arrivee sans premiere seance affichee deux fois qu'une seule, tout en bas.
//
// ⚠ L'INACTIF AUSSI REMONTE, DEPUIS LE 19/09/2026. La version du 18/09 le
// gardait en bas, en distinguant « qui n'a pas commence » de « qui s'est
// arrete ». Kevin a tranche le lendemain, devant la grille : « fais apparaitre
// tous les athletes qui ont cree leur compte, juste ne mets pas ceux en
// attente ». La distinction etait juste en soi, mais elle repondait a une
// autre question. La grille ne demande pas « qui dois-je regarder
// aujourd'hui » — les trois cadres du bas et « Mes notifications » s'en
// chargent. Elle demande « qui sont mes athletes », et quelqu'un qui s'est
// arrete en fait toujours partie : c'est meme souvent celui qu'on cherche.
//
// IL N'EN RESTE DONC QU'UNE FAMILLE DEHORS : l'invitation non honoree. Pas de
// dossier, pas de seance, pas de photo — son rond serait vide, sous un nom que
// personne ne porte encore.
//
// LE DOUBLON EST ASSUME, et il l'etait deja : jamais demarre comme inactif
// gardent leur ligne dans leur cadre du bas, qui porte le bouton de relance et
// le nombre de jours depuis le dernier signe. Rien de tout cela ne tient dans
// un rond.
//
// LE MEME PREDICAT SERT LA PUCE « En attente » ET CETTE EXCLUSION, et ce n'est
// pas un detail : ce que l'une cache, l'autre le montre. Les ecrire deux fois,
// c'etait se donner rendez-vous pour les voir diverger — la puce annoncant un
// nombre, la liste en montrant un autre.
function _enAttenteInscription(c){
  return !!(c&&(c._fromCode||!c.email));
}
// PURE. La liste, du plus ancien rattachement au plus recent : celui qui
// attend depuis douze jours passe avant celui qui attend depuis trois.
function listeJamaisDemarre(clients,maintenant){
  return (clients||[]).filter(c=>jamaisDemarre(c,maintenant))
    .sort((a,b)=>dateRattachement(a)-dateRattachement(b));
}
// PURE. Le brouillon propose au coach. Un BROUILLON : il s'ouvre dans la
// fenetre de redaction, il ne part pas tout seul, et le coach le reecrit s'il
// veut. Le prenom est insere tel quel — c'est la fenetre de redaction qui
// echappe, pas cette fonction, qui rend du texte et non du HTML.
function brouillonJamaisDemarre(c){
  const p=String((c&&c.fname)||'').trim();
  return 'Salut '+(p||'toi')+', j’ai vu que tu n’as pas encore lancé ta '
    +'première séance. Dis-moi ce qui bloque, on règle ça en deux minutes.';
}
// PURE. La carte, ou la chaine VIDE quand personne n'est concerne — jamais un
// cadre vide annoncant zero. Une liste de relance qui s'affiche a zero devient
// du decor, et on cesse de la lire le jour ou elle dit quelque chose.
//
// LE GRIS ET NON LE ROUGE. Ce n'est pas une alerte : personne n'a mal, rien
// n'est en retard. C'est une relance commerciale, et la peindre comme « A
// traiter » lui volerait l'attention que la sante doit garder.
/**
 * Le geste « Relancer » d'une carte : les deux canaux directs, pour UNE
 * personne.
 *
 * ⚠ CE CHEMIN NE PASSE PAS PAR LE TUNNEL COMMERCIAL, ET C'EST DELIBERE. Le
 *   tunnel compte les gens qui n'ont JAMAIS utilise leur acces
 *   (`tunnelPersonnes` ecarte tout nom deja inscrit) ; ceux-ci ont ouvert un
 *   compte. Brancher le bouton sur `tunnelRelancer` aurait ecrit des relances
 *   dans un dossier que `tunnelListe` ne rend jamais — le coach aurait
 *   enregistre dans le vide — et la quatrieme aurait DESACTIVE le code d'un
 *   athlete deja inscrit, donc ferme la porte a quelqu'un qui est deja entre.
 *
 * ⚠ ET IL NE PASSE PAS NON PLUS PAR LE CANAL. Le canal est lu par tous les
 *   athletes suivis : une relance s'adresse a une personne. C'est la regle
 *   posee le 19/09/2026, elle ne bouge pas parce que la carte a change de
 *   forme.
 * @param {string} id  l'identifiant de l'athlete
 */
function jdRelancer(id){
  const c=(getClients()||[]).find(x=>x&&String(x.id)===String(id));
  if(!c){ toast('Athlète introuvable','var(--orange)'); return false; }
  const k=canauxRelanceJamaisDemarre(c);
  const nom=String(((c.fname||'')+' '+(c.lname||'')).trim())||'cet athlète';
  const lien=(href,lib)=>'<a href="'+_safeContactUrl(href)+'" target="_blank" rel="noopener" '
    +'class="btn btn-blanc btn-sm" style="flex:1;margin:0;min-height:46px;display:flex;'
    +'align-items:center;justify-content:center">'+lib+'</a>';
  closeModal();
  document.body.insertAdjacentHTML('beforeend',
  '<div id="modal-overlay" onclick="closeModal()" style="position:fixed;inset:0;background:var(--scrim);z-index:var(--z-modal);display:flex;align-items:flex-end;justify-content:center">'
  +'<div onclick="event.stopPropagation()" role="dialog" aria-modal="true" style="background:var(--surface-2);border-radius:var(--r-4) var(--r-4) 0 0;padding:16px 20px 20px;width:100%;max-width:480px;max-height:88vh;overflow-y:auto">'
  +'<h2 style="margin-bottom:4px">Relancer</h2>'
  +'<div class="sub" style="font-size:var(--fs-xs);margin-bottom:14px">'+escapeHtml(nom)
  +' · compte créé, aucune séance</div>'
  // NI NUMERO NI ADRESSE : on le DIT. Deux boutons qui n'ouvrent rien feraient
  // croire a une panne, et le coach cliquerait deux fois avant de comprendre
  // que le manque est dans la fiche de l'athlete.
  +((k.wa||k.mail)
    ?'<div style="display:flex;gap:8px;margin-bottom:12px">'
      +(k.wa?lien(k.wa,'WhatsApp'):'')+(k.mail?lien(k.mail,'Mail'):'')+'</div>'
      +'<p class="sub" style="font-size:var(--fs-2xs);line-height:1.55;margin:0 0 14px">'
      +'Le message s’ouvre pré-rédigé et modifiable dans l’application choisie. '
      +'C’est toi qui appuies sur envoyer : RepCore n’envoie rien à ta place.</p>'
    :'<p class="sub" style="font-size:var(--fs-xs);line-height:1.6;margin:0 0 14px">'
      +'Cette fiche ne porte ni numéro ni adresse : RepCore ne peut ouvrir aucun '
      +'message. Ajoute-les depuis le profil de l’athlète.</p>')
  +'<button type="button" class="btn btn-outline btn-sm" style="width:100%;margin:0;min-height:44px" '
  +'onclick="closeModal()">Fermer</button>'
  +'</div></div>');
  return true;
}
function _htmlJamaisDemarre(liste,maintenant){
  const l=liste||[];
  if(!l.length) return '';
  const n=l.length;
  // HUIT RECTANGLES OUVERTS, LE RESTE REPLIE. Demande de Kevin, et c'est aussi
  // la regle deja posee pour « Mes notifications » : une carte d'accueil qui
  // deroule treize dossiers n'oriente plus rien.
  //
  // ⚠ REPLIE, ET NON RENVOYE AILLEURS. Le surplus se deplie SUR PLACE parce
  //   qu'aucun autre ecran ne montre cette population : le Tunnel commercial
  //   compte les gens qui n'ont JAMAIS utilise leur acces, et ceux-ci ont
  //   ouvert un compte. Un bouton « voir tout le tunnel » aurait mene a un
  //   ecran ou aucun d'eux ne figure.
  const MAX=8;
  const reste=Math.max(0,n-MAX);
  const jour=t=>{ if(!t) return '—'; const q=new Date(t), p=x=>String(x).padStart(2,'0');
    return p(q.getDate())+'/'+p(q.getMonth()+1)+'/'+q.getFullYear(); };
  return '<div style="background:var(--surface-1);border:1px solid var(--border);'
    +'border-left:3px solid var(--sub);border-radius:var(--r-card);margin-bottom:20px;'
    // ⚠ L'ESPACE AU-DESSUS, demande par Kevin : le bandeau « Jamais démarré »
    //   touchait le pied du cadre precedent, et les deux se lisaient comme un
    //   seul bloc dont on ne voyait plus la couture.
    +'margin-top:22px;'
    +'overflow:hidden;box-shadow:var(--el-1)">'
    +'<div style="padding:9px 14px;display:flex;align-items:center;justify-content:space-between;'
    +'gap:10px;background:var(--surface-2);border-bottom:1px solid var(--border)">'
    +'<span style="font-size:13px;font-weight:800;color:var(--text-strong);text-transform:uppercase;'
    +'letter-spacing:2.4px">Jamais démarré</span>'
    +'<span style="background:var(--surface-1);border:1px solid var(--border);color:var(--text);'
    +'font-size:14px;font-weight:400;padding:1px 9px;border-radius:var(--r-3);'
    +'font-family:var(--pile-titre);letter-spacing:1px">'+n+'</span>'
    +'</div>'
    +'<div class="jd-grille">'
    +l.map((c,rang)=>{
      const j=joursDepuisRattachement(c,maintenant);
      // XSS STOCKE : le prenom est saisi par l'athlete et atterrit dans le
      // tableau de bord de son coach. Meme precaution que renderTodoBlock, et
      // pour la meme raison — le defaut y avait ete trouve en testant des
      // prenoms hostiles.
      const nom=escapeHtml(String(((c.fname||'')+' '+(c.lname||'')).trim())||'Athlète');
      // LA DATE DE CREATION DU COMPTE, demandee explicitement. Ces gens SE SONT
      // INSCRITS — c'est ce qui les separe de « En attente » juste en dessous —
      // et la date qui les concerne est celle de leur compte, pas celle du code
      // qu'ils ont deja consomme.
      return '<div class="jd-carte'+(rang>=MAX?' jd-plus" hidden':'"')+'>'
        +'<div><div class="jd-nom" title="'+nom+'">'+nom+'</div>'
        +'<div class="jd-date">Compte créé<br>le '+jour(dateRattachement(c))
        +'<br>il y a '+j+' jour'+(j>1?'s':'')+'</div></div>'
        +'<div class="jd-cmd">'
        // UN SEUL GESTE, ET IL EST ROUGE. Demande de Kevin : c'est la seule
        // chose a faire pour quelqu'un qui a un compte et ne s'en sert pas.
        +'<button type="button" class="btn btn-red btn-sm" onclick="jdRelancer(\''+escapeHtml(String(c.id||''))+'\')">Relancer</button>'
        +'</div></div>';
    }).join('')
    +'</div>'
    +(reste?'<button type="button" onclick="jdVoirTout(this)" style="display:block;width:100%;background:none;border:none;'
      +'border-top:1px solid var(--border);color:var(--red-text);font-family:Montserrat,sans-serif;'
      +'font-size:var(--fs-2xs);font-weight:800;letter-spacing:1px;text-transform:uppercase;'
      +'cursor:pointer;padding:11px 14px;min-height:42px;text-align:left">+ '+reste+' autre'
      +(reste>1?'s':'')+' · tout afficher</button>':'')
    +'<div class="sub" style="font-size:var(--fs-2xs);line-height:1.55;padding:2px 14px 12px">'
    +'« Relancer » ouvre le message pré-rédigé, en WhatsApp ou par mail. RepCore n’envoie rien à ta place.'
    +'</div></div>';
}
// ⚠ AUCUN ENVOI, POUR LES DEUX CADRES. Les boutons OUVRENT WhatsApp ou le
// client mail avec le texte dedans, modifiable ; rien ne part tant que le
// coach n'a pas appuye sur « envoyer » lui-meme. Et aucun des deux chemins
// n'ecrit dans le dossier de l'athlete : ce sont des liens, pas des ecritures.
// ══ LE CADRE « INACTIFS » ═════════════════════════════════════════════════
//
// PURE. Le brouillon propose au coach. Un BROUILLON : il ouvre WhatsApp ou le
// client mail avec le texte dedans, modifiable, et rien ne part tant que le
// coach n'a pas appuye sur « envoyer » lui-meme.
//
// ⚠ AUCUN REPROCHE, ET C'EST UNE REGLE DU PRODUIT, pas une preference de ton.
// Le message ne dit pas « tu n'as rien fait depuis un mois » : il demande ce
// qui bloque et propose d'ajuster. Un athlete qui s'arrete a une raison, et
// elle est rarement la paresse.
//
// ⚠ ET IL NE PORTE AUCUNE DONNEE DE SANTE. Il parle de SEANCES et de temps, ni
// de poids, ni de douleur, ni de bilan — meme discipline que messageRelance et
// que le message d'acces qui expire.
function brouillonInactif(c,maintenant){
  const p=String((c&&c.fname)||'').trim();
  const j=joursDepuisSigne(c,maintenant||Date.now());
  // Le nombre de jours n'est dit QUE s'il est connu. « depuis 0 jour » serait
  // du bruit, et inventer une duree serait pire.
  const depuis=j>0?(' depuis '+j+' jour'+(j>1?'s':'')):'';
  return 'Salut '+(p||'toi')+', je n’ai pas vu de séance de ton côté'+depuis+'. '
    +'Aucun reproche — je veux juste savoir ce qui bloque : le temps, le '
    +'programme, la motivation ? Dis-moi, on ajuste ensemble.';
}
// Les objets de mail. Courts, et sans point d'interrogation anxieux dans la
// boite de reception.
// ══════════════ LE TUNNEL COMMERCIAL ═══════════════════════════════════════
//
// Relancer les gens qui ont RECU un acces et ne s'en sont jamais servis. Ce
// n'est pas de l'assiduite — ceux-la ne se sont pas arretes, ils n'ont jamais
// commence — et ce n'est pas du coaching : c'est du commercial, et ca se suit
// comme tel.
//
// ══ OU VIT LA DONNEE, ET POURQUOI LA ═══════════════════════════════════════
//
// DANS L'ENTREE DU CODE, `currentUser.studentCodes[i].crm`. Pas dans un noeud
// neuf, pas dans le dossier de l'athlete — qui n'existe pas encore, c'est tout
// le sujet. Trois raisons, et elles se cumulent :
//   • LE CODE EST DEJA LA SOURCE DE VERITE de cette population. getClients
//     fabrique les profils `_code_…` a partir de lui ; le tunnel compte donc
//     exactement les memes personnes, sans second predicat a faire diverger.
//   • IL SE SYNCHRONISE DEJA. `studentCodes` est dans la liste des champs
//     pousses du dossier coach : le tunnel suit le coach d'un appareil a
//     l'autre sans une ligne de reseau de plus.
//   • LA DESACTIVATION EST AU MEME ENDROIT. La quatrieme relance ferme le
//     code ; le compteur qui l'a declenchee et le drapeau `active` qu'elle
//     baisse sont deux champs voisins du meme objet.
//
// ⚠ AUCUNE DONNEE N'EST DETRUITE QUAND LE TUNNEL SE TERMINE. Le code passe a
//   `active:false` — l'acces ne s'ouvre plus — mais l'entree reste, avec ses
//   quatre relances, leurs canaux, leurs notes et leurs dates. Un dossier
//   commercial ferme reste un dossier commercial.
//
// ══ RETROCOMPATIBILITE ═════════════════════════════════════════════════════
//
// AUCUNE MIGRATION N'EST ECRITE, ET C'EST VOULU. `tunnelCrm` rend un objet
// complet pour une entree qui n'a jamais vu le tunnel : zero relance, aucune
// echeance, dossier ouvert. Un code cree il y a six mois entre donc dans le
// tunnel a 0/4 sans qu'on ait touche a un seul enregistrement — et un code
// qu'on n'ouvre jamais ne se voit jamais reecrit. Une migration aurait reecrit
// tous les dossiers coach pour y poser des objets vides.

/** Quatre relances, et c'est fini. La quatrieme ferme l'acces. */
const TUNNEL_MAX=4;
/**
 * PURE. Le statut commercial, DEDUIT du nombre de relances et de rien
 * d'autre. Il ne se regle pas a la main : deux coachs qui l'ajusteraient
 * chacun au juge ne compareraient plus rien.
 * @param {number} n  relances effectuees
 * @returns {'chaud'|'tiede'|'froid'|'fin'}
 */
function tunnelStatut(n){
  const k=Math.max(0,Math.min(TUNNEL_MAX,Math.round(Number(n)||0)));
  if(k>=TUNNEL_MAX) return 'fin';
  if(k>=3) return 'froid';
  if(k>=2) return 'tiede';
  return 'chaud';
}
/** Les libelles et les couleurs des quatre statuts, en un seul endroit. */
const TUNNEL_LIB=Object.freeze({
  chaud:{lib:'Chaud',c:'#E02020'},
  tiede:{lib:'Tiède',c:'#f5a524'},
  froid:{lib:'Froid',c:'#4DA3FF'},
  fin:{lib:'Fin du tunnel',c:'#8a8a8a'}});
/**
 * Les quatre canaux. `reel` dit si l'application sait VRAIMENT ouvrir l'envoi
 * — un lien WhatsApp ou un mailto pre-rempli — ou si elle ne fait
 * qu'enregistrer ce que le coach a fait de son cote. Voir tunnelValider : on
 * n'ecrit jamais « envoye » quand rien n'est parti.
 */
const TUNNEL_CANAUX=Object.freeze([
  {cle:'whatsapp',lib:'WhatsApp',reel:true},
  {cle:'email',   lib:'Email',   reel:true},
  {cle:'tel',     lib:'SMS / téléphone',reel:false},
  {cle:'push',    lib:'Notification RepCore',reel:false}]);
/**
 * PURE. Le dossier commercial d'une entree de code, TOUJOURS complet — une
 * entree qui n'a jamais vu le tunnel rend un dossier vierge plutot que null.
 * C'est ce qui rend la migration inutile.
 * @param {any} code  une entree de currentUser.studentCodes
 * @returns {{relances:any[], prochaine:number|null, termineLe:number|null}}
 */
function tunnelCrm(code){
  const k=(code&&code.crm&&typeof code.crm==='object')?code.crm:{};
  const l=Array.isArray(k.relances)?k.relances:[];
  // ⚠ BORNE A QUATRE A LA LECTURE AUSSI. Un dossier venu du reseau avec cinq
  //   relances — appareil en retard, reprise de sauvegarde — ne doit pas faire
  //   dire « 5/4 » ni sortir des quatre statuts.
  const relances=l.filter(x=>x&&typeof x==='object').slice(0,TUNNEL_MAX);
  const p=Number(k.prochaine);
  const t=Number(k.termineLe);
  return {relances,
    prochaine:(isFinite(p)&&p>0)?p:null,
    termineLe:(isFinite(t)&&t>0)?t:null};
}
/**
 * PURE. L'etat de l'echeance : rien de prevu, a venir, aujourd'hui, ou en
 * retard. Le jour se compare en JOURS CIVILS et non en millisecondes — une
 * relance prevue ce matin a 9 h n'est pas « en retard » a 10 h, elle est
 * d'aujourd'hui.
 * @param {number|null} prochaine
 * @param {number} maintenant
 * @returns {'aucune'|'avenir'|'aujourdhui'|'retard'}
 */
function tunnelEcheance(prochaine,maintenant){
  if(!prochaine) return 'aucune';
  const t=Number(maintenant)||Date.now();
  const j=x=>{ const q=new Date(x); return new Date(q.getFullYear(),q.getMonth(),q.getDate()).getTime(); };
  const jp=j(prochaine), jt=j(t);
  if(jp<jt) return 'retard';
  if(jp===jt) return 'aujourdhui';
  return 'avenir';
}
/**
 * PURE. Les personnes du tunnel, telles qu'on les affiche.
 *
 * ⚠ LE MEME PREDICAT DE POPULATION QUE getClients, a la lettre : un code dont
 *   l'eleve s'est inscrit n'est plus dans le tunnel, il est dans la liste des
 *   athletes. La liste des inscrits est passee en argument plutot que lue ici,
 *   pour que cette fonction reste PURE et testable hors application.
 *
 * ⚠ LES CODES DESACTIVES RESTENT, contrairement a getClients qui les ecarte.
 *   C'est le tunnel qui les a fermes a la quatrieme relance : les faire
 *   disparaitre effacerait le dossier commercial au moment precis ou il est
 *   complet. Ils sortent de la liste ACTIVE par `fini`, pas de la donnee.
 * @param {any} u  le dossier du coach
 * @param {any[]} athletes  ses athletes inscrits
 * @param {number} maintenant
 * @returns {any[]}
 */
function tunnelPersonnes(u,athletes,maintenant){
  const t=Number(maintenant)||Date.now();
  const inscrits=new Set((athletes||[]).filter(Boolean)
    .map(a=>((a.fname||'')+' '+(a.lname||'')).toLowerCase().trim()).filter(Boolean));
  const mails=new Set((athletes||[]).filter(Boolean)
    .map(a=>String(a.email||'').toLowerCase()).filter(Boolean));
  const out=[];
  for(const c of ((u&&u.studentCodes)||[])){
    if(!c||!c.codeId) continue;
    const nom=String(c.studentName||'').toLowerCase().trim();
    // DEJA INSCRIT : il a utilise son acces, il n'a plus rien a faire ici.
    if(nom&&inscrits.has(nom)) continue;
    if(!nom&&c.athleteEmail&&mails.has(String(c.athleteEmail).toLowerCase())) continue;
    const k=tunnelCrm(c);
    const n=k.relances.length;
    const fini=n>=TUNNEL_MAX;
    const libelle=String(c.studentName||c.usedBy||c.athleteEmail||'Élève sans nom').trim();
    out.push({
      codeId:c.codeId, code:c, id:'_code_'+c.codeId,
      fname:libelle.split(' ')[0],
      lname:libelle.split(' ').slice(1).join(' '),
      nom:libelle,
      email:String(c.athleteEmail||''),
      tel:String(c.athletePhone||c.phone||''),
      photo:String(c.athletePhoto||''),
      nb:n, statut:tunnelStatut(n), fini,
      derniere:n?(Number(k.relances[n-1].date)||0):0,
      prochaine:k.prochaine,
      // UN DOSSIER TERMINE N'A PLUS D'ECHEANCE : laisser « en retard » sur
      // quelqu'un qu'on ne relancera plus le ferait remonter chaque jour.
      echeance:fini?'aucune':tunnelEcheance(k.prochaine,t),
      actif:c.active!==false,
      relances:k.relances, termineLe:k.termineLe,
      ajouteLe:Number(c.createdAt)||0});
  }
  return out;
}
/**
 * PURE. Le resume affiche sur l'accueil et en tete du tunnel. Les dossiers
 * termines sont comptes A PART : ils ne sont plus a relancer, et les melanger
 * au total ferait annoncer douze personnes pour trois a traiter.
 * @param {any[]} liste
 * @returns {any}
 */
function tunnelResume(liste){
  const l=(liste||[]).filter(Boolean);
  const actifs=l.filter(p=>!p.fini);
  return {
    total:actifs.length,
    chauds:actifs.filter(p=>p.statut==='chaud').length,
    tiedes:actifs.filter(p=>p.statut==='tiede').length,
    froids:actifs.filter(p=>p.statut==='froid').length,
    aujourdhui:actifs.filter(p=>p.echeance==='aujourdhui').length,
    retard:actifs.filter(p=>p.echeance==='retard').length,
    termines:l.length-actifs.length};
}
/**
 * PURE. La phrase de l'accueil. Elle dit ce qu'il y a A FAIRE, pas ce qu'il y
 * a en stock : « 12 personnes » ne fait pas ouvrir un ecran, « 3 relances
 * aujourd'hui » si.
 * @param {any} r  un resume
 * @returns {string}
 */
function tunnelPhrase(r){
  const du=(r.aujourdhui||0)+(r.retard||0);
  if(!r.total){
    return r.termines
      ? ('Personne à relancer · '+r.termines+' dossier'+(r.termines>1?'s':'')+' terminé'+(r.termines>1?'s':''))
      : 'Personne à relancer.';
  }
  if(!du) return 'Aucune relance à effectuer.';
  const bouts=[];
  if(r.retard) bouts.push(r.retard+' en retard');
  if(r.aujourdhui) bouts.push(r.aujourdhui+' aujourd’hui');
  return du+' relance'+(du>1?'s':'')+' à effectuer : '+bouts.join(' · ')+'.';
}

// ══ LES GESTES DU TUNNEL ═══════════════════════════════════════════════════

/** L'entree de code d'une personne du tunnel, ou null. */
function _tunnelCode(codeId){
  if(!currentUser) return null;
  return ((currentUser.studentCodes)||[]).find(c=>c&&c.codeId===codeId)||null;
}
/** Ecrit le dossier coach et le pousse. Un seul chemin pour les trois gestes. */
function _tunnelEcrire(){
  currentUser.updatedAt=Date.now();
  const users=DB.get('users')||{};
  users[currentUser.email]=currentUser;
  const ok=DB.set('users',users);
  try{ DB.set('session',currentUser); }catch(e){}
  return {ok,envoi:CLOUD.pushOne(currentUser.email,currentUser)};
}
/**
 * ⚠ LE VERROU CONTRE LE DOUBLE APPUI. Une relance s'ecrit, se pousse au
 *   reseau, et ferme parfois un code a distance : entre le premier appui et le
 *   rendu qui suit, il y a de la place pour un second. Sans ce verrou, deux
 *   appuis rapides faisaient passer quelqu'un de 2/4 a 4/4 — et fermaient son
 *   acces deux relances trop tot.
 *   UN VERROU PAR PERSONNE, et non un verrou global : le coach qui enchaine
 *   trois relances sur trois personnes differentes ne doit pas attendre.
 */
const _tunnelEnCours=new Set();
/**
 * ⚠ LA CLEF SE REND APRES UN DELAI, ET C'EST TOUT L'INTERET DU VERROU.
 *   Le chemin d'une relance ordinaire est ENTIEREMENT SYNCHRONE : rendre la
 *   clef dans le `finally` la rendait avant meme que le second appui n'arrive,
 *   et le verrou ne protegeait de rien. Mesure au banc : deux validations
 *   enchainees faisaient passer quelqu'un de 0/4 a 2/4, puis a 4/4 — donc
 *   fermer son acces deux relances trop tot, et perdre la note du premier
 *   appui parce que la feuille etait deja refermee quand le second la lisait.
 *   Sept cents millisecondes couvrent le double-tap ; personne n'enregistre
 *   deux relances reelles dans cet intervalle.
 */
const TUNNEL_VERROU_MS=700;
/**
 * La feuille de relance : le canal, puis la note. Deux etapes dans la meme
 * feuille — c'est un geste que le coach repete dix fois par jour, et deux
 * fenetres l'auraient double.
 * @param {string} codeId
 */
function tunnelRelancer(codeId){
  const c=_tunnelCode(codeId);
  if(!c){ toast('Dossier introuvable','var(--orange)'); return false; }
  const k=tunnelCrm(c), n=k.relances.length;
  // ⚠ PAS DE CINQUIEME RELANCE. Le dossier est clos, l'acces est ferme :
  //   rouvrir la feuille laisserait croire qu'on peut encore agir.
  if(n>=TUNNEL_MAX){ toast('Tunnel terminé : ce dossier ne se relance plus.','var(--orange)'); return false; }
  const nom=String(c.studentName||c.athleteEmail||'cette personne').trim();
  const rang=n+1;
  const dernier=rang===TUNNEL_MAX;
  closeModal();
  document.body.insertAdjacentHTML('beforeend',
  '<div id="modal-overlay" onclick="closeModal()" style="position:fixed;inset:0;background:var(--scrim);z-index:var(--z-modal);display:flex;align-items:flex-end;justify-content:center">'
  +'<div onclick="event.stopPropagation()" role="dialog" aria-modal="true" style="background:var(--surface-2);border-radius:var(--r-4) var(--r-4) 0 0;padding:16px 20px 20px;width:100%;max-width:480px;max-height:88vh;overflow-y:auto">'
  +'<h2 style="margin-bottom:4px">Relance '+rang+'/'+TUNNEL_MAX+'</h2>'
  +'<div class="sub" style="font-size:var(--fs-xs);margin-bottom:14px">'+escapeHtml(nom)+'</div>'
  // ⚠ LA DERNIERE TENTATIVE SE DIT AVANT, PAS APRES. Fermer un acces est
  //   irreversible du point de vue de la personne : elle ne peut plus entrer.
  +(dernier?'<div style="background:var(--surface-1);border:1px solid var(--orange);border-left:3px solid var(--orange);border-radius:var(--r-2);padding:10px 12px;margin-bottom:14px;font-size:var(--fs-xs);line-height:1.55;color:var(--text-strong)">'
      +'<strong>Dernière tentative.</strong> En validant, le dossier passe en fin de tunnel et le code d’accès de '
      +escapeHtml(nom)+' est désactivé. L’historique des quatre relances est conservé.</div>':'')
  +'<div class="ml-lab" style="margin-bottom:6px">Canal utilisé</div>'
  +'<div id="tun-canaux" style="display:grid;grid-template-columns:repeat(auto-fit,minmax(140px,1fr));gap:6px;margin-bottom:6px">'
  +TUNNEL_CANAUX.map((x,i)=>'<button type="button" class="btn btn-blanc btn-sm tun-c'+(i?'':' actif')+'" data-canal="'+x.cle+'"'
     +' onclick="tunnelChoisirCanal(this)" style="min-height:40px;padding:8px 10px;letter-spacing:.3px">'+escapeHtml(x.lib)+'</button>').join('')
  +'</div>'
  // ⚠ ON N'ECRIT JAMAIS « ENVOYE ». RepCore n'envoie rien ici : il enregistre
  //   ce que le coach a fait de son cote. Les deux canaux qui SAVENT ouvrir un
  //   message pre-rempli le proposent par un lien ; les deux autres non.
  +'<p class="sub" id="tun-avis" style="font-size:var(--fs-2xs);line-height:1.5;margin:0 0 8px"></p>'
  // ⚠ CE LIEN EST LA SEULE CHOSE QUI ENVOIE VRAIMENT — et encore, il ne fait
  //   qu'OUVRIR le message pre-rempli dans WhatsApp ou le client mail, ou le
  //   coach appuie lui-meme sur « envoyer ». Valider, en dessous, n'envoie
  //   rien : ca enregistre l'action. Les deux gestes sont separes a l'ecran
  //   parce qu'ils sont separes en fait.
  +'<div id="tun-ouvrir" style="margin-bottom:12px"></div>'
  +'<div class="ml-lab" style="margin-bottom:6px">Note (facultative)</div>'
  +'<textarea id="tun-note" rows="3" maxlength="400" placeholder="WhatsApp envoyé — rappel de l’activation RepCore."'
  +' style="width:100%;background:var(--surface-1);border:1px solid var(--border);border-radius:var(--r-2);color:var(--text);padding:10px;font-family:Montserrat,sans-serif;font-size:var(--fs-sm);resize:vertical;margin-bottom:14px"></textarea>'
  +'<div style="display:flex;gap:8px">'
  +'<button type="button" class="btn btn-outline btn-sm" style="flex:1;margin:0;min-height:44px" onclick="closeModal()">Annuler</button>'
  +'<button type="button" id="tun-valider" class="btn btn-red btn-sm" style="flex:1;margin:0;min-height:44px" onclick="tunnelValider(\''+escapeHtml(codeId)+'\')">Enregistrer la relance</button>'
  +'</div></div></div>');
  // L'avis a besoin de savoir DE QUI il parle pour proposer le bon lien. Le
  // codeId voyage sur le noeud plutot qu'en variable globale : deux feuilles
  // ouvertes coup sur coup ne peuvent pas se melanger.
  const _p=document.getElementById('tun-avis');
  if(_p) _p.dataset.code=codeId;
  _tunnelMajAvis();
  return true;
}
/** Un seul canal a la fois. */
function tunnelChoisirCanal(b){
  const z=document.getElementById('tun-canaux');
  if(!z||!b) return false;
  z.querySelectorAll('.tun-c').forEach(x=>x.classList.toggle('actif',x===b));
  _tunnelMajAvis();
  return true;
}
/** Le canal choisi, ou le premier par defaut. */
function _tunnelCanalChoisi(){
  const a=document.querySelector('#tun-canaux .tun-c.actif');
  return a?String(a.dataset.canal||''):TUNNEL_CANAUX[0].cle;
}
/**
 * ⚠ LA PHRASE DIT LA VERITE SUR L'ENVOI. « Action enregistrée » n'est pas
 *   « message envoyé », et le coach doit savoir lequel des deux il obtient.
 */
function _tunnelMajAvis(){
  const p=document.getElementById('tun-avis');
  const z=document.getElementById('tun-ouvrir');
  if(!p) return;
  const cle=_tunnelCanalChoisi();
  const c=TUNNEL_CANAUX.find(x=>x.cle===cle);
  const code=_tunnelCode(String(p.dataset.code||''));
  const k=code?tunnelCanaux(code):{wa:'',mail:''};
  const lien=cle==='whatsapp'?k.wa:cle==='email'?k.mail:'';
  if(z){
    z.innerHTML=lien
      ? '<a href="'+_safeContactUrl(lien)+'" target="_blank" rel="noopener" class="btn btn-blanc btn-sm"'
        +' style="width:100%;margin:0;min-height:40px;display:flex;align-items:center;justify-content:center">'
        +'Ouvrir '+(cle==='whatsapp'?'WhatsApp':'le mail')+' pré-rempli</a>'
      : '';
  }
  p.textContent=(c&&c.reel)
    ? (lien
       ? 'Le bouton ci-dessous OUVRE le message pré-rempli ; c’est toi qui appuies sur envoyer. Valider, en dessous, enregistre seulement l’action.'
       : (cle==='whatsapp'?'Aucun numéro sur cette fiche : RepCore ne peut pas ouvrir WhatsApp.'
                          :'Aucune adresse sur cette fiche : RepCore ne peut pas ouvrir le mail.')
         +' L’action est enregistrée telle que tu l’as faite de ton côté.')
    : 'RepCore n’envoie pas par ce canal. L’action est enregistrée telle que tu l’as faite de ton côté.';
}
/**
 * Valider la relance : elle s'ajoute, le compteur monte, le statut suit, et la
 * quatrieme ferme l'acces.
 * @param {string} codeId
 * @returns {Promise<boolean>}
 */
async function tunnelValider(codeId){
  if(_tunnelEnCours.has(codeId)) return false;
  const c=_tunnelCode(codeId);
  if(!c) return false;
  const k=tunnelCrm(c);
  // ⚠ LE PLAFOND EST RELU ICI, et non seulement a l'ouverture de la feuille :
  //   entre les deux, un autre appareil a pu pousser une quatrieme relance.
  if(k.relances.length>=TUNNEL_MAX){ closeModal(); toast('Tunnel déjà terminé.','var(--orange)'); return false; }
  _tunnelEnCours.add(codeId);
  const b=document.getElementById('tun-valider');
  if(b instanceof HTMLButtonElement){ b.disabled=true; b.textContent='Enregistrement…'; }
  try{
    const canal=_tunnelCanalChoisi();
    const note=String((document.getElementById('tun-note')||{}).value||'').trim().slice(0,400);
    const rang=k.relances.length+1;
    const relance={n:rang,date:Date.now(),canal,note,
      // LE COACH QUI A FAIT LE GESTE. Un cabinet a plusieurs coachs relit son
      // historique et doit savoir qui a appele.
      par:String((currentUser&&currentUser.email)||'')};
    // ⚠ ON N'ECRASE JAMAIS : on ajoute. L'historique est la seule trace de ce
    //   qui a ete tente, et il ne se reecrit pas.
    c.crm={relances:k.relances.concat([relance]),
      prochaine:null,   // l'echeance est consommee ; on en proposera une neuve
      termineLe:k.termineLe};
    const fini=rang>=TUNNEL_MAX;
    if(fini) c.crm.termineLe=Date.now();
    const {ok,envoi}=_tunnelEcrire();
    closeModal();
    if(fini){
      // LA FERMETURE PASSE PAR LE CHEMIN EXISTANT, et par lui seul : le noeud
      // distant d'abord, le drapeau local ensuite. C'est deja la regle de
      // toggleStudentCode — « un code annonce ferme continuait d'ouvrir
      // l'acces, avec un coach persuade du contraire ».
      const ferme=await _tunnelFermerAcces(c);
      tunnelRendre();
      toast(ferme
        ? 'Relance 4/4 · tunnel terminé, accès désactivé.'
        : 'Relance 4/4 enregistrée, mais l’accès n’a PAS pu être désactivé : vérifie la connexion, puis ferme le code à la main.',
        ferme?'var(--green)':'var(--orange)');
      return true;
    }
    tunnelRendre();
    toastSync(ok,envoi,'Relance '+rang+'/'+TUNNEL_MAX+' enregistrée','la relance est');
    // ⚠ LA PLANIFICATION SUIT IMMEDIATEMENT. Une relance sans prochaine date
    //   sort du radar : elle n'a plus d'echeance, donc plus rien ne la fait
    //   remonter. C'est exactement comme cela qu'on perd un dossier.
    setTimeout(()=>{ try{ tunnelPlanifier(codeId,true); }catch(e){} },260);
    return true;
  } finally {
    setTimeout(()=>{ try{ _tunnelEnCours.delete(codeId); }catch(e){} },TUNNEL_VERROU_MS);
  }
}
/**
 * Ferme l'acces au bout du tunnel. Rend true seulement si le noeud distant a
 * SUIVI : un code annonce ferme qui continue d'ouvrir l'acces est pire que
 * pas de fermeture du tout.
 * @param {any} c
 * @returns {Promise<boolean>}
 */
async function _tunnelFermerAcces(c){
  if(c.active===false) return true;          // deja ferme : rien a faire
  // Un code trop ancien n'a pas de jeton, donc pas de noeud a fermer. On le
  // DIT plutot que de laisser croire a une fermeture.
  if(!c.token) return false;
  let distant=false;
  try{ distant=await _majActifDistant(c.token,false); }catch(e){ distant=false; }
  if(!distant) return false;
  c.active=false;
  _tunnelEcrire();
  return true;
}
/**
 * Planifier — ou replanifier — la prochaine relance.
 *
 * ⚠ AUCUNE ECRITURE DANS L'HISTORIQUE. Replanifier n'est pas relancer : le
 *   coach qui decale un rendez-vous trois fois ne doit pas apparaitre avec
 *   trois relances faites. L'historique est reserve a ce qui a ete TENTE.
 * @param {string} codeId
 * @param {boolean} [apresRelance]  ouvre la feuille juste apres une relance
 */
function tunnelPlanifier(codeId,apresRelance){
  const c=_tunnelCode(codeId);
  if(!c) return false;
  const k=tunnelCrm(c);
  if(k.relances.length>=TUNNEL_MAX){ toast('Tunnel terminé : plus rien à planifier.','var(--orange)'); return false; }
  const nom=String(c.studentName||c.athleteEmail||'cette personne').trim();
  // PAR DEFAUT DANS TROIS JOURS, a dix heures : une proposition qu'on accepte
  // d'un geste vaut mieux qu'un champ vide qu'il faut remplir deux fois.
  const base=k.prochaine?new Date(k.prochaine):(()=>{ const q=new Date(); q.setDate(q.getDate()+3); q.setHours(10,0,0,0); return q; })();
  const p2=x=>String(x).padStart(2,'0');
  const dISO=base.getFullYear()+'-'+p2(base.getMonth()+1)+'-'+p2(base.getDate());
  const hISO=p2(base.getHours())+':'+p2(base.getMinutes());
  closeModal();
  document.body.insertAdjacentHTML('beforeend',
  '<div id="modal-overlay" onclick="closeModal()" style="position:fixed;inset:0;background:var(--scrim);z-index:var(--z-modal);display:flex;align-items:flex-end;justify-content:center">'
  +'<div onclick="event.stopPropagation()" role="dialog" aria-modal="true" style="background:var(--surface-2);border-radius:var(--r-4) var(--r-4) 0 0;padding:16px 20px 20px;width:100%;max-width:480px">'
  +'<h2 style="margin-bottom:4px">'+(k.prochaine?'Replanifier':'Prochaine relance')+'</h2>'
  +'<div class="sub" style="font-size:var(--fs-xs);margin-bottom:14px">'+escapeHtml(nom)
  +(apresRelance?' · relance '+k.relances.length+'/'+TUNNEL_MAX+' enregistrée':'')+'</div>'
  +'<div style="display:flex;gap:8px;margin-bottom:14px">'
  +'<label style="flex:1"><span class="ml-lab" style="display:block;margin-bottom:5px">Date</span>'
  +'<input type="date" id="tun-date" value="'+dISO+'" style="width:100%;background:var(--surface-1);border:1px solid var(--border);border-radius:var(--r-2);color:var(--text);padding:10px;font-family:Montserrat,sans-serif;font-size:var(--fs-sm)"></label>'
  +'<label style="flex:0 0 120px"><span class="ml-lab" style="display:block;margin-bottom:5px">Heure</span>'
  +'<input type="time" id="tun-heure" value="'+hISO+'" style="width:100%;background:var(--surface-1);border:1px solid var(--border);border-radius:var(--r-2);color:var(--text);padding:10px;font-family:Montserrat,sans-serif;font-size:var(--fs-sm)"></label>'
  +'</div>'
  +'<div style="display:flex;gap:8px">'
  +'<button type="button" class="btn btn-outline btn-sm" style="flex:1;margin:0;min-height:44px" onclick="closeModal()">'
  +(apresRelance?'Plus tard':'Annuler')+'</button>'
  +'<button type="button" class="btn btn-red btn-sm" style="flex:1;margin:0;min-height:44px" onclick="tunnelPoserEcheance(\''+escapeHtml(codeId)+'\')">Planifier</button>'
  +'</div></div></div>');
  return true;
}
/** Pose l'echeance choisie. Elle seule bouge — l'historique ne change pas. */
function tunnelPoserEcheance(codeId){
  const c=_tunnelCode(codeId);
  if(!c) return false;
  const jd=String((document.getElementById('tun-date')||{}).value||'');
  const jh=String((document.getElementById('tun-heure')||{}).value||'10:00');
  if(!/^\d{4}-\d{2}-\d{2}$/.test(jd)){ toast('Choisis une date.','var(--orange)'); return false; }
  const t=new Date(jd+'T'+(/^\d{2}:\d{2}$/.test(jh)?jh:'10:00')).getTime();
  if(!isFinite(t)){ toast('Date illisible.','var(--orange)'); return false; }
  const k=tunnelCrm(c);
  c.crm={relances:k.relances,prochaine:t,termineLe:k.termineLe};
  const {ok,envoi}=_tunnelEcrire();
  closeModal();
  tunnelRendre();
  toastSync(ok,envoi,'Prochaine relance : '+_tunnelQuand(t),'l’échéance est');
  return true;
}
/** PURE-ish. « 23/09 à 10:00 » — la forme courte qu'on lit sur une carte. */
function _tunnelQuand(t){
  if(!t) return '';
  const q=new Date(t), p2=x=>String(x).padStart(2,'0');
  return p2(q.getDate())+'/'+p2(q.getMonth()+1)+' à '+p2(q.getHours())+':'+p2(q.getMinutes());
}

// ══ L'ECRAN DU TUNNEL ══════════════════════════════════════════════════════

/** Le filtre et le tri ne sont pas enregistres : ce sont des gestes de lecture. */
let _tunFiltre='tous';
let _tunTri='prochaine';
/** Les filtres, dans l'ordre ou on les touche : d'abord ce qui presse. */
const TUNNEL_FILTRES=Object.freeze([
  ['retard','En retard'],['aujourdhui','Aujourd’hui'],['tous','Tous'],
  ['chaud','Chaud'],['tiede','Tiède'],['froid','Froid'],['fini','Tunnel terminé']]);
const TUNNEL_TRIS=Object.freeze([
  ['prochaine','Prochaine relance'],['derniere','Dernière relance'],
  ['nb','Nombre de relances'],['nom','Nom']]);
/** Ouvre le tunnel. */
/**
 * Le resume de la carte d'accueil. Il dit d'abord ce qu'il y a A FAIRE — une
 * relance en retard fait ouvrir l'ecran, « 12 personnes » non — puis la
 * repartition, qui dit ou en est le portefeuille.
 * @param {any[]} [clients]  les athletes deja calcules, pour ne pas les relire
 */
function _majResumeTunnel(clients){
  const z=document.getElementById('ch-tunnel-resume');
  if(!z||!currentUser) return false;
  let ath=clients;
  if(!Array.isArray(ath)){ try{ ath=getClients()||[]; }catch(e){ ath=[]; } }
  const r=tunnelResume(tunnelPersonnes(currentUser,ath.filter(c=>c&&!c._fromCode),Date.now()));
  const bouts=[];
  if(r.total) bouts.push(r.total+' personne'+(r.total>1?'s':''));
  const rep=[];
  if(r.chauds) rep.push(r.chauds+' chaud'+(r.chauds>1?'s':''));
  if(r.tiedes) rep.push(r.tiedes+' tiède'+(r.tiedes>1?'s':''));
  if(r.froids) rep.push(r.froids+' froid'+(r.froids>1?'s':''));
  if(rep.length) bouts.push(rep.join(' · '));
  z.textContent=tunnelPhrase(r)+(bouts.length?'  —  '+bouts.join('  ·  '):'');
  return true;
}
function tunnelOuvrir(){
  go('s-coach-tunnel');
  tunnelRendre();
  return true;
}
/** @param {string} f */
function tunnelSetFiltre(f){ _tunFiltre=TUNNEL_FILTRES.some(x=>x[0]===f)?f:'tous'; tunnelRendre(); return true; }
/**
 * Le filtre des tuiles : il BASCULE. Toucher celle qui est deja active la
 * relache et rend la liste entiere.
 *
 * ⚠ C'EST CE QUI REMPLACE LE BOUTON « TOUS », retire avec sa barre le
 *   20/09/2026. Sans bascule, trois tuiles seules auraient enferme le coach
 *   dans un statut sans aucun moyen d'en sortir.
 * @param {string} f
 */
function tunnelBasculer(f){ return tunnelSetFiltre(_tunFiltre===f?'tous':f); }
/** @param {string} t */
function tunnelSetTri(t){ _tunTri=TUNNEL_TRIS.some(x=>x[0]===t)?t:'prochaine'; tunnelRendre(); return true; }
/**
 * PURE. Le filtre et le tri appliques a une liste. Sortie de la fonction de
 * rendu pour qu'une assertion puisse la verifier sans peindre un ecran.
 * @param {any[]} liste
 * @param {string} filtre
 * @param {string} tri
 * @returns {any[]}
 */
function tunnelVue(liste,filtre,tri){
  const l=(liste||[]).filter(Boolean);
  // ⚠ « TOUS » NE VEUT PAS DIRE « Y COMPRIS LES TERMINES ». Un dossier clos
  //   n'est plus a relancer : le melanger aux autres ferait chercher parmi des
  //   gens qu'on ne rappellera jamais. Il a son propre filtre.
  const v=filtre==='fini'?l.filter(p=>p.fini):l.filter(p=>!p.fini).filter(p=>
      filtre==='tous'?true
    : filtre==='retard'?p.echeance==='retard'
    : filtre==='aujourdhui'?p.echeance==='aujourdhui'
    : p.statut===filtre);
  const parNom=(a,b)=>String(a.nom||'').localeCompare(String(b.nom||''),'fr');
  if(tri==='nom') return v.sort(parNom);
  if(tri==='nb') return v.sort((a,b)=>b.nb-a.nb||parNom(a,b));
  if(tri==='derniere') return v.sort((a,b)=>b.derniere-a.derniere||parNom(a,b));
  // PAR PROCHAINE RELANCE, ET C'EST LE DEFAUT : c'est la question que le coach
  // se pose en ouvrant l'ecran. ⚠ SANS ECHEANCE PASSE EN DERNIER, et non en
  // premier : `null` vaudrait zero, et les dossiers qu'on n'a pas encore
  // planifies coifferaient ceux qui sont en retard depuis trois jours.
  return v.sort((a,b)=>(a.prochaine||Infinity)-(b.prochaine||Infinity)||parNom(a,b));
}
/** La liste du tunnel, telle que l'application la voit. */
function tunnelListe(){
  let ath=[];
  try{ ath=(getClients()||[]).filter(c=>c&&!c._fromCode); }catch(e){ ath=[]; }
  return tunnelPersonnes(currentUser,ath,Date.now());
}
/**
 * PURE. Un buste et une tete, PLEINS.
 *
 * ⚠ ELLE N'ENTRE PAS DANS `ICONS`, ET C'EST VOULU. Tout ce jeu est dessine au
 *   TRAIT — `icon()` rend `fill="none" stroke="currentColor"` — et une
 *   silhouette est par definition une forme PLEINE. L'y mettre l'aurait rendue
 *   creuse, c'est-a-dire tout sauf une silhouette ; et changer `icon()` pour
 *   elle aurait touche les cinquante autres.
 *
 * `currentColor` : elle prend la teinte de la tuile qui la porte, sans qu'on
 * ait a la lui passer.
 * @param {number} px
 */
function _htmlSilhouette(px){
  const t=Number(px)||30;
  return '<svg viewBox="0 0 24 24" fill="currentColor" aria-hidden="true" '
    +'style="width:'+t+'px;height:'+t+'px;display:block">'
    +'<circle cx="12" cy="7.1" r="4.3"/>'
    +'<path d="M12 12.9c-4.5 0-7.8 2.7-7.8 6.3 0 .9.7 1.6 1.6 1.6h12.4c.9 0 1.6-.7 1.6-1.6 0-3.6-3.3-6.3-7.8-6.3z"/>'
    +'</svg>';
}
function tunnelRendre(){
  const z=document.getElementById('tun-body');
  if(!z||!currentUser) return false;
  const tout=tunnelListe();
  const r=tunnelResume(tout);
  const vue=tunnelVue(tout,_tunFiltre,_tunTri);
  // ⚠ LA TUILE EST LE FILTRE. Demande de Kevin, 20/09/2026 : « seuls les carres
  //   sont cliquables ». Elle BASCULE — retoucher celle qui est active relache
  //   le filtre et rend la liste entiere. Sans ce relachement, trois tuiles
  //   sans bouton « Tous » auraient enferme le coach dans un statut.
  const stat=(cle,n,lib,c)=>'<button type="button" class="tun-stat'
    +(_tunFiltre===cle?' actif':'')+'" style="--c:'+c+'"'
    +' aria-pressed="'+(_tunFiltre===cle)+'" onclick="tunnelBasculer(\''+cle+'\')">'
    +'<div class="tun-sil">'+_htmlSilhouette(34)+'</div>'
    +'<b>'+n+'</b><span>'+lib+'</span></button>';
  // ⚠ LES DEUX BARRES SONT RETIREES, demande de Kevin — sauf UNE porte, et elle
  //   ne s'ouvre que s'il y a quelque chose derriere. « Tous » excluait deja les
  //   dossiers TERMINES : `tunnelVue` le dit en toutes lettres, un dossier clos
  //   n'est plus a relancer. Son filtre etait donc le SEUL chemin vers eux, et
  //   le build 1314 promet noir sur blanc qu'ils « se relisent dans le filtre
  //   Tunnel terminé ». Le supprimer sans rien aurait rendu ces dossiers — leurs
  //   quatre relances, leurs canaux, leurs notes — definitivement invisibles.
  //   La ligne n'apparait donc QUE s'il en existe : a zero, l'ecran est celui
  //   que Kevin a demande, sans rien de plus.
  const fini=(r.termines>0)
    ? '<div class="tun-fini"><button type="button" class="tun-fini-b'
      +(_tunFiltre==='fini'?' actif':'')+'" onclick="tunnelBasculer(\'fini\')">'
      +(_tunFiltre==='fini'
        ? '← Revenir au tunnel'
        : (r.termines+' dossier'+(r.termines>1?'s':'')+' terminé'+(r.termines>1?'s':'')+' · voir'))
      +'</button></div>'
    : '';
  let h='<div class="tun-stats">'
    +stat('chaud',r.chauds,'Chauds',TUNNEL_LIB.chaud.c)
    +stat('tiede',r.tiedes,'Tièdes',TUNNEL_LIB.tiede.c)
    +stat('froid',r.froids,'Froids',TUNNEL_LIB.froid.c)
    +'</div>'+fini;
  if(!tout.length){
    h+='<div class="sub" style="text-align:center;padding:28px 12px;font-size:var(--fs-sm);line-height:1.6">'
      +'Personne dans le tunnel.<br>Les codes d’accès que tu crées y entrent automatiquement, '
      +'et en sortent dès que la personne ouvre RepCore.</div>';
  } else if(!vue.length){
    h+='<div class="sub" style="text-align:center;padding:24px 12px;font-size:var(--fs-sm)">Aucun dossier dans ce filtre.</div>';
  } else {
    h+=vue.map(_tunCarte).join('');
  }
  z.innerHTML=h;
  return true;
}
/** Une carte. Le nom et le statut en tete, l'echeance en pied. */
function _tunCarte(p){
  const s=TUNNEL_LIB[p.statut]||TUNNEL_LIB.chaud;
  const nom=escapeHtml(p.nom||'Élève sans nom');
  const ini=escapeHtml(((p.fname||'?')[0]||'?')+((p.lname||'')[0]||'')).toUpperCase();
  const rond=p.photo
    ? '<img src="'+escapeHtml(p.photo)+'" alt="">'
    : ini;
  // L'ECHEANCE EST LE FAIT QUI DECIDE : elle porte sa propre couleur, et les
  // deux mots qui disent quoi faire — « aujourd'hui », « en retard ».
  const ech=p.fini
    ? '<span>Terminé le <b>'+(p.termineLe?_tunJour(p.termineLe):'—')+'</b></span>'
    : p.prochaine
      ? '<span>Prochaine : <b class="'+(p.echeance==='retard'?'tun-retard':p.echeance==='aujourdhui'?'tun-du':'')+'">'
        +_tunnelQuand(p.prochaine)+'</b>'
        +(p.echeance==='retard'?' <span class="tun-retard">· en retard</span>'
         :p.echeance==='aujourdhui'?' <span class="tun-du">· aujourd’hui</span>':'')+'</span>'
      : '<span class="tun-du">Aucune relance planifiée</span>';
  return '<div class="tun-carte" style="--c:'+s.c+'">'
    +'<div class="tun-tete">'
      +'<span class="tun-rond">'+rond+'</span>'
      +'<div style="flex:1;min-width:0"><div class="tun-nom">'+nom+'</div>'
        +'<div class="tun-jauge">'+[0,1,2,3].map(i=>'<i class="'+(i<p.nb?'on':'')+'"></i>').join('')+'</div></div>'
      +'<span class="tun-badge">'+escapeHtml(s.lib)+'</span>'
    +'</div>'
    +'<div class="tun-faits">'
      +'<span>Relance <b>'+p.nb+'/'+TUNNEL_MAX+'</b></span>'
      +'<span>Dernière : <b>'+(p.derniere?_tunJour(p.derniere):'jamais')+'</b></span>'
      +ech
      +(p.fini&&!p.actif?'<span>Accès désactivé — tunnel terminé</span>':'')
    +'</div>'
    +'<div class="tun-cmd">'
      +(p.fini?''
        :'<button type="button" class="btn btn-red btn-sm" onclick="tunnelRelancer(\''+escapeHtml(p.codeId)+'\')">Relancer</button>'
         +'<button type="button" class="btn btn-blanc btn-sm" onclick="tunnelPlanifier(\''+escapeHtml(p.codeId)+'\')">'
         +(p.prochaine?'Replanifier':'Planifier')+'</button>')
      +'<button type="button" class="btn btn-outline btn-sm" onclick="openClientDetail(\''+escapeHtml(p.id)+'\',false,true)">Profil</button>'
    +'</div></div>';
}
/** PURE-ish. « 23/09 » — la forme la plus courte qui reste lisible. */
function _tunJour(t){
  if(!t) return '—';
  const q=new Date(t), p2=x=>String(x).padStart(2,'0');
  return p2(q.getDate())+'/'+p2(q.getMonth()+1);
}
const INACTIF_OBJET='On fait le point ?';
const JAMAIS_OBJET='On démarre ?';
// ══ UNE RELANCE S'ADRESSE A UNE PERSONNE ════════════════════════════════════
//
// ⚠ JAMAIS PAR LE CANAL, et c'est une regle du produit depuis le 19/09/2026.
//   Demande de Kevin. La relance « jamais demarre » ouvrait la fenetre du
//   CANAL avec un brouillon nominatif dedans : « Salut Jean, j'ai vu que tu
//   n'as pas encore lance ta premiere seance. » Le canal est lu par TOUS les
//   athletes suivis — l'envoyer tel quel apprenait au groupe entier que Jean
//   n'avait pas commence. L'ecran posait bien un avertissement orange, mais
//   un avertissement ne repare pas un chemin : il demande a l'utilisateur de
//   rattraper le produit. Les deux relances passent desormais par les memes
//   canaux directs — WhatsApp ou mail — que le cadre « Inactifs » employait
//   deja.
//
// PURE. Les deux adresses ouvrables pour cet athlete, ou '' pour chacune.
// waLink et non un replace brut : un numero saisi en « 06… » produit un lien
// que WhatsApp refuse, et mieux vaut ne pas poser le bouton qu'en poser un
// mort — c'est la regle deja ecrite pour le contact du coach.
//
// UNE SEULE FABRIQUE POUR LES DEUX CADRES : le durcissement du `mailto:`
// ci-dessous est une precaution de securite, et une precaution recopiee est
// une precaution qu'on oubliera de recopier la troisieme fois.
function _canauxRelance(c,texte,objet){
  const tel=_telAthlete(c);
  const mail=String((c&&c.email)||'').trim();
  return {
    texte:texte,
    wa:tel?waLink(tel,texte):'',
    // ⚠ L'ADRESSE N'EST PAS PERCENT-ENCODEE, le sujet et le corps le sont.
    // `mailto:x%40t.fr` fait tomber une partie des clients mail — l'arobase
    // encodee n'est pas reconnue comme separateur. Seuls les PARAMETRES de la
    // requete se codent. L'adresse est nettoyee des caracteres qui pourraient
    // en faire sortir : sans cela, un champ email contenant « ?body= » aurait
    // reecrit le message que le coach croit envoyer.
    mail:(mail.indexOf('@')>0&&!/[\s?&#<>"']/.test(mail))
      ?('mailto:'+mail+'?subject='+encodeURIComponent(objet)
        +'&body='+encodeURIComponent(texte))
      :''
  };
}
function canauxRelanceInactif(c,maintenant){
  return _canauxRelance(c,brouillonInactif(c,maintenant),INACTIF_OBJET);
}
function canauxRelanceJamaisDemarre(c){
  return _canauxRelance(c,brouillonJamaisDemarre(c),JAMAIS_OBJET);
}
/**
 * Les deux liens ouvrables pour une personne du TUNNEL. Elle n'a pas de
 * dossier — c'est tout le sujet — donc on fabrique le minimum que
 * `canauxRelanceJamaisDemarre` attend a partir de son entree de code.
 *
 * ⚠ UNE SEULE FABRIQUE DE LIENS POUR LES DEUX CHEMINS. Le durcissement du
 *   `mailto:` vit dans `_canauxRelance` ; le recopier ici en aurait fait une
 *   seconde version a oublier de corriger.
 * @param {any} code  une entree de studentCodes
 */
function tunnelCanaux(code){
  const nom=String((code&&code.studentName)||'').trim();
  return canauxRelanceJamaisDemarre({
    fname:nom.split(' ')[0]||'',
    lname:nom.split(' ').slice(1).join(' '),
    email:String((code&&code.athleteEmail)||''),
    phone:String((code&&(code.athletePhone||code.phone))||'')});
}
// PURE. Le cadre, ou la chaine VIDE quand personne n'est concerne — jamais un
// cadre vide annoncant zero. Meme regle que « Jamais demarre » juste en
// dessous, et pour la meme raison : une liste de relance qui s'affiche a zero
// devient du decor, et on cesse de la lire le jour ou elle dit quelque chose.
//
// LE GRIS ET NON LE ROUGE, encore. Ce n'est pas une alerte : personne n'a mal,
// rien n'est en retard. La peindre comme « A traiter » lui volerait l'attention
// que la sante doit garder.
function _htmlInactifs(liste,maintenant){
  const l=liste||[];
  if(!l.length) return '';
  const t=Number(maintenant)||Date.now();
  const n=l.length;
  const bouton=(href,lib)=>'<a href="'+_safeContactUrl(href)+'" target="_blank" rel="noopener" '
    +'class="btn btn-outline btn-sm rel-b">'+lib+'</a>';
  return '<div style="background:var(--surface-1);border:1px solid var(--border);'
    +'border-left:3px solid var(--sub);border-radius:var(--r-card);margin-bottom:20px;'
    +'overflow:hidden;box-shadow:var(--el-1)">'
    +'<div style="padding:9px 14px;display:flex;align-items:center;justify-content:space-between;'
    +'gap:10px;background:var(--surface-2);border-bottom:1px solid var(--border)">'
    +'<span style="font-size:13px;font-weight:800;color:var(--text-strong);text-transform:uppercase;'
    +'letter-spacing:2.4px">Inactifs</span>'
    +'<span style="background:var(--surface-1);border:1px solid var(--border);color:var(--text);'
    +'font-size:14px;font-weight:400;padding:1px 9px;border-radius:var(--r-3);'
    +'font-family:var(--pile-titre);letter-spacing:1px">'+n+'</span>'
    +'</div>'
    +'<div style="padding:0 14px">'
    +renderDataList(l,c=>{
      const j=joursDepuisSigne(c,t);
      // XSS STOCKE : le prenom est saisi par l'athlete et atterrit dans le
      // tableau de bord de son coach. Meme precaution que renderTodoBlock.
      const nom=escapeHtml(String(c.fname||'').trim()||'Athlète');
      const k=canauxRelanceInactif(c,t);
      // NI NUMERO NI ADRESSE : on le DIT. Deux boutons qui n'ouvrent rien
      // feraient croire a une panne, et le coach cliquerait deux fois avant de
      // comprendre que le manque est dans la fiche de l'athlete.
      const actions=(k.wa||k.mail)
        ?('<div class="rel-a">'
          +(k.wa?bouton(k.wa,'WhatsApp'):'')
          +(k.mail?bouton(k.mail,'Mail'):'')+'</div>')
        :'<span class="sub" style="font-size:var(--fs-2xs);flex:0 0 auto;text-align:right;'
          +'line-height:1.4;max-width:104px">Ni numéro<br>ni adresse</span>';
      return '<div style="flex:1;min-width:0">'
        +'<div style="font-size:var(--fs-sm);font-weight:800;line-height:1.3">'+nom+'</div>'
        +'<div class="sub" style="font-size:var(--fs-2xs);margin-top:2px">'
        +(j>0?('plus de séance depuis '+j+' jour'+(j>1?'s':'')):'plus de séance récente')
        +'</div></div>'+actions;
    },{pad:'11px 0'})
    +'</div>'
    +'<div class="sub" style="font-size:var(--fs-2xs);line-height:1.55;padding:2px 14px 12px">'
    +'Le message s’ouvre pré-rédigé et modifiable. RepCore n’envoie rien à ta place.'
    +'</div></div>';
}
