// Icônes intensité (flammes) et hydratation (verres à niveau)
const BICON={
  flame1:'<path d="M24,16 C20.5,20.5 17,24.5 17,29 a7,7 0 0 0 14,0 C31,24.5 27.5,20.5 24,16 Z"/>',
  flame2:'<path d="M19.5,12 C16,17 12.5,21.5 12.5,26.5 a7,7 0 0 0 14,0 C26.5,21.5 23,17 19.5,12 Z"/><path d="M32.5,21 C30.5,23.8 28.5,26 28.5,28.8 a4,4 0 0 0 8,0 C36.5,26 34.5,23.8 32.5,21 Z"/>',
  flame3:'<path d="M24,7 C20,13 15.5,18.5 15.5,25 a8.5,8.5 0 0 0 17,0 C32.5,18.5 28,13 24,7 Z"/><path d="M24,19 C22,21.5 21,23.5 21,26 a3,3 0 0 0 6,0 C27,23.5 26,21.5 24,19 Z" class="emo-dot"/><path d="M10.5,23 C9,25 7.5,26.5 7.5,28.5 a3.2,3.2 0 0 0 6.4,0 C13.9,26.5 12.5,25 10.5,23 Z"/><path d="M37.5,23 C36,25 34.5,26.5 34.5,28.5 a3.2,3.2 0 0 0 6.4,0 C40.9,26.5 39.5,25 37.5,23 Z"/>',
  glass:(lvl)=>`<path d="M15,8 L15,39 a5,5 0 0 0 5,5 h8 a5,5 0 0 0 5,-5 L33,8"/><path d="M13,8 L35,8"/><path d="M18.5,${lvl} h11 v${38.2-lvl<0?0:38.2-lvl} a3.6,3.6 0 0 1 -3.6,3.6 h-3.8 a3.6,3.6 0 0 1 -3.6,-3.6 Z" class="emo-dot" stroke="none"/>`
};
// Choix Homme/Femme — cartes avec les silhouettes du schéma de mensurations
function bGenderCards(gid){
  const opts=[{v:'Homme',b:BSCH_M},{v:'Femme',b:BSCH_F}];
  return `<div class="gsl-row">`+opts.map(o=>
    `<div class="gsl-opt${bilData[gid]===o.v?' sel':''}" data-grp="${gid}" data-val="${o.v}" onclick="pickBilChoice('${gid}',this.dataset.val,false)" role="button" tabindex="0" onkeydown="if(event.key==='Enter'||event.key===' '){event.preventDefault();this.click()}">`+
    `<svg viewBox="0 48 360 484" preserveAspectRatio="xMidYMid meet"><path class="gsl-body" d="${o.b.body}" fill-rule="evenodd"/></svg>`+
    `<div class="gsl-lbl">${o.v.toUpperCase()}</div></div>`).join('')+`</div>`;
}
// Curseur néon 1-10 — stocke "X/10" (affiché tel quel côté coach)
const BSL_COLORS=['#E02020','#ef4116','#f97316','#fb9d1e','#eab308','#c9d411','#a3e635','#67dd2f','#3ad348','#22c55e'];
const BSL_LABELS=['À plat','Très faible','En baisse','Fragile','Moyenne','Correcte','Bonne','Très bonne','Excellente','EN FEU !'];
// Poses de reference pour les photos de progression (extraites du visuel "LES PHOTOS")
const BPOSE={
  face:'data:image/png;base64,',
  back:'data:image/png;base64,',
  side:'data:image/png;base64,'
};
// Meme visuel, version femme : les trois silhouettes du « LES PHOTOS » feminin
// du coach, decoupees de la meme facon et a la meme hauteur que celles du
// jeu masculin. Le bandeau de legende qui barrait les tibias a ete enjambe,
// et les gris ont ete posterises — a 118 px, la plus grande taille ou l'app
// les affiche, ca ne se voit pas, et le poids reste celui du jeu masculin.
const BPOSE_F={
  face:'data:image/png;base64,',
  back:'data:image/png;base64,',
  side:'data:image/png;base64,'
};
// Poses selon le genre. Le questionnaire de depart fait foi quand il porte la
// reponse — un athlete remplit son premier bilan avant que son profil ne soit
// complet — sinon on retombe sur le profil. Meme regle que bBodySchema, pour
// que le schema de mensurations et les poses photo ne se contredisent jamais.
function posesGenre(prefix){
  let femme;
  if(prefix==='deb'&&bilData['deb-gender']) femme=bilData['deb-gender']==='Femme';
  else femme=isFemale(currentUser&&(currentUser._evol_gender||currentUser.gender));
  return femme?BPOSE_F:BPOSE;
}
// 3 cartes photo avec personnage neon : la pose a reproduire est montree au-dessus du bouton
function bPhotoCards(prefix){
  const B=posesGenre(prefix);
  const P=[{k:'face',l:'DE FACE',img:B.face},{k:'back',l:'DE DOS',img:B.back},{k:'side',l:'DE PROFIL',img:B.side}];
  return `<div style="display:flex;gap:8px">`+P.map(p=>{
    const key=prefix+'-photo-'+p.k;
    const done=!!bilData[key];
    return `<div style="flex:1;min-width:0;background:var(--surface-1);border:1px solid #222;border-radius:var(--r-3);padding:14px 6px 12px;text-align:center">
      <img src="${p.img}" alt="${p.l}" style="height:118px;max-width:100%;object-fit:contain;filter:drop-shadow(0 0 7px rgba(255,255,255,.4));margin-bottom:8px">
      <div style="font-size:var(--fs-xs);font-weight:800;letter-spacing:1.2px;color:#ccc;margin-bottom:9px">${p.l}</div>
      <label style="display:inline-block;background:${done?'#001a00':'#1a0000'};border:1px solid ${done?'#22c55e':'var(--red)'};color:${done?'#22c55e':'var(--red)'};padding:6px 12px;border-radius:var(--r-1);font-size:var(--fs-xs);font-weight:700;cursor:pointer;letter-spacing:.5px">${done?' Ajoutée':'AJOUTER'} <input type="file" accept="image/*" style="display:none" onchange="loadBilPhoto(this,'${key}')"></label>
    </div>`;
  }).join('')+`</div>`;
}
function bSlider(gid){
  const parsed=parseInt(String(bilData[gid]||'').match(/\d+/)?.[0]||0);
  const set=parsed>=1&&parsed<=10;
  const v=set?parsed:5;
  const c=set?BSL_COLORS[v-1]:'#555';
  const pct=(v-1)/9*100;
  const track=set?`linear-gradient(90deg,${c} ${pct}%,#1a1a1a ${pct}%)`:'#1a1a1a';
  return `<div class="bsl-wrap">
    <div class="bsl-value" id="bsl-num-${gid}" style="color:${c};${set?`--halo-c:${c};text-shadow:var(--halo-2)66`:''}">${set?v:'–'}<span class="bsl-max">/10</span></div>
    <div class="bsl-feedback" id="bsl-fb-${gid}" style="color:${set?c:'var(--text-dim)'}">${set?BSL_LABELS[v-1]:'Fais glisser le curseur'}</div>
    <input type="range" min="1" max="10" step="1" value="${v}" class="bslider" id="bsl-in-${gid}" style="--bsl:${set?c:'#555'};--bsl-glow:${set?c+'66':'transparent'};background:${track}" oninput="bSliderInput('${gid}',this.value)">
    <div class="bsl-scale"><span>1</span><span>2</span><span>3</span><span>4</span><span>5</span><span>6</span><span>7</span><span>8</span><span>9</span><span>10</span></div>
  </div>`;
}
function bSliderInput(gid,val){
  const v=parseInt(val);
  bilData[gid]=v+'/10';
  const c=BSL_COLORS[v-1];
  const num=document.getElementById('bsl-num-'+gid);
  if(num){num.innerHTML=v+'<span class="bsl-max">/10</span>';num.style.color=c;num.style.textShadow='0 0 16px '+c+'66';}
  const fb=document.getElementById('bsl-fb-'+gid);
  if(fb){fb.textContent=BSL_LABELS[v-1];fb.style.color=c;}
  const inp=document.getElementById('bsl-in-'+gid);
  if(inp){if(inp.value!==String(v))inp.value=v;const pct=(v-1)/9*100;inp.style.setProperty('--bsl',c);inp.style.setProperty('--bsl-glow',c+'66');inp.style.background=`linear-gradient(90deg,${c} ${pct}%,#1a1a1a ${pct}%)`;}
}

// ── Profession : saisie libre AVEC suggestions ──────────────────────────────
// Le champ reste un texte libre : un métier absent de la liste doit pouvoir
// être écrit. Reconnu, il donne son niveau d'activité ; inconnu, le calcul
// retombe sur le barème par séances et le dit.
function bMetier(id){
  const v=bilData[id]||'';
  const n=facteurProfession(v);
  return `<div style="position:relative">
    <input type="text" id="${id}" autocomplete="off" placeholder="Commence à taper : maçon, infirmier, comptable…"
      value="${escapeHtml(v)}" oninput="_bMetierSaisie('${id}',this.value)" onfocus="_bMetierSaisie('${id}',this.value)">
    <div id="${id}-sug" style="display:none;position:absolute;left:0;right:0;top:100%;z-index:var(--z-raised);background:var(--dark);border:1px solid var(--border);border-radius:0 0 var(--r-3) var(--r-3);max-height:210px;overflow:auto"></div>
    <div id="${id}-niv" style="font-size:var(--fs-2xs);line-height:1.6;margin-top:5px;color:${n?'var(--success)':'var(--text-faint)'}">${
      n?escapeHtml(n.lib)+' → facteur '+String(n.f).replace('.',',')
       :(v?'Métier non reconnu : le calcul utilisera le nombre de séances.':'')}</div>
  </div>`;
}
function _bMetierSaisie(id,val){
  bilData[id]=val;
  const zs=document.getElementById(id+'-sug');
  const zn=document.getElementById(id+'-niv');
  const l=chercherMetiers(val,8);
  if(zs){
    // On ne propose plus rien dès que la saisie EST un métier connu : la liste
    // resterait ouverte par-dessus la suite du formulaire.
    const exact=!!niveauMetier(val);
    zs.style.display=(l.length&&!exact)?'block':'none';
    zs.innerHTML=l.map(m=>`<div onclick="_bMetierChoisi('${id}',this.dataset.n)" role="button" tabindex="0" onkeydown="if(event.key==='Enter'||event.key===' '){event.preventDefault();this.click()}" data-n="${escapeHtml(m.nom)}"
      style="padding:9px 12px;font-size:var(--fs-sm);color:var(--text-strong);cursor:pointer;border-bottom:1px solid var(--border)">
      ${escapeHtml(m.nom)}<span style="color:var(--text-faint);font-size:var(--fs-2xs)"> · ${escapeHtml(m.fam)}</span></div>`).join('');
  }
  if(zn){
    const n=facteurProfession(val);
    zn.style.color=n?'var(--success)':'var(--text-faint)';
    zn.textContent=n?(n.lib+' → facteur '+String(n.f).replace('.',','))
      :(val?'Métier non reconnu : le calcul utilisera le nombre de séances.':'');
  }
}
// ── Niveau d'activite hors sport : DECLARE PAR LA PERSONNE ─────────
//
// ⚠ IL PASSE DEVANT LA PROFESSION, et c'etait tout l'objet du changement.
// Deduire le NEAT d'un intitule de metier se trompe souvent : deux personnes
// qui ecrivent « infirmier » ne bougent pas pareil selon le service, et un
// « comptable » qui marche une heure par jour etait classe sedentaire sans
// recours. La personne sait, elle : on le lui demande.
//
// La question reste FACULTATIVE. Sans reponse, la deduction par le metier
// continue de servir exactement comme avant — on ajoute un niveau de
// priorite, on n'en retire aucun.
function bNaf(id){
  const cur=nafDepuisReponse(bilData[id]);
  return NAF_ECHELLE.map(x=>
    `<div class="choice-opt naf-opt${cur&&cur.cle===x.cle?' sel':''}" data-grp="${id}" data-val="${escapeHtml(x.lib)}" onclick="pickBilChoice('${id}',this.dataset.val,false)" role="button" tabindex="0" onkeydown="if(event.key==='Enter'||event.key===' '){event.preventDefault();this.click()}">`+
    `<span class="naf-lib">${escapeHtml(x.lib)}</span>`+
    `<span class="naf-aide">${escapeHtml(x.aide)}</span>`+
    `</div>`).join('');
}
function _bMetierChoisi(id,nom){
  bilData[id]=nom;
  const el=document.getElementById(id);
  if(el) el.value=nom;
  const zs=document.getElementById(id+'-sug');
  if(zs) zs.style.display='none';
  _bMetierSaisie(id,nom);
}

// ── Sports pratiqués : sport + intensité + heures par semaine ───────────────
// Stocké comme un TABLEAU d'objets, pas comme du texte libre : c'est lui qui
// alimente le calcul de dépense, et une phrase ne se calcule pas.
function _bSportsListe(id){
  const l=bilData[id];
  return Array.isArray(l)?l:[];
}
function bSports(id){
  const l=_bSportsListe(id);
  const noms=Object.keys(SPORTS_KCAL_H);
  const ligne=(e,i)=>{
    const kh=kcalHeureSport(e.sport,e.intensite);
    return `<div style="display:flex;gap:5px;align-items:center;margin-bottom:6px">
      <select onchange="_bSportSet('${id}',${i},'sport',this.value)"
        style="flex:2;min-width:0;padding:8px;background:var(--surface-2);border:1px solid var(--border);border-radius:var(--r-2);color:var(--text);font-family:Montserrat,sans-serif;font-size:var(--fs-xs)">
        ${noms.map(n=>`<option value="${escapeHtml(n)}"${e.sport===n?' selected':''}>${escapeHtml(n)}</option>`).join('')}
      </select>
      <select onchange="_bSportSet('${id}',${i},'intensite',this.value)"
        style="flex:1.3;min-width:0;padding:8px;background:var(--surface-2);border:1px solid var(--border);border-radius:var(--r-2);color:var(--text);font-family:Montserrat,sans-serif;font-size:var(--fs-xs)">
        ${SPORT_INTENSITES.map(x=>`<option value="${x.cle}"${e.intensite===x.cle?' selected':''}>${x.lib}</option>`).join('')}
      </select>
      <input type="number" min="0" step="0.5" value="${e.heures!=null?e.heures:''}" placeholder="h/sem"
        oninput="_bSportSet('${id}',${i},'heures',this.value)"
        style="flex:1;min-width:0;width:auto;text-align:right;padding:8px;background:#080808;border:1px solid #222;border-radius:var(--r-2);color:var(--text);font-size:var(--fs-sm);font-weight:700;margin:0">
      <button type="button" onclick="_bSportRetirer('${id}',${i})" class="hit44"
        style="flex:0 0 auto;background:none;border:none;color:var(--text-dim);font-size:var(--fs-lg);cursor:pointer;padding:0 4px;min-width:30px">✕</button>
    </div>
    ${kh!=null&&Number(e.heures)>0?`<div style="font-size:var(--fs-2xs);color:var(--text-faint);margin:-3px 0 8px 2px">${kh} kcal/h × ${String(e.heures).replace('.',',')} h = ${Math.round(kh*Number(e.heures))} kcal par semaine</div>`:''}`;
  };
  const total=depenseSportsParJour(l);
  return `<div id="${id}-zone">
    ${l.map(ligne).join('')}
    <button type="button" onclick="_bSportAjouter('${id}')" class="btn btn-outline btn-sm"
      style="width:100%;margin:2px 0 0;letter-spacing:1px;font-size:var(--fs-2xs)">+ Ajouter un sport</button>
    <div data-sports-total style="font-size:var(--fs-xs);color:var(--success);line-height:1.6;margin-top:8px">${total.semaine>0?total.semaine+' kcal par semaine, soit '+total.jour+' kcal par jour ajoutés à ta dépense.':''}</div>
    <div style="font-size:var(--fs-2xs);color:var(--text-faint);line-height:1.6;margin-top:6px">Compte ici ce que tu fais EN DEHORS de RepCore. Tes créneaux du programme sont déjà comptés à part : si tu ajoutes quand même une ligne « Musculation », elle ne s'additionne pas à eux.</div>
  </div>`;
}
// R35 — PURE. Les sports reellement declares : une ligne sans sport, ou
// « Aucun », ne compte pas.
function _bSportsDeclares(id){
  return _bSportsListe(id).filter(e=>e&&e.sport&&e.sport!=='Aucun').length;
}
function _bRepeindreSports(id){
  const z=document.getElementById(id+'-zone');
  if(z) z.outerHTML=bSports(id);
  // R35 — la question d'intensite du second sport suit la liste : elle ne se
  // montre qu'a partir de deux sports declares.
  if(id==='deb-sports'){
    const b2=document.getElementById('deb-intensity-2-bloc');
    if(b2) b2.style.display=_bSportsDeclares(id)<2?'none':'';
  }
}
function _bSportAjouter(id){
  const l=_bSportsListe(id).slice();
  l.push({sport:'Musculation',intensite:'moderee',heures:''});
  bilData[id]=l;
  _bRepeindreSports(id);
}
function _bSportRetirer(id,i){
  const l=_bSportsListe(id).slice();
  l.splice(i,1);
  bilData[id]=l;
  _bRepeindreSports(id);
}
function _bSportSet(id,i,champ,val){
  const l=_bSportsListe(id).slice();
  if(!l[i]) return;
  l[i]=Object.assign({},l[i],{[champ]:champ==='heures'?val:String(val)});
  bilData[id]=l;
  // On ne repeint que sur les listes déroulantes : repeindre à chaque frappe
  // dans le champ des heures ferait perdre le focus au bout d'un caractère.
  if(champ!=='heures') _bRepeindreSports(id);
  else{
    const z=document.getElementById(id+'-zone');
    if(z){
      const t=depenseSportsParJour(l);
      // Mise à jour du seul total, sans toucher aux champs de saisie.
      const tot=z.querySelector('[data-sports-total]');
      if(tot) tot.textContent=t.semaine>0?(t.semaine+' kcal par semaine, soit '+t.jour+' kcal par jour ajoutés à ta dépense.'):'';
    }
  }
}

function bSec(title,html){return`<div style="margin-bottom:22px"><div style="font-size:var(--fs-xs);color:var(--red-text);text-transform:uppercase;letter-spacing:2px;font-weight:800;margin-bottom:12px;padding-bottom:8px;border-bottom:1px solid rgba(224,32,32,.28);--halo-c:rgba(224,32,32,.4);text-shadow:var(--halo-2)">${title}</div>${html}</div>`;}
function bMeas(id,label,unit){return`<div class="bil-row"><span class="bil-row-label">${label}</span><div style="display:flex;align-items:center;gap:6px">${bQ(id)}<span class="bil-unit">${unit}</span></div></div>`;}

