  const lignesSp=Array.isArray(t.sportLignes)?t.sportLignes:[];
  const spCoach=t.sportSource==='coach';
  const optSport=cur=>Object.keys(SPORTS_KCAL_H).filter(k=>k!=='Aucun')
    .concat(SPORTS_KCAL_H[cur]&&cur!=='Aucun'?[]:[cur])
